    ["Trade the Orcish Axe to any Gate Guard in San d'Oria."] = "オークアクスをサンドリアのいずれかのゲートガードにトレードする。",
    ["Bat Hunt"] = "コウモリ退治",
    ["Enter King Ranperre's Tomb from East Ronfaure at (H-11) and hunt Ding Bats at night for Orcish Mail Scales."] = "東ロンフォール(H-11)からランペールの墓へ入り、夜に Ding Bat を倒して Orcish Mail Scales を入手する。",
    ["Examine Tombstone (H/I-10)."] = "墓石(H/I-10)を調べる。",
    ["The Ding Bats and tombstone can be handled in either order."] = "Ding Bat と墓石はどちらを先に済ませてもよい。",
    ["Trade the Orcish Mail Scales to any Gate Guard in San d'Oria."] = "Orcish Mail Scales をサンドリアのいずれかのゲートガードにトレードする。",
    ["Infiltrate Davoi"] = "ダボイ潜入計画",
    ["Travel to Chateau d'Oraguille and examine Prince's Royal Room (G/H-7)."] = "ドラギーユ城へ行き、王子の部屋(G/H-7)の扉を調べる。",
    ["Travel through Jugner Forest and enter Davoi from (G-12)."] = "ジャグナー森林を抜け、(G-12)からダボイへ入る。",
    ["Follow the right wall until the path turns north, then take the left path at the three-way intersection to reach the bridge."] = "右壁沿いに進み、道が北へ曲がったら三叉路で左へ進んで橋に出る。",
    ["Wait on the bridge and speak with Quemaricond (H-7) to receive the Royal Knights' Davoi Report."] = "橋の上で待ち、Quemaricond(H-7)に話して王立騎士団のダボイ調査報告書を受け取る。",
    ["Return to Chateau d'Oraguille and speak with Prince Trion in Prince's Royal Room (G/H-7)."] = "ドラギーユ城へ戻り、王子の部屋(G/H-7)の Trion王子に話す。",
    ["The Crystal Spring"] = "クリスタルの泉",
    ["Travel to Crystalwater Spring at (J-9) in Jugner Forest and obtain a Crystal Bass."] = "ジャグナー森林(J-9)の泉へ行き、クリスタルバスを入手する。",
    ["Trade the Crystal Bass to any Gate Guard in San d'Oria."] = "クリスタルバスをサンドリアのいずれかのゲートガードにトレードする。",
    ["Enter Chateau d'Oraguille and speak with Chalvatot (F-7)."] = "ドラギーユ城に入り、Chalvatot(F-7)に話す。",
    ["Appointment to Jeuno"] = "ジュノ大使館へ赴任",
    ["Speak with Halver (I-9) at Chateau d'Oraguille."] = "ドラギーユ城で Halver(I-9)に話す。",
    ["Examine the Great Hall behind Halver."] = "Halverの奥にある謁見の間の扉を調べる。",
    ["Travel to the San d'Orian Embassy in Ru'Lude Gardens and speak with Nelcabrit (H-9)."] = "ル・ルデの庭のサンドリア大使館へ行き、Nelcabrit(H-9)に話す。",
    ["Travel to Lower Delkfutt's Tower and enter the basement through the Cermet Door at (E-8) if you already have a Delkfutt's Key."] = "デルクフのカギを持っていれば、デルクフの塔下層(E-8)の Cermet Door から地下へ入る。",
    ["If you do not have a Delkfutt's Key, climb the tower to the tenth floor. Use the teleports and stairways to reach Upper Delkfutt's Tower, then go to (H-7), defeat Mimas if necessary, and enter Porphyrion's room."] = "デルクフのカギがない場合は塔を10階まで登る。テレポーターと階段でデルクフの塔上層へ進み、(H-7)で必要なら Mimas を倒して Porphyrion の部屋へ入る。",
    ["Defeat Porphyrion and obtain a Delkfutt's Key."] = "Porphyrion を倒してデルクフのカギを入手する。",
    ["Use the elevator beside Porphyrion at (H-8) to descend, then take the long staircase down to the basement."] = "Porphyrion の横(H-8)の昇降機で降り、長い階段を下って地下へ向かう。",
    ["In the basement, head east to the large room and use the Delkfutt's Key on the Cermet Door at (L-8)."] = "地下では東の大部屋へ進み、(L-8)の Cermet Door をデルクフのカギで開ける。",
    ["Return to the San d'Orian Embassy in Ru'Lude Gardens and examine the Embassy door to complete the mission."] = "ル・ルデの庭のサンドリア大使館へ戻り、大使館の扉を調べて完了。",
    ["Speak with Nelcabrit (H-9) and enter the San d'Orian Embassy door in Ru'Lude Gardens."] = "Nelcabrit(H-9)に話し、ル・ルデの庭のサンドリア大使館の扉から入る。",
    ["Examine the Audience Chamber to receive the Letter to Aldo."] = "謁見の間を調べ、Aldoへの手紙を受け取る。",
    ["Enter Neptune's Spire in Lower Jeuno and speak with Aldo (J-8) to receive the Silver Bell."] = "ジュノ下層の天晶堂に入り、Aldo(J-8)に話して銀の鈴を受け取る。",
    ["If you still need the Yagudo Torch, speak with Paya-Sabya at (I-8) in Upper Jeuno, then speak with Muckvix at (H-9) in Lower Jeuno."] = "ヤグードの松明が必要なら、ジュノ上層(I-8)の Paya-Sabya、次にジュノ下層(H-9)の Muckvix に話す。",
    ["Speak with Sattal-Mansal at (J-8): trade a Quadav Charm for the Coruscant Rosary, then trade a Quadav Augury Shell for the Black Matinee Necklace."] = "Sattal-Mansal(J-8)に話し、Quadav Charm を渡して Coruscant Rosary を、Quadav Augury Shell を渡して Black Matinee Necklace を得る。",
    ["In Upper Jeuno, speak with Baudin at (G-8) and trade him Coeurl Meat for the Crest of Davoi."] = "ジュノ上層(G-8)の Baudin にクァールの肉をトレードし、Crest of Davoi を受け取る。",
    ["The prerequisite key items are shared between the three nations' Magicite missions, so only missing items need to be obtained."] = "前提のだいじなものは三国の魔晶石ミッションで共通なので、足りない物だけ集めればよい。",
    ["The three Magicite locations can be completed in any order."] = "魔晶石3か所はどの順番で回ってもよい。",
    ["Davoi: travel to (G-7), avoid or defeat the Orcs, use Sneak if needed, and pass through the Wall of Dark Arts into Monastic Cavern to obtain Optistone."] = "ダボイ：(G-7)へ向かい、オークを避けるか倒し（必要ならスニーク）、Wall of Dark Arts を抜けて修道窟で Optistone を入手。",
    ["Castle Oztroja: follow the right wall to the Brass Door at (H-9), light the torch, continue south, turn right to the next Brass Door, and enter the Altar Room to obtain Orastone."] = "オズトロヤ城：右壁沿いに(H-9)の Brass Door へ行き松明を灯す。南へ進んで右折し、次の Brass Door から祭壇の間へ入り Orastone を入手。",
    ["Beadeaux: follow the left wall to (H-7), enter Qulun Dome, open the inner door, and obtain Aurastone."] = "ベドー：左壁沿いに(H-7)へ進み、クゥルン大堂の奥の扉を開けて Aurastone を入手。",
    ["Return to the Audience Chamber after obtaining all three Magicites."] = "魔晶石を3つ集めたら謁見の間へ戻る。",
    ["Return to Nelcabrit (H-9) at the San d'Orian Embassy."] = "サンドリア大使館の Nelcabrit(H-9)のもとへ戻る。",
    ["The Ruins of Fei'Yin"] = "廃墟フェ・イン",
    ["Travel to Chateau d'Oraguille."] = "ドラギーユ城へ向かう。",
    ["Speak with any Gate Guard in San d'Oria and accept the mission."] = "サンドリアのいずれかのゲートガードに話し、ミッションを受ける。",
    ["Speak with Halver (I-9) to receive the New Fei'Yin Seal."] = "Halver(I-9)に話し、新しいフェ・インの封印を受け取る。",
    ["Travel to Fei'Yin and enter battlefield entrance."] = "フェ・インへ行き、バトルフィールドの入口へ向かう。",
    ["Enter the Rank 5 battlefield and defeat Archlich Taber'quoan. Ancient Sorcerers and Ancient Warriors will also appear during the battle."] = "ランク5のバトルフィールドに入り、Archlich Taber'quoan を倒す。戦闘中に Ancient Sorcerer と Ancient Warrior も現れる。",
    ["Return to Halver (I-9)."] = "Halver(I-9)のもとへ戻る。",
    ["The Shadow Lord"] = "闇の王を討て！",
    ["Speak with any Gate Guard in San d'Oria to accept the mission."] = "サンドリアのいずれかのゲートガードに話してミッションを受ける。",
    ["Examine the Prince's Royal Room (G/H-7)."] = "王子の部屋(G/H-7)の扉を調べる。",
    ["Enter the Throne Room battlefield and defeat the Shadow Lord in both forms."] = "王の間のバトルフィールドに入り、2形態の闇の王を倒す。",
    ["Return to Chateau d'Oraguille and speak with Halver (I-9) to complete the mission."] = "ドラギーユ城へ戻り、Halver(I-9)に話して完了。",
    ["Examine the Great Hall."] = "謁見の間の扉を調べる。",
    ["Examine the Prince's Royal Room (G/H-7) again to unlock Trust: Trion."] = "もう一度王子の部屋(G/H-7)を調べ、フェイス: トリオンを入手する。",
    ["Leaute's Last Wishes"] = "ローテ王妃の遺言",
    ["Enter the Great Hall and receive the King's request for a Dreamrose."] = "謁見の間に入り、国王からドリームローズの依頼を受ける。",
    ["Speak with Halver (I-9) again."] = "もう一度 Halver(I-9)に話す。",
    ["Travel to Western Altepa Desert and examine Dreamrose (G-7) at (G-7) to face Sabotender Enamorado."] = "西アルテパ砂漠(G-7)の Dreamrose を調べ、Sabotender Enamorado と戦う。",
    ["Defeat Sabotender Enamorado."] = "Sabotender Enamorado を倒す。",
    ["Examine Dreamrose (G-7) again to receive the Dreamrose."] = "再び Dreamrose(G-7)を調べてドリームローズを入手する。",
    ["Travel to Queen Leaute's Garden (F-8) at (F-8)."] = "ローテ王妃の庭園(F-8)へ行く。",
    ["Receive the Piece of Paper after completing the event at the Garden."] = "庭園でのイベント後、紙切れを受け取る。",
    ["Ranperre's Final Rest"] = "龍王の眠る場所",
    ["Travel to Chateau d'Oraguille and speak with Prince Trion in Prince's Royal Room (G/H-7)."] = "ドラギーユ城へ行き、王子の部屋(G/H-7)の Trion王子に話す。",
    ["Travel to King Ranperre's Tomb and make your way to Heavy Stone Door (H-8)."] = "ランペールの墓へ行き、Heavy Stone Door(H-8)まで進む。",
    ["Examine the Heavy Stone Door to face Corrupted Soffeil, Corrupted Yorgos, and Corrupted Ulbrig."] = "Heavy Stone Door を調べ、Corrupted Soffeil・Corrupted Yorgos・Corrupted Ulbrig と戦う。",
    ["Defeat all three Skeletons."] = "3体の骸骨をすべて倒す。",
    ["Examine Heavy Stone Door (H-8) again and enter the chamber."] = "もう一度 Heavy Stone Door(H-8)を調べて奥の部屋へ入る。",
    ["Examine the tombstone inside to receive the Ancient San d'Orian Book."] = "奥の墓石を調べ、古いサンドリアの書を受け取る。",
    ["Return to any Gate Guard in San d'Oria."] = "サンドリアのいずれかのゲートガードのもとへ戻る。",
    ["Speak with the Gate Guard three times about the book; after the guard says it will take time to decipher, return later and speak with the guard again."] = "本についてゲートガードに3回話す。解読に時間がかかると言われたら、時間をおいて再び話す。",
    ["Follow the Gate Guard's instructions and return to Prince Trion in Prince's Royal Room (G/H-7)."] = "ゲートガードの指示に従い、王子の部屋(G/H-7)の Trion王子のもとへ戻る。",
    ["Return to Heavy Stone Door (H-8) in King Ranperre's Tomb and examine it again."] = "ランペールの墓の Heavy Stone Door(H-8)へ戻り、再び調べる。",
    ["Prestige of the Papsque"] = "教皇の威信",
    ["Travel to Northern San d'Oria and enter the Papal Chambers on the third floor of the Cathedral."] = "北サンドリアへ行き、大聖堂3階の教皇の間に入る。",
    ["Travel to Chateau d'Oraguille and enter Bostaunieux Oubliette."] = "ドラギーユ城へ行き、ボストーニュ監獄に入る。",
    ["Reach the Sewer Lid around (E-7/E-8) and speak with the attendant beside it to descend."] = "(E-7/E-8)付近の Sewer Lid へ行き、横の係員に話して下へ降りる。",
    ["Follow the right wall through the lower area and zone into West Ronfaure."] = "下層を右壁沿いに進み、西ロンフォールへ抜ける。",
    ["Examine ??? (E-8) to face Marauder Dvogzog."] = "???(E-8)を調べ、Marauder Dvogzog と戦う。",
    ["Defeat Marauder Dvogzog."] = "Marauder Dvogzog を倒す。",
    ["Examine the same target again to receive the Ancient San d'Orian Tablet."] = "同じ場所をもう一度調べ、古いサンドリアの石板を受け取る。",
    ["Return to Northern San d'Oria and enter the Papal Chambers."] = "北サンドリアへ戻り、教皇の間に入る。",
    ["The Secret Weapon"] = "獣人兵器の秘密",
    ["Travel to Chateau d'Oraguille and head toward (F-7)."] = "ドラギーユ城の(F-7)方面へ向かう。",
    ["Return to any Gate Guard in San d'Oria to receive the mission."] = "サンドリアのいずれかのゲートガードに戻り、ミッションを受ける。",
    ["Travel through Ghelsba Outpost to Yughott Grotto and enter battlefield entrance."] = "ゲルスバ野営陣を経てユグホトの岩屋へ行き、バトルフィールドの入口に入る。",
    ["Enter the battlefield and defeat Darokbok of Clan Reaper, Derakbak of Clan Wolf, Jagidbod of Clan Reaper, Wolf Clan Warmachine, and Reaper Clan Warmachine."] = "バトルフィールドで Darokbok of Clan Reaper・Derakbak of Clan Wolf・Jagidbod of Clan Reaper・Wolf Clan Warmachine・Reaper Clan Warmachine を倒す。",
    ["Receive the Crystal Dowser, then return to any Gate Guard in San d'Oria."] = "クリスタル・ダウザーを受け取り、サンドリアのいずれかのゲートガードへ戻る。",
    ["Save the Children"] = "子供の救助",
    ["Travel to Northern San d'Oria and speak with Arnau (M-6) in the Cathedral."] = "北サンドリアの大聖堂で Arnau(M-6)に話す。",
    ["Travel through West Ronfaure and enter Ghelsba Outpost."] = "西ロンフォールを抜け、ゲルスバ野営陣に入る。",
    ["Make your way to Hut Door (G-9) in the large open area."] = "広場にある Hut Door(G-9)へ向かう。",
    ["Examine the Hut Door to enter the battlefield."] = "Hut Door を調べてバトルフィールドに入る。",
    ["Defeat Fodderchief Vokdek, Strongarm Zodvad, and Sureshot Snatgat."] = "Fodderchief Vokdek・Strongarm Zodvad・Sureshot Snatgat を倒す。",
    ["Examine Hut Door (G-9) again after the battle."] = "戦闘後、もう一度 Hut Door(G-9)を調べる。",
    ["Coming of Age"] = "成人の儀",
    ["Examine the two doors to the Princes' quarters if you want to hear their additional dialogue."] = "王子たちの部屋の扉2つを調べると追加の会話が聞ける（任意）。",
    ["Travel to Eastern Altepa Desert and enter Quicksand Caves at (H-10)."] = "東アルテパ砂漠(H-10)から流砂洞に入る。",
    ["Reach Map 2, drop through the hole at (E-11), and continue to Fountain of Kings (G-14)."] = "マップ2へ進み、(E-11)の穴から落ちて Fountain of Kings(G-14)へ向かう。",
    ["Examine Fountain of Kings (G-14) to face Honor and Valor."] = "Fountain of Kings(G-14)を調べ、Honor と Valor と戦う。",
    ["Defeat Honor and Valor, then examine the Fountain again to receive the Drops of Amnio."] = "Honor と Valor を倒し、再び泉を調べて Drops of Amnio を受け取る。",
    ["Wait until after Japanese midnight, then zone into Northern San d'Oria."] = "日本時間の0時を過ぎてから北サンドリアへエリアチェンジする。",
    ["Lightbringer"] = "聖剣探索",
    ["Travel to Chateau d'Oraguille and examine the Great Hall."] = "ドラギーユ城へ行き、謁見の間の扉を調べる。",
    ["Speak with Rahal (H-9) at (H-9) to receive the Crystal Dowser and instructions."] = "(H-9)の Rahal に話し、クリスタル・ダウザーと指示を受け取る。",
    ["Travel to Temple of Uggalepih and obtain a Prelate Key from the required Tonberries."] = "ウガレピ寺院へ行き、指定のトンベリから高僧のカギを入手する。",
    ["Reach Map 2 and continue to the door at (I-10)."] = "マップ2へ進み、(I-10)の扉へ向かう。",
    ["If the Temple Guardian blocks the route, defeat it to open the way, then continue through the nearby passage."] = "Temple Guardian が道をふさいでいたら倒して道を開き、近くの通路を進む。",
    ["Pass through the door at (J-10)."] = "(J-10)の扉を通る。",
    ["Examine ??? (G-10), ??? (H-10), first Broken Key target, and ??? (I-10) to collect the three Pieces of a Broken Key."] = "???(G-10)・???(H-10)（1つ目のカギのかけら）・???(I-10)を調べ、カギのかけら3つを集める。",
    ["After obtaining all three pieces, examine the second door at (H-10), then examine ??? (H-10), battle/cutscene target."] = "かけら3つがそろったら(H-10)の2つ目の扉を調べ、続いて ???(H-10)（戦闘／イベント地点）を調べる。",
    ["Defeat Nio-Hum and Nio-A."] = "Nio-Hum と Nio-A を倒す。",
    ["Examine ??? (H-10), battle/cutscene target again."] = "もう一度 ???(H-10)（戦闘／イベント地点）を調べる。",
    ["Return to Chateau d'Oraguille and examine the Great Hall."] = "ドラギーユ城へ戻り、謁見の間の扉を調べる。",
    ["Breaking Barriers"] = "厚き壁",
    ["The three objectives must be completed in order. Before entering Eldieme Necropolis alone, obtain a Magicked Astrolabe from Churano-Shurano in Windurst Waters (F-8) to open the required doors."] = "3つの目標は順番どおりに進める必要がある。エルディーム古墳に1人で入る前に、ウィンダス水の区(F-8)の Churano-Shurano から Magicked Astrolabe をもらい、扉を開けられるようにしておく。",
    ["First, travel to Cape Terrigan and reach the Valley of Sorrows entrance at (J-8). Cross to (I-8) and examine ??? (I-8) to receive the Figure of Titan."] = "まずテリガン岬へ行き、(J-8)の慟哭の谷入口へ。(I-8)へ渡り ???(I-8)を調べてタイタンの像を受け取る。",
    ["Next, travel to Xarcabard and reach (H-7). Examine ??? (H-7) near the clustered trees to receive the Figure of Garuda."] = "次にザルカバードの(H-7)へ行き、木々の近くの ???(H-7)を調べてガルーダの像を受け取る。",
    ["Finally, enter the southern Eldieme Necropolis entrance from Batallia Downs at (I-10)."] = "最後にバタリア丘陵(I-10)からエルディーム古墳の南側入口に入る。",
    ["Reach the southern room and drop through the center hole at (G-9), then follow the route through Maps 2 and 3 and exit back to Batallia Downs at (J-9)."] = "南の部屋の中央の穴(G-9)から落ち、マップ2・3を経由して(J-9)からバタリア丘陵へ出る。",
    ["Reach ??? (J-11) near the Stone Monument and examine it to face Suparna and Suparna Fledgling."] = "Stone Monument 近くの ???(J-11)を調べ、Suparna と Suparna Fledgling と戦う。",
    ["Defeat both, then examine the same target again to receive the Figure of Leviathan."] = "2体を倒し、同じ場所を再び調べてリヴァイアサンの像を受け取る。",
    ["The Heir to the Light"] = "光の継承者",
    ["Rank 10, 100,000 gil, San d'Orian Flag, Ability to buy Atma of the Heir"] = "ランク10、100,000ギル、王国旗、王者の人工アートマ購入可",
    ["Zone into Northern San d'Oria for the Rites of Succession."] = "継承の儀のため北サンドリアへエリアチェンジする。",
    ["Zone into Chateau d'Oraguille."] = "ドラギーユ城へエリアチェンジする。",
    ["Travel to Fei'Yin and continue to battlefield entrance."] = "フェ・インへ行き、バトルフィールドの入口へ進む。",
    ["Enter The Heir to the Light battlefield. The first battle consists of Death Clan Destroyer, Yukvok of Clan Death, three Worgbut of Clan Death, three Rallbrog of Clan Death, and three Vangknok of Clan Death."] = "「光の継承者」のバトルフィールドに入る。1戦目は Death Clan Destroyer、Yukvok of Clan Death、Worgbut of Clan Death×3、Rallbrog of Clan Death×3、Vangknok of Clan Death×3。",
    ["Defeat the first group, then continue to the second battle with Prince Trion. Defeat Warlord Rojgnoj, Rojgnoj's Left Hand, and Rojgnoj's Right Hand."] = "1戦目の敵を倒すと、Trion王子と共に2戦目へ。Warlord Rojgnoj、Rojgnoj's Left Hand、Rojgnoj's Right Hand を倒す。",
    ["Zone into Northern San d'Oria."] = "北サンドリアへエリアチェンジする。",
    ["Travel to King Ranperre's Tomb and examine Heavy Stone Door (H-8)."] = "ランペールの墓へ行き、Heavy Stone Door(H-8)を調べる。",
    ["Return to Chateau d'Oraguille and speak with Halver (I-9)."] = "ドラギーユ城へ戻り、Halver(I-9)に話す。",
    ["Return to Northern San d'Oria and visit the Papal Chambers to learn what happened to Shamonde."] = "北サンドリアへ戻り、教皇の間で Shamonde の行方を聞く。",
    ["Zone into Southern San d'Oria for the final epilogue."] = "最後のエピローグのため南サンドリアへエリアチェンジする。",
    ["The Rescue Drill"] = "救助訓練",
    ["Travel to La Theine Plateau and speak with Galaihaurat (E-6)."] = "ラテーヌ高原へ行き、Galaihaurat(E-6)に話す。",
    ["Continue down the canyon and speak with Equesobillot (F-6) at (F-6)."] = "渓谷を下り、Equesobillot(F-6)に話す。",
    ["Enter Ordelle's Caves and follow the left wall to Ruillont (G-3) by the pond."] = "オルデール鍾乳洞に入り、左壁沿いに池のそばの Ruillont(G-3)へ向かう。",
    ["Return to La Theine Plateau. Deaufrain (F-6), Equesobillot (F-6), and Galaihaurat (E-6) are the three who may provide the Bronze Sword."] = "ラテーヌ高原へ戻る。ブロンズソードを渡してくれるのは Deaufrain(F-6)・Equesobillot(F-6)・Galaihaurat(E-6)のいずれか。",
    ["Speak with them again until you find the one carrying the Bronze Sword, then trade it to Ruillont (G-3) in Ordelle's Caves."] = "ブロンズソードを持つ騎士が見つかるまで話しかけ、オルデール鍾乳洞の Ruillont(G-3)にトレードする。",
    ["Return to La Theine Plateau and speak with Vicorpasse (F-6) to receive the Rescue Training Certificate."] = "ラテーヌ高原へ戻り、Vicorpasse(F-6)に話して救助訓練修了証を受け取る。",
    ["The Davoi Report"] = "ダボイ調査報告",
    ["Travel to La Theine Plateau and enter Jugner Forest at (M-8), then follow the right side of Jugner Forest to Davoi at (G-12)."] = "ラテーヌ高原(M-8)からジャグナー森林に入り、森の右側を進んで(G-12)からダボイへ向かう。",
    ["Find Zantaviat just inside Davoi."] = "ダボイ入口すぐの Zantaviat を見つける。",
    ["Walk south to the pond around (J-8)."] = "南へ歩き、(J-8)付近の池へ行く。",
    ["Examine ??? (J-8), south bank of the pond on the south bank to obtain the Lost Document."] = "池の南岸の ???(J-8)を調べ、紛失した文書を入手する。",
    ["Return to Zantaviat to receive the Temple Knights' Davoi Report."] = "Zantaviat のもとへ戻り、神殿騎士団のダボイ調査報告書を受け取る。",
    ["Enter the Papal Chambers on the top floor of the Cathedral in Northern San d'Oria."] = "北サンドリアの大聖堂最上階にある教皇の間に入る。",
    ["Journey Abroad"] = "他国を回れ",
    ["Choose whether to visit Bastok or Windurst first. The two paths can be completed in either order."] = "バストゥークとウィンダスのどちらを先に回るか選ぶ。順番はどちらでもよい。",
    ["Bastok First:"] = "バストゥークを先に回る場合：",
    ["Travel to Bastok and speak with Savae E. Paleade (I-9), Pius (J-8), and Grohm (G-9)."] = "バストゥークへ行き、Savae E. Paleade(I-9)・Pius(J-8)・Grohm(G-9)に話す。",
    ["In Palborough Mines, trade a Pickaxe to a Mythril Seam to obtain Mine Gravel."] = "パルブロ鉱山で Mythril Seam につるはしをトレードし、Mine Gravel を入手する。",
    ["On the third floor, trade the Gravel to the Refiner, pull the lever, drop to the second floor, pull the second lever, and obtain Mythril Sand."] = "3階で Refiner に Gravel をトレードしてレバーを引き、2階へ降りて2つ目のレバーを引き、ミスリルの砂を入手する。",
    ["Return to Savae E. Paleade (I-9) and trade the Mythril Sand."] = "Savae E. Paleade(I-9)へ戻り、ミスリルの砂をトレードする。",
    ["Travel to Windurst Woods and speak with Mourices (F/G-10)."] = "ウィンダス森の区へ行き、Mourices(F/G-10)に話す。",
    ["Enter Heavens Tower and speak with Kupipi in the Clerical Chamber to receive the Dark Key."] = "天の塔に入り、Kupipi に話して Dark Key を受け取る。",
    ["Travel through Giddeus to Balga's Dais and enter the Rank 2 Final Mission battlefield."] = "ギデアスを抜けてバルガの舞台へ行き、ランク2最終ミッションのバトルフィールドに入る。",
    ["Defeat Searcher and Black Dragon."] = "Searcher と Black Dragon を倒す。",
    ["Return to Windurst Woods and speak with Mourices (F/G-10) to receive the Kindred Report."] = "ウィンダス森の区へ戻り、Mourices(F/G-10)に話して Kindred Report を受け取る。",
    ["Windurst First:"] = "ウィンダスを先に回る場合：",
    ["Enter Heavens Tower and speak with Kupipi in the Clerical Chamber to receive the Shield Offering."] = "天の塔に入り、Kupipi に話して Shield Offering を受け取る。",
    ["Enter Giddeus from West Sarutabaruta at (F-8), then drop through the hole at (G-8) and head north to (G/H-7)."] = "西サルタバルタ(F-8)からギデアスに入り、(G-8)の穴から落ちて北の(G/H-7)へ向かう。",
    ["Defeat Zhuu Buxu the Silent twice to obtain two Parana Shields."] = "Zhuu Buxu the Silent を2回倒し、パラナシールドを2つ入手する。",
    ["Travel west to (F-7) and speak with Uu Zhoumo (F-7) to offer the Shield Offering."] = "西の(F-7)へ進み、Uu Zhoumo(F-7)に話して Shield Offering を捧げる。",
    ["Return to Mourices (F/G-10) and trade the two Parana Shields."] = "Mourices(F/G-10)へ戻り、パラナシールド2つをトレードする。",
    ["Travel through Palborough Mines, obtain Mine Gravel and turn it into Mythril Sand, then return to Savae E. Paleade (I-9)."] = "パルブロ鉱山で Mine Gravel を入手してミスリルの砂にし、Savae E. Paleade(I-9)へ戻る。",
    ["Enter Waughroon Shrine and complete the Rank 2 Final Mission against Seeker and Dark Dragon."] = "ワールンの祠に入り、ランク2最終ミッションで Seeker と Dark Dragon を倒す。",
    ["Return to Savae E. Paleade (I-9) to receive the Kindred Report."] = "Savae E. Paleade(I-9)へ戻り、Kindred Report を受け取る。",
    ["Return to Halver (I-9) at Chateau d'Oraguille after both national paths are complete."] = "両国のルートを終えたら、ドラギーユ城の Halver(I-9)のもとへ戻る。",
    ["Journey to Bastok"] = "他国を回れ（バストゥーク編）",
    ["Travel to Windurst to continue with the second leg."] = "ウィンダスへ向かい、後半ルートを続ける。",
    ["Journey to Windurst"] = "他国を回れ（ウィンダス編）",
    ["Travel to Bastok to continue with the second leg."] = "バストゥークへ向かい、後半ルートを続ける。",
    ["Return to Halver (I-9) at Chateau d'Oraguille to complete the mission."] = "ドラギーユ城の Halver(I-9)のもとへ戻って完了。",

    -- ============================================================
    -- Windurst missions. Titles: https://wiki.ffo.jp/html/14896.html ;
    -- 2-1 白き書 cross-checked with https://wiki.ffo.jp/html_2006/8257.html .
    -- ============================================================
    ["The Horutoto Ruins Experiment"] = "ホルトト遺跡の大実験",
    ["Travel to the Orastery in Port Windurst and speak with Hakkuru-Rinkuru."] = "ウィンダス港の口の院へ行き、Hakkuru-Rinkuru に話す。",
    ["Travel to East Sarutabaruta and enter Inner Horutoto Ruins through the eastern magic tower."] = "東サルタバルタの東の魔法塔から内ホルトト遺跡に入る。",
    ["Proceed to the Cracked Wall at (H-9) and examine it to enter the passage."] = "(H-9)の Cracked Wall を調べて通路に入る。",
    ["Continue to the Gate: Magical Gizmo at (I-9) and examine it."] = "(I-9)の Gate: Magical Gizmo まで進んで調べる。",
    ["Search the six Ancient Magical Gizmos until one yields the Cracked Mana Orb."] = "6つの Ancient Magical Gizmo を調べ、割れた魔導球が見つかるまで探す。",
    ["Return to Hakkuru-Rinkuru with the orb."] = "魔導球を持って Hakkuru-Rinkuru のもとへ戻る。",
    ["The Heart of the Matter"] = "カーディアンの心",
    ["Travel to the Manustery in Windurst Woods and speak with Apururu (H-9)."] = "ウィンダス森の区の手の院へ行き、Apururu(H-9)に話す。",
    ["Travel to East Sarutabaruta and enter the southeastern magic tower of Outer Horutoto Ruins."] = "東サルタバルタの南東の魔法塔から外ホルトト遺跡に入る。",
    ["Place the six Dark Mana Orbs on the corresponding pedestals."] = "6つの暗き魔導球を対応する台座に置く。",
    ["Examine the Cracked Walls to reach the hidden rooms containing the remaining pedestals."] = "Cracked Wall を調べ、残りの台座がある隠し部屋へ進む。",
    ["Pass through the eastern Cracked Wall and examine the Gate: Magical Gizmo for the event."] = "東側の Cracked Wall を抜け、Gate: Magical Gizmo を調べてイベントを見る。",
    ["Retrieve the six Glowing Mana Orbs from the pedestals."] = "台座から輝く魔導球を6つ回収する。",
    ["Return to Apururu (H-9)."] = "Apururu(H-9)のもとへ戻る。",
    ["To Each His Own Right"] = "それぞれの正義",
    ["Rank Points, Starway Stairway bauble"] = "ランクポイント、Starway Stairway Bauble",
    ["Speak with Kupipi in Heavens Tower."] = "天の塔の Kupipi に話す。",
    ["Proceed to the upper portion of Heavens Tower and speak with Rhy Epocan."] = "天の塔の上階へ進み、Rhy Epocan に話す。",
    ["Speak with Hakkuru-Rinkuru."] = "Hakkuru-Rinkuru に話す。",
    ["Travel to Castle Oztroja and enter through the trap door at (I-8)."] = "オズトロヤ城へ行き、(I-8)の落とし戸から入る。",
    ["Complete the required event and return to Rhy Epocan."] = "必要なイベントを済ませ、Rhy Epocan のもとへ戻る。",
    ["Written in the Stars"] = "星読み",
    ["Rank Points, Portal charm"] = "ランクポイント、Portal Charm",
    ["Speak with Zubaba."] = "Zubaba に話す。",
    ["Travel to East Sarutabaruta and enter Inner Horutoto Ruins."] = "東サルタバルタから内ホルトト遺跡に入る。",
    ["Pass through the Three Mages Gate and proceed to the small room around (G-7)."] = "Three Mages Gate を抜け、(G-7)付近の小部屋へ進む。",
    ["Examine the Gate of Light."] = "Gate of Light を調べる。",
    ["Return to Zubaba."] = "Zubaba のもとへ戻る。",
    ["A New Journey"] = "新たなる旅立ち",
    ["Enter the Vestal Chamber at the top of Heavens Tower."] = "天の塔最上階の星の神子の間に入る。",
    ["Speak with Pakh-Jatalfih (I-9)."] = "Pakh-Jatalfih(I-9)に話す。",
    ["Use Delkfutt's Key to enter the Cermet Door at (L-7) in the basement of Delkfutt's Tower."] = "デルクフのカギを使い、デルクフの塔地下(L-7)の Cermet Door から入る。",
    ["Return to Pakh-Jatalfih (I-9)."] = "Pakh-Jatalfih(I-9)のもとへ戻る。",
    ["Enter the Windurstian Embassy in Ru'Lude Gardens."] = "ル・ルデの庭のウィンダス大使館に入る。",
    ["Speak with Pakh-Jatalfih (I-9) in the Windurstian Embassy and enter the Ambassador's room."] = "ウィンダス大使館の Pakh-Jatalfih(I-9)に話し、大使の部屋に入る。",
    ["Examine the Audience Chamber door."] = "謁見の間の扉を調べる。",
    ["If this is your first Magicite mission, speak with Paya-Sabya."] = "初めての魔晶石ミッションなら Paya-Sabya に話す。",
    ["Speak with Muckvis."] = "Muckvis に話す。",
    ["Speak with Sattal-Mansal in Lower Jeuno and obtain the required key items."] = "ジュノ下層の Sattal-Mansal に話し、必要なだいじなものを集める。",
    ["Trade Coeurl Meat to Baudin in Upper Jeuno to obtain the Crest of Davoi."] = "ジュノ上層の Baudin にクァールの肉をトレードし、Crest of Davoi を受け取る。",
    ["Visit the three magicite locations in any order."] = "魔晶石3か所を好きな順番で回る。",
    ["Davoi (G-7): pass through the Wall of Dark Arts, enter Monastic Cavern, and obtain the magicite."] = "ダボイ(G-7)：Wall of Dark Arts を抜けて修道窟に入り、魔晶石を入手する。",
    ["Castle Oztroja: enter through the Brass Door at (I-8), proceed through the upper floors, light the torch at (H-9), then reach the Altar Room and obtain the magicite."] = "オズトロヤ城：(I-8)の Brass Door から入って上階を進み、(H-9)の松明を灯して祭壇の間で魔晶石を入手する。",
    ["Beadeaux: follow the left wall to the tunnel at (H-7), enter Qulun Dome, and obtain the magicite."] = "ベドー：左壁沿いに(H-7)のトンネルへ進み、クゥルン大堂で魔晶石を入手する。",
    ["Return to the Audience Chamber and obtain the Letter to Jeuno."] = "謁見の間へ戻り、ジュノからの書状を受け取る。",
    ["Return to Pakh-Jatalfih (I-9) to complete the mission."] = "Pakh-Jatalfih(I-9)のもとへ戻って完了。",
    ["The Final Seal"] = "最後の護符",
    ["Travel to Fei'Yin and enter the ruins."] = "フェ・インへ行き、遺跡に入る。",
    ["Proceed to Qu'Bia Arena and complete the Rank 5 battlefield."] = "クゥ・ビア闘技場へ進み、ランク5のバトルフィールドをクリアする。",
    ["Return to the Vestal Chamber."] = "星の神子の間へ戻る。",
    ["The Shadow Awaits"] = "最果てにて君を待つ闇",
    ["Travel to Castle Zvahl Keep and enter the Throne Room."] = "ズヴァール城内郭へ行き、王の間に入る。",
    ["Defeat the Shadow Lord."] = "闇の王を倒す。",
    ["Return to Heavens Tower and enter the Vestal Chamber."] = "天の塔へ戻り、星の神子の間に入る。",
    ["Full Moon Fountain"] = "満月の泉",
    ["Speak with Hakkuru-Rinkuru in the Orastery."] = "口の院の Hakkuru-Rinkuru に話す。",
    ["Travel to West Sarutabaruta and enter the southwestern tower of Outer Horutoto Ruins."] = "西サルタバルタの南西の塔から外ホルトト遺跡に入る。",
    ["Examine the Cracked Wall at (I-8)."] = "(I-8)の Cracked Wall を調べる。",
    ["Examine the second Cracked Wall at (J-8)."] = "(J-8)の2つ目の Cracked Wall を調べる。",
    ["Continue to the Gate: Magical Gizmo and examine it to spawn the four Jack Cardians."] = "Gate: Magical Gizmo まで進んで調べ、Jack Cardian 4体を出現させる。",
    ["Defeat the Jack Cardians."] = "Jack Cardian を倒す。",
    ["Examine the Gate: Magical Gizmo again after the battlefield."] = "バトルフィールド後、もう一度 Gate: Magical Gizmo を調べる。",
    ["Enter Full Moon Fountain in Toraimarai Canal."] = "トライマライ水路から満月の泉に入る。",
    ["Saintly Invitation"] = "聖者の招待",
    ["Rank 7, 40,000 gil, Ashura Necklace"] = "ランク7、40,000ギル、Ashura Necklace",
    ["Travel to Balga's Dais in Giddeus and complete the Saintly Invitation battlefield."] = "ギデアスのバルガの舞台へ行き、「聖者の招待」のバトルフィールドをクリアする。",
    ["Travel to Castle Oztroja and obtain the Judgment Key from the Flagellants around (H-5)."] = "オズトロヤ城へ行き、(H-5)付近の Flagellant から Judgment Key を入手する。",
    ["Pass through the password trap door and reach the Brass Door."] = "合言葉の落とし戸を抜けて Brass Door へ向かう。",
    ["Trade the Judgment Key to the Brass Door."] = "Brass Door に Judgment Key をトレードする。",
    ["Speak with Kaa Toru the Just."] = "Kaa Toru the Just に話す。",
    ["The Sixth Ministry"] = "第6の院",
    ["Speak with Tosuka-Poruka (G-8) in the Optistery."] = "目の院の Tosuka-Poruka(G-8)に話す。",
    ["Enter Toraimarai Canal."] = "トライマライ水路に入る。",
    ["Reach Map 2 around (G-8)."] = "マップ2の(G-8)付近へ進む。",
    ["Defeat the four Hinge Oils to open the Marble Door."] = "Hinge Oil 4体を倒して Marble Door を開ける。",
    ["Examine the Tome of Magic at the mission location."] = "ミッション地点の Tome of Magic を調べる。",
    ["Return to Tosuka-Poruka (G-8)."] = "Tosuka-Poruka(G-8)のもとへ戻る。",
    ["Awakening of the Gods"] = "蘇る神々",
    ["Speak with Leepe-Hoppe (J-8) on the roof of the Rhinostery in Windurst Waters."] = "ウィンダス水の区・鼻の院の屋上で Leepe-Hoppe(J-8)に話す。",
    ["Speak with Kerutoto in the northern Rhinostery building."] = "鼻の院北側の建物にいる Kerutoto に話す。",
    ["Travel to Kazham and speak with Romaa Mihgo (H-11) at (H-11) in Mihgo's Residence."] = "カザムへ行き、ミスラの家の Romaa Mihgo(H-11)に話す。",
    ["Travel through Yhoator Jungle to the Den of Rancor."] = "ヨアトル大森林を抜けて怨念洞へ向かう。",
    ["Enter Temple of Uggalepih and proceed to Map 3 around (J-9)."] = "ウガレピ寺院に入り、マップ3の(J-9)付近へ進む。",
    ["Defeat Bonze Marberry and obtain the Cursed Key."] = "Bonze Marberry を倒し、Cursed Key を入手する。",
    ["Travel to the Granite Door at (J-6)."] = "(J-6)の Granite Door へ向かう。",
    ["Trade the Cursed Key to Granite Door (J-6)."] = "Granite Door(J-6)に Cursed Key をトレードする。",
    ["Return to Leepe-Hoppe (J-8) on the roof of the Rhinostery."] = "鼻の院屋上の Leepe-Hoppe(J-8)のもとへ戻る。",
    ["The Price of Peace"] = "平和のために",
    ["Travel to the roof of the Rhinostery in Windurst Waters and speak with Leepe-Hoppe (J-8)."] = "ウィンダス水の区・鼻の院の屋上へ行き、Leepe-Hoppe(J-8)に話す。",
    ["Travel to Giddeus and deliver the Food Offering to Laa Mozi (H-7) at (H-7)."] = "ギデアスへ行き、Laa Mozi(H-7)に献上品・食料品を渡す。",
    ["Deliver the Drink Offering to Ghoo Pakya (G-7) at (G-7)."] = "Ghoo Pakya(G-7)に献上品・飲み物を渡す。",
    ["Return to the Rhinostery and speak with Leepe-Hoppe (J-8)."] = "鼻の院へ戻り、Leepe-Hoppe(J-8)に話す。",
    ["Return to Gate Guard."] = "ゲートガードのもとへ戻る。",
    ["Vain"] = "ヴェイン",
    ["Speak with Moreno-Toeno (L-6) in the Aurastery at (L-6)."] = "耳の院の Moreno-Toeno(L-6)に話す。",
    ["Travel to Ro'Maeve and examine Gu'Hau Spring."] = "ロ・メーヴへ行き、Gu'Hau Spring を調べる。",
    ["Travel to Davoi and enter Monastic Cavern through the second entrance."] = "ダボイへ行き、2つ目の入口から修道窟に入る。",
    ["Defeat Dirtyhanded Gochakzuk."] = "Dirtyhanded Gochakzuk を倒す。",
    ["Obtain the Curse Wand."] = "Curse Wand を入手する。",
    ["Trade the Curse Wand to Sedal-Godjal (J-8)."] = "Curse Wand を Sedal-Godjal(J-8)にトレードする。",
    ["Return to Moreno-Toeno (L-6)."] = "Moreno-Toeno(L-6)のもとへ戻る。",
    ["The Jester Who'd Be King"] = "王と道化師",
    ["Speak with Apururu (H-9) in Windurst Woods."] = "ウィンダス森の区の Apururu(H-9)に話す。",
    ["Speak with Tosuka-Poruka (G-8) in Windurst Waters."] = "ウィンダス水の区の Tosuka-Poruka(G-8)に話す。",
    ["Travel to Fei'Yin and speak with Rukususu at (F-6) on Map 2 through the Cermet Door."] = "フェ・インへ行き、Cermet Door の先、マップ2(F-6)の Rukususu に話す。",
    ["Travel to Davoi, enter Monastic Cavern through the second entrance, and speak with Sedal-Godjal (J-8)."] = "ダボイへ行き、2つ目の入口から修道窟に入って Sedal-Godjal(J-8)に話す。",
    ["Return to Windurst Waters and speak with Tosuka-Poruka (G-8)."] = "ウィンダス水の区へ戻り、Tosuka-Poruka(G-8)に話す。",
    ["Return to Apururu (H-9) to continue."] = "Apururu(H-9)のもとへ戻って続きを進める。",
    ["Travel to West Sarutabaruta and enter Outer Horutoto Ruins."] = "西サルタバルタから外ホルトト遺跡に入る。",
    ["Examine the Cracked Wall at (I-6) and proceed to the next map."] = "(I-6)の Cracked Wall を調べ、次のマップへ進む。",
    ["Examine the Cracked Wall at (G-8) to spawn Queen of Coins and Queen of Swords."] = "(G-8)の Cracked Wall を調べ、Queen of Coins と Queen of Swords を出現させる。",
    ["Defeat both Cardian NMs."] = "カーディアンNM2体を倒す。",
    ["Examine the Cracked Wall again and obtain the Orastery Ring."] = "もう一度 Cracked Wall を調べ、口の院の指輪を入手する。",
    ["Speak with Shantotto (K-7)."] = "Shantotto(K-7)に話す。",
    ["Enter Inner Horutoto Ruins and pass the Three Mages Gate."] = "内ホルトト遺跡に入り、Three Mages Gate を抜ける。",
    ["Reach the Gate of Darkness at (I-7) on Map 4."] = "マップ4(I-7)の Gate of Darkness へ向かう。",
    ["Complete the event and return to Apururu (H-9)."] = "イベントを見て Apururu(H-9)のもとへ戻る。",
    ["Doll of the Dead"] = "死者の人形",
    ["Travel to the hidden area of The Boyahda Tree Map 1."] = "ボヤーダ樹のマップ1の隠しエリアへ行く。",
    ["Find the Mandragora Warden and trade it Goobbue Humus."] = "Mandragora Warden を見つけ、Goobbue Humus をトレードする。",
    ["Enter Full Moon Fountain."] = "満月の泉に入る。",
    ["Moon Reading"] = "月詠み",
    ["Rank 10, 100,000 gil, Windurstian Flag, Ability to buy Atma of the Full Moon"] = "ランク10、100,000ギル、連邦旗、天導の人工アートマ購入可",
    ["Visit Qu'Hua Spring in Ro'Maeve and obtain the Ancient Verse of Ro'Maeve."] = "ロ・メーヴの Qu'Hua Spring を訪れ、ロ・メーヴの古詩を入手する。",
    ["Enter the Chamber of Oracles and obtain the Ancient Verse of Altepa."] = "宣託の間に入り、アルテパの古詩を入手する。",
    ["Travel to Temple of Uggalepih Map 2 and obtain the Uggalepih Key."] = "ウガレピ寺院のマップ2へ行き、ウガレピのカギを入手する。",
    ["Use the Uggalepih Key to reach the ??? and obtain the Ancient Verse of Uggalepih."] = "ウガレピのカギで ??? までたどり着き、ウガレピの古詩を入手する。",
    ["Travel to Full Moon Fountain and complete the final battlefield."] = "満月の泉へ行き、最後のバトルフィールドをクリアする。",
    ["Lost for Words"] = "白き書",
    ["Travel to the Optistery in Windurst Waters and speak with Tosuka-Poruka (G-8)."] = "ウィンダス水の区・目の院へ行き、Tosuka-Poruka(G-8)に話す。",
    ["Speak with Nanaa Mihgo (J-3)."] = "Nanaa Mihgo(J-3)に話す。",
    ["Travel through Maze of Shakhrami to the Fossil Rocks around (G-6)."] = "シャクラミの地下迷宮を進み、(G-6)付近の Fossil Rock へ向かう。",
    ["Continue to Map 2 around (H-5) and examine the Fossil Rocks to obtain Lapis Coral."] = "マップ2の(H-5)付近へ進み、Fossil Rock を調べて瑠璃サンゴを入手する。",
    ["Return to Nanaa Mihgo (J-3)."] = "Nanaa Mihgo(J-3)のもとへ戻る。",
    ["Examine Mahogany Door in the required chamber."] = "指定の部屋にある Mahogany Door を調べる。",
    ["Continue to the House of the Hero."] = "英雄の家へ向かう。",
    ["A Testing Time"] = "試験の行方",
    ["Travel to Tahrongi Canyon."] = "タロンギ大峡谷へ行く。",
    ["Defeat at least 30 monsters before the trial ends."] = "試験終了までにモンスターを30体以上倒す。",
    ["During the final Vana'diel hour of the trial, return to Moreno-Toeno (L-6) to complete the mission."] = "試験の最後のヴァナ・ディール時間内に Moreno-Toeno(L-6)へ戻って完了。",
    ["The Three Kingdoms"] = "三大強国",
    ["Bastok Path:"] = "バストゥーク・ルート：",
    ["Travel to Bastok and speak with Patt-Pott (I-7)."] = "バストゥークへ行き、Patt-Pott(I-7)に話す。",
    ["Speak with Pius at (J-8), then Grohm at (G-9)."] = "Pius(J-8)、次に Grohm(G-9)に話す。",
    ["Travel to Palborough Mines and obtain Mine Gravel from a Mythril Seam at (F-7) or (I-8)."] = "パルブロ鉱山の(F-7)または(I-8)の Mythril Seam から Mine Gravel を入手する。",
    ["Place the Gravel in the Refiner, operate the levers as required, and obtain Mythril Sand."] = "Refiner に Gravel を入れ、指示どおりレバーを操作してミスリルの砂を入手する。",
    ["Return to Metalworks and trade the Mythril Sand to Patt-Pott (I-7)."] = "大工房へ戻り、Patt-Pott(I-7)にミスリルの砂をトレードする。",
    ["Travel to Northern San d'Oria and speak with Kasaroro at (H-9)."] = "北サンドリアへ行き、Kasaroro(H-9)に話す。",
    ["Speak with Halver (I-9)."] = "Halver(I-9)に話す。",
    ["Enter Horlais Peak and complete the required battlefield."] = "ホルレーの岩峰に入り、指定のバトルフィールドをクリアする。",
    ["Return to Northern San d'Oria and speak with Kasaroro again."] = "北サンドリアへ戻り、再び Kasaroro に話す。",
    ["San d'Oria Path:"] = "サンドリア・ルート：",
    ["Travel to Northern San d'Oria and speak with Heruze-Moruze, then Helaku at (K-10)."] = "北サンドリアへ行き、Heruze-Moruze、次に Helaku(K-10)に話す。",
    ["Speak with Halver (I-9) when directed."] = "指示されたら Halver(I-9)に話す。",
    ["Travel to Ghelsba Outpost and defeat Warchief Vatgit."] = "ゲルスバ野営陣へ行き、Warchief Vatgit を倒す。",
    ["Return to Northern San d'Oria and speak with Kasaroro."] = "北サンドリアへ戻り、Kasaroro に話す。",
    ["Return to Bastok and speak with Patt-Pott (I-7)."] = "バストゥークへ戻り、Patt-Pott(I-7)に話す。",
    ["Enter Waughroon Shrine and complete the required battlefield."] = "ワールンの祠に入り、指定のバトルフィールドをクリアする。",
    ["Return to Patt-Pott (I-7)."] = "Patt-Pott(I-7)のもとへ戻る。",
    ["Return to Kupipi after both paths are complete."] = "両ルートを終えたら Kupipi のもとへ戻る。",
    ["The Three Kingdoms (San d'Oria)"] = "三大強国（サンドリア編）",
    ["The Three Kingdoms (Bastok)"] = "三大強国（バストゥーク編）",
    ["Return to Kupipi in Heavens Tower to complete the mission."] = "天の塔の Kupipi のもとへ戻って完了。",
    ["Travel to Palborough Mines and enter Waughroon Shrine from the upper level at (H-10)."] = "パルブロ鉱山の上層(H-10)からワールンの祠に入る。",
    ["Complete the required battlefield."] = "指定のバトルフィールドをクリアする。",
    ["Return to Patt-Pott (I-7) in Metalworks."] = "大工房の Patt-Pott(I-7)のもとへ戻る。",

    -- ============================================================
    -- Rise of the Zilart missions. Titles: https://wiki.ffo.jp/html/279.html ;
    -- per-mission wiki.ffo.jp pages listed in docs/sources_zilart_cop.tsv .
    -- "The Outlands" (ID 2) has no wiki title -> intentionally left English.
    -- ============================================================
    ["The New Frontier"] = "新たなる世界",
    ["Key Item: Map of Norg"] = "だいじなもの：ノーグ地図",
    ["Reach Rank 6 in your home nation."] = "所属国でランク6に到達する。",
    ["Enter Norg."] = "ノーグに入る。",
    ["Headstone Pilgrimage"] = "古代石碑巡礼",
    ["Key Items: Earth fragment, Fire fragment, Ice fragment, Light fragment, Lightning fragment, Water fragment, Wind fragment"] = "だいじなもの：土の祈り、炎の祈り、氷の祈り、光の祈り、雷の祈り、水の祈り、風の祈り",
    ["Examine the seven required Cermet Headstones in any order."] = "必要な7つの石碑（Cermet Headstone）を好きな順番で調べる。",
    ["Examine Cermet Headstone in Western Altepa Desert (H-8) to obtain the Earth fragment."] = "西アルテパ砂漠(H-8)の石碑を調べ、土の祈りを入手する。",
    ["Examine Cermet Headstone in La Theine Plateau (G-11) to obtain the Water fragment."] = "ラテーヌ高原(G-11)の石碑を調べ、水の祈りを入手する。",
    ["Examine Cloister of Frost in Fei'Yin to obtain the Ice fragment."] = "フェ・インの凍結の回廊を調べ、氷の祈りを入手する。",
    ["Examine Cermet Headstone in Yuhtunga Jungle (L-6/7), defeat Carthi and Tipha, then examine it again to obtain the Fire fragment."] = "ユタンガ大森林(L-6/7)の石碑を調べ、Carthi と Tipha を倒してから再び調べて炎の祈りを入手する。",
    ["Examine Cermet Headstone in Behemoth's Dominion (G-9), defeat Legendary Weapon and Ancient Weapon, then examine it again to obtain the Lightning fragment."] = "ベヒーモスの縄張り(G-9)の石碑を調べ、Legendary Weapon と Ancient Weapon を倒してから再び調べて雷の祈りを入手する。",
    ["Examine Cermet Headstone in Cape Terrigan (H-5), defeat Axesarion the Wanderer, then examine it again to obtain the Wind fragment."] = "テリガン岬(H-5)の石碑を調べ、Axesarion the Wanderer を倒してから再び調べて風の祈りを入手する。",
    ["Examine Cermet Headstone in the Sanctuary of Zi'Tah (I-7), defeat Doomed Pilgrims, then examine it again to obtain the Light fragment."] = "聖地ジ・タ(I-7)の石碑を調べ、Doomed Pilgrims を倒してから再び調べて光の祈りを入手する。",
    ["Through the Quicksand Caves"] = "流砂洞を越えて",
    ["Obtain the Loadstone from the Open Sesame quest if entering the weight doors solo."] = "ソロで重量扉を通るなら、クエスト「Open Sesame」で重量石を入手しておく。",
    ["Enter Quicksand Caves from Western Altepa Desert through the southern entrance around (C/D-11)."] = "西アルテパ砂漠の南側(C/D-11)付近の入口から流砂洞に入る。",
    ["Reach Weighted Door (I-9) at (I-9) and use the weight pad to pass through."] = "(I-9)の重量扉へ行き、重量床を使って通過する。",
    ["Proceed west to Weighted Door (H-7) at (H-7) and use the second weight pad to pass through."] = "西へ進み、(H-7)の重量扉も2つ目の重量床で通過する。",
    ["Drop through the hole in the next room and continue to the Chamber of Oracles."] = "次の部屋の穴から落ち、宣託の間へ進む。",
    ["Enter Chamber of Oracles."] = "宣託の間に入る。",
    ["Enter the battlefield and defeat Centurio V-III, Triarius V-VIII, and Princeps V-XI."] = "バトルフィールドに入り、Centurio V-III・Triarius V-VIII・Princeps V-XI を倒す。",
    ["The Chamber of Oracles"] = "宣託の間",
    ["Key Item: Prismatic fragment"] = "だいじなもの：虹の祈り",
    ["Examine all eight sections of Chamber of Oracles to place the eight fragments."] = "宣託の間の8つの台座をすべて調べ、8つの祈りをはめ込む。",
    ["Return to Delkfutt's Tower"] = "デルクフの塔再び",
    ["Zone into Lower Delkfutt's Tower from Qufim Island."] = "クフィム島からデルクフの塔下層へエリアチェンジする。",
    ["If you have a Delkfutt's Key, go to (E-8), pass through the Cermet Door, and continue to the next Cermet Door at (J-8)."] = "デルクフのカギがあれば、(E-8)の Cermet Door を抜けて(J-8)の次の Cermet Door へ進む。",
    ["Proceed to (H-8) and examine the ??? in the spiral staircase to reach the 10th floor."] = "(H-8)へ進み、らせん階段の ??? を調べて10階へ上がる。",
    ["If you do not have a Delkfutt's Key, climb the tower normally until you reach the 10th floor."] = "デルクフのカギがなければ、通常どおり塔を登って10階を目指す。",
    ["From the 10th floor, go to (F-8) and continue through Upper Delkfutt's Tower to the 11th floor."] = "10階から(F-8)へ進み、デルクフの塔上層を経て11階へ。",
    ["Proceed to (J-6) to reach the 12th floor, then head to (F-10) and use the teleporter to enter Stellar Fulcrum at the top of Delkfutt's Tower."] = "(J-6)から12階へ上がり、(F-10)のテレポーターで塔最上部の天輪の場へ入る。",
    ["Walk forward and examine Qe'lov Gate in Upper Delkfutt's Tower to enter the battlefield."] = "前へ進み、Qe'lov Gate を調べてバトルフィールドに入る。",
    ["Defeat Kam'lanaut."] = "Kam'lanaut を倒す。",
    ["Ro'Maeve"] = "ロ・メーヴ",
    ["Travel to Norg."] = "ノーグへ向かう。",
    ["Speak with Gilgamesh (L-8) and choose the option to open the Oaken Door."] = "Gilgamesh(L-8)に話し、Oaken Door を開ける選択肢を選ぶ。",
    ["Continue to Norg after reaching Rank 6 in your home nation."] = "所属国でランク6に到達したら、ノーグへ向かう。",
    ["Enter Oaken Door (L-8) in Norg."] = "ノーグの Oaken Door(L-8)に入る。",
    ["The Temple of Desolation"] = "聖地ジ・タ～滅びの神殿",
    ["Travel to Ro'Maeve."] = "ロ・メーヴへ向かう。",
    ["Reach the Hall of the Gods at (H-5) and examine the Cermet Grate twice."] = "(H-5)の神々の間へ進み、格子戸（Cermet Grate）を2回調べる。",
    ["The Hall of the Gods"] = "神々の間",
    ["Return to Norg after reaching the sealed grate in the Hall of the Gods."] = "神々の間の閉ざされた格子戸を確認したら、ノーグへ戻る。",
    ["Open Oaken Door (K-8) and speak with Gilgamesh (L-8) about the Mithra carrying a mysterious crystal."] = "Oaken Door(K-8)を開け、Gilgamesh(L-8)から不思議なクリスタルを持つミスラの話を聞く。",
    ["The Mithra and the Crystal"] = "ミスラとクリスタル",
    ["Key Item: Cerulean crystal"] = "だいじなもの：青水晶",
    ["Travel to Rabao."] = "ラバオへ向かう。",
    ["Speak with Maryoh Comyujah (G-7) at (G-7) and choose the top dialogue option."] = "Maryoh Comyujah(G-7)に話し、一番上の選択肢を選ぶ。",
    ["Enter Quicksand Caves through the secret entrance in Western Altepa Desert at (C/D-11)."] = "西アルテパ砂漠(C/D-11)の隠し通路から流砂洞に入る。",
    ["Reach Weighted Door (K-8) at (K-8) and use the pressure plate to pass through."] = "(K-8)の重量扉へ行き、重量床を使って通過する。",
    ["Reach Weighted Door (G-8) at (G-8), pass through, and drop into the lower room."] = "(G-8)の重量扉を通過し、下の部屋へ落ちる。",
    ["Examine ??? near the landing area and choose Yes to spawn Ancient Vessel."] = "着地点付近の ??? を調べ「はい」を選んで Ancient Vessel を出現させる。",
    ["Defeat Ancient Vessel."] = "Ancient Vessel を倒す。",
    ["Examine ??? near the landing area again to obtain the Scrap of Papyrus."] = "着地点付近の ??? を再び調べ、パピルスの切れ端を入手する。",
    ["Return to Rabao and speak with Maryoh Comyujah (G-7) again to receive the Cerulean crystal."] = "ラバオへ戻り、Maryoh Comyujah(G-7)に話して青水晶を受け取る。",
    ["Travel to the Hall of the Gods and examine Cermet Gate in the Hall of the Gods to pass through the gate."] = "神々の間へ行き、Cermet Gate を調べて扉を抜ける。",
    ["Proceed down the hallway and examine the Shimmering Circle."] = "通路を進み、Shimmering Circle を調べる。",
    ["The Gate of the Gods"] = "神の扉トゥー・リア",
    ["Access to Tu'Lia"] = "トゥー・リアへの移動が可能に",
    ["Return to the Hall of the Gods and examine Cermet Gate in the Hall of the Gods again."] = "神々の間へ戻り、再び Cermet Gate を調べる。",
    ["Pass through the gate and continue to the shimmering light at the far end."] = "扉を抜け、奥の光まで進む。",
    ["Examine the shimmering light."] = "光を調べる。",
    ["Zone into Ru'Aun Gardens to unlock access to Tu'Lia."] = "ル・オンの庭へエリアチェンジし、トゥー・リアへの道を開く。",
    ["Ark Angels"] = "アーク・ガーディアン",
    ["Key Items: Shard of Apathy, Shard of Arrogance, Shard of Cowardice, Shard of Envy, Shard of Rage; one of: Abyssal Earring, Beastly Earring, Bushinomimi, Knight's Earring, Suppanomimi"] = "だいじなもの：無知のかけら、驕慢のかけら、怯懦のかけら、嫉妬のかけら、憎悪のかけら／いずれか1つ：Abyssal Earring、Beastly Earring、Bushinomimi、Knight's Earring、Suppanomimi",
    ["Zone into Ru'Aun Gardens."] = "ル・オンの庭へエリアチェンジする。",
    ["Enter the Shrine of Ru'Avitau."] = "ル・アビタウ神殿に入る。",
    ["To face all five Ark Angels at once, examine Blank target (H-11) twice, then obtain an Ark Pentasphere."] = "5体同時に挑む場合は、(H-11)の対象を2回調べて Ark Pentasphere を入手する。",
    ["Use the red portals in Ru'Aun Gardens to reach the five La'Loff Amphitheater battlefields."] = "ル・オンの庭の赤いポータルから、5か所のラ・ロフの劇場のバトルフィールドへ向かう。",
    ["Defeat Ark Angel HM, Ark Angel TT, Ark Angel MR, Ark Angel EV, and Ark Angel GK."] = "Ark Angel HM・Ark Angel TT・Ark Angel MR・Ark Angel EV・Ark Angel GK を倒す。",
    ["Alternatively, use the Ark Pentasphere at La'Loff Amphitheater and defeat all five Ark Angels in the same battle."] = "または、ラ・ロフの劇場で Ark Pentasphere を使い、5体を同じ戦闘で倒す。",
    ["The Sealed Shrine"] = "閉ざされし門",
    ["Speak with Gilgamesh (L-8)."] = "Gilgamesh(L-8)に話す。",
    ["Return to Ru'Aun Gardens."] = "ル・オンの庭へ戻る。",
    ["Enter Shrine of Ru'Avitau."] = "ル・アビタウ神殿に入る。",
    ["The Celestial Nexus"] = "宿星の座",
    ["Enter Shrine of Ru'Avitau from Ru'Aun Gardens at (I-6)."] = "ル・オンの庭(I-6)からル・アビタウ神殿に入る。",
    ["Pass through the first yellow door at (J-7), then continue west through the second yellow door to reach the room with the two Monoliths at (H-7)."] = "(J-7)の1つ目の黄色い扉を抜け、西の2つ目の黄色い扉を通って(H-7)のモノリスが2つある部屋へ。",
    ["Continue south around the square hallway to the room with the two Dark Elementals around (H-10)."] = "四角い通路を南へ回り、(H-10)付近のダークエレメンタルが2体いる部屋へ。",
    ["Go north and descend the stairs to Celestial Nexus (H-9) at (H-9)."] = "北へ進み、階段を下りて(H-9)の宿星の座へ。",
    ["Enter the battlefield and defeat Eald'narche."] = "バトルフィールドに入り、Eald'narche を倒す。",
    ["Awakening"] = "1万年の夢の終わりに",
    ["Enter Norg and speak with Gilgamesh (L-8)."] = "ノーグに入り、Gilgamesh(L-8)に話す。",
    ["If the opening dialogue does not occur, proceed to the Captain's Chamber and speak with Gilgamesh (L-8) there."] = "最初の会話が起きない場合は、Captain's Chamber へ進みそこで Gilgamesh(L-8)に話す。",
    ["Examine Neptune's Spire Inn door (J-8) in Lower Jeuno to speak with Aldo."] = "ジュノ下層・天晶堂奥の扉(J-8)を調べ、Aldo と話す。",
    ["Complete both conversations before zoning into Ru'Lude Gardens."] = "ル・ルデの庭へエリアチェンジする前に、両方の会話を済ませる。",
    ["The Last Verse"] = "すべての終わりが閉ざされん",
    ["The Last Verse is recorded after completing Apocalypse Nigh."] = "クエスト「世界に在りて君は何を想うのか？」のクリア後に記録される。",
    ["Welcome t'Norg"] = "海賊の巣窟ノーグ",
    ["Enter Oaken Door (L-8)."] = "Oaken Door(L-8)に入る。",
    ["Kazham's Chieftainess"] = "カザム族長",
    ["Key Item: Sacrificial Chamber key"] = "だいじなもの：生贄の間へのカギ",
    ["Travel to Kazham."] = "カザムへ向かう。",
    ["Speak with Jakoh Wahcondalo (J-9) at (J-9) to receive the Sacrificial Chamber key."] = "Jakoh Wahcondalo(J-9)に話し、生贄の間へのカギを受け取る。",
    ["The Temple of Uggalepih"] = "ウガレピ寺院",
    ["Key Item: Dark fragment"] = "だいじなもの：闇の祈り",
    ["Travel to the Temple of Uggalepih and make your way to the Den of Rancor."] = "ウガレピ寺院を抜けて怨念洞へ向かう。",
    ["Use the Den of Rancor Home Point or Unity Warp if available. Otherwise, enter through the Temple of Uggalepih and use the Paintbrush of Souls route."] = "開通していれば怨念洞の Home Point かユニティワープを使う。なければウガレピ寺院から Paintbrush of Souls のルートで進む。",
    ["Obtain an Unlit Lantern unless another player can open the Rancor door for you."] = "他のプレイヤーに怨念洞の扉を開けてもらえない場合は Unlit Lantern を入手する。",
    ["Trade the Unlit Lantern to the Altar of Rancor for a Rancor Flame, then use it to light the four lanterns outside the Sacrificial Chamber. Repeat as needed."] = "Altar of Rancor に Unlit Lantern をトレードして怨みの炎を得て、生贄の間前の4つのランタンに灯す。必要なら繰り返す。",
    ["Enter the Sacrificial Chamber."] = "生贄の間に入る。",
    ["Enter the battlefield and defeat Grav'iton, Molyb'iton, and Tungs'iton."] = "バトルフィールドに入り、Grav'iton・Molyb'iton・Tungs'iton を倒す。",

    -- ============================================================
    -- Chains of Promathia missions. Titles: https://wiki.ffo.jp/html/278.html ;
    -- per-mission pages in docs/sources_zilart_cop.tsv . Unverified JA names
    -- for items/objects/NPCs stay English.
    -- ============================================================
    ["Ancient Flames Beckon"] = "誘うは古のほむら",
    ["The Rites of Life"] = "命の洗礼",
    ["Key Item: Mysterious amulet"] = "だいじなもの：不思議なアミュレット",
    ["Enter Lower Delkfutt's Tower in Qufim Island."] = "クフィム島のデルクフの塔下層に入る。",
    ["Travel to Upper Jeuno."] = "ジュノ上層へ向かう。",
    ["Speak with Monberaux (G-10) in the Infirmary at (G-10)."] = "(G-10)の医務室で Monberaux に話す。",
    ["Receive the Mysterious Amulet."] = "不思議なアミュレットを受け取る。",
    ["Below the Arks"] = "楼閣の下に",
    ["Access to Promyvions"] = "プロミヴォンへの移動が可能に",
    ["Travel to Ru'Lude Gardens and speak with Pherimociel at (G-6) in the Grand Duke's Palace."] = "ル・ルデの庭の大公宮(G-6)で Pherimociel に話す。",
    ["Visit the three Halls of Transference and enter Promyvion-Dem, Promyvion-Mea, and Promyvion-Holla in any order."] = "3つの転移の間を訪れ、プロミヴォン-デム・メア・ホラに好きな順番で入る。",
    ["Examine Large Apparatus when entering a Promyvion for the first time."] = "初めてプロミヴォンに入るときは Large Apparatus を調べる。",
    ["Progress through the Promyvions by defeating Memory Receptacles and following the Memory Stream portals."] = "Memory Receptacle を倒し、Memory Stream のワープを使ってプロミヴォンを進む。",
