    ["Defeat Procreator, Cumulator, and Agonizer."] = "Procreator・Cumulator・Agonizer を倒す。",
    ["Three Paths"] = "みっつの道",
    ["Travel to Bastok Metalworks and speak with Cid (H-8). Complete the three paths in any order."] = "大工房の Cid(H-8)に話す。3つのルートは好きな順番で進められる。",
    ["Past Sins: travel to Tavnazian Safehold and speak with Despachiaire (K-10) at (K-10), then travel to Windurst Woods and speak with Perih Vashai at (K-7)."] = "汝の罪は：タブナジア地下壕の Despachiaire(K-10)に話し、続いてウィンダス森の区(K-7)の Perih Vashai に話す。",
    ["Travel to Bibiki Bay, reach Purgonorgo Isle, and examine ??? Warmachine (H-11) at (H-11). Speak with Yoran-Oran at (E-5) in Windurst Walls for additional dialogue."] = "ビビキー湾からプルゴノルゴ島へ渡り、(H-11)の ??? Warmachine を調べる。ウィンダス石の区(E-5)の Yoran-Oran からも追加の会話が聞ける。",
    ["Zone into Oldton Movalpolos, then travel to Mine Shaft #2716 and face Chekochuk, Movamuq, Swipostik, Trikotrak, and Bugbby."] = "ムバルポロス旧市街へ入り、2716号採石場で Chekochuk・Movamuq・Swipostik・Trikotrak・Bugbby と戦う。",
    ["Defeat all five opponents, return to Cid (H-8), then travel to Newton Movalpolos and obtain a Gold Key."] = "5体すべてを倒して Cid(H-8)のもとへ戻り、ムバルポロス新市街で黄金のカギを入手する。",
    ["Return to Mine Shaft #2716 and trade the Gold Key to the Shaft Entrance, then return to Cid (H-8)."] = "2716号採石場へ戻って Shaft Entrance に黄金のカギをトレードし、Cid(H-8)のもとへ戻る。",
    ["The Pursuit of Paradise: travel to La Theine Plateau and examine ??? (G-6) at (G-6)."] = "楽園を求めるは：ラテーヌ高原(G-6)の ??? を調べる。",
    ["Enter Pso'Xja through the tower at (J-8) in Beaucedine Glacier, pass through the sixteen Stone Doors, descend the elevator, and examine the Avatar Gate."] = "ボスディン氷河(J-8)の塔からソ・ジヤに入り、16の Stone Door を抜けてエレベーターで降り、Avatar Gate を調べる。",
    ["Travel to Upper Jeuno and speak with Monberaux (G-10) at (G-10) to receive the Envelope, then travel to Ru'Lude Gardens and speak with Pherimociel at (G-6)."] = "ジュノ上層の Monberaux(G-10)に話してモンブローの封筒を受け取り、ル・ルデの庭の Pherimociel(G-6)に話す。",
    ["Return to Upper Jeuno and speak with Monberaux (G-10) again. Enter Batallia Downs and examine the ??? near (K-8) twice to obtain the Delkfutt Recognition Device."] = "ジュノ上層の Monberaux(G-10)へ戻って話す。バタリア丘陵(K-8)付近の ??? を2回調べ、デルクフ解除キーを入手する。",
    ["Enter Lower Delkfutt's Tower, examine the Cermet Door at (H-5), defeat Disaster Idol, and examine the Cermet Door again."] = "デルクフの塔下層(H-5)の Cermet Door を調べて Disaster Idol を倒し、もう一度 Cermet Door を調べる。",
    ["Return to Pso'Xja through the (H-10) entrance in Beaucedine Glacier, follow the right wall to (I-8), pass through the wall, drop down, take the elevator to the Avatar Gate, and examine it before returning to Cid (H-8)."] = "ボスディン氷河(H-10)の入口から再びソ・ジヤに入り、右壁沿いに(I-8)へ。壁を抜けて飛び降り、エレベーターで Avatar Gate へ行って調べたら Cid(H-8)のもとへ戻る。",
    ["Where Messengers Gather: travel to Southern San d'Oria and speak with Hinaree (B-6) at (B-6), then zone into Port San d'Oria and speak with Chasalvige (L-6) in Northern San d'Oria."] = "群れ立つ使者は：南サンドリアの Hinaree(B-6)に話し、サンドリア港へエリアチェンジしてから北サンドリアの Chasalvige(L-6)に話す。",
    ["Travel to Windurst Waters and speak with Kerutoto at (J-8), then speak with Yoran-Oran (E-5) at (E-5) in Windurst Walls."] = "ウィンダス水の区の Kerutoto(J-8)に話し、続いてウィンダス石の区の Yoran-Oran(E-5)に話す。",
    ["Enter Boneyard Gully in Attohwa Chasm and defeat Shikaree X, Shikaree Y, and Shikaree Z."] = "アットワ地溝の千骸谷に入り、Shikaree X・Shikaree Y・Shikaree Z を倒す。",
    ["Travel to Uleguerand Range and enter Bearclaw Pinnacle through the hole at (J-9). Enter the Flames for the Dead battlefield and defeat Snoll Tzar."] = "ウルガラン山脈(J-9)の穴から熊爪嶽へ入り、「迎え火」のバトルフィールドで Snoll Tzar を倒す。",
    ["Use Shu'Meyo Salt during the battle to extend the time available when needed, then return to Cid (H-8) after all three paths are complete."] = "必要に応じて戦闘中に Shu'Meyo Salt を使って時間を稼ぐ。3つのルートを終えたら Cid(H-8)のもとへ戻る。",
