    ["Wait until after Japanese midnight."] = "日本時間の0時を過ぎるまで待つ。",
    ["Travel to Southern San d'Oria and speak with Hinaree (B-6) at (B-6)."] = "南サンドリアへ行き、Hinaree(B-6)に話す。",
    ["Travel to Uleguerand Range for the next event, then return to Southern San d'Oria and approach Count Caffaule's Manor."] = "ウルガラン山脈で次のイベントを見たら南サンドリアへ戻り、Count Caffaule's Manor に近づく。",
