    ["Speak with Naja Salaheem (I-10). and receive the Supplies Package."] = "Naja Salaheem(I-10)と話し、「不滅隊への差し入れ」を受け取る。",
    ["Take the package to any Imperial staging point except Nyzul Isle."] = "ナイズル島以外の監視哨を1か所選び、差し入れを運ぶ。",
    ["At the staging point, speak with the Immortal beside the Runic Portal and deliver the package."] = "監視哨の移送の幻灯付近にいる不滅隊隊士に話しかけ、差し入れを届ける。",
    ["The available staging points are Azouph Isle, Dvucca Isle, Mamool Ja, Halvung, and Ilrusi Atoll."] = "対象はアズーフ島・ドゥブッカ島・マムージャ・ハルブーン・イルルシ環礁の各監視哨。",
    ["Use the Runic Portal to return to Aht Urhgan Whitegate."] = "移送の幻灯(Runic Portal)でアトルガン白門へ戻る。",
    ["Speak with Naja Salaheem (I-10). to complete the mission."] = "Naja Salaheem(I-10)に報告してミッションを終える。",
    ["Leave Aht Urhgan Whitegate and return after completing Immortal Sentries."] = "「不滅の防人」完了後、一度アトルガン白門からエリア移動して戻る。",
    ["Speak with Naja Salaheem (I-10).."] = "Naja Salaheem(I-10)と話す。",
    ["Complete the cutscene to gain access to Assault and the Mog Locker."] = "イベントを見て、アサルトとモグロッカーの案内を受ける。",
    ["Travel to Nashmau and speak with Cacaroon (G-11).."] = "Cacaroon(G-11)と話す。【Wikiとの差異】原文はナシュモとなっているが、日本語Wikiではアトルガン白門(G-11)。",
    ["Give Cacaroon either 1,000 gil or one Imperial Bronze Piece."] = "Cacaroonに1,000ギルまたはアトルガン青銅貨1枚をトレードする。",
    ["Travel to Walahra Temple and continue to the Shararat Teahouse."] = "ワラーラ寺院へ行き、続いて茶屋シャララトへ向かう。",
    ["Complete the events there and continue through the resulting cutscenes."] = "現地での一連のイベントを見る。",
    ["Travel to Chateau d'Oraguille in San d'Oria."] = "サンドリアのドラギーユ城へ向かう。",
    ["Speak with Halver (I-9).."] = "Halver(I-9)と話す。",
    ["Deliver Raillefal's letter and complete the royal event."] = "ライファルの書状を届け、城でのイベントを見る。",
    ["Travel to Aht Urhgan Whitegate and enter the Palace."] = "宮殿入口でイベントを見る。【Wikiとの差異】原文はアトルガン白門だが、日本語Wikiの「東風」はル・ルデの庭(H-7)の大公宮入口。",
    ["Choose the affirmative response when asked for assistance."] = "協力を求められたら肯定の返答を選ぶ。",
    ["Receive 10 Imperial Bronze Pieces."] = "アトルガン青銅貨10枚を受け取る。",
    ["Travel to the Shararat Teahouse."] = "茶屋シャララトへ向かう。",
    ["Complete the cutscene."] = "イベントを見る。",
    ["Return to Naja Salaheem (I-10).."] = "Naja Salaheem(I-10)のもとへ戻る。",
    ["Leave Aht Urhgan Whitegate and return after the required transition."] = "必要な進行条件を満たしてから、アトルガン白門を出入りする。",
    ["Speak with Naja Salaheem (I-10). to continue the mercenary storyline."] = "Naja Salaheem(I-10)付近でイベントを進める。【Wiki補足】「傭兵のつとめ」はエリア移動後、Abquhbah(I-10)に近づくと進行する。",
    ["If the Nyzul Isle staging point is not yet accessible, trade one Imperial Silver Piece to Kamih Mapokhalam in Bhaflau Thickets (F-6) to open the route."] = "ナイズル島監視哨が未開通なら、バフラウ段丘(F-6)のKamih Mapokhalamにアトルガン白銀貨1枚をトレードして遺跡への通路を使う。",
    ["Travel to the Alzadaal Undersea Ruins through Bhaflau Thickets."] = "バフラウ段丘からアルザダール海底遺跡群へ向かう。",
    ["Reach the Gilded Doors at (H-8) and trigger the cutscene."] = "(H-8)のGilded Doors付近に進んでイベントを見る。",
    ["Proceed through the ruins and reach the Nyzul Isle staging point."] = "遺跡を進み、ナイズル島監視哨に到達する。",
    ["If the staging point was just unlocked, return to Aht Urhgan Whitegate and use the Runic Portal to reach Nyzul Isle."] = "監視哨を新たに開通させた場合は、アトルガン白門へ戻り、移送の幻灯からナイズル島へ移動する。",
    ["Take the transport device at (H-9), then use the eastern transport device to enter the Alzadaal Undersea Ruins."] = "(H-9)の転送装置を使い、続いて東側の転送装置からアルザダール海底遺跡群へ進む。",
    ["Complete the scouting event upon entering the ruins."] = "遺跡へ入った際の巡視イベントを見る。",
    ["Return to Aht Urhgan Whitegate."] = "アトルガン白門へ戻る。",
    ["Wait until the next Vana'diel day before continuing."] = "次のヴァナ・ディール日付になるのを待つ。",
    ["After the required Vana'diel day has passed, leave the area and return to Aht Urhgan Whitegate."] = "ヴァナ・ディール日付をまたいでエリア移動し、アトルガン白門へ戻る。",
    ["After the required Vana'diel day has passed, return to Aht Urhgan Whitegate."] = "必要なヴァナ・ディール日付の経過後、アトルガン白門へ戻る。",
    ["Travel to Nashmau and speak with Pyopyoroon (H-7).."] = "ナシュモへ行き、Pyopyoroon(H-7)と話す。",
    ["Obtain Jody's Acid from Ameretats in Bhaflau Thickets or Wajaom Woodlands."] = "バフラウ段丘またはワジャーム樹林のAmeretatなどから「ジョディの消化液」を入手する。",
    ["Trade Jody's Acid to Pyopyoroon (H-7).."] = "Pyopyoroon(H-7)にジョディの消化液をトレードする。",
    ["Complete the resulting event and receive the Vial of Spectral Scent."] = "イベントを見て、だいじなもの「ピョピョルン特製招魂香」を受け取る。",
    ["Travel to Caedarva Mire through the western exit of Nashmau."] = "ナシュモの西口からカダーバの浮沼へ向かう。",
    ["Reach Jazaratt's Headstone. at (E-10)."] = "(E-10)の墓石Jazaraat's Headstoneへ向かう（原文表記はJazaratt's Headstone）。",
    ["Examine the headstone to begin the event."] = "墓石を調べ、イベントを見る。",
    ["Examine the headstone again to face Jazaraat."] = "もう一度墓石を調べ、Jazaraatとの戦闘を開始する。",
    ["Defeat Jazaraat."] = "Jazaraatを倒す。",
    ["Examine the headstone a third time to receive the Ephramadian Gold Coin."] = "再び墓石を調べ、だいじなもの「イフラマド金貨」を入手する。",
    ["Travel through Caedarva Mire and enter Arrapago Reef."] = "カダーバの浮沼を通ってアラパゴ暗礁域へ入る。",
    ["Approach Cutter. at (H-8)."] = "(H-8)のCutterに近づく。",
    ["Complete the opening event."] = "開始時のイベントを見る。",
    ["Enter The Black Coffin battlefield."] = "バトルフィールド「漆黒の柩」に入る。",
    ["Defeat the Ashu Talif Captain."] = "Ashu Talif Captainと戦う（決着条件は次の手順を参照）。",
    ["Reduce the Ashu Talif Captain to 20% HP or below to complete the battle."] = "原文の目安ではAshu Talif CaptainのHPを20%以下にすると戦闘終了。実際のサーバーの勝利条件に従う。",
    ["Speak with Naja Salaheem (I-10). and prepare for the palace visit."] = "Naja Salaheem(I-10)と話し、皇宮への参内を準備する。",
    ["Equip an accepted chest piece for the ceremony."] = "参内に認められる胴装備を着用する。",
    ["Equip gloves, leg armor, and boots as well."] = "両手・両脚・両足の装備も着用する（原文の手順。Wikiでは頭装備も含めて確認）。",
    ["Return to Naja Salaheem (I-10). after changing your equipment."] = "装備を整えてNaja Salaheem(I-10)のもとへ戻る。",
    ["Approach Imperial Gate Door. to enter the palace event."] = "皇宮の門Imperial Whitegateを調べ、参内のイベントを見る（原文表記はImperial Gate Door）。",
    ["Enter Aydeewa Subterrane from Wajaom Woodlands."] = "ワジャーム樹林からエジワ蘿洞へ入る。",
    ["Reach Map 5 and enter the room containing the large tree root."] = "マップ5の大きな木の根がある部屋へ進む。",
    ["Examine blank target.."] = "名前のないターゲット「＿」を調べる。",
    ["Return to Salaheem's Sentinels."] = "サラヒム・センチネルへ戻る。",
    ["Speak with Salaheem's Sentinels.."] = "サラヒム・センチネルに入り、イベントを進める。",
    ["Travel to Mount Zhayolm."] = "ゼオルム火山へ向かう。",
    ["Reach the Navukgo Execution Chamber."] = "ナバゴ処刑場へ向かう。",
    ["Examine Decorative Bronze Gate. to enter the battlefield."] = "Decorative Bronze Gateを調べ、イベント後にバトルフィールドへ入る。",
    ["Defeat Khimaira 13."] = "Khimaira 13を倒す。",
    ["Keep Karababa alive throughout the battle."] = "戦闘中はKarababaを戦闘不能にしない。",
    ["Wait until the required transition has passed before continuing."] = "次へ進むためのエリア移動・日付経過などの条件を満たす。",
    ["Leave the area and return to Salaheem's Sentinels after the required transition."] = "必要な条件を満たしてエリア移動し、サラヒム・センチネルへ戻る。",
    ["Receive five Imperial Gold Pieces."] = "アトルガン黄金貨5枚を受け取る。",
    ["Return to Naja Salaheem (I-10). after the required transition."] = "必要な日付経過・エリア移動の後、Naja Salaheem(I-10)のもとへ戻る。",
    ["Choose Aphmau when prompted."] = "選択肢が出たらAphmauを選ぶ（原文の指定。Wikiでは選択肢による大差はない）。",
    ["Remove your weapon and shield."] = "武器と盾を外す（原文の手順。「魔蛇の封蝋」はWikiではメイン武器を外せばよい）。",
    ["Examine Imperial Gate Door.."] = "皇宮の門Imperial Whitegateを調べる（原文表記はImperial Gate Door）。",
    ["Travel to Walahra Temple."] = "ワラーラ寺院へ向かう。",
    ["Choose the second dialogue option."] = "2番目の選択肢を選ぶ（原文の指定）。",
    ["Travel to Jade Sepulcher through the Mamool Ja staging point."] = "マムージャ監視哨を経由して翡翠廟へ向かう。",
    ["Examine Ornamental Door.."] = "Ornamental Doorを調べる。",
    ["Examine the door again to enter the battlefield."] = "もう一度扉を調べ、バトルフィールドへ入る。",
    ["Defeat Lancelord Gaheel Ja."] = "Lancelord Gaheel Jaを倒す。",
    ["Enter Arrapago Reef."] = "アラパゴ暗礁域へ入る。",
    ["Complete the opening cutscene."] = "冒頭のイベントを見る。",
    ["Complete the following cutscene to obtain the Periqia Assault access."] = "続くイベントを見て、だいじなもの「アサルト領域特別通行許可証・ペリキア」を入手する。",
    ["Travel to the Dvucca Isle staging point in Caedarva Mire."] = "カダーバの浮沼のドゥブッカ島監視哨へ向かう。",
    ["Enter Periqia through the Runic Seal beside the staging point."] = "監視哨付近の秘封(Runic Seal)からペリキアのバトルフィールドへ入る。",
    ["Defeat the K23H1-LAMIA gathered around (H-9)."] = "(H-9)付近のK23H1-LAMIAを倒す。",
    ["Continue defeating the Lamia until the battle ends."] = "ラミアを倒して戦闘を終える。日本語Wikiでは3体の撃破でクリア。",
    ["Complete the cutscene after winning the battle."] = "勝利後のイベントを見る。",
    ["If the battle is failed, return after one Vana'diel day and obtain another permit from Nahshib."] = "敗北時はNahshibから許可証を再発行してもらう。原文はヴァナ日付経過を指定するが、Wikiでは初回の再発行は即時、続けて失敗した場合に日付経過が必要。",
    ["Return to the mission area after the required transition."] = "必要な日付経過・エリア移動の後、ミッションの場所へ戻る。",
    ["Travel to Arrapago Reef."] = "アラパゴ暗礁域へ向かう。",
    ["Approach Cutter.."] = "Cutterに近づく。",
    ["Travel to Talacca Cove."] = "タラッカ入江へ向かう。",
    ["Examine Rock Slab. to enter the battlefield."] = "Rock Slabを調べ、バトルフィールドへ入る。",
    ["Defeat Gessho."] = "Gesshoと戦い、バトルフィールドをクリアする。",
    ["Gessho withdraws after being reduced to approximately 10% HP."] = "原文ではGesshoの残りHP約10%が撤退の目安。実際のサーバーの勝利条件に従う。",
    ["Travel to the Hazhalm Testing Grounds entrance in Caedarva Mire."] = "カダーバの浮沼にあるハザルム試験場の入口へ向かう。",
    ["Examine Entry Gate.."] = "Entry Gateを調べる。",
    ["Complete the resulting cutscene."] = "続くイベントを見る。",
    ["After the required Vana'diel day has passed, travel to the Shararat Teahouse."] = "必要なヴァナ・ディール日付の経過後、茶屋シャララトへ向かう。",
    ["Receive the Allied Council Summons."] = "だいじなもの「四国軍事会議召喚状」を受け取る。",
    ["Enter the Palace and complete the royal cutscene."] = "大公宮に入り、会議のイベントを見る。【Wiki補足】「連合の混迷」の目的地はル・ルデの庭(H-7)。",
    ["After the required transition, travel to Aht Urhgan Whitegate."] = "必要な条件を満たした後、原文ではアトルガン白門へ向かう。【Wikiとの差異】「紐解ける理」はル・ルデの庭の大公宮で進める。",
    ["Speak with Pherimociel.."] = "Pherimocielと話す（日本語Wikiではル・ルデの庭の大公宮1階(G-6)）。",
    ["Speak with Rodin-Comidin (I-7). outside the Automaton Workshop at (I-7)."] = "アトルガン白門(I-7)・2階のRodin-Comidinと話す。",
    ["Prepare for the battle and travel to the Nyzul Isle staging point."] = "戦闘の準備を整え、ナイズル島監視哨へ向かう。",
    ["At the Nyzul Isle staging point, examine blank target. at (J-9)."] = "ナイズル島監視哨(J-9)の名前のないターゲット「＿」を調べる。",
    ["Choose to proceed."] = "先へ進む選択肢を選ぶ。",
    ["Examine Runic Seal. at (I-9) to enter the battlefield."] = "(I-9)の秘封(Runic Seal)を調べ、バトルフィールドへ入る。",
    ["Keep Naja alive throughout the battle."] = "戦闘中はNajaを戦闘不能にしない。",
    ["Defeat the enemies and rescue Luzaf."] = "敵を倒し、Luzafを救出する。",
    ["Travel to the Nyzul Isle staging point."] = "ナイズル島監視哨へ向かう。",
    ["Examine blank target. for the opening event."] = "名前のないターゲット「＿」を調べ、開始イベントを見る。",
    ["Examine Runic Seal. to enter the battlefield."] = "秘封(Runic Seal)を調べ、バトルフィールドへ入る。",
    ["Defeat Raubahn three times as he re-raises twice."] = "Raubahnは2回復活するため、計3回倒す（原文の手順）。",
    ["Continue through the remaining battles of the mission."] = "続く戦闘を進める。",
    ["Complete all three battles within the 45-minute limit."] = "制限時間45分以内に一連の3戦を終える。",
    ["Approach Naja Salaheem (I-10).."] = "Naja Salaheem(I-10)に近づく。",
    ["Equip one of the accepted chest pieces for the imperial ceremony."] = "戴冠式への参内に認められる胴装備を着用する。",
    ["Equip gloves, leg armor, and boots."] = "両手・両脚・両足の装備を着用する。",
    ["Remove all main-hand and off-hand equipment."] = "メインウェポンとサブウェポンをすべて外す。",
    ["Examine Imperial Gate Door. at (L-8)."] = "(L-8)の皇宮の門Imperial Whitegateを調べる（原文表記はImperial Gate Door）。",
    ["Complete the coronation cutscene."] = "戴冠式のイベントを見る。",
    ["Complete the coronation event."] = "戴冠式のイベントを終える。",
    ["Choose one of the three rings: Balrahn's Ring, Jalzahn's Ring, or Ulthalam's Ring."] = "バルラーンリング・ジャルザーンリング・ウルタラムリングから1つを選ぶ。",
    ["Receive the Imperial Standard."] = "皇国旗を受け取る。",
    ["Complete the final cutscene."] = "最後のイベントを見る。",
    ["Receive the Glory Crown."] = "グローリークラウンを受け取る。",
    ["Assault access"] = "アサルト参加権",
    ["Glory Crown"] = "グローリークラウン",
    ["Imperial Bronze Piece x10"] = "アトルガン青銅貨×10",
    ["Imperial Silver Piece x2"] = "アトルガン白銀貨×2",
    ["Imperial Standard; one of: Balrahn's Ring, Jalzahn's Ring, Ulthalam's Ring"] = "皇国旗／バルラーンリング・ジャルザーンリング・ウルタラムリングから1つ",
    ["Key Item: Allied Council Summons"] = "だいじなもの：四国軍事会議召喚状",
    ["Key Item: Astral compass"] = "だいじなもの：魔笛指向儀",
    ["Key Item: Ephramadian gold coin"] = "だいじなもの：イフラマド金貨",
    ["Key Item: Luminian dagger"] = "だいじなもの：輝金の短剣",
    ["Key Item: Mythril mirror"] = "だいじなもの：霊銀の鏡",
    ["Key Item: Nyzul Isle route"] = "だいじなもの：ナイズル島ルートメモ",
    ["Key Item: PSC Wildcat badge; 150 Imperial Standing; Mog Locker access"] = "だいじなもの：山猫二等傭兵バッジ／皇国軍戦績150／モグロッカー利用",
    ["Key Item: Percipient eye"] = "だいじなもの：Percipient eye（原文表記・和名未確認）",
    ["Key Item: Periqia Assault area entry permit"] = "だいじなもの：アサルト領域特別通行許可証・ペリキア",
    ["Key Item: Raillefal's letter"] = "だいじなもの：ライファルの書状",
    ["Key Item: Vial of spectral scent"] = "だいじなもの：ピョピョルン特製招魂香",
    ["Unlocks Ashu Talif Assault"] = "アシュタリフ号関連クエストの参加条件を満たす",
    ["Zone & Day: wait for the next mission"] = "次のミッションへ：エリア移動・日付経過の条件を確認",
    ["Zone & Day: wait for the next mission; Imperial Gold Piece x1"] = "次へのエリア移動・日付経過／アトルガン黄金貨×1",
    ["Zone & Day: wait for the next mission; Imperial Gold Piece x5"] = "次へのエリア移動・日付経過／アトルガン黄金貨×5",
    ["Zone & Day: wait for the next mission; Imperial Mythril Piece; Salvage access"] = "次へのエリア移動・日付経過／アトルガン霊銀貨／サルベージ参加条件",

