    ["Forget Me Not"] = "揺籃の宙",
    ["Pillar of Hope"] = "光陰の御許に",
    ["Glimmer of Life"] = "さかしまの時",
    ["Time Slips Away"] = "霧らふ世界",
    ["When Wills Collide"] = "夢見果てし時",
    ["Whispers of Dawn"] = "映りしは、暁の",
    ["A Dreamy Interlude"] = "瞼に見るもの",
    ["Cait in the Woods"] = "羅針の行方",
    ["Fork in the Road"] = "轍辿りて",
    ["Maiden of the Dusk"] = "翼もつ女神",
    ["Where It All Began"] = "はじまりの地",
    ["A Token of Troth"] = "約束の刻",
    ["Lest We Forget"] = "忘らるる君へ",
    ["Examine one of the three Cavernous Maws:"] = "次の3か所の禁断の口(Cavernous Maw)から1つを調べる。",
    ["Batallia Downs: Cavernous Maw (H-5).."] = "バタリア丘陵：Cavernous Maw(H-5)。",
    ["Rolanberry Fields: Cavernous Maw (H-6).."] = "ロランベリー耕地：Cavernous Maw(H-6)。",
    ["Sauromugue Champaign: Cavernous Maw (J-10)., beyond Banishing Gate #3 in Garlaige Citadel."] = "ソロムグ原野：ガルレージュ要塞の第3魔防門の先にある禁断の口。原文座標は(J-10)だが、日本語Wikiでは(K-9)。",
    ["The first Maw you examine carries you to the past."] = "初めて禁断の口を調べると過去世界へ移動する。調べた場所と到着先が一致するとは限らない。",
    ["After arriving in the past, examine the other two Maws to open their passages between the past and present."] = "過去へ着いたら、ほかの禁断の口も過去側から使い、現代との通路を開通させておく。",
    ["If you leave the past before opening another Maw, return to the first Maw you used."] = "別の口を開通させずに過去から離れた場合、原文では最初に使用した口へ戻る手順。開通状況を確認する。",
    ["Travel to Garlaige Citadel [S], Crawlers' Nest [S], or The Eldieme Necropolis [S]."] = "ガルレージュ要塞〔Ｓ〕・クロウラーの巣〔Ｓ〕・エルディーム古墳〔Ｓ〕のいずれかへ向かう。",
    ["Obtain a recommendation letter from the Allied fortress."] = "連合軍の拠点で推薦状を入手する。",
    ["Choose a nation and enlist with its Allied forces."] = "国を1つ選び、その国の連合軍に入隊する。",
    ["San d'Oria: speak with Mainchelite (I-9). in Southern San d'Oria [S] and complete Gifts of the Griffon and Claws of the Griffon."] = "サンドリア：南サンドリア〔Ｓ〕のMainchelite(I-9)と話し、Gifts of the GriffonとClaws of the Griffonを進める（クエスト名は原文表記）。",
    ["Bastok: speak with Adelbrecht (E-9). in Bastok Markets [S] and complete The Fighting Fourth, Better Part of Valor, and Fires of Discontent."] = "バストゥーク：バストゥーク商業区〔Ｓ〕のAdelbrecht(E-9)と話し、The Fighting Fourth・Better Part of Valor・Fires of Discontentを進める（原文表記）。",
    ["Windurst: speak with Miah Riyuh (H-9). in Windurst Waters [S] and complete Snake on the Plains, The Tigress Stirs, and The Tigress Strikes."] = "ウィンダス：ウィンダス水の区〔Ｓ〕のMiah Riyuh(H-9)と話し、Snake on the Plains・The Tigress Stirs・The Tigress Strikesを進める（原文表記）。",
    ["Your allegiance does not prevent you from helping the other nations."] = "所属国以外の国のクエストにも協力できる。",
    ["After completing one of the three national storylines, examine a Cavernous Maw in the past near Jeuno."] = "必要な過去三国クエストのうち1国分を終え、過去のジュノ近郊にある禁断の口を調べる。",
    ["Present-day Maws surrounding Jeuno can also be used after they have been opened from the past."] = "過去側から開通済みなら、現代のジュノ近郊の禁断の口からも進行できる。",
    ["San d'Oria: complete Boy and the Beast and Wrath of the Griffon."] = "サンドリア：Boy and the BeastとWrath of the Griffonを完了する（原文表記。Wikiの条件は「ちいさな勝利、ひとつの決意」まで）。",
    ["Bastok: complete Light in the Darkness and Burden of Suspicion."] = "バストゥーク：Light in the DarknessとBurden of Suspicionを完了する（原文表記。Wikiの条件は「新たなる猜疑」まで）。",
    ["Windurst: complete Knot Quite There and A Manifest Problem."] = "ウィンダス：Knot Quite ThereとA Manifest Problemを完了する（原文表記。Wikiの条件は「降臨、異貌の徒」まで）。",
    ["After completing one pair of national storylines, enter Southern San d'Oria [S] by walking from East Ronfaure [S]."] = "必要な1国分のクエストを終えたら、東ロンフォール〔Ｓ〕から徒歩で南サンドリア〔Ｓ〕に入る。",
    ["Travel to Southern San d'Oria [S]."] = "南サンドリア〔Ｓ〕へ向かう。",
    ["Examine Lion Springs Tavern door (K-6). at the Lion Springs Tavern."] = "(K-6)のレストラン「獅子の泉」の扉を調べる。",
    ["Speak with Turlough (G-7). in Upper Jeuno."] = "現代のジュノ上層でTurlough(G-7)と話す。",
    ["Return to Lion Springs Tavern door (K-6). and examine the tavern door again."] = "(K-6)の「獅子の泉」へ戻り、再び扉を調べる。",
    ["Travel from Southern San d'Oria [S] to East Ronfaure [S]."] = "南サンドリア〔Ｓ〕から東ロンフォール〔Ｓ〕へ移動する。",
    ["Enter East Ronfaure [S]."] = "東ロンフォール〔Ｓ〕へ入る。",
    ["Travel to Jugner Forest [S]."] = "ジャグナー森林〔Ｓ〕へ向かう。",
    ["Enter La Vaule [S] at (G-11)."] = "(G-11)からラヴォール村〔Ｓ〕へ入る。",
    ["Travel to La Vaule [S]."] = "ラヴォール村〔Ｓ〕へ向かう。",
    ["Reach the Reinforced Gateway at (F-9)."] = "(F-9)のReinforced Gatewayへ向かう。",
    ["Examine the Reinforced Gateway."] = "Reinforced Gatewayを調べる。",
    ["Examine it again to enter the battle against Galarhigg."] = "もう一度調べ、Galarhiggとの戦闘に入る。",
    ["Your buffs are removed upon entering the battlefield, so summon Trusts after entering."] = "突入時に強化が解除されるため、フェイスはバトルフィールドに入ってから呼び出す。",
    ["Defeat Galarhigg."] = "Galarhiggを倒す。",
    ["Bastok: complete Storm on the Horizon and Fire in the Hole."] = "バストゥーク：Storm on the HorizonとFire in the Holeを完了する（原文表記。Wikiの条件は「隠滅の炎」まで）。",
    ["San d'Oria: complete Perils of the Griffon and In a Haze of Glory."] = "サンドリア：Perils of the GriffonとIn a Haze of Gloryを完了する（原文表記。Wikiの条件は「それぞれの死地へ」まで）。",
    ["Windurst: complete When One Man Is Not Enough and In a Haze of Glory."] = "ウィンダス：原文はWhen One Man Is Not EnoughとIn a Haze of Gloryを指定。ただし日本語Wikiで必要なのは「淑女たちの饗宴」までの進行。",
    ["Return to Southern San d'Oria [S]."] = "南サンドリア〔Ｓ〕へ戻る。",
    ["Travel to Southern San d'Oria [S] and speak with Raustigne (I-7).."] = "南サンドリア〔Ｓ〕へ行き、Raustigne(I-7)と話す。",
    ["Travel to Jugner Forest [S] and examine Elegant Footprints (I-6).."] = "ジャグナー森林〔Ｓ〕のElegant Footprints(I-6)を調べる。",
    ["Answer the questions presented there."] = "質問に答える。返答によって要求されるアイテムが変わる場合がある。",
    ["Obtain the requested item: Gold Beastcoin, Lynx Meat, or Nyumomo Doll."] = "指定された獣人金貨・リンクスの肉・ニュモモちゃんのいずれかを用意する。",
    ["Leave the area after obtaining the requested item."] = "指定品を持っている場合も、トレード前に一度エリア移動する。",
    ["Return to Elegant Footprints (I-6). and trade the requested item."] = "Elegant Footprints(I-6)へ戻り、指定されたアイテムをトレードする。",
    ["Travel to Southern San d'Oria [S] and speak with Amaura (G-6).."] = "Amaura(G-6)と話す。【Wikiとの差異】原文は南サンドリア〔Ｓ〕だが、この人物は現代の南サンドリア。",
    ["Obtain a Cernunnos Bulb from Wandering Saplings in Jugner Forest [S] if necessary."] = "必要ならジャグナー森林〔Ｓ〕のWandering Saplingからケルヌンノスの球根を入手する。",
    ["Trade the Cernunnos Bulb to Amaura."] = "Amauraにケルヌンノスの球根をトレードする。",
    ["Travel to Jugner Forest [S] and trade the bulb to Humus-rich Earth (E-6).."] = "過去のジャグナー森林〔Ｓ〕にあるHumus-rich Earth(E-6)へ球根をトレードする。",
    ["Travel to present-day Jugner Forest and examine Humus-rich Earth (E-6). to spawn Cernunnos."] = "現代のジャグナー森林に戻り、Humus-rich Earth(E-6)を調べてCernunnosを出現させる。",
    ["Defeat Cernunnos."] = "Cernunnosを倒す。",
    ["Examine Humus-rich Earth (E-6). again to obtain Cernunnos Resin."] = "Humus-rich Earth(E-6)を再度調べ、だいじなもの「ケルヌンノスの樹脂」を入手する。",
    ["After the required interval has passed, change zones and return to Amaura (G-6).."] = "必要な日付経過とエリア移動の後、Amaura(G-6)のもとへ戻る。",
    ["Speak with Amaura again to receive the Bottle of Treant Tonic."] = "Amauraと再び話し、だいじなもの「鎮静薬」を受け取る。",
    ["Speak with Raustigne (I-7).."] = "Raustigne(I-7)と話す。",
    ["Travel to Bastok Markets [S]."] = "バストゥーク商業区〔Ｓ〕へ向かう。",
    ["Speak with Radford near the Metalworks."] = "大工房前のRadfordと話す。",
    ["Travel to Windurst Waters [S] and speak with Velda-Galda (K-9).."] = "ウィンダス水の区〔Ｓ〕へ行き、Velda-Galda(K-9)と話す。",
    ["Receive Count Borel's letter."] = "だいじなもの「ボーレル卿の封書」を受け取る。",
    ["Travel to Sauromugue Champaign [S]."] = "ソロムグ原野〔Ｓ〕へ向かう。",
    ["Examine Bulwark Gate (F-6).."] = "Bulwark Gate(F-6)を調べる。",
    ["Receive the Underpass Hatch Key."] = "だいじなもの「ハッチのカギ」を受け取る。",
    ["Choose the first dialogue option."] = "1番目の選択肢を選ぶ（原文の指定）。",
    ["Travel to Batallia Downs [S]."] = "バタリア丘陵〔Ｓ〕へ向かう。",
    ["Examine Underpass Hatch (J-9/K-9).."] = "Underpass Hatch(J-9/K-9境界付近)を調べる。",
    ["Examine it again with the Underpass Hatch Key to enter Everbloom Hollow."] = "ハッチのカギを所持して再度調べ、常花の石窟へ入る。",
    ["Defeat the three beastmen waves."] = "3部隊の獣人を倒す。",
    ["Defeat One-eyed Gwajboj."] = "One-eyed Gwajbojを倒す。",
    ["Receive the Jeunoan Flag."] = "大公国旗を受け取る。",
    ["If there is no room for the flag, retrieve it from the reward object near the battlefield exit."] = "所持品がいっぱいで旗を受け取れなかった場合、入口付近の報酬用「???」から受け取る。",
    ["Complete the required national storyline for your nation."] = "必要な過去三国クエストのうち1国分を進める。",
    ["Enter Southern San d'Oria [S] by walking from East Ronfaure [S]."] = "東ロンフォール〔Ｓ〕から徒歩で南サンドリア〔Ｓ〕に入る。",
    ["Enter Beaucedine Glacier [S]."] = "ボスディン氷河〔Ｓ〕へ入る。",
    ["A Campaign Arbiter provides a convenient route to the area."] = "Campaign Arbiterによる戦績テレポを利用すると現地へ移動しやすい。",
    ["Travel to Beaucedine Glacier [S]."] = "ボスディン氷河〔Ｓ〕へ向かう。",
    ["Visit the five northernmost Pso'Xja towers and examine their Regal Pawprints."] = "北側の魔法塔5か所を巡り、各Regal Pawprintsを調べる。",
    ["Complete the Cait Sith minigame at each tower."] = "各塔でケット・シーのミニゲームをクリアする。",
    ["Cait Sith Ceithir: use the tower around (G-9)."] = "Cait Sith Ceithir：原文では(G-9)付近の塔を指定。",
    ["Cait Sith Aon: use the tower around (H-8)."] = "Cait Sith Aon：原文では(H-8)付近の塔を指定。",
    ["Cait Sith Tri: use the tower around (F-7)."] = "Cait Sith Tri：原文では(F-7)付近の塔を指定。",
    ["Complete the remaining two tower minigames in the required sequence."] = "残る2か所のミニゲームも終える。日本語Wikiでは5か所を回る順番は自由。",
    ["After all five Shadow Bugs have been planted, examine Regal Pawprints (H-10). near the broken tree."] = "5か所すべてに尾行蟲を付けたら、折れた木付近のRegal Pawprints(H-10)を調べる。",
    ["Examine Regal Pawprints (H-9).."] = "Regal Pawprints(H-9)を調べる。",
    ["Examine it again to spawn Count Halphas and four Dark Demons."] = "再度調べ、Count HalphasとDark Demon4体を出現させる。",
    ["Defeat Count Halphas."] = "Count Halphasを倒す。",
    ["Examine Regal Pawprints (H-9). again."] = "Regal Pawprints(H-9)をもう一度調べる。",
    ["Collect the required signatures from NPCs throughout Southern San d'Oria [S]."] = "南サンドリア〔Ｓ〕各所の軍関係者から必要な署名を集める。日本語Wikiでは20名分以上が条件。",
    ["Complete the question-and-answer requirements at the appropriate NPCs."] = "対象NPCのクイズや依頼をこなして署名を得る。",
    ["Return to Raustigne (I-7). with all required signatures."] = "必要な署名を集め、Raustigne(I-7)に提出する。",
    ["Travel to Beaucedine Glacier [S] and examine Regal Pawprints (G-9).."] = "ボスディン氷河〔Ｓ〕のRegal Pawprints(G-9)を調べる。",
    ["Examine the Regal Pawprints again to enter the Everbloom Hollow battlefield."] = "再度Regal Pawprintsを調べ、常花の石窟のミッションに入る。",
    ["The battlefield has a 30-minute time limit."] = "制限時間は30分。",
    ["Proceed northwest while keeping to the right-hand wall."] = "右手の壁に沿って北西へ進む（以降の詳細な経路・座標は原文の案内）。",
    ["Use a Ratstail Explosive on explosive wall (H/I-9).."] = "(H/I-9)の岩盤にネズミ火薬を使う。",
    ["Use another Ratstail Explosive on explosive wall (H-8).."] = "(H-8)の岩盤にもネズミ火薬を使う。",
    ["Defeat the Goblin Reaver."] = "Goblin Reaverを倒す。",
    ["Examine glowing ??? left by Goblin Reaver. to obtain Ratstail Explosives."] = "Goblin Reaverを倒した跡の光る「???」を調べ、ネズミ火薬を拾う。",
    ["Repeat the examination as needed, up to three explosives in your inventory."] = "必要に応じて調べ直す。ネズミ火薬は最大3個まで所持できる。",
    ["Use a Ratstail Explosive on southeast explosive wall (I-9).."] = "南東側(I-9)の岩盤にネズミ火薬を使う。",
    ["Examine dead-end target (J-7).."] = "行き止まりのターゲット(J-7)を調べる。",
    ["Examine it again and place the jar of Firesand."] = "もう一度調べて火薬を設置する（原文の案内。現地の導火線・選択肢を確認）。",
    ["Return to green switch (H-7/I-7 area). and activate the switch."] = "緑色のスイッチ(H-7/I-7付近)へ戻って作動させる。",
    ["Return to dead-end target (J-7). and pass through the opened route."] = "行き止まりのターゲット(J-7)へ戻り、開いた通路を進む。",
    ["Use a Ratstail Explosive on explosive wall (G-8/9).."] = "(G-8/9)の岩盤にネズミ火薬を使う。",
    ["Travel east and use another Ratstail Explosive on explosive wall (I-9).."] = "東へ進み、(I-9)の岩盤にもネズミ火薬を使う。",
    ["Examine blue warp ??? exit. to leave the battlefield."] = "青い渦の出口「???」を調べ、エリアから退去してクリアする。",
    ["Travel north from the Beaucedine Glacier [S] Campaign Arbiter."] = "ボスディン氷河〔Ｓ〕のCampaign Arbiter付近から北へ進む。",
    ["Enter the hole in the ground on the southeast side of the area."] = "原文の案内に従い、南東側の地面の穴へ降りる。Wikiでは(H-7)テンキー3付近の穴を近道として紹介。",
    ["Examine Regal Pawprints (H-7). to warp to Ruhotz Silvermines."] = "Regal Pawprints(H-7)を調べ、ルホッツ銀山へ移動する。",
    ["Defeat Cait Sith Ceithir while keeping Lilisette alive."] = "Lilisetteを戦闘不能にせず、Cait Sith Ceithirを倒す（原文の戦闘手順）。",
    ["After a failed attempt, obtain another Umbra Bug from the Regal Pawprints near the broken tree after the required interval."] = "敗北時は必要な日付経過後、折れた木付近のRegal Pawprintsからだいじなもの「蝕甚蟲」を再入手する。",
    ["Enter Southern San d'Oria [S] from East Ronfaure [S]."] = "東ロンフォール〔Ｓ〕から南サンドリア〔Ｓ〕へ入る。【Wikiとの差異】「現世と隠世と」でこの文が使われる場合、Wikiでは現代の両エリアが正しい。",
    ["Travel to Chateau d'Oraguille and speak with Halver (I-9).."] = "ドラギーユ城へ行き、Halver(I-9)と話す。",
    ["If Halver directs you to Rahal, follow the requested storyline before returning."] = "HalverからRahalのもとへ行くよう言われたら、該当する別クエストの進行を確認してから戻る。",
    ["Travel to Batallia Downs."] = "現代のバタリア丘陵へ向かう。",
    ["Trade a Lilac to Weathered Gravestone (I-10).."] = "Weathered Gravestone(I-10)にライラックをトレードする。",
    ["Enter Xarcabard [S]."] = "ザルカバード〔Ｓ〕へ入る。",
    ["Proceed to Rally Point: Red (F-8).."] = "Rally Point: Red(F-8)へ向かう。",
    ["Proceed to Rally Point: Green (G-9).."] = "Rally Point: Green(G-9)へ向かう。",
    ["Examine Spell-worked Snow.."] = "Spell-worked Snowを調べる。",
    ["Speak with Pesoso inside to begin the three-wave battle."] = "中にいるPesosoと話し、3区画の敵との戦闘を始める。",
    ["Defeat all three waves."] = "3区画の敵をすべて倒す。引き返した先に残った敵も確認する。",
    ["Return to Pesoso."] = "Pesosoのもとへ戻る。",
    ["Proceed to Rally Point: Blue (H-8).."] = "Rally Point: Blue(H-8)へ向かう。",
    ["Speak with Antje at Excavated Snow.."] = "Excavated Snowを調べて中に入り、Antjeと話す。",
    ["Reach all 24 Republic Operatives while maintaining Flee."] = "スプリントまたはとんずら状態を維持しながら、Republic Operative全24人に話しかける。",
    ["Allow each operative to detonate its charge."] = "各隊員の作業が完了するようにする。",
    ["After all 24 charges have detonated, report to Captain Antje."] = "全24人の作業が終わったら、隊長Antjeに報告する。",
    ["Return to Rally Point: Red (F-8).."] = "Rally Point: Red(F-8)へ戻る。",
    ["Proceed from Rally Point: Red (F-8). and enter Castle Zvahl Baileys [S]."] = "Rally Point: Red(F-8)から進み、ズヴァール城外郭〔Ｓ〕へ入る。",
    ["Examine Peculiar Glint (G-7).."] = "Peculiar Glint(G-7)を調べる。",
    ["Examine it again to enter the battlefield against Count Bifrons and four Orcs."] = "再度調べ、Count Bifronsとオーク4体がいる戦闘エリアへ入る。",
    ["Defeat Count Bifrons."] = "Count Bifronsを倒す。",
    ["Examine the Rally Point."] = "Rally Pointを調べる。",
    ["Enter Castle Zvahl Baileys [S]."] = "ズヴァール城外郭〔Ｓ〕へ入る。",
    ["Travel through Castle Zvahl Baileys [S] and Castle Zvahl Keep [S]."] = "ズヴァール城外郭〔Ｓ〕からズヴァール城内郭〔Ｓ〕へ進む。",
    ["Enter Throne Room [S]."] = "王の間〔Ｓ〕へ入る。",
    ["Examine the Throne Room door to enter the battlefield against Aquila and Haudrale."] = "王の間の扉を調べ、AquilaとHaudraleとの戦闘に入る。",
    ["Lilisette joins the battle after approximately three minutes."] = "原文では約3分後にLilisetteが戦闘に加わるとしている。",
    ["Defeat Aquila and Haudrale while keeping Lilisette alive."] = "Lilisetteを戦闘不能にせず、AquilaとHaudraleを倒す。",
    ["Complete the required national objectives for your nation."] = "必要な過去三国クエストのうち1国分の条件を満たす。",
    ["Examine one of the Cavernous Maws:"] = "次の禁断の口から1つを調べる。",
    ["Sauromugue Champaign: Cavernous Maw (J-10).."] = "ソロムグ原野：原文座標(J-10)の禁断の口。日本語Wikiでは(K-9)。",
    ["Use the appropriate Maw to continue."] = "開通状況に合う禁断の口を使って進める。",
    ["Complete Her Memories: Homecoming Queen to obtain the first Large Memory Fragment."] = "「彼女の想ひ出～帰郷」を終え、想ひ出のかけらを1つ得る。",
    ["Complete Her Memories: Of Malign Maladies to obtain the second Large Memory Fragment."] = "「彼女の想ひ出～不治の病」を終え、想ひ出のかけらを1つ得る。",
    ["Complete Her Memories: Operation Cupid to obtain the third Large Memory Fragment."] = "「彼女の想ひ出～キューピッド作戦」を終え、想ひ出のかけらを1つ得る。",
    ["Complete the required national storyline to obtain the fourth Large Memory Fragment."] = "必要な過去三国クエストを進め、4つ目の想ひ出のかけらを得る。",
    ["Return to Cait Sith after obtaining all four Large Memory Fragments."] = "想ひ出のかけら4つをそろえてCait Sithのもとへ戻る。Wikiではジュノ近郊の禁断の口を使って進行。",
    ["Unequip all weapons and your shield."] = "武器と盾をすべて外す。",
    ["Examine Veridical Conflux (F-5).."] = "幽門石Veridical Conflux(F-5)を調べる。",
    ["After the required time has passed, change zones."] = "必要な時間が経過したらエリア移動する。",
    ["Return to Veridical Conflux (F-5).."] = "幽門石Veridical Conflux(F-5)へ戻る。",
    ["Examine the Veridical Conflux again."] = "再びVeridical Confluxを調べる。",
    ["A Punch Bug can be obtained while waiting."] = "待ち時間の間に鑽孔蟲を用意しておくこともできる。",
    ["Obtain a Punch Bug from Lou Carcolhs, Ancient Quadavs, Vajra Quadavs, or Gold Quadavs in Pashhow Marshlands [S] or Beadeaux [S]."] = "パシュハウ沼〔Ｓ〕やベドー〔Ｓ〕のLou Carcolh・Ancient Quadav・Vajra Quadav・Gold Quadavなどから鑽孔蟲を入手する。",
    ["Trade the Punch Bug to Veridical Conflux (F-5). in Grauberg [S]."] = "グロウベルグ〔Ｓ〕のVeridical Conflux(F-5)に鑽孔蟲をトレードする。",
    ["Receive the Bottled Punch Bug."] = "だいじなもの「鑽孔蟲のフラスコ」を受け取る。",
    ["Examine Veridical Conflux (F-5). to enter the Walk of Echoes."] = "Veridical Conflux(F-5)を調べ、ウォークオブエコーズへ入る。",
    ["Examine Ornate Door. north of the Veridical Conflux."] = "幽門石から奥へ進み、Ornate Doorを調べる。",
    ["Examine the Ornate Door again to enter the battlefield."] = "Ornate Doorを再度調べ、バトルフィールドへ入る。",
    ["Defeat the four Spitewardens."] = "冥護四衆を倒す。",
    ["The Bottled Punch Bug is consumed upon entry."] = "突入時に鑽孔蟲のフラスコを消費する。",
    ["After the required time has passed, change zones before examining the Veridical Conflux again."] = "必要な日付経過とエリア移動の後、再びVeridical Confluxを調べる。",
    ["Travel to East Ronfaure [S]."] = "東ロンフォール〔Ｓ〕へ向かう。",
    ["Examine Blank Target (H-7). to obtain the Ronfaure dawndrop."] = "名前のないターゲット「＿」(H-7)を調べ、黎明の雫を入手する。",
    ["The Ronfaure dawndrop is obtained automatically."] = "ロンフォール分の黎明の雫は前節で入手済み。",
    ["Collect the remaining dawndrops:"] = "残りの黎明の雫を集める（各エリアの「＿」を調べる）。",
    ["Blank Target (I-6)."] = "名前のないターゲット「＿」(I-6)。",
    ["Blank Target (K-9)."] = "名前のないターゲット「＿」(K-9)。",
    ["Blank Target (K-6)."] = "名前のないターゲット「＿」(K-6)。",
    ["Blank Target (H-9)."] = "名前のないターゲット「＿」(H-9)。",
    ["Blank Target (F-8)."] = "名前のないターゲット「＿」(F-8)。",
    ["Blank Target."] = "名前のないターゲット「＿」。",
    ["Blank Target south of the conflux."] = "幽門石付近の名前のないターゲット「＿」（原文は南側。Wikiでは幽門石の背後の途切れた階段）。",
    ["After all eight dawndrops have been obtained, they combine into the Primal glow."] = "黎明の雫を8つそろえると、だいじなもの「原初の輝き」になる。",
    ["Defeat Lilith in her first form."] = "第1形態のLilithを倒す。",
    ["Defeat Lilith Ascendant in her second form."] = "第2形態のLilith Ascendantを倒す。",
    ["Examine Lion Springs Tavern door (K-6). to receive the Wedding Invitation key item."] = "(K-6)の「獅子の泉」の扉を調べ、だいじなもの「結婚式招待状」を受け取る。",
    ["Unequip your weapons and shield."] = "武器と盾を外す。",
    ["Examine the Bulwark Gate again."] = "Bulwark Gateをもう一度調べる。",
    ["Receive the mission rewards."] = "ミッション報酬を受け取る。",

    -- ACP/MKD/ASA: wiki.ffo.jp; ambiguous upstream titles intentionally retain English.
    ["A Crystalline Prophecy"] = "石の見る夢",
