    ["Born of Her Nightmares"] = "共鳴 悪夢と失われた頌歌と",
    ["Banishing the Echo"] = "残響を打ち消す者",
    ["Ode of Life Bestowing"] = "天よ聴け 魂の返歌",
    ["A Crystalline Prophecy (Fin.)"] = "石の見る夢＜完＞",
    ["A Moogle Kupo d'Etat"] = "戦慄！モグ祭りの夜",
    ["Drenched! It Began with a Raindrop"] = "ぴちょん！始まりは一滴の雨漏り",
    ["Hasten! In a Jam in Jeuno?"] = "いざゆけ！出張モグハウス",
    ["Welcome! To My Decrepit Domicile"] = "ようこそ！スウィート・モグリハウス",
    ["Curses! A Horrifically Harrowing Hex"] = "恐怖！呪われし悪霊の部屋",
    ["An Errand! The Professor's Price"] = "走れ！解呪の品を求めて",
    ["Shock! Arrant Abuse of Authority"] = "愕然！今日から借金王",
    ["Lender Beware! Read the Fine Print"] = "モグ金！ご利用は計画的に",
    ["Rescue! A Moogle's Labor of Love"] = "焦燥！愛しいあの子はいずこ",
    ["Roar! A Cat Burglar Bares Her Fangs"] = "吠えよ！やとわれ用心棒",
    ["Relief! A Triumphant Return"] = "帰還！ふたりの家路",
    ["Joy! Summoned to a Fabulous Fete"] = "歓喜！モグ祭りへの招待状",
    ["A Challenge! You Could Be a Winner"] = "めざせ！超モグボナンザ抽選会",
    ["Smash! A Malevolent Menace"] = "砕け！邪なる者の野望",
    ["A Moogle Kupo d'Etat (Fin.)"] = "戦慄！モグ祭りの夜＜完＞",
    ["A Shantotto Ascension"] = "シャントット帝国の陰謀",
    ["Burgeoning Dread"] = "不吉な予感",
    ["That Which Curdles Blood"] = "謎の召集令状",
    ["Sugar-coated Directive"] = "甘美なる指令",
    ["Sugar-coated Subterfuge"] = "甘美なる企み",
    ["Shantotto in Chains"] = "囚われのシャントット",
    ["Fountain of Trouble"] = "くじけ！甘美なる陰謀",
    ["Battaru Royale"] = "クローン・タルタル部隊",
    ["Romancing the Clone"] = "ふたりがちからを合わせたら",
    ["Sisters in Arms"] = "ストップ！ダブル・シャントット",
    ["Project: Shantottofication"] = "呪われる世界",
    ["An Uneasy Peace"] = "悪夢去りし後……",
    ["A Shantotto Ascension (Fin)"] = "シャントット帝国の陰謀＜完＞",
    ["Reach level 10."] = "レベル10以上になる。",
    ["Enter Lower Jeuno."] = "ジュノ下層へ入る。",
    ["Examine Tales' Beginning (G-9). to begin A Crystalline Prophecy."] = "Tales' Beginning(G-9)を調べ、「石の見る夢」を始める。",
    ["Collect Seedspall Lux from Orcs in Jugner Forest around (G-11)."] = "ジャグナー森林(G-11)付近のオークから日光の欠片を集める。",
    ["Collect Seedspall Luna from Quadavs in Pashhow Marshlands around (K-10)."] = "パシュハウ沼(K-10)付近のクゥダフから月光の欠片を集める。",
    ["Collect Seedspall Astrum from Yagudos in Meriphataud Mountains around (K-8)."] = "メリファト山地(K-8)付近のヤグードから星彩の欠片を集める。",
    ["Trade all three Seedspalls to ??? (G-6).."] = "3種類の欠片を「???」(G-6)にまとめてトレードする。",
    ["Obtain the Bowl of bland Goblin salad from Goblins in Batallia Downs."] = "バタリア丘陵のゴブリンから、だいじなもの「ゴブリン風サラダ」を入手する。",
    ["Examine ??? (F-5). to face Vegnix Greenthumb."] = "「???」(F-5)を調べ、Vegnix Greenthumbを出現させる。",
    ["Defeat Vegnix Greenthumb to obtain Seedspall Roseum."] = "Vegnix Greenthumbを倒し、赤石の欠片を入手する。",
    ["Obtain the Jug of greasy Goblin juice from Goblins in Rolanberry Fields."] = "ロランベリー耕地のゴブリンから、だいじなもの「ゴブリンジュース」を入手する。",
    ["Examine ??? (D-11). to face Chuglix Berrypaws."] = "「???」(D-11)を調べ、Chuglix Berrypawsを出現させる。原文座標は(D-11)、日本語Wikiでは(E-11)。",
    ["Defeat Chuglix Berrypaws to obtain Seedspall Caerulum."] = "Chuglix Berrypawsを倒し、青石の欠片を入手する。",
    ["Obtain the Chunk of smoked Goblin grub from Goblins in Sauromugue Champaign."] = "ソロムグ原野のゴブリンから、だいじなもの「ゴブリン風燻製」を入手する。",
    ["Examine ??? (I-9). to face Dribblix Greasemaw."] = "「???」(I-9)を調べ、Dribblix Greasemawを出現させる。原文座標は(I-9)、日本語Wikiでは(J-9)。",
    ["Defeat Dribblix Greasemaw to obtain Seedspall Viridis."] = "Dribblix Greasemawを倒し、緑石の欠片を入手する。",
    ["Return to ??? (G-6). with all three Seedspalls."] = "3種類の石の欠片をそろえ、「???」(G-6)へ戻る。",
    ["Afterward, speak with Squintrox Dryeyes (G-8). to receive the Viridian Key."] = "続いてSquintrox Dryeyes(G-8)から緑玉のカギを受け取る手順。日本語Wikiではトリガー3種との交換で、進行の待ち時間に注意。",
    ["Prepare for battle; you must fight without Trusts."] = "フェイスを使えない戦闘に備える。",
    ["Examine ??? (G-6). to begin the battle."] = "「???」(G-6)を調べ、戦闘を始める。",
    ["Defeat six waves of Seed Mandragoras, 30 enemies total."] = "Seed Mandragoraを計30体倒す（原文は6回の出現に区分）。",
    ["Receive the Amber Key when the battle ends."] = "戦闘終了後、黄玉のカギを受け取る。",
    ["Examine ??? (G-6). again."] = "「???」(G-6)を再度調べる。",
    ["Travel to Fei'Yin."] = "フェ・インへ向かう。",
    ["Enter Fei'Yin from Beaucedine Glacier."] = "ボスディン氷河からフェ・インへ入る。",
    ["Collect the nine Seed Afterglows in Fei'Yin:"] = "フェ・イン各所のSeed Afterglowを調べ、9色の光を集める。",
    ["red Seed Afterglow."] = "赤色のSeed Afterglow。",
    ["orange Seed Afterglow."] = "橙色のSeed Afterglow。",
    ["yellow Seed Afterglow."] = "黄色のSeed Afterglow。",
    ["green Seed Afterglow."] = "緑色のSeed Afterglow。",
    ["cerulean Seed Afterglow."] = "水色のSeed Afterglow。",
    ["blue Seed Afterglow."] = "青色のSeed Afterglow。",
    ["golden Seed Afterglow."] = "金色のSeed Afterglow。",
    ["silver Seed Afterglow."] = "銀色のSeed Afterglow。",
    ["white Seed Afterglow."] = "白色のSeed Afterglow。",
    ["You have 12 Vana'diel hours and 30 Vana'diel minutes to collect all nine."] = "原文ではヴァナ時間12時間30分以内に9色すべてを集める指定。現地の制限時間を確認する。",
    ["The Seed Afterglows periodically move within their general areas."] = "Seed Afterglowはそれぞれの区画内を定期的に移動する。",
    ["If the yellow Seed Afterglow is not at its usual location, check the circular room around (H-9)/(I-9)."] = "黄色の光が見つからなければ、(H-9)/(I-9)付近の円形の部屋も探す。",
    ["After collecting all nine, choose the Mark of Seed to continue or the Azure Key to open the level 60 treasure coffer in Lower Jeuno."] = "9色をそろえたら、進行用のシードの紋章か、ジュノ下層の宝箱用の青玉のカギを選ぶ。カギを選ぶとミッション進行に待ち時間が生じる。",
    ["Examine Burning Circle. once."] = "Burning Circleを一度調べる。",
    ["Examine it again to enter the battlefield."] = "再度調べ、バトルフィールドへ入る。",
    ["Defeat Seed Orc, Seed Yagudo, Seed Quadav, and Seed Goblin."] = "Seed Orc・Seed Yagudo・Seed Quadav・Seed Goblinを倒す。",
    ["Anyone seeking the Ivory Key must have a Mark of Seed."] = "白玉のカギを得たい参加者は、シードの紋章を所持しておく。",
    ["Receive the Ivory Key after winning."] = "勝利後、白玉のカギを受け取る。",
    ["Enter the Hall of the Gods through Hall of the Gods entrance.."] = "神々の間の入口から中へ入る。",
    ["If you entered the Hall of the Gods from Ru'Aun Gardens, return to Ro'Maeve and enter the Hall of the Gods again."] = "ル・オンの庭側から神々の間へ入った場合は、ロ・メーヴへ戻って入り直す。",
    ["Travel to Lower Delkfutt's Tower."] = "デルクフの塔下層へ向かう。",
    ["Enter Lower Delkfutt's Tower."] = "デルクフの塔下層へ入る。",
    ["Examine each Seed Fragment to receive the level 30 restriction before collecting the Seed Afterglows in its tower section."] = "各区画のSeed Fragmentでレベル30制限を受けてから、その区画のSeed Afterglowを集める。",
    ["Examine Seed Fragment (H-10).."] = "Seed Fragment(H-10)を調べる。",
    ["Collect Seed Afterglow (J-10).."] = "Seed Afterglow(J-10)を調べ、石を集める。",
    ["Collect Seed Afterglow (H-7).."] = "Seed Afterglow(H-7)を調べ、石を集める。",
    ["Collect Seed Afterglow (I-9).."] = "Seed Afterglow(I-9)を調べ、石を集める。",
    ["Examine Seed Fragment (G-6).."] = "Seed Fragment(G-6)を調べる。",
    ["Collect Seed Afterglow (H-10).."] = "Seed Afterglow(H-10)を調べ、石を集める。",
    ["Collect Seed Afterglow (G-7).."] = "Seed Afterglow(G-7)を調べ、石を集める。",
    ["Collect Seed Afterglow (F-8).."] = "Seed Afterglow(F-8)を調べ、石を集める。",
    ["Collect Seed Afterglow (H-9).."] = "Seed Afterglow(H-9)を調べ、石を集める。",
    ["Collect Seed Afterglow (I-8).."] = "Seed Afterglow(I-8)を調べ、石を集める。",
    ["Collect Seed Afterglow (G-8).."] = "Seed Afterglow(G-8)を調べ、石を集める。",
    ["Examine Seed Fragment (F-7).."] = "Seed Fragment(F-7)を調べる。",
    ["Collect Seed Afterglow (F-10).."] = "Seed Afterglow(F-10)を調べ、石を集める（原文座標）。Wikiの上層10階の石は(G-9)。",
    ["Collect all 12 stone key items, then examine Seed Fragment. to receive the Omnis Stone."] = "だいじなものの石12種をそろえ、Seed Fragmentを調べて「輝ける石」を入手する。",
    ["Examine Qe'Iov Gate., then examine it again to enter the battlefield."] = "Qe'Iov Gateを調べ、イベント後に再度調べてバトルフィールドへ入る。",
    ["Defeat the Seed Crystal."] = "Seed Crystalを倒す。",
    ["Receive the Ebon Key and Prismatic Key."] = "黒玉のカギと虹玉のカギを受け取る。",
    ["Return to Lower Jeuno."] = "ジュノ下層へ戻る。",
    ["Examine Tenshodo Treasure Coffer (J-8). to select your reward."] = "天晶堂のTreasure Coffer(J-8)を調べ、報酬を選ぶ。",
    ["Choose one: Nuevo Coselete, Mirke Wardecors, or Royal Redingote."] = "ヌエボコセレーテ・マルクワルドコル・ロイヤルルダンゴトから1つを選ぶ。",
    ["Only one of the three body armors may be owned at a time."] = "3種類の胴装備は、同時に1つだけ所持できる。",
    ["You can obtain the Atma of Echoes after clearing the scenario."] = "シナリオのクリア後、Atma of Echoesの取得条件を満たす（名称・詳細は原文表記）。",
    ["Enter your home nation Mog House and speak with Moogle.."] = "自国のモグハウスへ入り、Moogleと話す。",
    ["Speak with Moogle. in your home nation Mog House."] = "自国のモグハウスでMoogleと話す。",
    ["Obtain an Orcish Armor Plate from Orcs in Yughott Grotto or King Ranperre's Tomb."] = "ユグホトの岩屋または龍王ランペールの墓でオークの装甲板を入手する。Wikiではランペールの墓の対象はゴブリン。",
    ["Obtain a Quadav Backscale from Quadavs in Palborough Mines."] = "パルブロ鉱山のクゥダフからクゥダフの背甲部品を入手する。",
    ["Obtain a Yagudo Caulk from Yagudos in Giddeus."] = "ギデアスのヤグードからヤグードパテを入手する。",
    ["Return to your home nation Mog House and trade all three items to Moogle. at once."] = "自国のモグハウスへ戻り、3種類をMoogleにまとめてトレードする。",
    ["Examine Inconspicuous Door (H-8). at (H-8)."] = "(H-8)のInconspicuous Doorを調べる。",
    ["Examine Inconspicuous Door (H-8). in Upper Jeuno."] = "ジュノ上層のInconspicuous Door(H-8)を調べる。",
    ["Obtain a Sturdy Metal Strip through mining."] = "採掘で、だいじなもの「鋭い金属片」を入手する。",
    ["Return to Inconspicuous Door (H-8). and trade the Sturdy Metal Strip."] = "Inconspicuous Door(H-8)へ戻り、鋭い金属片を渡す。",
    ["Obtain a Piece of Rugged Tree Bark through logging."] = "伐採で、だいじなもの「硬い樹皮」を入手する。",
    ["Return to Inconspicuous Door (H-8). and trade the Piece of Rugged Tree Bark."] = "Inconspicuous Door(H-8)へ戻り、硬い樹皮を渡す。",
    ["Obtain a Savory Lamb Roast through harvesting."] = "収穫で、だいじなもの「皮付き羊肉の燻製」を入手する。",
    ["Return to Inconspicuous Door (H-8). and trade the Savory Lamb Roast."] = "Inconspicuous Door(H-8)へ戻り、皮付き羊肉の燻製を渡す。",
    ["Travel to Windurst Walls and speak with Shantotto (K-7).."] = "ウィンダス石の区へ行き、Shantotto(K-7)と話す。",
    ["Learn that Shantotto requires a Ripe Starfruit."] = "シャントットから、熟れた星の木の実が必要だと聞く。",
    ["Return to Shantotto (K-7). for instructions concerning the Very Special Cardian in Outer Horutoto Ruins."] = "Shantotto(K-7)から外ホルトト遺跡の特別なカーディアンについて聞く。",
    ["Obtain one or more Orb Key Items from the required Cardians in Outer Horutoto Ruins."] = "外ホルトト遺跡の対象カーディアンを倒し、魔導球を1種類以上入手する。",
    ["The available Orbs are Orb of Batons, Orb of Cups, Orb of Coins, and Orb of Swords."] = "対象はバトン・カップ・コイン・ソードの各魔導球。",
    ["Enter Outer Horutoto Ruins from East Sarutabaruta at (H-3)."] = "東サルタバルタ(H-3)から外ホルトト遺跡へ入る。",
    ["Examine Magical Gizmo. to face the Custom Cardians."] = "Magical Gizmoを調べ、Custom Cardianとの戦闘を始める（ターゲット名は原文表記）。",
    ["Defeat the Custom Cardians."] = "Custom Cardianを倒す。",
    ["With one or two Orbs, fifteen Custom Cardians appear; with three Orbs, ten appear; with all four, five appear."] = "魔導球が1～2種類なら15体、3種類なら10体、4種類すべてなら5体のCustom Cardianが出現する。",
    ["Each participant must carry at least one Orb Key Item before entering the battle."] = "進行する参加者は魔導球を1種類以上所持して戦闘へ入る。",
    ["After the battle, receive the Ripe Starfruit and Peach Coral Key."] = "戦闘後、熟れた星の木の実と桃珊瑚のカギを受け取る。",
    ["Return to Windurst Walls and speak with Shantotto (K-7).."] = "ウィンダス石の区へ戻り、Shantotto(K-7)と話す。",
    ["Pay Shantotto 5,000 gil."] = "Shantottoに5,000ギルを支払う。",
    ["Return to Upper Jeuno and examine Inconspicuous Door (H-8).."] = "ジュノ上層へ戻り、Inconspicuous Door(H-8)を調べる。",
    ["Learn which zone contains the Moldy, worm-eaten chest."] = "泥だらけの木箱が埋まっている指定エリアを確認する。",
    ["Obtain Gysahl Greens and ride a Chocobo in the assigned zone."] = "ギサールの野菜を用意し、指定エリアでチョコボに乗る。",
    ["Follow the Chocobo digging clues until you find the Moldy, worm-eaten chest."] = "チョコボ掘りの方向・距離のヒントを追い、泥だらけの木箱を見つける。",
    ["The chest changes location when you leave the zone."] = "エリア移動すると木箱の場所が変わるので注意する。",
    ["Return to Upper Jeuno and examine Inconspicuous Door (H-8). with the Moldy, worm-eaten chest."] = "泥だらけの木箱を持ってジュノ上層へ戻り、Inconspicuous Door(H-8)を調べる。",
    ["Obtain a Sahagin Key."] = "サハギンのカギを用意する。",
    ["Travel to Sea Serpent Grotto and reach the hidden area around (C-8)."] = "海蛇の岩窟へ向かい、(C-8)付近の隠し通路を通る。",
    ["Examine Shady Sconce (C-8). and examine it again to complete the full event."] = "Shady Sconce(C-8)を調べ、続くイベントも確認する。原文座標は(C-8)、Wikiでは隠し通路の先(C-5)。",
    ["Travel to (J-11) and use the Sahagin Key on Ornamental Door (J-11).."] = "(J-11)のサハギン扉でサハギンのカギを使う。",
    ["Proceed across the bridge to Waterfall Basin (H-6). at (H-6) and examine it."] = "橋を渡り、Waterfall Basin(H-6)を調べる。",
    ["Obtain the Map of the Quicksand Caves."] = "流砂洞地図を入手しておく。",
    ["Enter Quicksand Caves through the hidden southern entrance from Western Altepa Desert at (D-12)."] = "西アルテパ砂漠(D-12)の南側の入口から流砂洞へ入る。",
    ["Speak with Goblin Geologist. to mark nine locations on your map."] = "Goblin Geologistと話し、地図に9か所を記入してもらう。",
    ["Search the marked ??? in the Quicksand Caves and obtain the nine stones."] = "流砂洞の地図に記された「???」を巡り、9種類の石を集める。",
    ["Obtain Stone of Surya."] = "Stone of Suryaを入手する（和名未確認のため原文識別名）。",
    ["Obtain Stone of Chandra."] = "Stone of Chandraを入手する（原文識別名）。",
    ["Obtain Stone of Mangala."] = "Stone of Mangalaを入手する（原文識別名）。",
    ["Obtain Stone of Budha."] = "Stone of Budhaを入手する（原文識別名）。",
    ["Obtain Stone of Brihaspati."] = "Stone of Brihaspatiを入手する（原文識別名）。",
    ["Obtain Stone of Shukra."] = "Stone of Shukraを入手する（原文識別名）。",
    ["Obtain Stone of Shani."] = "Stone of Shaniを入手する（原文識別名）。",
    ["Obtain Stone of Rahu."] = "Stone of Rahuを入手する（原文識別名）。",
    ["Obtain Stone of Ketu."] = "Stone of Ketuを入手する（原文識別名）。",
    ["Return to Goblin Geologist. after collecting all nine stones."] = "9種類の石をそろえてGoblin Geologistのもとへ戻る。",
    ["Receive the Navaratna Talisman."] = "だいじなもの「九曜星の数珠」を受け取る。",
    ["Travel to the Chamber of Oracles and examine Shimmering Circle.."] = "宣託の間へ向かい、Shimmering Circleを調べる。",
    ["Enter the battlefield and face Nanaa Mihgo, Goblin Repossessor, Goblin Intimidator, and Goblin Enforcer."] = "バトルフィールドへ入り、Nanaa Mihgo・Goblin Repossessor・Goblin Intimidator・Goblin Enforcerと戦う。",
    ["Nanaa Mihgo summons either Bopa Greso or Cha Lebagta during the battle."] = "戦闘中にNanaa MihgoがBopa GresoまたはCha Lebagtaを呼び出す（原文の戦術情報）。",
    ["Defeat Nanaa Mihgo to complete the battlefield."] = "Nanaa Mihgoを倒してバトルフィールドをクリアする。",
    ["Receive the Red Coral Key and the following event."] = "紅珊瑚のカギを受け取り、続くイベントを見る。",
    ["Return to Upper Jeuno."] = "ジュノ上層へ戻る。",
    ["Travel to Castle Zvahl Baileys."] = "ズヴァール城外郭へ向かう。",
    ["Enter Castle Zvahl Baileys."] = "ズヴァール城外郭へ入る。",
    ["Travel to Castle Zvahl Baileys and examine Shadowy Pillar (J-8). at (J-8)."] = "ズヴァール城外郭(J-8)のShadowy Pillarを調べる。",
    ["Travel to Beaucedine Glacier and examine Lonely Evergreen (G-7). at (G-7)."] = "ボスディン氷河(G-7)のLonely Evergreenを調べる。",
    ["Travel to the tower around (H-8) and speak with Goblin Grenadier (H-8).."] = "(H-8)付近の塔へ行き、Goblin Grenadierと話す。",
    ["Examine the six Pip objects around the tower and follow the elemental day order to determine the number formed by their connections."] = "塔の周辺6か所のPipを調べ、ヴァナ・ディールの曜日順で属性を結んだ数字を読み取る。",
    ["Give the resulting number to Goblin Grenadier (H-8). to receive the Pocket Mogbomb."] = "Goblin Grenadier(H-8)に数字を答え、だいじなもの「魅惑のきらきら爆弾」を受け取る。",
    ["Return to Lonely Evergreen (G-7). at (G-7) and exchange the Pocket Mogbomb for the Trivia Challenge Kupon."] = "Lonely Evergreen(G-7)へ戻り、きらきら爆弾とヴリトラクイズ参加券を交換する。",
    ["Travel to Xarcabard and answer three trivia questions correctly using the three answer locations: Option One (G/H-8)., Option Two (G-9)., and Option Three (G-8).."] = "ザルカバードでクイズに3回正解する。回答地点はOption One(G/H-8)・Option Two(G-9)・Option Three(G-8)（原文座標）。",
    ["Receive the Gauntlet Challenge Kupon."] = "Gauntlet Challenge Kuponを受け取る（和名未確認のため原文表記）。",
    ["Return to Castle Zvahl Baileys and examine Shadowy Pillar (J-8).."] = "ズヴァール城外郭へ戻り、Shadowy Pillar(J-8)を調べる。",
    ["Enter the gauntlet with your level reduced to 1 and reach Flames of Fate (G-8). at (G-8) before the 8-minute limit expires."] = "レベル1制限で肝試しを始め、原文の制限時間8分以内にFlames of Fate(G-8)へ到達する。",
    ["Receive the Festival Souvenir Kupon at Flames of Fate (G-8).."] = "Flames of Fate(G-8)でFestival Souvenir Kuponを受け取る（和名未確認）。",
    ["Enter Castle Zvahl Keep and examine Ominous Pillar.."] = "ズヴァール城内郭へ入り、Ominous Pillarを調べる。",
    ["Follow the beastmen beacon teleports and examine the Craggy Pillar in each room until you find the correct one."] = "獣人の転送装置を使い、各部屋のCraggy Pillarを調べて正解を探す。",
    ["Examine Craggy Pillar #1.."] = "Craggy Pillar #1を調べる。",
    ["Examine Craggy Pillar #2.."] = "Craggy Pillar #2を調べる。",
    ["Examine Craggy Pillar #3.."] = "Craggy Pillar #3を調べる。",
    ["Examine Craggy Pillar #4.."] = "Craggy Pillar #4を調べる。",
    ["Receive the Mega Bonanza Kupon from the correct Craggy Pillar."] = "正解のCraggy Pillarから、だいじなもの「超モグボナンザ参加券」を受け取る。",
    ["Proceed through the Throne Room and examine the Throne Room door."] = "王の間へ進み、奥の扉を調べる。",
    ["Travel to Castle Zvahl Keep and examine Throne Room door.."] = "ズヴァール城内郭から王の間へ向かい、奥の扉を調べる。",
    ["Examine Throne Room door. again to enter the battlefield."] = "王の間の扉を再度調べ、バトルフィールドへ入る。",
    ["Defeat Riko Kupenreich and his Henchman Moogles."] = "Riko KupenreichとHenchman Moogleたちを倒す（原文の戦術情報）。",
    ["Defeat Riko Kupenreich to complete the battle; his HP is reduced in phases during the fight."] = "段階的に進む戦闘を経てRiko Kupenreichを倒す。",
    ["Receive the Angel Skin Key and Oxblood Key."] = "ボケ珊瑚のカギと血赤珊瑚のカギを受け取る。",
    ["The Mega Bonanza Kupon is consumed upon entry when the battle is used to obtain these keys."] = "カギを得るための突入時には、超モグボナンザ参加券を消費する。",
    ["Travel to Lower Jeuno and enter Tenshodo Headquarters."] = "ジュノ下層の天晶堂へ向かう。",
    ["Examine the Treasure Coffer at (J-8)."] = "Treasure Coffer(J-8)を調べる。",
    ["Use the Angel Skin Key to select your scenario reward."] = "原文ではAngel Skin Keyで最終報酬を選ぶ手順だが、Wikiではボケ珊瑚のカギは背装備等用。最終頭装備には血赤珊瑚のカギを使う。",
    ["Choose one: Champion's Galea, Anwig Salade, or Selenian Cap."] = "ナイトの兜・ダイアの冑・魔人の帽子から1つを選ぶ。",
    ["The Oxblood Key can be used at the same coffer for its separate reward."] = "原文ではOxblood Keyを別報酬用としているが、Wikiでは血赤珊瑚のカギが最終頭装備用。カギを取り違えないよう確認する。",
    ["Completion unlocks the ability to purchase Atma of Dread."] = "クリアによりAtma of Dreadの購入条件を満たす（名称・詳細は原文表記）。",
    ["Enter Windurst Walls from Windurst Woods or Windurst Waters."] = "ウィンダス森の区または水の区から、徒歩でウィンダス石の区へ入る。",
    ["Enter East Sarutabaruta or West Sarutabaruta through one of Windurst's gates."] = "ウィンダスの門から東サルタバルタか西サルタバルタへ出る。",
    ["Complete the cutscene and note which Enfeeblement Kit you are instructed to create."] = "イベントを見て、作成を命じられた呪符キットの種類を確認する。",
    ["Create the Enfeeblement Kit requested during Burgeoning Dread. The required kit is one of Silence, Sleep, Poison, or Blindness."] = "指示された呪符キットを作成する。対象は黙・睡・毒・暗のいずれか。",
    ["If you need the recipe, speak with Kuroido-Moido (E-7). in Port Windurst, or with Faulpie in Southern San d'Oria or Abd-al-Raziq in Bastok Mines."] = "必要ならウィンダス港のKuroido-Moido(E-7)、南サンドリアのFaulpie、バストゥーク鉱山区のAbd-al-Raziqに製法を聞く。",
    ["Gather the required components and synthesize the completed Enfeeblement Kit yourself."] = "材料を集め、自分で合成して呪符キットを完成させる。",
    ["Travel to Qufim Island and trade the completed kit to Trodden Snow (H-7). at (H-7)."] = "クフィム島(H-7)のTrodden Snowに、指定された呪符キットをトレードする。",
    ["After the Qufim Island event, receive six seals."] = "クフィム島のイベント後、ドルチェ特製のお札6種を受け取る。",
    ["Take the seals to their corresponding protocrystals and defeat the avatars."] = "対応する各プロトクリスタルへお札を持っていき、召喚獣を倒す。",
    ["At the Cloister of Flames protocrystal., defeat Ifrit Prime."] = "灼熱の回廊のプロトクリスタルでIfrit Primeを倒す。",
    ["At the Cloister of Frost protocrystal., defeat Shiva Prime."] = "凍結の回廊のプロトクリスタルでShiva Primeを倒す。",
    ["At the Cloister of Gales protocrystal., defeat Garuda Prime."] = "突風の回廊のプロトクリスタルでGaruda Primeを倒す。",
    ["At the Cloister of Storms protocrystal., defeat Ramuh Prime."] = "雷鳴の回廊のプロトクリスタルでRamuh Primeを倒す。",
    ["At the Cloister of Tides protocrystal., defeat Leviathan Prime."] = "海流の回廊のプロトクリスタルでLeviathan Primeを倒す。",
    ["At the Cloister of Tremors protocrystal., defeat Titan Prime."] = "震動の回廊のプロトクリスタルでTitan Primeを倒す。",
    ["Defeat at least three of the six avatars to complete the required progression."] = "6体のうち3体以上を倒し、必要な進行条件を満たす。",
    ["After each victory, examine the corresponding protocrystal again to receive its counterseal."] = "勝利するたびにプロトクリスタルをもう一度調べ、お札を貼って台紙を受け取る。",
    ["Return to Qufim Island and examine Trodden Snow (H-7).."] = "クフィム島へ戻り、Trodden Snow(H-7)を調べる。",
    ["Speak with Andrause (I-8). to receive the Black Book."] = "Andrause(I-8)と話し、黒革の帳面を受け取る。【Wiki補足】指定された海蛇の岩窟の敵3体の封獣板を、1枚ずつ渡す必要がある。",
    ["Travel to Gustav Tunnel."] = "グスタフの洞門へ向かう。",
    ["Examine Outcropping (F-10). at (F-10)."] = "Outcropping(F-10)を調べる。",
    ["Return to Outcropping (F-10). at (F-10)."] = "Outcropping(F-10)へ戻る。",
    ["Examine the Outcropping again to begin the battle."] = "Outcroppingを再度調べ、戦闘を始める。",
    ["Defeat Renfred, Bompupu, and Gorattz. Their clones will continue to appear during the fight."] = "Renfred・Bompupu・Gorattzを倒す。戦闘中は分身も出現する（原文の戦術情報）。",
    ["Trust Magic is unavailable during the battle."] = "この戦闘ではフェイスを使用できない。",
    ["Receive the Cactuar key after defeating all three agents."] = "3人の手下を倒し、サボテンダー座のカギを受け取る。",
    ["Examine Outcropping (F-10). again for the final event."] = "Outcropping(F-10)をもう一度調べ、戦闘後のイベントを見る。",
    ["Enter Tenshodo Headquarters and speak with Aldo (J-8). at (J-8)."] = "天晶堂に入り、Aldo(J-8)と話す。",
    ["Examine Ensorcelled Door (B-10). at (B-10) to learn about the hexagonal depression."] = "Ensorcelled Door(B-10)を調べ、六角形の窪みを確認してから欠片を集める。",
    ["Collect the six Luminous Fragments by defeating the required Notorious Monsters."] = "対象NMを倒し、チップの欠片6種を集める。",
    ["Defeat Lode Golem. around (E-9/E-10) to obtain the Luminous blue fragment."] = "(E-9/E-10)付近のLode Golemを倒し、ブルーチップの欠片を入手する。",
    ["Defeat Fired Urn. around (K-9/K-10) to obtain the Luminous purple fragment."] = "(K-9/K-10)付近のFired Urnを倒し、パープルチップの欠片を入手する。",
    ["Defeat Steely Weapon. around (G-10/G-11) to obtain the Luminous yellow fragment."] = "(G-10/G-11)付近のSteely Weaponを倒し、イエローチップの欠片を入手する（原文座標。WikiではH-11）。",
    ["Defeat Holey Horror. at (H-8) in the Sanctuary of Zi'Tah to obtain the Luminous green fragment."] = "聖地ジ・タ(H-8)のHoley Horrorを倒し、グリーンチップの欠片を入手する。",
    ["Defeat Skeleton Scuffler. at (F-8) in the Sanctuary of Zi'Tah to obtain the Luminous red fragment."] = "聖地ジ・タ(F-8)のSkeleton Scufflerを倒し、レッドチップの欠片を入手する。",
    ["Defeat Blest Bones. at (F-7) in the Sanctuary of Zi'Tah to obtain the Luminous beige fragment."] = "聖地ジ・タ(F-7)のBlest Bonesを倒し、クリアチップの欠片を入手する（原文座標。WikiではF-6）。",
    ["Return to Ensorcelled Door (B-10). after obtaining all six fragments."] = "6種の欠片をそろえ、Ensorcelled Door(B-10)へ戻る。",
    ["Travel to Toraimarai Canal through Inner Horutoto Ruins or Windurst Walls."] = "内ホルトト遺跡またはウィンダス石の区からトライマライ水路へ入る。",
    ["Collect at least one elemental Sap Key Item."] = "だいじなもの「大樹の星屑」を1種類以上集める。",
    ["Obtain the Dark Sap crystal at (F-8), Map 1."] = "マップ1(F-8)で大樹の星屑・闇を入手する。",
    ["Obtain the Earth Sap crystal at (J-8) or (H-7), Map 1."] = "マップ1(J-8)または(H-7)で大樹の星屑・土を入手する（原文の候補地）。",
    ["Obtain the Water Sap crystal at (H-7) or (J-9), Map 1."] = "マップ1(H-7)または(J-9)で大樹の星屑・水を入手する（原文の候補地）。",
    ["Obtain the Fire Sap crystal at (J-9), Map 1, or (F-10)/(J-8), Map 2."] = "マップ1(J-9)、またはマップ2(F-10)/(J-8)で大樹の星屑・火を入手する（原文の候補地）。",
    ["Obtain the Ice Sap crystal at (I-8) or (H-7), Map 2."] = "マップ2(I-8)または(H-7)で大樹の星屑・氷を入手する（原文の候補地）。",
    ["Obtain the Light Sap crystal at (G-8), Map 2; there are two possible positions."] = "マップ2(G-8)付近の候補2か所で大樹の星屑・光を探す。",
    ["Obtain the Lightning Sap crystal at (H-7), Map 1, or (G-10/G-11), Map 2."] = "マップ1(H-7)、またはマップ2(G-10/G-11)で大樹の星屑・雷を入手する（原文の候補地）。",
    ["Obtain the Wind Sap crystal at (H-9) or (J-9), Map 2."] = "マップ2(H-9)または(J-9)で大樹の星屑・風を入手する（原文の候補地）。",
    ["The eight Sap types weaken the corresponding elemental Astral Flow abilities in the next battlefield."] = "8種類の星屑で、次の戦闘の対応属性の敵を弱体できる。原文ではアストラルフロウへの対策として紹介。",
    ["If you only need to advance the story at high level, one Sap is enough."] = "高レベルで物語だけ進める場合も、星屑は最低1種類必要。",
    ["Travel to Full Moon Fountain and examine Moon Spiral. with at least one Sap Key Item."] = "大樹の星屑を1種類以上持って満月の泉へ行き、Moon Spiralを調べる。",
    ["After the Fountain of Trouble event, examine Moon Spiral. again while possessing at least one elemental Sap."] = "「くじけ！甘美なる陰謀」のイベント後、星屑を1種類以上所持した状態でMoon Spiralを再度調べる。",
    ["Enter the Battaru Royale battlefield."] = "バトルフィールド「クローン・タルタル部隊」へ入る。",
    ["Defeat the eight elemental Tarutaru Fomor clones: Boulders, Torrents, Gusts, Flames, Glaciers, Sparks, Lights, and Shadows."] = "土・水・風・火・氷・雷・光・闇の8属性のタルタルのクローンを倒す。",
    ["Each clone can summon the corresponding avatar at around 50% HP and use its Astral Flow."] = "原文では各クローンが残りHP約50%で対応する召喚獣を呼び、アストラルフロウを使うとしている。",
    ["Receive the Chocobo key after victory."] = "勝利後、チョコボ座のカギを受け取る。",
    ["Return to Tenshodo Headquarters in Lower Jeuno."] = "ジュノ下層の天晶堂へ戻る。",
    ["Speak with Aldo (J-8). at (J-8)."] = "Aldo(J-8)と話す。",
    ["Travel through the Temple of Uggalepih to the Den of Rancor and reach the Sacrificial Chamber."] = "ウガレピ寺院から怨念洞を通り、生贄の間へ向かう。",
    ["Obtain at least one Tablet of Hexes to receive credit for the following battlefield. Collecting all 16 grants the full set of battle enhancements."] = "進行には呪いの古代文字が1種類以上必要。16種類すべて集めると各強化効果を得られる。",
    ["Obtain the Tablet of Hexes - Malice."] = "呪いの古代文字を入手する（原文識別名：Malice）。",
    ["Obtain the Tablet of Hexes - Deceit."] = "呪いの古代文字を入手する（原文識別名：Deceit）。",
    ["Obtain the Tablet of Hexes - Envy."] = "呪いの古代文字を入手する（原文識別名：Envy）。",
    ["Obtain the Tablet of Hexes - Greed."] = "呪いの古代文字を入手する（原文識別名：Greed）。",
    ["Obtain the Tablet of Hexes - Pride."] = "呪いの古代文字を入手する（原文識別名：Pride）。",
    ["Obtain the Tablet of Hexes - Bale."] = "呪いの古代文字を入手する（原文識別名：Bale）。",
    ["Obtain the Tablet of Hexes - Strife."] = "呪いの古代文字を入手する（原文識別名：Strife）。",
    ["Obtain the Tablet of Hexes - Regret."] = "呪いの古代文字を入手する（原文識別名：Regret）。",
    ["Obtain the Tablet of Hexes - Dolor."] = "呪いの古代文字を入手する（原文識別名：Dolor）。",
    ["Obtain the Tablet of Hexes - Agony."] = "呪いの古代文字を入手する（原文識別名：Agony）。",
    ["Obtain the Tablet of Hexes - Rancor."] = "呪いの古代文字を入手する（原文識別名：Rancor）。",
    ["Obtain the Tablet of Hexes - Rage."] = "呪いの古代文字を入手する（原文識別名：Rage）。",
    ["Obtain the Tablet of Hexes - Despair."] = "呪いの古代文字を入手する（原文識別名：Despair）。",
    ["Obtain the Tablet of Hexes - Penury."] = "呪いの古代文字を入手する（原文識別名：Penury）。",
    ["Obtain the Tablet of Hexes - Death."] = "呪いの古代文字を入手する（原文識別名：Death）。",
    ["Obtain the Tablet of Hexes - Blight."] = "呪いの古代文字を入手する（原文識別名：Blight）。",
    ["Obtain four Rancor Flames to pass through the Sacrificial Chamber entrance unless its Home Point is already unlocked."] = "生贄の間のホームポイントが未開通なら、入口を通るため怨みの炎4つを用意する（原文の手順）。",
    ["Examine Mahogany Door.."] = "Mahogany Doorを調べる。",
    ["After the event at Mahogany Door., examine the door again."] = "Mahogany Doorのイベント後、再度扉を調べる。",
    ["Enter the Project: Shantottofication battlefield."] = "バトルフィールド「呪われる世界」へ入る。",
    ["Defeat Shantotto and D. Shantotto."] = "ShantottoとD. Shantottoを倒す。",
    ["Any Tablets of Hexes you possess are consumed upon entry and grant battle enhancements."] = "突入時に所持している呪いの古代文字を消費し、対応する強化効果を得る。",
