    ["Speak with Brenton (E-8).."] = "Brenton(E-8)と話す。",
    ["Receive the Pioneer's Badge, Map of Adoulin, and 1,000 Bayld."] = "開拓者バッジ・アドゥリン地図・同盟戦績1,000ベヤルドを受け取る。",
