    ["Return to Brenton (E-8). in the Pioneers' Coalition."] = "パイオニア・ワークスのBrenton(E-8)に報告する。",
    ["Receive the Dinner invitation and access to Wildskeeper Reives."] = "晩餐会への招待状を受け取り、ワイルドキーパー・レイヴへの参加条件を確認する。",
