    ["Enter your home nation after reaching level 3."] = "レベル3以上になり、自国の街へ入る。",
    ["San d'Oria: Southern San d'Oria (H-8), Northern San d'Oria (J-10), or Port San d'Oria (H-9)."] = "サンドリア：南サンドリア(H-8)・北サンドリア(J-10)・サンドリア港(H-9)が導入地点。",
    ["Bastok: Bastok Mines (I-9), Bastok Markets (I-8), or Port Bastok (D-7)."] = "バストゥーク：鉱山区(I-9)・商業区(I-8)・港区(D-7)が導入地点。",
    ["Windurst: Windurst Waters (F-5), Windurst Walls (C-6), Port Windurst (B-5), or Windurst Woods (J-10)."] = "ウィンダス：水の区(F-5)・石の区(C-6)・港区(B-5)・森の区(J-10)が導入地点。",
    ["If the opening event does not occur, examine a Tales' Beginning at one of those locations."] = "導入イベントが発生しない場合は、いずれかの地点のTales' Beginningを調べる。",
    ["Enter Selbina or Mhaura."] = "セルビナまたはマウラへ入る。",
    ["The town you choose determines which path you will follow in Emissary from the Seas."] = "入った町によって「外洋からの使者」の進行ルートが決まる。",
    ["Selbina: speak with Naillina at (F-9) in the Mayor's Residence."] = "セルビナ：町長官邸(F-9)のNaillinaと話す。",
    ["Selbina: choose the first dialogue option, \"You wanted an adventurer?\""] = "セルビナ：最初の選択肢「冒険者を探してる？」を選ぶ。",
    ["Mhaura: speak with Numi Adaligo at (F-9) in the Governor's House."] = "マウラ：総督府(F-9)のNumi Adaligoと話す。",
    ["Mhaura: choose the first dialogue option, \"You're searching for adventurers?\""] = "マウラ：最初の選択肢「冒険者を探してる？」を選ぶ。",
    ["Selbina: obtain 3 Bee Pollen from Huge Wasps in La Theine Plateau or Konschtat Highlands, or purchase them from the Auction House."] = "セルビナ：ラテーヌ高原かコンシュタット高地のHuge Waspから蜂花粉を3個集める。競売でも購入可能。",
    ["Selbina: return to Selbina and trade all 3 Bee Pollen to Abelard."] = "セルビナへ戻り、Abelardに蜂花粉3個をまとめてトレードする。",
    ["Mhaura: obtain 3 Mandragora Dewdrops from Pygmaioi in Tahrongi Canyon, or purchase them from the Auction House."] = "マウラ：タロンギ大峡谷のPygmaioiからマンドラゴラの露を3個集める。競売でも購入可能。",
    ["Mhaura: return to Mhaura and trade all 3 Mandragora Dewdrops to Ekokoko."] = "マウラへ戻り、Ekokokoにマンドラゴラの露3個をまとめてトレードする。",
    ["If your Support Job is not unlocked, the mission awards Gilgamesh's introductory letter instead of a Copper Voucher."] = "サポートジョブ未取得の場合、互助会引換券・銅の代わりにギルガメッシュの紹介状を受け取る。",
    ["Selbina: speak with Pacomart at (H-10) to travel to Norg."] = "セルビナ：Pacomart(H-10)と話し、ノーグへ渡る。",
    ["Selbina: examine Oaken Door (K-8). in Norg."] = "セルビナルート：ノーグのOaken Door(K-8)を調べる。",
    ["Mhaura: speak with Tonasav at (H-9) to travel to Norg."] = "マウラ：Tonasav(H-9)と話し、ノーグへ渡る。",
    ["Mhaura: examine Oaken Door (K-8). in Norg."] = "マウラルート：ノーグのOaken Door(K-8)を調べる。",
    ["Examine Oaken Door (K-8). in Norg again."] = "ノーグのOaken Door(K-8)をもう一度調べる。",
    ["Receive Rhapsody in White."] = "星唄の煌めき【一奏】を受け取る。",
    ["Reach Rank 3 in your home nation."] = "自国のランクを3にする（原文の目安。Wikiでは三国ミッション2-3クリアが条件）。",
    ["Examine a Shattered Telepoint at the Crag of Holla, Dem, or Mea."] = "ホラ・デム・メアの岩のいずれかでShattered Telepointを調べる。",
    ["Choose the Qufim Island response to continue."] = "クフィム島についての選択肢を選んで進む。",
    ["If the relevant rank missions were already completed, speak with Halver at Chateau d'Oraguille (I-9) for Cipher: Halver's Alter Ego."] = "対象の三国ミッションをクリア済みなら、ドラギーユ城(I-9)のHalverと話し、盟-ハルヴァーを受け取る。",
    ["If the relevant rank missions were already completed, speak with Kupipi in Heavens Tower for Cipher: Semih's Alter Ego."] = "対象の三国ミッションをクリア済みなら、天の塔のKupipiと話し、盟-セミを受け取る。",
    ["Travel to Qufim Island and head to Home Point #1 at (G-8)."] = "クフィム島(G-8)のホームポイント#1へ向かう。",
    ["Examine Undulating Confluence (G-8)."] = "Undulating Confluence(G-8)を調べる。",
    ["Return to Home Point #1 at (G-8) in Qufim Island."] = "クフィム島(G-8)のホームポイント#1へ戻る。",
    ["Prepare for the battle and examine Undulating Confluence (G-8)."] = "戦闘の準備を済ませ、Undulating Confluence(G-8)を調べる。",
    ["Defeat Ophiotaurus."] = "Ophiotaurusを倒す。",
    ["After defeating Ophiotaurus, examine Undulating Confluence (G-8). again."] = "Ophiotaurusを倒したら、Undulating Confluence(G-8)を再度調べる。",
    ["Return to the Shattered Telepoint at the Crag of Holla, Dem, or Mea."] = "ホラ・デム・メアの岩のいずれかにあるShattered Telepointへ戻る。",
    ["Examine the Shattered Telepoint."] = "Shattered Telepointを調べる。",
    ["Receive Rhapsody in Umber and Cipher: Lion's Alter Ego II."] = "星唄の煌めき【二奏】と盟-ライオンIIを受け取る。",
    ["Reach Rank 6 in your home nation by completing the required Rank missions through The Shadow Lord."] = "闇王戦までの三国ミッションを進め、ランク6にする（原文の目安。Wikiでは闇の王を倒して闇の破片を得た時点で進行可能）。",
    ["San d'Oria: complete The Shadow Lord."] = "サンドリア：「闇の王を討て！」を進める。",
    ["Bastok: complete Xarcabard, Land of Truths."] = "バストゥーク：「ザルカバードに眠る真実」を進める。",
    ["Windurst: complete The Shadow Awaits."] = "ウィンダス：「最果てにて君を待つ闇」を進める。",
    ["After reaching Rank 6, enter your home nation."] = "ランク6到達後、自国の街へ入る。",
    ["Continue to Norg and examine the Oaken Door if the Rank 6 event does not advance your progression."] = "ランク6のイベントで進まない場合は、ノーグのOaken Doorを調べる。",
    ["Examine Gilgamesh's Oaken Door (K-8). in Norg."] = "ノーグのギルガメッシュの部屋、Oaken Door(K-8)を調べる。",
    ["Travel to (J-12) in Sea Serpent Grotto."] = "海蛇の岩窟(J-12)へ向かう。",
    ["Examine sparkling ??? (J-12).."] = "光る「???」(J-12)を調べる。",
    ["Travel to Yuhtunga Jungle."] = "ユタンガ大森林へ向かう。",
    ["Examine sparkling ??? (F-11). at (F-11)."] = "光る「???」(F-11)を調べる。",
    ["Examine sparkling ??? (F-11). to begin the battle against Siren."] = "光る「???」(F-11)を調べ、Sirenとの戦闘を始める。",
    ["Defeat Siren within 15 minutes."] = "Sirenを15分以内に倒す（原文の制限時間）。",
    ["After the battle, examine sparkling ??? (F-11). again."] = "戦闘後、光る「???」(F-11)をもう一度調べる。",
    ["If you called for help during the battle, wait about one minute and examine the target again."] = "戦闘中に救援要請を使った場合は、原文の目安として約1分待って調べ直す。",
    ["Receive Rhapsody in Azure."] = "星唄の煌めき【三奏】を受け取る。",
    ["Examine Oaken Door (K-8). in Norg."] = "ノーグのOaken Door(K-8)を調べる。",
    ["Receive Cipher: Zeid II."] = "盟-ザイドIIを受け取る。",
    ["Examine Gilgamesh's Oaken Door (K-8). in Norg multiple times."] = "ノーグのギルガメッシュの部屋、Oaken Door(K-8)を繰り返し調べる。",
    ["Enter Gilgamesh's room and speak with him at (K-8)."] = "ギルガメッシュの部屋に入り、(K-8)の本人と話す。",
    ["Complete Chains of Promathia through The Road Forks."] = "プロマシアを「ふたつの道」まで進める（原文の目安。Wikiでは「主のなき都」終了で進行可能）。",
    ["Approach the Palace and Audience Chamber area around (H-7)."] = "(H-7)付近の宮殿・謁見の間へ近づく。",
    ["Travel to Port Jeuno."] = "ジュノ港へ向かう。",
    ["Receive Cipher: Prishe's Alter Ego II."] = "盟-プリッシュIIを受け取る。",
    ["Examine Marble Bridge (F-7). at (F-7)."] = "Marble Bridge(F-7)の扉を調べる。",
    ["Enter Aht Urhgan Whitegate."] = "アトルガン白門へ入る。",
    ["If you do not have access, speak with Faursel in the Tenshodo in Lower Jeuno and obtain Aht Urhgan access."] = "未開通なら、ジュノ下層の天晶堂でFaurselと話し、アトルガンへの渡航手続きを進める。",
    ["Obtain an Aht Urhgan boarding permit through the Tenshodo."] = "天晶堂でアトルガンの渡航免状を入手する。",
    ["Once the permit is obtained, travel to Aht Urhgan Whitegate."] = "渡航免状を得たらアトルガン白門へ向かう。",
    ["Complete the meeting with Tenzen."] = "テンゼンとのイベントを進める。",
    ["If Treasures of Aht Urhgan is complete through Royal Puppeteer, examine Imperial Whitegate (L-9).."] = "アトルガンが「無手の傀儡師」まで進んでいる場合は、Imperial Whitegate(L-9)を調べる。",
    ["If Treasures of Aht Urhgan is not yet complete, continue that storyline until Royal Puppeteer."] = "まだなら、アトルガンの物語を「無手の傀儡師」まで進める。",
    ["If the home-nation event appears during this progression, return there and continue to Aht Urhgan Whitegate afterward."] = "途中で自国のイベントが発生する場合は、先にそちらを見てからアトルガン白門へ戻る。",
    ["Speak with Abquhbah after the event to receive Cipher: Abquhbah."] = "イベント後にAbquhbahと話し、盟-アブクーバを受け取る。",
    ["Continue Treasures of Aht Urhgan until Royal Puppeteer is complete."] = "アトルガンの「無手の傀儡師」を進める（原文の案内。実際の進行可否はアフマウの登場状況にも左右される）。",
    ["Continue into Aphmau's Light when the storyline advances."] = "物語が進んだら「浄化の光」へ続ける。",
    ["Continue Treasures of Aht Urhgan until Aphmau's storyline has advanced far enough for Rhapsodies to proceed."] = "アフマウの物語を、星唄を進行できる段階まで進める。",
    ["Examine Imperial Whitegate (L-9). when directed."] = "指示に従い、Imperial Whitegate(L-9)を調べる。",
    ["Receive Cipher: Nashmeira's Alter Ego II."] = "盟-ナシュメラIIを受け取る。",
    ["Examine Imperial Whitegate (L-9). after Aphmau's return."] = "アフマウの帰還後、Imperial Whitegate(L-9)を調べる。",
    ["Continue the Tenzen and Aphmau events until the next Rhapsodies mission becomes available."] = "次の星唄ミッションが発生するまで、テンゼンとアフマウのイベントを進める。",
    ["Travel to Alzadaal Undersea Ruins."] = "アルザダール海底遺跡群へ向かう。",
    ["Enter through the Chamber of Passage and reach the Nyzul Isle Staging Point."] = "移送の幻灯を使い、ナイズル島監視哨へ向かう。",
    ["Use 200 Imperial Standing to travel to the staging point, or use an Assault tag to enter Nyzul Isle Investigation and reach Alzadaal Undersea Ruins."] = "皇国軍戦績200点で監視哨へ移動するか、アサルトの認識票を使ってナイズル島踏査指令からアルザダール海底遺跡群へ向かう（原文の経路）。",
    ["Enter Alzadaal Undersea Ruins."] = "アルザダール海底遺跡群へ入る。",
    ["Examine Imperial Whitegate (L-9). at the Palace Door."] = "皇宮の扉、Imperial Whitegate(L-9)を調べる。",
    ["Receive Rhapsody in Crimson."] = "星唄の煌めき【四奏】を受け取る。",
    ["Examine the sparkling ??? beside a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign."] = "バタリア丘陵・ロランベリー耕地・ソロムグ原野の禁断の口に隣接する、光る「???」を調べる。",
    ["The corresponding [S] Cavernous Maw locations can also be used."] = "対応する過去〔Ｓ〕側の禁断の口も利用できる。",
    ["The corresponding [S] locations can also be used."] = "対応する過去〔Ｓ〕の地点でも進行できる。",
    ["If Wings of the Goddess has not been started, receive Lightsworm here."] = "アルタナ未開始の場合は、ここで露光蟲を受け取る（原文の案内）。",
    ["If Wings of the Goddess is complete, examine the sparkling ??? beside a Cavernous Maw in Batallia Downs, Rolanberry Fields, or Sauromugue Champaign."] = "アルタナをクリア済みの場合は、ジュノ近郊3エリアの禁断の口に隣接する光る「???」を調べる。後日談クエストの状況にも注意する。",
    ["If Wings of the Goddess is incomplete, progress to at least In the Name of the Father and zone into Southern San d'Oria (S)."] = "アルタナ未クリアの場合は「天涯の娘」まで進め、南サンドリア〔Ｓ〕へ入る（原文の目安）。",
    ["If the Southern San d'Oria (S) event does not occur, first examine the sparkling ??? beside a present-day Cavernous Maw."] = "南サンドリア〔Ｓ〕でイベントが起きなければ、現代の禁断の口に隣接する光る「???」を先に調べる。",
    ["Receive Lightsworm if your Wings of the Goddess progression requires it."] = "アルタナの進行に応じて、露光蟲を受け取る。",
    ["Receive Cipher: Lilisette's Alter Ego II."] = "盟-リリゼットIIを受け取る。",
    ["Enter the Walk of Echoes."] = "ウォークオブエコーズへ入る。",
    ["Reach the top of the stairs and examine Ornate Door.."] = "階段を上がり、Ornate Doorを調べる。",
    ["Continue through the event into Grauberg (S)."] = "イベントを進め、グロウベルグ〔Ｓ〕へ移動する。",
    ["Continue from Grauberg (S) at (F-5) after the previous mission's event."] = "前のイベントに続き、グロウベルグ〔Ｓ〕(F-5)から進める。",
    ["Examine ??? near Witchfire Glen (F-5/H-6 area). to face Cetus."] = "幽境の沢付近(F-5/H-6)の「???」を調べ、Cetusを出現させる（原文の範囲表記）。",
    ["Defeat Cetus."] = "Cetusを倒す。",
    ["Examine ??? near Witchfire Glen (F-5/H-6 area). again."] = "幽境の沢付近(F-5/H-6)の「???」をもう一度調べる。",
    ["Examine the ??? beside Veridical Conflux (F-5). to enter the Walk of Echoes."] = "Veridical Conflux(F-5)に隣接する「???」を調べ、ウォークオブエコーズへ入る。",
    ["Examine Gilgamesh's Oaken Door (K-8).."] = "ギルガメッシュの部屋、Oaken Door(K-8)を調べる。",
    ["Travel to Misareaux Coast (G-5)."] = "ミザレオ海岸(G-5)へ向かう。",
    ["Examine Undulating Confluence (G-5). and the nearby sparkling ???."] = "Undulating Confluence(G-5)と、その近くの光る「???」を調べる。",
    ["Return to Misareaux Coast (G-5)."] = "ミザレオ海岸(G-5)へ戻る。",
    ["Examine the ??? next to Undulating Confluence (G-5).."] = "Undulating Confluence(G-5)に隣接する「???」を調べる。",
    ["Choose one training focus for Iroha: Strength, Endurance, or Style."] = "イロハの稽古を「筋力」「体力」「スタイル」から1つ選ぶ。",
