    ["Speak with Mandragora Warden (F-4). and trade Acidic Humus."] = "Mandragora Warden(F-4)と話し、酸性腐葉土をトレードする。",
    ["Complete the Magh Bihu event."] = "マッグビフのイベントを進める。",
    ["Return to Mandragora Warden (F-4). and trade a Watermelon."] = "Mandragora Warden(F-4)のもとへ戻り、ウォーターメロンをトレードする。",
    ["Complete the final event."] = "最後のイベントを見る。",
    ["Obtain six Fat Worm Meat."] = "極太ワームの新鮮肉を6個集める。",
    ["Trade all six pieces to Hedrov (H-7).."] = "Hedrov(H-7)に6個まとめてトレードする。",
    ["Speak with Tarnotik (K-10). and continue to Mine Shaft #2716.."] = "Tarnotik(K-10)と話し、2716号採石場へ向かう。",
    ["Enter the battlefield and complete the required Destiny Destroyers encounter."] = "バトルフィールドへ入り、ディスティニーデストロイヤー団に関する戦闘を進める。",
    ["Equip a Stage 2 Prime Weapon with a damage attribute. Instruments and shields do not qualify."] = "第2段階のプライムウェポンを装備する。原文ではダメージ属性を持つ武器を指定し、楽器と盾は対象外。",
    ["Examine Heroes' Gambit (J-9). in Xarcabard."] = "ザルカバードのHeroes' Gambit(J-9)を調べる。",
    ["Examine Valhallan Rift (G-7). in Castle Zvahl Keep."] = "ズヴァール城内郭のValhallan Rift(G-7)を調べる。",
    ["Examine the Valhallan Rift again to enter the battlefield."] = "Valhallan Riftを再度調べ、バトルフィールドへ入る。",
    ["Receive Despairing Psyche."] = "絶望のプシュケーを受け取る。",
    ["Change areas after completing the previous mission."] = "前のミッションを終えたら、エリア移動する。",
    ["Enter Dynamis - Xarcabard."] = "デュナミス-ザルカバードへ入る。",
    ["Collect the four psyche fragments from the four Twinkling Presence targets."] = "4か所のTwinkling Presenceから、魂の破片を4つ集める。",
    ["Examine the target near Castle Zvahl at (D-7) after collecting all four fragments."] = "4つ集めたら、ズヴァール城付近(D-7)のポイントを調べる。",
    ["Return to Bastok Mines and speak with Gumbah (J-7).."] = "バストゥーク鉱山区へ戻り、Gumbah(J-7)と話す。",
    ["Speak with your Mog House Moogle."] = "モグハウスのMoogleと話す。",
    ["Travel to the Stone Circle in La Theine Plateau at (G-6)."] = "ラテーヌ高原(G-6)のストーンサークルへ向かう。",
    ["Examine the ??? there for the cutscene."] = "その場の「???」を調べ、イベントを見る。",
    ["Travel to the Moogle Meeting target at (H-10) in La Theine Plateau."] = "ラテーヌ高原(H-10)のMoogle Meetingへ向かう。",
    ["Examine the Moogle Meeting target again to enter the battlefield."] = "Moogle Meetingを再度調べ、バトルフィールドへ入る。",
    ["Defeat Spikehelm Argok, Tethys, Garmatur the Merciless, and Antican Curule Aedillis."] = "Spikehelm Argok・Tethys・Garmatur the Merciless・Antican Curule Aedillisを倒す。",
    ["Travel to Castle Zvahl Keep and examine Valhallan Rift (G-7).."] = "ズヴァール城内郭へ向かい、Valhallan Rift(G-7)を調べる。",
    ["Examine the Valhallan Rift again to enter The Voracious Beast battlefield."] = "Valhallan Riftを再度調べ、「蝕世の霊獣カオス」のバトルフィールドへ入る。",
    ["Defeat Garazu-Horeizu and the remaining enemies."] = "Garazu-Horeizuと残りの敵を倒す（原文の要約。Wikiでは連続する2戦）。",
    ["Choose one of the available rings after the battle."] = "戦闘後、報酬リングを1つ選ぶ（原文の要約。WikiではHeroes' Gambitを調べて選択）。",
    ["Receive the Vial of Chaos's blood."] = "だいじなもの「カオスの血」を受け取る。",
    ["Continue through the epilogue after The Voracious Beast."] = "「蝕世の霊獣カオス」の後のエピローグを進める（原文の案内。Wikiでは本節は完了状態で、別途後日談がある）。",
    ["Speak with Elijah after the final events to begin the remaining Prime Weapon progression."] = "最後のイベント後、Elijahと話して、プライムウェポンの残りの強化について確認する（原文の案内。Wikiでは追加報酬に個別条件あり）。",

    -- Assault / Nyzul: wiki.ffo.jp source manifests in maintenance bundle.
