    ["Lost and Found"] = "指輪捜索指令",
    ["Deserter"] = "脱走兵武装解除指令",
    ["Desperately Seeking Cephalopods"] = "鱆号作戦",
    ["Bellerophon's Bliss"] = "ベレロフォン作戦",
    ["Nyzul Isle Investigation"] = "ナイズル島踏査指令",
    ["Nyzul Isle Uncharted Area Survey"] = "ナイズル島未開領域踏査指令",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Private Second Class or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫二等傭兵以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Leujaoam Cleansing. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「ルジャワン掃討作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Azouph Isle Staging Point in Caedarva Mire (K-9). Assault Orders do not let you travel to Runic Portals you have not already visited."] = "カダーバの浮沼(K-9)のアズーフ島監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["The party must choose a single leader by talking to the Imperial Guard at the Staging Point. 50 Imperial Standing can be exchanged for an Assault Armband, which is needed to lead the mission."] = "監視哨のImperial Guardと話し、隊長を1人決める。隊長になる人は皇国軍戦績50点を払い、アサルト隊長腕章を受け取る。",
    ["Enter the assault area. A timer starts and the party is told the time limit, which is 30 minutes."] = "作戦領域へ入り、カウント開始と制限時間の表示を確認する。原文は30分だが、作戦によっては15分なので突入時の表示を優先する。",
    ["General Afkaam is to inspect Leujaoam Sanctum. Mission orders: remove all threats. The recommended level is 50."] = "アフカーン将軍の視察に備え、ルジャワン霊窟の危険な生物を排除する。原文の推奨レベルは50。",
    ["Defeat all 15 Leujaoam Worms in the area. They are aggressive and link, and they can use Earth-based magic depending on the level cap of the assault."] = "Leujaoam Wormを15体すべて倒す。アクティブでリンクし、レベル制限によっては土属性魔法を使う。",
    ["Examine the Rune of Release before the time limit runs out, or the mission fails even if all the objectives were met. Then speak with Rytaal in Aht Urhgan Whitegate (K-10) to finalize the mission and hand back the Assault Orders."] = "制限時間内に帰還の幻灯(Rune of Release)を調べて退出する。目標達成だけでは時間切れ失敗になる。退出後はアトルガン白門(K-10)のRytaalに報告し、参加証を返す。",
    ["Each member earns 1 Rank-Up Point for a successful assault. The first time you complete that assault you earn 5 Rank-Up Points in total."] = "成功すると勤務評価が1点上がる。その作戦の初回成功は合計5点になる。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Private First Class or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫一等傭兵以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Orichalcum Survey. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「オリハルコン鉱脈調査」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["There is a rumor that orichalcum ore has been discovered in Leujaoam Sanctum. Mission orders: discover orichalcum ore. The recommended level is 50."] = "ルジャワン霊窟でオリハルコン鉱を発見するのが目標。原文の推奨レベルは50。",
    ["Mine up an Orichalcum Ore from the mining points scattered around the map."] = "マップ内の採掘ポイントで、オリハルコン鉱を掘り当てる。",
    ["The Qiqirn Miners become hostile after an Orichalcum Ore has been mined, so it is recommended to use Invisible and run back to the starting NPC."] = "オリハルコン鉱の発見後はQiqirn Minerが敵対するため、インビジを使って開始地点のNPCへ戻る。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Superior Private or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫上等傭兵以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Escort Professor Chanoix. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「クラボエール男爵警護」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A long-haired marid has been found frozen in the eternal ice of Leujaoam Sanctum. Mission orders: protect the professor. The recommended level is 60."] = "永久凍土で見つかった毛長マーリドを調査する男爵を護衛する。原文の推奨レベルは60。",
    ["Guide and protect Professor Clavauert B Chanoix to the room at (J-5) or (G-9)."] = "Professor Clavauert B Chanoixを護衛し、(J-5)または(G-9)の部屋へ導く（原文座標。WikiはゴールI-8）。",
    ["All enemies in the assault aggro Professor Chanoix, as well as any party member without Sneak or with yellow or lower HP."] = "敵は男爵に襲いかかる。PCもスニークがない場合やHPが黄色以下の場合は、敵の感知に注意する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Lance Corporal or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫傭兵長以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Shanarha Grass Conservation. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「シャナーハ草保護作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Rabbits are sending the shanarha grass, unique to Leujaoam Sanctum, to the verge of extinction. Mission orders: protect the vegetation."] = "ウサギからルジャワン霊窟の希少なシャナーハ草を守る。",
    ["Drive away the rabbits: kill the enemies before the vegetation is consumed."] = "薬草が食べ尽くされる前に、ウサギをすべて倒す。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Corporal or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫伍長以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Counting Sheep. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「黒羊買付作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The Imperial Army on the eastern front is being hit by a peculiar cold wave, and warm uniforms are in short supply. Mission orders: buy black sheep."] = "寒波に見舞われた東部戦線に防寒服を届けるため、黒羊を買い付ける。",
    ["Buy as many sheep as you can from the markets in Leujaoam. Read all the information given in the assault carefully before you begin."] = "ルジャワンの競り市で、できるだけ多くの黒羊を買い付ける。開始前に現地での説明を確認する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Sergeant or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫軍曹以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Supplies Recovery. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「補給物資奪還指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A logistics unit headed to the front lines of the war with the Far East was attacked and its supplies were stolen. The enemy then fled towards Leujaoam Sanctum. Mission orders: retrieve the supplies."] = "東方戦線へ向かう部隊から奪われた補給物資を、ルジャワン霊窟で取り戻す。",
    ["An Immortals unit also joins in the recovery."] = "別働隊の不滅隊も物資回収に参加する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Sergeant Major or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫曹長以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Azure Experiments. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「青の治験」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Mission orders: become a test subject."] = "被験者として治験に協力する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Chief Sergeant or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫特務曹長以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Imperial Code. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「オグマ奪取指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Check the mission orders shown when you enter the assault, as they describe the objective."] = "突入時に表示される作戦指令を読み、その作戦の目標を確認する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank Second Lieutenant or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫少尉以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Red Versus Blue. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「不滅隊・魔滅隊合同演習」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault is offered to mercenaries of the rank First Lieutenant or higher, and it requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。原文の受領条件は山猫中尉以上。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Yahsra at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Bloody Rondo. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でYahsraと話し、「ヘルシング作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["After years of quietly defying Imperial rule, the recluse Count Dracula has begun preparations for an assault on Al Zahbi. Infiltrate Leujaoam Sanctum, locate the count and slay him before he can execute his plans. Mission orders: defeat the count."] = "アルザビへの反攻準備を進めるCount Draculaを、ルジャワン霊窟で討ち取る。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Imperial Agent Rescue. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「皇国エージェント救出作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Mamool Ja Staging Point inside Bhaflau Thickets. Assault Orders do not let you travel to Runic Portals you have not already visited."] = "バフラウ段丘のマムージャ監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["An agent sent to spy on the secret training grounds of the Mamool Ja has been captured. Rescue him before he is interrogated for Imperial secrets. Mission orders: rescue the agent."] = "マムージャの訓練所で捕らえられた皇国のエージェントを、尋問される前に救出する。",
    ["The goal is to rescue the NPC Brujeel by tricking the Mamool Ja into breaking the impassable gates."] = "マムージャに扉を壊させ、閉じ込められているBrujeelを救出する。",
    ["There are 3 gates, as marked on the map, and Brujeel is trapped in a pot beyond one of them."] = "対象の扉は3か所。Brujeelはそのいずれかの先にいる（原文では壺の中と説明）。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Preemptive Strike. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「秘密訓練所急襲作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A unit of Mamool Ja soldiers is training in assassination techniques. Destroy them before they can become a threat to the Empress. Mission orders: destroy the assassins."] = "暗殺訓練を受けるマムージャ特殊部隊を、聖皇への脅威となる前に殲滅する。",
    ["Among the enemies are Mamool Ja Executioners and Puk Executioners."] = "Mamool Ja ExecutionerとPuk Executionerがいる。Wikiではプークの撃破は必須ではない。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Sagelord Elimination. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「賢哲王暗殺作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Sagelord Molaal Ja is visiting the training grounds to oversee the progress of the soldiers. His elimination would sow chaos and confusion in the Mamool Ja ranks. Mission orders: defeat Sagelord Molaal Ja. The recommended level is 60."] = "訓練所を訪れるSagelord Molaal Jaを倒すのが目標。原文の推奨レベルは60だが、Wikiの募集要員は70。",
    ["The Mamool Ja Trainees are aggressive and link. Sagelord Molaal Ja himself does not aggro."] = "Mamool Ja Traineeはアクティブでリンクする。Sagelord Molaal Ja自身は非アクティブ。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Breaking Morale. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「慰問物資強奪作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Scouts report that the new Mamool Ja soldiers have received supplies from their families. Destroy their morale by stealing these supplies while being careful to remain undetected."] = "マムージャ兵に届けられた慰問物資を、見つからないように奪う。",
    ["In the main area of the assault there are many Mamool Ja Trainers (blue mages) and Recruits (orange melees) that must be avoided. Refer to the map for the locations of the treasure coffers."] = "Mamool Ja Trainer（青魔道士）とMamool Ja Recruit（橙色の前衛）が多数いるので避ける。箱の位置は地図を確認する。",
    ["The Mamool Ja move around very frequently, which makes it difficult to avoid aggro."] = "マムージャは頻繁に動くため、見つからないよう周囲に注意する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select The Double Agent. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「二重スパイ捕縛作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Imperial Treasure Retrieval. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「魔宝石回収指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A puk recently stole a treasure box containing enchanted gems from the royal treasury. The gems were then given to Mamool Ja officers as a reward for duty. Find and retrieve the treasure. Mission orders: recover the treasure."] = "皇宮から盗まれ、マムージャ士官に配られた魔宝石を回収する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Blitzkrieg. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「謝鱗祭襲撃作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Marids in the Mist. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「マーリドガーデン作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Azure Ailments. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「青の症例」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Isdebaaq at the desks in the lower area of the Commissions Agency (L-9/L-10) and select The Susanoo Shuffle. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でIsdebaaqと話し、「スサノオ作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Excavation Duty. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「土竜作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Halvung Staging Point inside Mount Zhayolm. Assault Orders do not let you travel to Runic Portals you have not already visited."] = "ゼオルム火山のハルブーン監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Lebros Supplies. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「レベロス補給作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Troll Fugitives. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「落ち武者追撃戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Evade and Escape. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「土筆作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Siegemaster Assassination. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「傭兵軍師狙撃作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Apkallu Breeding. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「アプカル繁殖指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Match the male Lebros Apkallu up to the female Lebros Apkallu. You only need to match up one pair to win, but you receive reduced points for every pair fewer than 8."] = "オスのLebros Apkalluをメスに引き合わせ、つがいを作る。1組で成功となるが、8組に届かない分だけ戦績が減る（原文の説明）。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Wamoura Farm Raid. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「ワモーラファーム襲撃作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Egg Conservation. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「ハンターキラー作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["There have been reports that Qiqirn hunters have been collecting the eggs of the army's messenger apkallus. Mission orders: drive out the hunters."] = "伝書鳥アプカルの卵を狙うキキルンのハンターを追い払う。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Operation: Black Pearl. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「ブラックパール作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A ship carrying Princess Kadjaya of the Imperial family back from a diplomatic mission to the West has run aground near Lebros Cavern. Mission orders: rescue Princess Kadjaya."] = "座礁した船に取り残されたカジャーヤ姫を救出・保護する。",
    ["Speak with Famad at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Better Than One. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でFamadと話し、「ヘラクレス作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Recently there have been multiple reports of a three-headed beast attacking traders on the way to Al Zahbi. Travel to its rumored lair in Lebros Cavern and slay it. Mission orders: defeat Black Shuck."] = "街道で隊商を襲うBlack Shuckを、レベロス風穴で討ち取る。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Seagull Grounded. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「海猫護送作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Dvucca Isle Staging Point in Caedarva Mire (I-9). Assault Orders do not let you travel to Runic Portals you have not already visited."] = "カダーバの浮沼(I-9)のドゥブッカ島監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["The Immortals have captured a member of the Seagull Phratrie, a rebel organization. Escort the prisoner safely to a holding area."] = "不滅隊が捕らえた海猫党の捕虜を、指定の収容地点まで安全に護送する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Requiem. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「レクイエム作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Saving Private Ryaaf. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「ライアーフ捜索作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A squad sent to search for the Seagull Phratrie hideout has failed to report. Find any survivors, especially Private Ryaaf, a relative of the Galeserpent General. Mission orders: find the survivors."] = "消息を絶った調査隊を捜し、ライアーフを含む生存者全員を発見する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Shooting Down the Baron. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「黒い男爵撃墜作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Enter the assault area. A timer starts and the party is told the time limit, which is 15 minutes."] = "作戦領域へ入り、カウント開始と制限時間15分の表示を確認する。",
    ["An imp known as the Black Baron has hit Periqia like a meteor strike, single-handedly defeating 79 Imperial soldiers. Mission orders: eliminate the Black Baron. The recommended level is 60."] = "79名の皇国兵を倒したというBlack Baronを撃破する。原文の推奨レベルは60。",
    ["You enter on the east side of the map, in the room at (I-8), which is also where the Rune of Release appears."] = "東側の部屋(I-8)から開始し、帰還の幻灯もそこに出現する（原文の座標。Wiki本文には開始H-8、ゴールI-8との説明もある）。",
    ["The Periqia Pugils are scattered around the middle of the map and detect by sound. The Black Baron appears at random in one of several places (the middle area or one of the corner tunnels) and does not show on Widescan."] = "中央部のPeriqia Pugilは聴覚感知。Black Baronは中央部か隅の通路などにランダム出現し、広域スキャンに表示されない。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Building Bridges. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「ペリキア架橋作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Thanks to the enemy destroying a bridge along the path of the attack, the unit assaulting Periqia is at an impasse. Mission orders: activate the bridge."] = "爆破された進軍路を確保するため、架橋装置を起動する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Stop the Bloodshed. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「ブラッドバス計画抑止作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The Lamiae are preparing to release swarms of chigoes in Al Zahbi to collect blood samples. Destroy the chigoes and thwart their plan. Mission orders: exterminate the chigoes."] = "アルザビに放たれる前にチゴーを殲滅し、ラミアの血液採取計画を阻止する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Defuse the Threat. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「地雷原処理作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The Lamiae have hired Qiqirn demolition experts to set land mines in Periqia. Mission orders: clear the mine fields. The recommended level is 60."] = "キキルンの発破屋が埋めた地雷を処理する。原文の推奨レベルは60。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Operation: Snake Eyes. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「双頭の蛇作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Generals Karazahm and Umarid of the Imperial Army's Arrapago division have disappeared from camp headquarters while on a mission on Sharug Isle. Mission orders: locate the generals."] = "シャルーグ島で姿を消したウマリド、カラザーム両将軍を捜索・保護する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Wake the Puppet. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「人形の目覚め作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["During a previous mission to eradicate the Undead Swarm presence from Periqia, the Imperial forces had to abandon several Mark-II automatons when they retreated. Mission orders: retrieve the Mark-IIs."] = "以前の撤退時に放棄されたII号軍用オートマトンを回収する。",
    ["Speak with Lageegee at the desks in the lower area of the Commissions Agency (L-9/L-10) and select The Price Is Right. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でLageegeeと話し、「キラーロード作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The target is King Goldemar. He uses the regular dvergr weapon skills, among them Cackle, an area attack that lowers magic attack, magic defense and magic accuracy."] = "King Goldemarを討つ。ドゥエルグの通常の特殊技に加え、魔攻・魔防・魔命を下げる範囲技Cackleなどに注意する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Golden Salvage. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「黄金の遺産収集作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Ilrusi Atoll Staging Point in Arrapago Reef (G-5). Assault Orders do not let you travel to Runic Portals you have not already visited."] = "アラパゴ暗礁域(G-5)のイルルシ環礁監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["Rumor has it that the golden figurehead from the Black Coffin, the ship of Luzaf the pirate, can be found somewhere within Ilrusi Atoll. Mission orders: recover the figurehead."] = "イルルシ環礁を調査し、ルザフの船ブラックコフィン号に由来する黄金の船首像を探す。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Lamia No. 13. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「ラミア13号討伐作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The enemy of this assault is Lamia No. 13, who detects by sight and links."] = "Lamia No. 13が討伐対象。視覚感知でリンクする。",
    ["The NPCs can be put to sleep while they are charmed, and can be healed and given non-party buffs while they are not under the control of Lamia No. 13."] = "魅了された兵士NPCは睡眠が有効。ラミアの支配を離れたNPCには回復や、パーティ外にも使える強化を行える。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Extermination. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「蠱物駆除作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The enemies of this assault are Carrion monsters (Carrion Crabs, Carrion Leeches, Carrion Slimes and Carrion Toads), which detect by sound."] = "Carrion Crab・Carrion Leech・Carrion Slime・Carrion Toadなどの敵は聴覚感知。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Demolition Duty. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「イルルシ掃海作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["A confidential report states that corsairs are secretly collecting the remains of shipwrecks on Ilrusi Atoll. Mission orders: demolish the shipwrecks."] = "コルセアが集める座礁船の残骸を解体する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Searat Salvation. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「シーラット送迎作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Apkallu Seizure. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「アプカル捕獲指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Famous biologist Professor Clavauert is researching apkallu on Ilrusi Atoll. The more discoveries he makes in Aht Urhgan, the more likely he is to join the Empire. Assist him by capturing apkallu. Mission orders: capture the apkallu."] = "クラボエール男爵の調査を手伝い、イルルシ環礁のアプカルを捕獲する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Lost and Found. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「指輪捜索指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Deserter. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「脱走兵武装解除指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["To win this assault, subdue at least one Lamia or Merrow by breaking its weapon."] = "ラミアかメローを、武器を壊して最低1体拘束する（原文の成功条件。Wikiでは殺害して報告することでも成功可能）。",
    ["Weapons can sometimes be broken with critical-hit weapon skills and critical hits."] = "クリティカルヒットや、クリティカルが発生するWSなどで武器を壊せる場合がある。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Desperately Seeking Cephalopods. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「鱆号作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["To increase production of special nighttime camouflage, the Imperial marines need large quantities of a secretion from a rare cephalopod known as the ahtapot, found on Ilrusi Atoll. Mission orders: collect ahtapot."] = "夜戦装備に使う分泌物を確保するため、イルルシ環礁でアフポットを捕獲する。",
    ["Speak with Bhoy Yhupplo at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Bellerophon's Bliss. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でBhoy Yhupploと話し、「ベレロフォン作戦」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Troll mercenary leader Martial Maestro Megomak has finished his newest creation, the Khimaira 14X, and taken it to Ilrusi Atoll for combat testing. Mission orders: defeat Khimaira 14X."] = "Martial Maestro Megomakが持ち込んだ新型合成獣Khimaira 14Xを討伐する。",
    ["Speak with Sorrowful Sage at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Nyzul Isle Investigation. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でSorrowful Sageと話し、「ナイズル島踏査指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["Go to the Nyzul Isle Staging Point in Alzadaal Undersea Ruins. Assault Orders do not let you travel to Runic Portals you have not already visited."] = "アルザダール海底遺跡群のナイズル島監視哨へ向かう。参加証があっても、未開通の移送の幻灯には移動できない。",
    ["Obtain an Imperial Army I.D. Tag from Rytaal in the Commissions Agency of Aht Urhgan Whitegate (K-10). This assault requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-10)の公務代理店でRytaalから皇国軍認識票を受け取る。「アトルガンの秘宝」の利用が必要。",
    ["Speak with Sorrowful Sage at the desks in the lower area of the Commissions Agency (L-9/L-10) and select Nyzul Isle Uncharted Area Survey. You receive Assault Orders in exchange for the tag, and every party member needs their own."] = "公務代理店下段の受付(L-9/L-10)でSorrowful Sageと話し、「ナイズル島未開領域踏査指令」を選ぶ。認識票と引き換えにアサルト参加証を受け取る。メンバー全員が自分の参加証を用意する。",
    ["The recommended level is 99. The Nyzul Isle Uncharted Area is a 100-floor tower, with boss floors yielding increasingly powerful armor every 20 floors."] = "推奨レベル99。ナイズル島未開領域は100層で、20層ごとのボスから得られる防具が上位になる。",
    ["Assault Points: up to 1,000"] = "作戦戦績：原文表記で最大1,000（人数・達成内容・ボーナスで変動）",
    ["Assault Points: up to 1,200"] = "作戦戦績：原文表記で最大1,200（人数・達成内容・ボーナスで変動）",
    ["Assault Points: up to 1,100"] = "作戦戦績：原文表記で最大1,100（人数・達成内容・ボーナスで変動）",
    ["Assault Points: up to 1,333"] = "作戦戦績：原文表記で最大1,333（人数・達成内容・ボーナスで変動）",
    ["Assault Points: up to 1,166"] = "作戦戦績：原文表記で最大1,166（人数・達成内容・ボーナスで変動）",
