    ["To take part in Campaign Ops you must have joined your nation's campaign faction and have an Op Credit. One Op Credit is granted per Vana'diel day and the NPC can store up to 7. Below level 10 you earn Allied Notes but no experience points."] = "カンパニエopsには所属国の軍への入団と受領券が必要。原文ではヴァナ・ディール1日ごとに1枚補充、最大7枚保管、レベル10未満は連合軍戦績のみで経験値なし。補充間隔は小売版Wikiの地球時間1日（星唄の煌めき【六奏】で短縮）と異なるため、実際の案内を優先する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Smokescreen I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「拠点攻略 I（王国軍）」を受領する。",
    ["This operation needs the campaign rank Bronze Ribbon of Service or higher."] = "この作戦には二級連合従軍章以上が必要。",
    ["Objective: join a campaign battle and assist in your nation's siege of a beastman stronghold."] = "目標：カンパニエバトルに参加し、自国軍による獣人拠点の攻略を支援する。",
    ["Join an offensive campaign battle in a territory that the beastmen control."] = "獣人支配地域で攻勢側のカンパニエバトルに参加する。",
    ["Return to Rasdinice to receive your Allied Notes and complete the operation."] = "Rasdiniceに報告し、連合軍戦績を受け取って作戦を完了する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Smokescreen II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「拠点攻略 II（王国軍）」を受領する。",
    ["This operation needs the campaign rank Allied Ribbon of Glory or higher."] = "この作戦には連合突撃章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Smokescreen III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「拠点攻略 III（王国軍）」を受領する。",
    ["This operation needs the campaign rank Golden Star or higher."] = "この作戦には黄金剣勲章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Smokescreen IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「拠点攻略 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Smokescreen V."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「拠点攻略 V（王国軍）」を受領する。",
    ["Objective: join a campaign battle and assist in your nation's siege of the Northlands."] = "目標：カンパニエバトルに参加し、自国軍の北方攻略を支援する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Splitting Heirs."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「黒太子討伐（王国軍）」を受領する。",
    ["Objective: travel to La Vaule and defeat Darkheir Grradhod."] = "目標：ラヴォール村へ向かい、Darkheir Grradhodを倒す。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Kinslayer: Baileys."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「近衛討伐【外郭】（王国軍）」を受領する。",
    ["Check the objective of the operation in your mission menu once you have signed up."] = "受領後、ミッションメニューで作戦の具体的な指令を確認する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Kinslayer: Keep."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「近衛討伐【内郭】（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Fiat Lux."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「無影大王討伐（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Pit Spider I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「補給部隊強襲 I（王国軍）」を受領する。",
    ["This operation needs the campaign rank Brass Ribbon of Service or higher."] = "この作戦には一級連合従軍章以上が必要。",
    ["Objective: ambush one of the enemy's supply caravans."] = "目標：敵の補給部隊を待ち伏せして襲撃する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Pit Spider II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「補給部隊強襲 II（王国軍）」を受領する。",
    ["This operation needs the campaign rank Sterling Star or higher."] = "この作戦には白銀剣勲章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for Pit Spider III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「補給部隊強襲 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category offensive operations and sign up for By Light of Fire I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「侵攻支援」から「野営地強襲 I（王国軍）」を受領する。",
    ["Objective: travel to Vunkerl Inlet (J-7) and obliterate the beastmen campground in Everbloom Hollow."] = "目標：ブンカール浦(J-7)から常花の石窟へ入り、野営する獣人部隊を殲滅する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Aegis Scream I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「拠点防衛 I（王国軍）」を受領する。",
    ["Objective: fend off a beastman siege against one of your nation's strongholds."] = "目標：自国拠点に対する獣人軍の攻撃を防ぐ。",
    ["Participate in a Campaign battle at a stronghold of San d'Oria. The objective is complete when you receive an Objective Completed message and are told to report back."] = "サンドリア軍の拠点でカンパニエバトルに参加する。目標達成と帰還報告を促すメッセージが出れば条件達成。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Aegis Scream II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「拠点防衛 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Aegis Scream III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「拠点防衛 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Aegis Scream IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「拠点防衛 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Aegis Scream V."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「拠点防衛 V（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Granite Rose I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「友軍支援 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Granite Rose II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「友軍支援 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category defensive operations and sign up for Granite Rose III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「防衛支援」から「友軍支援 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Hawk Eye I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「拠点偵察 I（王国軍）」を受領する。",
    ["Objective: gather intelligence from an enemy fortress."] = "目標：敵拠点で情報を収集する。",
    ["Click on the ??? around the enemy stronghold. You receive a Commencing intel extraction message, then repeated Gathering intel messages, until you receive Investigation complete!"] = "敵拠点付近の???を調べる。情報収集開始後、経過メッセージを経て調査完了となるまで待つ。",
    ["There are two ??? around the stronghold: one is used for Hawk Eye and the other for Slaughterhouse."] = "拠点付近の2つの???は用途が異なり、片方は「拠点偵察」、もう片方は「破壊工作」用。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Hawk Eye II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「拠点偵察 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Hawk Eye III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「拠点偵察 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Prying Eyes I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「本営偵察 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Hawk Eye IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「拠点偵察 IV（王国軍）」を受領する。",
    ["Objective: infiltrate an enemy stronghold and gather as much data as possible."] = "目標：敵本営に潜入し、可能な限り情報を集める。",
