    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Frozen Flame."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「拠点強襲（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category intel gathering and sign up for Bailey Borer."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「諜報工作」から「闇障壁弱体（王国軍）」を受領する。",
    ["Objective: allied scholars have determined that an unseen barrier is preventing direct damage to the walls of Castle Zvahl, greatly impeding our siege effort."] = "目標：ズヴァール城の城壁への直接攻撃を妨げる、目に見えない障壁に対処する。連合軍の調査では、この障壁が攻城作戦の障害となっている。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category military training and sign up for Brave Dawn I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「軍事訓練」から「兵士調練 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category military training and sign up for Brave Dawn II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「軍事訓練」から「兵士調練 II（王国軍）」を受領する。",
