    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category military training and sign up for Cut and Cauterize I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「軍事訓練」から「負傷兵救助 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category military training and sign up for Cut and Cauterize II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「軍事訓練」から「負傷兵救助 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category military training and sign up for Cut and Cauterize III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「軍事訓練」から「負傷兵救助 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Stock and Awe I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「戦略物資収集 I（王国軍）」を受領する。",
    ["Objective: give needed supplies to San d'Oria."] = "目標：サンドリア軍に必要な物資を納める。",
    ["Rasdinice sends you to the Quartermaster at (H-9) in Southern San d'Oria (S). Obtain the supplies that he requests, either by gathering them or by buying them at the Auction House, and hand them over."] = "Rasdiniceの指示で南サンドリア〔Ｓ〕(H-9)のQuartermasterを訪ねる。指定された物資を採集や競売などで調達し、トレードする。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Stock and Awe II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「戦略物資収集 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Stock and Awe III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「戦略物資収集 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Stock and Awe IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「戦略物資収集 IV（王国軍）」を受領する。",
    ["This operation needs the campaign rank Brass Wings of Service or higher."] = "この作戦には二級勲功翼章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Materiel Storm I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「軍需品調達 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Materiel Storm II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「軍需品調達 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Materiel Storm III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「軍需品調達 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Materiel Storm IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「軍需品調達 IV（王国軍）」を受領する。",
    ["This operation needs the campaign rank Mythril Wings of Service or higher."] = "この作戦には一級勲功翼章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category resource procurement and sign up for Search and Seizure I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「物資確保」から「敵物資強奪 I（王国軍）」を受領する。",
    ["Objective: attack and defeat any suppliers, seize the cargo and return it."] = "目標：敵の補給部隊を倒して物資を奪い、持ち帰る。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Vanguard-X I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「兵員輸送 I（王国軍）」を受領する。",
    ["Objective: escort a Reinforcement to the outpost."] = "目標：Reinforcement（補充兵）を拠点まで護送する。",
    ["Go to a Gate Sentry in an area that your nation controls and speak with him. A Reinforcement appears and follows you. Escort it to the outpost of that zone."] = "自国支配地域のGate Sentryに話すとReinforcementが現れて追従する。同じエリアの拠点まで護送する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Vanguard-X II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「兵員輸送 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Vanguard-X III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「兵員輸送 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Vanguard-X IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「兵員輸送 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Crimson Domino I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「軍需品運搬 I（王国軍）」を受領する。",
    ["Objective: bring supplies to a stronghold of your nation."] = "目標：自国の拠点へ物資を運ぶ。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Crimson Domino II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「軍需品運搬 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Crimson Domino III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「軍需品運搬 III（王国軍）」を受領する。",
    ["This operation needs the campaign rank Iron Emblem of Service or higher."] = "この作戦には一級戦功水晶章以上が必要。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Bridge Too Far I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「輸送計画立案 I（王国軍）」を受領する。",
    ["Objective: assist in devising a plan to secure safe supply transport."] = "目標：物資を安全に運ぶための輸送計画立案に協力する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply transport and sign up for Crimson Domino IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「輸送運搬」から「軍需品運搬 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Crystal Fist I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「職業訓練 I（王国軍）」を受領する。",
    ["Objective: lend your crafting knowledge to unskilled crafters."] = "目標：未熟な職人に合成の知識を伝える。",
    ["Supply manufacture operations are done with the Adjutant at (D-8) in Southern San d'Oria (S). They take place inside your city, with no battle outside, and any job and level can do them: you only need the knowledge of the craft."] = "生産支援は南サンドリア〔Ｓ〕(D-8)のAdjutantが担当する。街中で行うため外での戦闘はない。原文ではジョブ・レベル不問で合成の知識のみ必要とされるが、受領条件は実際の案内も確認する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Crystal Fist II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「職業訓練 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Crystal Fist III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「職業訓練 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Crystal Fist IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「職業訓練 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Iron Anvil I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「技術供与 I（王国軍）」を受領する。",
    ["Objective: lend your crafting knowledge to crafting adepts."] = "目標：経験を積んだ職人に合成の知識を伝える。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Iron Anvil II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「技術供与 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Iron Anvil III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「技術供与 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category supply manufacture and sign up for Iron Anvil IV."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「生産支援」から「技術供与 IV（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Streetsweeper I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「不審物回収 I（王国軍）」を受領する。",
    ["Objective: find a Suspicious Object in San d'Oria."] = "目標：サンドリアでSuspicious Object（不審物）を見つける。",
