    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Delta Strike I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「巡回任務 I（王国軍）」を受領する。",
    ["Objective: patrol local territories and eliminate any immediate threats."] = "目標：周辺地域を巡回し、差し迫った脅威を排除する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Delta Strike II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「巡回任務 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Delta Strike III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「巡回任務 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Steel Resolve I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「拠点防壁改装 I（王国軍）」を受領する。",
    ["Objective: fortify strongholds against siege turrets."] = "目標：攻城兵器に備えて拠点を補強する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Steel Resolve II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「拠点防壁改装 II（王国軍）」を受領する。",
