    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Magna Cache I."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「備蓄庫増築 I（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Magna Cache II."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「備蓄庫増築 II（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Magna Cache III."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「備蓄庫増築 III（王国軍）」を受領する。",
    ["Speak with Rasdinice in Southern San d'Oria (S) (I-9), select the category security and sign up for Hazardous Materials."] = "南サンドリア〔Ｓ〕(I-9)のRasdiniceに話し、「治安維持」から「増築資材運搬（王国軍）」を受領する。",
    ["Objective: carry hazardous materials to the stronghold."] = "目標：危険な資材を拠点まで運ぶ。",
    ["Speak with Hieronymus in Bastok Markets (S) (E-8), select the category offensive operations and sign up for Smokescreen I."] = "バストゥーク商業区〔Ｓ〕(E-8)のHieronymusに話し、「侵攻支援」から「拠点攻略 I（共和国軍）」を受領する。",
    ["Return to Hieronymus to receive your Allied Notes and complete the operation."] = "Hieronymusに報告し、連合軍戦績を受け取って作戦を完了する。",
    ["Speak with Hieronymus in Bastok Markets (S) (E-8), select the category offensive operations and sign up for Smokescreen II."] = "バストゥーク商業区〔Ｓ〕(E-8)のHieronymusに話し、「侵攻支援」から「拠点攻略 II（共和国軍）」を受領する。",
    ["Speak with Hieronymus in Bastok Markets (S) (E-8), select the category offensive operations and sign up for Smokescreen III."] = "バストゥーク商業区〔Ｓ〕(E-8)のHieronymusに話し、「侵攻支援」から「拠点攻略 III（共和国軍）」を受領する。",
    ["Speak with Hieronymus in Bastok Markets (S) (E-8), select the category offensive operations and sign up for Smokescreen IV."] = "バストゥーク商業区〔Ｓ〕(E-8)のHieronymusに話し、「侵攻支援」から「拠点攻略 IV（共和国軍）」を受領する。",
    ["Speak with Hieronymus in Bastok Markets (S) (E-8), select the category offensive operations and sign up for Smokescreen V."] = "バストゥーク商業区〔Ｓ〕(E-8)のHieronymusに話し、「侵攻支援」から「拠点攻略 V（共和国軍）」を受領する。",
