    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Crystal Fist I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「職業訓練 I（連邦軍）」を受領する。",
    ["Supply manufacture operations are done with the Adjutant at (F-9) in Windurst Waters (S). They take place inside your city, with no battle outside, and any job and level can do them: you only need the knowledge of the craft."] = "生産支援はウィンダス水の区〔Ｓ〕(F-9)のAdjutantが担当する。街中で行うため外での戦闘はない。原文ではジョブ・レベル不問で合成の知識のみ必要とされるが、受領条件は実際の案内も確認する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Crystal Fist II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「職業訓練 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Crystal Fist III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「職業訓練 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Crystal Fist IV."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「職業訓練 IV（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Iron Anvil I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「技術供与 I（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Iron Anvil II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「技術供与 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Iron Anvil III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「技術供与 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category supply manufacture and sign up for Iron Anvil IV."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「生産支援」から「技術供与 IV（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Streetsweeper I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「不審物回収 I（連邦軍）」を受領する。",
    ["Objective: find a Suspicious Object in Windurst."] = "目標：ウィンダスでSuspicious Object（不審物）を見つける。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Streetsweeper II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「不審物回収 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Streetsweeper III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「不審物回収 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Delta Strike I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「巡回任務 I（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Delta Strike II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「巡回任務 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Delta Strike III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「巡回任務 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Steel Resolve I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「拠点防壁改装 I（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Steel Resolve II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「拠点防壁改装 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Steel Resolve III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「拠点防壁改装 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Steel Resolve IV."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「拠点防壁改装 IV（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Magna Cache I."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「備蓄庫増築 I（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Magna Cache II."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「備蓄庫増築 II（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Magna Cache III."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「備蓄庫増築 III（連邦軍）」を受領する。",
    ["Speak with Emhi Tchaoryo in Windurst Waters (S) (H-9), select the category security and sign up for Hazardous Materials."] = "ウィンダス水の区〔Ｓ〕(H-9)のEmhi Tchaoryoに話し、「治安維持」から「増築資材運搬（連邦軍）」を受領する。",
