    ["440 Experience Points and 1180 Allied Notes (at one star)"] = "経験値440、連合軍戦績1180（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["100 Experience Points and 500 Allied Notes (at one star)"] = "経験値100、連合軍戦績500（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["200 Experience Points and 700 Allied Notes (at one star)"] = "経験値200、連合軍戦績700（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
