    ["150 Experience Points and 600 Allied Notes (at one star)"] = "経験値150、連合軍戦績600（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["250 Experience Points and 800 Allied Notes (at one star)"] = "経験値250、連合軍戦績800（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["350 Experience Points and 1000 Allied Notes (at one star)"] = "経験値350、連合軍戦績1000（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["60 Experience Points and 420 Allied Notes (at one star)"] = "経験値60、連合軍戦績420（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",
    ["280 Experience Points and 860 Allied Notes (at one star)"] = "経験値280、連合軍戦績860（原文の★1時の表記。小売版Wikiの現行値とは異なる場合あり）",

    -- Bastok quests: verified article titles; original concise JP walkthroughs.
    ["Obtain a Shell Shield, either at the Auction House or from Young Quadav enemies in North Gustaberg, South Gustaberg, Palborough Mines or Konschtat Highlands. Only level 7 or higher WAR, RDM, PLD, BST and SAM can equip it."] = "甲羅の盾を競売か北グスタベルグ／南グスタベルグ／パルブロ鉱山／コンシュタット高地のYoung Quadavから入手。装備可能なのはレベル7以上のWAR/RDM/PLD/BST/SAM。",
    ["Speak with Powhatan in Port Bastok (E-6) to start the quest."] = "バストゥーク港(E-6)のPowhatanから受領する。",
    ["Equip the Shell Shield."] = "甲羅の盾を装備する。",
    ["Speak with Bartolomeo in Port Bastok (F-7), one of the clerks inside the air travel agency."] = "バストゥーク港(F-7)の飛空旅行社の受付Bartolomeoに話す。",
    ["After the cutscene, return to Powhatan to complete the quest and receive a Spatha."] = "イベント後Powhatanに報告して完了、スパタを受け取る。",
    ["Speak with Talib in Port Bastok (F-6) to start the quest. After the cutscene, accept the quest to proceed to the next portion. If you declined it the first time, you can restart it by speaking with Parraggoh in Bastok Mines (H-5), who is on the lower level."] = "バストゥーク港(F-6)のTalibに話し、イベント後に依頼を承諾。断っていた場合はバストゥーク鉱山区(H-5)下層のParraggohから再開できる。",
    ["Obtain a Zinc Ore. Monsters in Gustaberg are known to drop it."] = "亜鉛鉱を入手する。グスタベルグの敵が落とすほか競売等でも調達可能。",
    ["Trade the Zinc Ore to Talib."] = "亜鉛鉱をTalibにトレードする。",
    ["Speak with Parraggoh in the house on the bottom level in Bastok Mines (H-5) to complete the quest and receive a Bronze Knife. You may need to speak with him twice."] = "バストゥーク鉱山区(H-5)下層の家のParraggohに報告してブロンズナイフを受け取る。会話が2回必要な場合あり。",
    ["Speak with Corann in Port Bastok (K-6), inside the northmost house, to start the quest."] = "バストゥーク港(K-6)最北の家のCorannから受領する。",
    ["Obtain a Quadav Backplate, either at the Auction House or by farming Amethyst Quadav enemies in North Gustaberg, South Gustaberg, Palborough Mines or Konschtat Highlands."] = "クゥダフの背甲を競売か北グスタベルグ／南グスタベルグ／パルブロ鉱山／コンシュタット高地のAmethyst Quadavから入手する。",
    ["Turn in the Quadav Backplate to Corann to complete the quest."] = "クゥダフの背甲をCorannに渡して完了。",
    ["You have to zone after completing Welcome to Bastok. You must be level 31 or higher. Speak with Powhatan in Port Bastok (E-6) to start the quest."] = "ようこそバストゥークへ完了後にエリアチェンジが必要。原文ではレベル31以上。バストゥーク港(E-6)のPowhatanから受領。",
    ["Equip either a Maul or a Replica Maul. A Maul can be bought at the Auction House, dropped by Garnet Quadav enemies in Rolanberry Fields and Beadeaux, or bought for 228 Sparks of Eminence from A.M.A.N. representatives."] = "モールかレプリカモールを装備。モールは競売、ロランベリー耕地／ベドーのGarnet Quadav、または互助会NPCの228エミネンスで調達できる。",
    ["Speak with Bartolomeo in Port Bastok (F-7), inside the Air Travel Agency."] = "バストゥーク港(F-7)の飛空旅行社のBartolomeoに話す。",
    ["Revisit Powhatan and select the second option, \"Where am I supposed to meet your guest?\"."] = "Powhatanに再度話し、2番目の「客とどこで会えばよいか」を尋ねる選択肢を選ぶ。",
    ["Speak with Steel Bones in Port Bastok (D-8)."] = "バストゥーク港(D-8)のSteel Bonesに話す。",
    ["Return to Powhatan to complete the quest and receive a Targe."] = "Powhatanに報告してタージェを受け取る。",
    ["Speak with Benita in Port Bastok (J-6) to begin the quest."] = "バストゥーク港(J-6)のBenitaから受領する。",
    ["Speak with Tete at (I-5) in Port Bastok."] = "バストゥーク港(I-5)のTeteに話す。",
    ["Obtain a Bomb Ash from the Auction House, from Tenshodo or Alchemy vendors, or by farming Lantern and Bomb type monsters."] = "ボムの灰を競売、天晶堂、錬金術ギルド、またはLanternやボム族から入手する。",
    ["Trade the Bomb Ash to Benita to complete the quest."] = "ボムの灰をBenitaに渡して完了。",
    ["Speak with Kaede in Port Bastok (J-5) to start the quest. You must have a job at level 30 or higher and the Rise of the Zilart pack. Ensetsu wants his item back from the Tenshodo, who will only trade it for a strangely shaped coral from Korroloka Tunnel."] = "レベル30以上とジラート導入が必要。バストゥーク港(J-5)のKaedeから開始。Ensetsuの品を天晶堂から取り戻すため、コロロカの洞門の奇妙な珊瑚を求められる。",
    ["In Korroloka Tunnel, click on the ??? to spawn 3 Korroloka Leech enemies. They link with any Thread Leech enemies nearby. If the leeches do not appear after you click the ???, try relogging."] = "コロロカの洞門の???を調べ、Korroloka Leech3体を出現させる。近くのThread Leechがリンクする。出現しない場合、原文は再ログインを案内している。",
    ["Once the leeches are defeated and their bodies despawn, click on the ??? to receive the key item Strangely shaped coral. Several players can do this at the same time: have one member spawn the leeches and, after they despawn, have the others select the ??? before the player who spawned them. If the player who spawned them is KO'd, do not raise them until the Korroloka Leeches are defeated, or the leeches respawn immediately."] = "3体を倒して死体が消えたら???を調べ、奇妙な珊瑚を入手。複数人なら出現させた人を最後に調査。出現させた人が戦闘不能の場合、倒し終わる前の蘇生で即再出現するため注意。",
    ["Return to Ensetsu in Port Bastok (I-5)."] = "バストゥーク港(I-5)のEnsetsuへ戻る。",
    ["Travel to Norg and speak with Ryoma at (H-8), who gives you the key item Sealed dagger."] = "ノーグ(H-8)のRyomaに話し、抜けない短刀を受け取る。",
    ["Return to Ensetsu to complete the quest."] = "Ensetsuに報告して完了。",
    ["Speak with Kurando in Port Bastok (H-6) to begin the quest."] = "バストゥーク港(H-6)のKurandoから受領する。",
    ["Travel to Rolanberry Fields and proceed to (K-7)."] = "ロランベリー耕地(K-7)へ向かう。",
    ["Look for the NM Silk Caterpillar. It spawns when an airship goes by, about every 11 to 14 minutes."] = "飛空艇通過時に出現するSilk Caterpillarを探す。原文の出現間隔目安は11〜14分。",
    ["Defeat the NM to receive a Silkworm Egg."] = "NMを倒して蚕の卵を入手する。",
    ["Return to Kurando and trade him the egg to complete the quest."] = "Kurandoに卵を渡して完了。",
    ["Speak with Qiji in Port Bastok (I-7); he wants to give his wife, Romilda, a Brass Hairpin."] = "バストゥーク港(I-7)のQijiに話す。妻Romildaへ黄銅の髪飾りを贈りたいという。",
    ["Obtain a Brass Hairpin. It can be bought at the Auction House, or crafted."] = "黄銅の髪飾りを競売か合成で用意する。",
    ["Trade the Brass Hairpin to Romilda, who is standing next to Qiji."] = "Qijiの隣のRomildaに黄銅の髪飾りを渡す。",
    ["Speak with Qiji to receive your reward, 300 gil."] = "Qijiに話し、300ギルを受け取る。",
    ["You must have zoned once after finishing Forever to Hold to receive this quest."] = "共に白髪の生えるまで完了後、一度エリアチェンジする。",
    ["Speak with Romilda in Port Bastok (I-7), who wants to give her husband, Qiji, a pair of Cotton Gloves."] = "バストゥーク港(I-7)のRomildaに話す。夫Qijiへコットングローブを贈りたいという。",
    ["Once you have the Cotton Gloves, trade them to Romilda to finish the quest and receive 2,000 gil."] = "コットングローブをRomildaに渡し、2,000ギルを受け取る。",
    ["Speak with Paujean in Port Bastok (F-6) to begin the quest."] = "バストゥーク港(F-6)のPaujeanから受領する。",
    ["Obtain a Rampaging Horn and a Lumbering Horn."] = "狂乱雄羊の角と暴走雄羊の角を用意する。",
    ["The Lumbering Horn comes from defeating Lumbering Lambert or Bloodtear Baldurf in La Theine Plateau; Bloodtear Baldurf is also a Records of Eminence objective under Combat: Region (Original Areas 1). It also comes from various battlefields."] = "暴走雄羊の角はラテーヌ高原のLumbering Lambert／Bloodtear Baldurfや一部BFで入手。Bloodtear Baldurfはエミネンスの戦闘・オリジナルエリア1の対象でもある。",
    ["The Rampaging Horn comes from defeating Rampaging Ram or Steelfleece Baldarich in Konschtat Highlands, or from various battlefields."] = "狂乱雄羊の角はコンシュタット高地のRampaging Ram／Steelfleece Baldarich、または一部BFで入手する。",
    ["Trade both horns to Paujean to complete the quest."] = "両方の角をPaujeanに渡して完了。",
    ["Speak with Yazan in Port Bastok (H-6), who asks you to exterminate Sand Bats in Valkurm Dunes."] = "バストゥーク港(H-6)のYazanからバルクルム砂丘のSand Bats退治を依頼される。",
    ["Obtain a Sand Bat Fang. It can be bought at the Auction House (Materials, Bonecraft) or taken from Sand Bat enemies found in the tunnels of Valkurm Dunes. It is also a Records of Eminence objective: Combat (Wide Area), Combat (Spoils) 2, Spoils (Sand Bat Fang)."] = "砂コウモリの牙を競売（骨材）かバルクルム砂丘の洞窟のSand Batsから入手。エミネンスの広域戦闘・戦利品2にも対象項目がある。",
    ["Once you have one, trade it to Yazan for your reward, 350 gil."] = "牙1個をYazanに渡し、350ギルを受け取る。",
    ["Optional: speak with Valah Molkot in Port Bastok (J-12). She does not say it at first, but she would like an Amaryllis."] = "任意：バストゥーク港(J-12)のValah Molkotに話す。欲しがっている花はアマリリス。",
    ["Obtain an Amaryllis. It can be bought at the Auction House, or from Areebah in Upper Jeuno (H-6)."] = "アマリリスを競売かジュノ上層(H-6)のAreebahから購入する。",
    ["Trade the Amaryllis to Valah Molkot to complete the quest."] = "アマリリスをValah Molkotに渡して完了。",
    ["If you trade her the wrong flower, such as one meant for the other two Mog House exit quests, she takes it and you will have to get another."] = "他国の出口クエスト用など別の花を渡すと回収され、花を用意し直す必要がある。",
    ["Speak with Alib-Mufalib in Port Bastok (K-7) to receive a Blue Sentinel badge and begin the quest. This quest requires the Treasures of Aht Urhgan pack."] = "アトルガン導入が必要。バストゥーク港(K-7)のAlib-Mufalibに話して青色の山猫バッジを受け取る。",
    ["Speak with the people around Bastok. In Bastok Mines: Deidogg (H-6), Echo Hawk (I-7), Griselda (H-5), Goraow (I-6) and Vaghron (H-9)."] = "バストゥーク鉱山区の5人：Deidogg(H-6)、Echo Hawk(I-7)、Griselda(H-5)、Goraow(I-6)、Vaghron(H-9)に話す。",
    ["In Bastok Markets: Horatius (I-9), Arawn (J-10), Harmodios (K-10), Pavel (E-11) and Ken (E-10)."] = "バストゥーク商業区の5人：Horatius(I-9)、Arawn(J-10)、Harmodios(K-10)、Pavel(E-11)、Ken(E-10)に話す。",
    ["In Port Bastok: Paujean (F-6), Kaede (J-5), Tilian (F-8), Hilda (E-6) and Patient Wheel (F-5). In Metalworks: Manilam (G-7), Invincible Shield (G-8), Ayame (K-7) and Kaela (I-8)."] = "バストゥーク港：Paujean(F-6)、Kaede(J-5)、Tilian(F-8)、Hilda(E-6)、Patient Wheel(F-5)。大工房：Manilam(G-7)、Invincible Shield(G-8)、Ayame(K-7)、Kaela(I-8)。原文の掲載者のみ記載。",
    ["Once you have spoken to all 20 people, return to Alib-Mufalib. He takes your Blue Sentinel badge and gives you a Blue invitation card."] = "計20人に話したらAlib-Mufalibへ。バッジと引き換えに青色の招待券を受け取る。",
    ["After joining Salaheem's Sentinels, speak with Naja Salaheem with the invitation card to be rewarded with Imperial currency; the more Lure of the Wildcat quests you have completed, the greater the reward. Alib-Mufalib will also offer to teleport you to Aht Urhgan Whitegate."] = "サラヒム・センチネル入社後、招待券を持ってNaja Salaheemに話すと貨幣報酬。各国山猫クエストの完了数で増える。Alib-Mufalibのアトルガン白門への転送も利用可能になる。",
    ["Zone after completing Love and Ice. You need Bastok fame level 6."] = "狂想曲「氷河に果てる恋」完了後にエリアチェンジ。原文の必要名声はバストゥーク6。",
    ["Speak with Carmelo in Port Bastok (E-6) to begin the quest."] = "バストゥーク港(E-6)のCarmeloから受領する。",
    ["Travel to the three required locations and obtain three key items from Treasure Chests: Un Moment, L'Ephemere and L'Ancienne, the missing parts of the Chanson de Liberte."] = "3地点のTreasure ChestからUn Moment、L'Ephemere、L'Ancienneの楽譜を集める。Chanson de Liberteの欠けた部分にあたる。",
    ["Return to Bastok and speak with Carmelo with all three key items in your possession."] = "楽譜3種を持ってCarmeloに報告する。",
    ["After the conversation, zone out, then return and speak with him one last time to complete the quest and receive 10,000 gil."] = "会話後エリアチェンジし、再度Carmeloに話して完了、10,000ギル。",
    ["Locate the key item you received during The Stars of Ifrit. You receive it before the end of that quest, so you do not need to complete The Stars of Ifrit before starting this one."] = "イフリートの空に向かう船の途中で得るだいじなものを確認する。この品は終了前に手に入るため、先行クエスト自体の完了は不要。",
    ["Speak with Carmelo inside the Steaming Sheep in Port Bastok (E-6) to receive the actual quest and Carmelo's song sheet. If you have The Siren's Tear active, you get a prompt to ask him about the Siren's Tear instead. You need Bastok fame level 5."] = "原文の必要名声はバストゥーク5。バストゥーク港(E-6)蒸気の羊亭のCarmeloに話し、Carmelo's song sheetを受け取る。セイレーンの涙進行中はそちらの話になる場合あり。",
    ["Travel to (G-10) in Beaucedine Glacier, at the ice pond, and click on the Mirror Pond. It only appears on days without snow or clouds."] = "ボスディン氷河(G-10)の氷の池でMirror Pondを調べる。原文では雪や雲のない日が条件。",
    ["After the cutscene, return to Bastok and speak with Carmelo to complete the quest."] = "イベント後Carmeloに報告して完了。",
    ["Zone after completing A Test of True Love. You need Bastok fame level 6."] = "死に至る病完了後にエリアチェンジ。原文の必要名声はバストゥーク6。",
    ["Speak with Carmelo in Port Bastok (E-6) to begin the quest and receive the key item Chanson de Liberte."] = "バストゥーク港(E-6)のCarmeloに話し、Chanson de Liberteを受け取る。",
    ["Travel to (H-8) in The Sanctuary of Zi'Tah to locate a ???, in the middle of the pool. The Survival Guide of The Sanctuary of Zi'Tah is the quickest way to get there."] = "聖地ジ・タ(H-8)の池の中央の???へ。Survival Guideを使うと近い。",
    ["Touch the ??? between 16:00 and 18:00 in-game time to complete the quest."] = "ヴァナ時間16:00〜18:00に???を調べて完了。",
    ["Speak with Hilda in Port Bastok (E-6) to begin the quest. You need Bastok fame level 5."] = "バストゥーク名声5が必要。バストゥーク港(E-6)のHildaから受領する。",
    ["Trade a King Truffle to Hilda to receive the Steaming Sheep invitation. King Truffle can be found at the Auction House, in Voidwatch, or dropped by some Funguar enemies in Crawlers' Nest."] = "キングトリュフをHildaに渡し、Steaming Sheep invitationを入手。競売、ヴォイドウォッチ、クロウラーの巣の一部キノコ族などで調達できる。",
    ["Travel to Metalworks and speak with Raibaht at (G-8), in Cid's Lab. Make sure you receive a short dialog for this specific quest and not a cutscene for one of the several quests that involve Raibaht."] = "大工房(G-8)のシド研究室のRaibahtに話す。他の依頼のイベントではなく、このクエスト専用の短い会話を確認する。",
    ["Return to the Steaming Sheep restaurant and speak with Hilda to complete the quest."] = "蒸気の羊亭へ戻りHildaに報告して完了。",
    ["You must be a Summoner of level 20 or higher. Speak with Ferrol in Port Bastok (I-8) to begin the quest and obtain a Mini tuning fork of earth."] = "原文は召喚士レベル20以上。バストゥーク港(I-8)のFerrolからMini tuning fork of earthを受け取る。",
    ["Prepare for the battle. Whenever you are ready, trade the tuning fork to Ferrol to be transported to the arena."] = "戦闘準備を済ませ、音叉をFerrolにトレードして会場へ転送してもらう。",
    ["Trade the fork to the Earth Protocrystal to enter the fighting arena."] = "Earth Protocrystalに音叉をトレードし、BFへ入る。",
    ["Defeat Titan Prime to complete the quest."] = "Titan Primeを倒して完了。",
    ["You can get the Mini tuning fork again from Ferrol at any point and repeat the fight, but he will no longer teleport you to the Cloister."] = "小音叉はFerrolから再入手でき再戦可能だが、クリア後は回廊への転送をしてもらえなくなる。",
    ["Speak with Juroro in Port Bastok (I-8); Home Point #1 is the closest. You need Bastok fame level 6. Once you have received the key item Tuning fork of earth, you can safely undertake the quest."] = "バストゥーク名声6が必要。バストゥーク港(I-8)のJuroroに話し、Tuning fork of earthを受け取る。Home Point #1が近い。",
    ["Travel to Quicksand Caves and go to (E-10) of the map to find the hidden entrance to the Cloister of Tremors. Each party member must have their own Tuning fork of earth."] = "流砂洞(E-10)から震動の回廊の隠し入口へ。全員が各自の土の音叉を所持する必要がある。",
    ["Defeat Titan Prime to receive the key item Whisper of tremors."] = "Titan Primeを倒し、Whisper of tremorsを入手する。",
    ["Return to Juroro with the whisper and she offers several rewards, including the ability to summon Titan. You can only select one reward at a time, and you can repeat the quest once per Earth day."] = "Juroroへ報告し、タイタン召喚などの報酬から1つを選ぶ。原文では地球時間1日ごとに再挑戦可能。",
    ["To save travel time to the Cloister of Tremors, you can use the Mini tuning fork of earth from the quest Trial-Size Trial by Earth. You must be on Summoner as your main job: get the Mini tuning fork from Ferrol, trade the fork back to Ferrol, and enter the Protocrystal normally. As long as you do not clear the level 20 version of the battlefield, you may warp to the Cloister as many times as you wish."] = "移動短縮には土の試練・改の小音叉も利用可能。メイン召喚士でFerrolから音叉を受け取り、Ferrolに渡して転送後、通常のプロトクリスタルを調べる。レベル20版BFをクリアしない限り繰り返し転送を使える。",
    ["You may also keep the whisper to meet the requirements of the quest The Moonlit Path. Do not turn in the quest if you want to complete The Moonlit Path."] = "The Moonlit Path用に息吹を保持することもできる。その場合は報酬交換をしない。",
    ["Speak with Raifa (D-6) in the Steaming Sheep Restaurant in Port Bastok to begin the quest. You must be level 25 or higher. You can only have one Eco-Warrior quest active at a time, and they cannot be deactivated."] = "原文はレベル25以上。バストゥーク港(D-6)蒸気の羊亭のRaifaから受領。各国Eco-Warriorは同時に1つのみで、原文では取消不可。",
    ["Head to Gusgen Mines and speak with Degga (H-9). Your level will be restricted to 25."] = "グスゲン鉱山(H-9)のDeggaに話し、レベル25制限を受ける。",
    ["Head to (H-6) to find a ???. It is on the top floor; do not go down the stairs. It is advised to clear the area around the ???."] = "上層(H-6)の???へ。階段を下りない。周辺の敵を先に処理すると安全。",
    ["Return to Raifa in Port Bastok to receive your reward, 5,000 gil and Dragon Chronicles. Only one Eco-Warrior quest can be completed per Conquest Tally."] = "Raifaに報告し、5,000ギルとランペール戦記。原文収録手順は討伐部分を省略。各国の退魔はコンクェスト集計ごとに1つのみ完了可能。",
    ["Speak with Trilok in Port Bastok (D-6) to begin the quest. Only one Escort for Hire quest can be active at a time, and only one can be completed each Conquest Tally."] = "バストゥーク港(D-6)のTrilokから受領。各国護衛は同時に1つ、集計ごとに1回のみ完了可能。",
    ["Zone into Crawlers' Nest from Rolanberry Fields. If you get a cutscene with a Hume female NPC named Olavia, you are ready to head out. If you do not, another team may already be on the quest, so wait a while and try zoning in again. You can summon Trusts, but zoning in with an Adventuring Fellow makes the escort NPC disappear."] = "ロランベリー耕地からクロウラーの巣へ入り、Olaviaのイベントを確認。出ない場合は他PTが実行中の可能性がある。フェイスは利用可能だがフェローを連れて入ると護衛NPCが消える。",
    ["Escort Olavia to the end point, and she presents you with a Completion certificate. Every member of the party or alliance must speak to her when she stops, or they will not get a completion."] = "Olaviaを終点まで護衛。停止時に参加者全員が話し、Completion certificateを受け取る。原文はPT/アライアンスとしているが小売版の受領範囲とは差があるため注意。",
    ["Return to Trilok to complete the quest. The first completion gives 10,000 gil and a Page from Miratete's Memoirs."] = "Trilokに報告。初回は10,000ギルとPage from Miratete's Memoirs。",
    ["Speak with Clarion Star in Port Bastok, near Home Point #1 at (K-7); he gives you the Blue institute card."] = "バストゥーク港(K-7)、Home Point #1付近のClarion Starに話し、Blue institute cardを受け取る。",
    ["Head to Metalworks, Home Point #1 (J-8), and speak with Naji."] = "大工房(J-8)、Home Point #1からNajiに会う。",
    ["If this is not your first Trust quest, you are finished with the quest at this point and receive the Bastok Trust permit."] = "他国フェイスを取得済みならこの時点で完了し、Bastok Trust permitを得る。",
    ["If this is your first Trust quest, you must use the Trust spell Naji in South Gustaberg or North Gustaberg. After that, return to Naji to receive the Bastok Trust permit."] = "初めてのフェイスなら南グスタベルグか北グスタベルグでNajiを呼び出した後、本人に報告してBastok Trust permitを得る。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need level 71, and the Rise of the Zilart pack."] = "他のWSクエスト進行中は開始不可。先の依頼人から取り消す。レベル71とジラート導入が必要。",
    ["Speak with Oggbi in Port Bastok (E-6) to receive the key item Weapon training guide and the Knuckles of Trials. You need to break the latent on the Knuckles of Trials before completing the rest of the quest."] = "バストゥーク港(E-6)のOggbiからWeapon training guideとトライアルナックルを受領し、武器の潜在効果を消す。",
    ["With the Knuckles of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points."] = "トライアルナックルをメインに装備し、経験値対象（原文Extremely Easy Prey以上）の敵でWSや連携の〆を行い300ポイントためる。",
    ["Your elemental resistances are listed underneath your equipped gear grid. The latent is broken when the elemental resistances of the Knuckles of Trials disappear from them."] = "装備一覧下の属性耐性を確認し、試練武器の耐性ボーナスが消えたら潜在消し完了。",
    ["Trade the Knuckles of Trials back to Oggbi. The Bostaunieux Oubliette page lists the notorious monster Bodach for this quest."] = "トライアルナックルをOggbiへ返す。対象NMはボストーニュ監獄のBodach。原文はこの討伐の詳細手順を省略している。",
    ["Go back and speak with Oggbi to receive your reward."] = "Oggbiに報告して報酬を受け取る。",
    ["Speak with Oggbi inside the Steaming Sheep Restaurant in Port Bastok (E-6) for a cutscene, as a Monk of level 40 or higher. Once the quest is active you can complete it on any job."] = "モンク40以上でバストゥーク港(E-6)蒸気の羊亭のOggbiに話す。受領後は他ジョブでも進行可能。",
    ["Get a Pickaxe from the Auction House or from any other source."] = "つるはしを競売等で用意する。",
    ["In Gusgen Mines, get to the third map by taking the ramp down at (F-5) and trade the Pickaxe to the ???."] = "グスゲン鉱山(F-5)から坂を下り、原文の3枚目のマップの???につるはしをトレード。",
    ["The Wandering Ghost that appears drops a Miner's Pendant, and the Pickaxe is still in your inventory."] = "出現するWandering Ghostからマイナーペンダントを入手。つるはしは手元に残る。",
    ["Trade the Miner's Pendant to Oggbi to receive the Beat Cesti."] = "マイナーペンダントをOggbiに渡し、ビートセスタスを受け取る。",
    ["You need to be level 66 or higher. Speak with Shamarhaan, the Puppetmaster standing near the fountain in Bastok Markets (F-9), as a Puppetmaster to begin the quest."] = "からくり士66以上でバストゥーク商業区(F-9)、噴水付近のShamarhaanから受領する。",
    ["Obtain a Puppetmaster's Testimony (Pup. Testimony). It drops from Troll Surveillant enemies in Bhaflau Thickets (F-8, northern map) and from Troll Engraver enemies in Halvung. It can be used for up to three fight attempts before you need a new one."] = "偉大な絡繰士の証をバフラウ段丘(F-8、北側マップ)のTroll SurveillantかハルブーンのTroll Engraverから入手。証1枚で3回まで挑戦可能。",
    ["Trade the Pup. Testimony to Shamarhaan to initiate the Navukgo Execution Chamber battlefield; you are warped there. Just like the Maat fight, you have to fight Shamarhaan to break the level cap limit."] = "証をShamarhaanに渡し、ナバゴ処刑場へ転送。マート戦と同様にShamarhaanとの限界突破戦になる。",
    ["Upon arrival at Navukgo Execution Chamber, trade the Testimony to the Decorative Bronze Gate to begin the battle. Shamarhaan is accompanied by his automaton Valkeng, so prepare for a fight against both of them. The time limit is 10 minutes."] = "Decorative Bronze Gateに証を渡してBFへ。ShamarhaanとオートマトンValkengの2体戦、制限10分。",
    ["Bring Shamarhaan down to -20% HP and you should win the battle. The quest does not need to be completed for the level limit increase if you have already completed New Worlds Await or better."] = "原文は「HP -20%」と記載するが表記が曖昧なため実際の勝利条件を確認。New Worlds Await以降の限界を突破済みなら、このクエストの完了は上限開放に必須ではない。",
    ["Speak with Ronan in Port Bastok (K-6) to activate the quest."] = "バストゥーク港(K-6)のRonanから受領。",
    ["Obtain Shell Bug x3 from Quadav enemies or at the Auction House, and trade them to Ronan. Shell Bug can also be obtained from the Green Thumb Moogle if you have a Baby eft memento."] = "Shell Bug3個をクゥダフや競売で入手しRonanへ。Baby eft memento所持ならGreen Thumb Moogleでも調達可能。",
    ["Zone out and back in again, then speak with Ronan to complete the quest."] = "エリアチェンジ後Ronanに報告して完了。",
    ["Speak with Wahid in Bastok Mines (I-8), near Home Point #1; he asks for a Siren's Tear."] = "バストゥーク鉱山区(I-8)、Home Point #1付近のWahidからセイレーンの涙を頼まれる。",
    ["Travel to (J-9) in North Gustaberg and look for a ???. It appears randomly up and down the length of the river. Taking Port Bastok Home Point #1 to North Gustaberg is the quickest way to reach the river."] = "北グスタベルグ(J-9)の川沿いにランダムで現れる???を探す。バストゥーク港のHome Point #1から出ると近い。",
    ["Make sure you have one free inventory slot. Unequip all weapons and shield in the Main and Sub slots, then examine the ??? and you receive the message that you have obtained a Siren's Tear."] = "持ち物を1枠空け、メイン・サブの武器と盾を全て外して???を調べ、セイレーンの涙を入手。",
    ["Go back to Wahid and trade the Siren's Tear to complete the quest and receive 150 gil. If you are doing this quest for a Vana'Bout objective and have already completed it once, you do not need to speak to Wahid again to start it."] = "Wahidにセイレーンの涙を渡して150ギル。既クリアでヴァナ・バウト目的なら再受領の会話は不要。",
    ["Speak with Elki in the Bat's Lair Inn in Bastok Mines (H-5) to trigger a cutscene and start the quest. When the cutscene ends you have a Bouquet for the pioneers."] = "バストゥーク鉱山区(H-5)コウモリのねぐらのElkiから受領し、Bouquet for the pioneersを得る。",
    ["Head out to Zegham Hill in North Gustaberg. Go up the winding hill until you reach the peak and find a monument at (J-7). Alternatively, use the Port Bastok exit near Home Point #1 and in North Gustaberg climb starting on the southwest part of the hill, in a patch of trees at the (H-8)/(I-8) border."] = "北グスタベルグのZegham Hill山頂(J-7)の記念碑へ。バストゥーク港のHome Point #1側から出て(H-8)/(I-8)境の木立の南西から登る経路もある。",
    ["Touch the monument for an event."] = "記念碑を調べてイベントを見る。",
    ["After the event ends, head back to Elki and speak to him to complete the quest."] = "Elkiに報告して完了。",
    ["After just completing Hearts of Mythril, you must zone to flag this quest. You need Bastok fame level 3."] = "ミスリルに賭けた男たち直後はエリアチェンジが必要。原文の必要名声はバストゥーク3。",
    ["Speak with Elki in Bastok Mines (H-5) to start the quest."] = "バストゥーク鉱山区(H-5)のElkiから受領。",
    ["Travel to the top floor of Palborough Mines (map 3). Palborough Mines Home Point #1 is the fastest way."] = "パルブロ鉱山最上階、マップ3へ。Home Point #1が近い。",
    ["Examine the Old Toolbox at the intersection of (H-7) and (H-8) to receive the key item Old toolbox."] = "(H-7)と(H-8)の境のOld Toolboxを調べ、Old toolboxを入手。",
    ["Return to Elki and speak to him."] = "Elkiに話す。",
    ["After the cutscene, speak with Babenn in Bastok Mines (J-6) to complete the quest."] = "イベント後バストゥーク鉱山区(J-6)のBabennに話して完了。",
    ["Speak with Gerbaum in Bastok Mines (F-8); he asks you to exterminate the pests that roam inside Zeruhn Mines."] = "バストゥーク鉱山区(F-8)のGerbaumからツェールン鉱山の害獣退治を頼まれる。",
    ["Collect Zeruhn Soot x3, either by defeating the monsters in Zeruhn Mines or by buying it at the Auction House."] = "Zeruhn Soot3個を鉱山の敵か競売で入手。",
    ["Trade the 3 Zeruhn Soot to Gerbaum for your reward, 150 gil."] = "GerbaumにZeruhn Soot3個を渡し、150ギル。",
    ["Speak with Pavvke in Bastok Mines (I-7), who asks you to bring back name tags."] = "バストゥーク鉱山区(I-7)のPavvkeから認識票を頼まれる。",
    ["Obtain a Silver Name Tag. It can be bought at the Auction House, or dropped by Onyx Quadav and Greater Quadav enemies in Palborough Mines. Since the tags are rare, you can only turn in one at a time."] = "銀の認識票を競売かパルブロ鉱山のOnyx Quadav／Greater Quadavから入手。Rare品のため1個ずつ納める。",
    ["Trade the Silver Name Tag to Pavvke for your reward, 550 gil."] = "Pavvkeに銀の認識票を渡し、550ギル。",
    ["Obtain a Mythril Sallet from the Auction House (Armor, Head) or for 437 Sparks."] = "ミスリルサリットを競売（頭装備）か437エミネンスで入手。",
    ["Speak with Detzo in Bastok Mines (I-6) to begin the quest."] = "バストゥーク鉱山区(I-6)のDetzoから受領。",
    ["Trade the Mythril Sallet to Detzo to complete the quest and receive your reward. The sallet is returned to you, so make sure you have space in your inventory."] = "Detzoにミスリルサリットを渡して報酬を受け取る。サリットは返却されるため持ち物を空けておく。",
    ["Speak with Goraow in Bastok Mines (I-6), in the upper stairway of Ore Street, to begin the quest. It is close to Bastok Mines Home Point #3."] = "バストゥーク鉱山区(I-6)鉱石通りの階段上のGoraowから受領。Home Point #3が近い。",
    ["Obtain a Quadav Helm. It only drops from Old Quadav enemies in Beadeaux; Old Quadav in other areas do not drop the same items. It can also be bought at the Auction House (Others, Beast-made)."] = "クゥダフヘルムをベドーのOld Quadavか競売（獣人製品）で入手。他地域の同名敵は落とさない。",
    ["Trade a Quadav Helm to Goraow to complete the quest and receive 900 gil. You can repeat it without zoning."] = "Goraowにクゥダフヘルムを渡して900ギル。エリアチェンジなしで反復可能。",
    ["Speak with Tami in Bastok Mines (J-8) to begin the quest. She gives you the key item Tami's note. If you open and read the key item, you can no longer repeat the quest."] = "バストゥーク鉱山区(J-8)のTamiからTami's noteを受領。メモの中身を読むと反復できなくなる。",
    ["If you do not read the note: proceed to Zeruhn Mines and locate Zelman at (I-8). He tells you that he is busy and to tell Tami. Return to Tami for your reward of 10 gil. You can then repeat the quest."] = "読まない場合：ツェールン鉱山(I-8)のZelmanに話して伝言を聞き、Tamiに報告して10ギル。再受領可能。",
    ["If you read the note: proceed to Zeruhn Mines and locate Zelman at (I-8), then go to the Bat's Lair Inn at (H-5) in Bastok Mines and buy a Meat Jerky from Griselda."] = "読む場合：ツェールン鉱山(I-8)のZelmanに話し、バストゥーク鉱山区(H-5)の宿のGriseldaから干し肉を買う。",
    ["Trade the Meat Jerky to Tami for your reward, a Rabbit Mantle. The quest is then complete and no longer repeatable."] = "干し肉をTamiに渡してラビットマント。以後は反復不可。",
    ["Teleport to Bastok Mines Home Point #1, go inside the house (upper floor) at (J-7) and speak with Gumbah. Speak to him repeatedly until you get the cutscene that begins the quest. You must be level 30 or higher."] = "レベル30以上。バストゥーク鉱山区のHome Point #1から(J-7)上階の家のGumbahに繰り返し話し、開始イベントを見る。",
    ["Travel to Palborough Mines and go to the top floor (map 3). If you have not unlocked it yet and have completed the limit break quest Beyond Infinity, you can use Domenic to teleport right to the home point outside Waughroon Shrine."] = "パルブロ鉱山最上階、マップ3へ。Beyond Infinity完了済みならDomenicからワールンの祠前へ転送できる。",
    ["Defeat the required number of monsters with the Chaosbringer. If you need to reobtain it, return to Palborough Mines and ride the boat back to Zeruhn Mines; your kill count is reset to zero."] = "カオスブリンガーで規定数の敵を倒す。取り直す場合はパルブロ鉱山からツェールン鉱山への船に乗るが、討伐数は0に戻る。",
    ["Set the Records of Eminence objective Conflict: South Gustaberg (or similar) to help you keep track of the kills."] = "エミネンスのConflict: 南グスタベルグ等を設定すると討伐数を数えやすい。",
    ["Zone in for a cutscene to complete the quest."] = "対象エリアへ入りイベントを見て完了。原文はこの手順のエリア名を省略している。",
    ["Speak with Black Mud in Bastok Mines (J-7) to begin the quest. You receive a Brass Canteen. If you drop it, you can speak to him again to get another one."] = "バストゥーク鉱山区(J-7)のBlack Mudから黄銅の水筒を受領。捨てた場合は再会話で入手可能。",
    ["Travel to Dangruf Wadi and head north from the entrance. The quickest method is the Survival Guide; otherwise zone in from South Gustaberg (D-9)."] = "ダングルフの涸れ谷へ入り北へ。Survival Guideが早く、徒歩なら南グスタベルグ(D-9)から入る。",
    ["Locate the Waterfall Base and trade the Brass Canteen to it, not to the ???, to receive Drachenfall Water. A headstone for the quest An Explorer's Footsteps is along the way."] = "Waterfall Baseに黄銅の水筒を渡し臥竜の滝の水を入手。???ではない。途中にAn Explorer's Footstepsの石碑もある。",
    ["Return to Bastok and trade the Drachenfall Water to Black Mud to complete the quest and receive 2,000 gil."] = "Black Mudに臥竜の滝の水を渡し、2,000ギル。",
    ["Speak with Gumbah in Bastok Mines (J-7) to receive the key item Letter from Zeid. You need Bastok fame level 3."] = "バストゥーク名声3が必要。バストゥーク鉱山区(J-7)のGumbahからLetter from Zeidを受領。",
    ["Use the Chaosbringer to slay 100 more enemies. If you discarded your Chaosbringer, take the boat from Palborough Mines to Zeruhn Mines to receive a new one from Zeid; this resets the blade, so you will have to kill a total of 200 monsters with it to complete the quest."] = "カオスブリンガーでさらに100体倒す。捨てた場合はパルブロ鉱山→ツェールン鉱山の船でZeidから再入手。数がリセットされ、合計200体分が必要になる。",
    ["The same rules apply as in the original quest: for example, weapon skill kills do not count."] = "前クエストと同様、WSで倒した敵は数に入らない。",
    ["Go to Gusgen Mines and trade the Chaosbringer to the ??? at (J-7) on map 1 to receive your reward, the Deathbringer. It is the same ??? used in Bastok Mission 3-2 to spawn the NM Blind Moby."] = "グスゲン鉱山マップ1(J-7)の???にカオスブリンガーを渡し、デスブリンガーを得る。バストゥークミッション3-2のBlind Mobyと同じ???。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need Great Sword skill 250 or higher and level 71."] = "他WSクエスト進行中は先に取消。レベル71以上、両手剣250以上が必要。",
    ["Speak with Gumbah in Bastok Mines (J-7) to receive the key item Weapon training guide and the Sword of Trials. You need to break the latent on the Sword of Trials before completing the rest of the quest."] = "バストゥーク鉱山区(J-7)のGumbahからWeapon training guideとトライアルソードを受け取り、潜在効果を消す。",
    ["With the Sword of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points."] = "トライアルソードをメインに装備し、経験値対象の敵でWSや連携の〆を行い300ポイントためる。",
    ["Trade the Sword of Trials back to Gumbah."] = "トライアルソードをGumbahに返す。",
    ["Go back and speak with Gumbah to receive your reward, the Ground Strike weapon skill."] = "Gumbahに報告してGround Strikeを習得。原文はこの間の討伐手順を省略している。",
    ["Speak with Phara in Bastok Mines (J-9), a Warrior of level 40 or higher; she is right beside the Gobbie Mystery Box at Home Point #2. She needs sword grip material to repair her son's sword, which can be found in a tent in Davoi."] = "戦士40以上でバストゥーク鉱山区(J-9)、Home Point #2の不思議な箱付近のPharaに話す。ダボイのテントの修理材料を頼まれる。",
    ["If multiple people are doing the quest, you will have to wait 5 minutes for the monsters to pop again."] = "複数人で進める場合、敵の再出現まで5分待つ。",
    ["Speak with Phara, then wait a game day (until the clock rolls past 00:00)."] = "Pharaに話した後、ヴァナ時間00:00を越えるまで待つ。",
    ["Speak with Phara again to receive Yasin's sword."] = "Pharaに再度話し、Yasin's swordを受け取る。",
    ["Speak with Naji outside the President's Office in Metalworks (J-8) for a cutscene that finishes the quest, and receive your Razor Axe."] = "大工房(J-8)大統領執務室前のNajiに話して完了、レイザーアクス。",
    ["Speak with Phara in Bastok Mines (J-9), a Warrior of level 50 or higher."] = "戦士50以上でバストゥーク鉱山区(J-9)のPharaに話す。",
    ["Speak with Deidogg in Bastok Mines (H-6) twice; he is at the bottom of the ramp that leads to the guild. After this point the quest can be completed on any job."] = "バストゥーク鉱山区(H-6)、ギルドへ上がる坂の下のDeidoggに2回話す。以後は他ジョブでも進行可能。",
    ["Go to Palborough Mines and work your way to the top floor. You will find a ??? at (G-10) in a dead-end room."] = "パルブロ鉱山最上階(G-10)行き止まりの部屋の???へ。",
    ["Return to Bastok and trade the Mottled Quadav Egg to Deidogg."] = "Mottled Quadav EggをDeidoggに渡す。",
    ["Go to Castle Oztroja and defeat the Yagudo Parasite in the pond on the third floor (H-9) for a Parasite Skin."] = "Castle Oztroja3階(H-9)の池のYagudo Parasiteからパラサイトの皮を入手。",
    ["Return to Bastok again and trade the Parasite Skin to Deidogg."] = "パラサイトの皮をDeidoggに渡す。",
    ["You must wait until the next game day after completing The Talekeeper's Truth before you can activate this quest. You must be a Warrior of level 50 or higher."] = "200年のすれ違い完了後、翌ヴァナ日まで待つ。戦士50以上が必要。",
    ["Speak with Deidogg in Bastok Mines (H-6)."] = "バストゥーク鉱山区(H-6)のDeidoggに話す。",
    ["Speak with Detzo in Bastok Mines (I-6), in the alleyway around the corner from Deidogg."] = "角を曲がったバストゥーク鉱山区(I-6)のDetzoに話す。",
    ["Obtain a Ginger Cookie, sold by the Curio Vendor Moogle or by Valeriano in Port Bastok, and trade it to Deidogg. The quest is not flagged in your log until after you trade the Ginger Cookie, and from then on it is active."] = "Curio Vendor Moogleかバストゥーク港のValeriano等からジンジャークッキーを買いDeidoggへ。トレード後にオファーリストへ載る。",
    ["Defeat the NMs, and zone out of Behemoth's Dominion back into Qufim to receive a cutscene and the reward for completing the quest."] = "NMを倒し、ベヒーモスの縄張りからQufimへ出るとイベントが発生し報酬を得る。原文はNMを出す詳細を省略している。",
    ["If you just finished Ghosts of the Past, you must zone before beginning this quest. You must be on Monk."] = "Ghosts of the Past直後はエリアチェンジが必要。受領時はモンク。",
    ["Speak with Oggbi inside the Steaming Sheep Restaurant in Port Bastok (E-6) for a cutscene. Once the quest is active you can complete it on any job."] = "バストゥーク港(E-6)蒸気の羊亭のOggbiに話す。受領後は他ジョブで進行可能。",
    ["Travel to Fei'Yin. You can use the Home Point warp #1 if you have it."] = "フェ・インへ。開通済みならHome Point #1を利用。",
    ["When ready, click the Hide Flap to pop Deloknok (PLD) and Bilopdop (MNK)."] = "準備後Hide Flapを調べ、Deloknok(PLD)とBilopdop(MNK)を出現させる。",
    ["Go back and speak with Oggbi to receive your Temple Gaiters."] = "Oggbiに報告してテンプルゲートルを受け取る。",
    ["Speak with Ayame in Metalworks (K-7), as a Monk of level 50 or higher. If you have finished the Treasures of Aht Urhgan missions, you may need to speak with her twice. Once you have talked to Ayame, the quest shows up in your quest log and you may switch to another job to complete it."] = "モンク50以上で大工房(K-7)のAyameに話す。アトルガンミッション済みなら会話が2回必要な場合あり。受領後は他ジョブでも進行可能。",
    ["Acquire a Yagudo Drink from the Auction House, or buy one from a Curio Vendor Moogle if you have the appropriate Rhapsody key item."] = "ヤグードドリンクを競売か、星唄の条件を満たしたCurio Vendor Moogleで入手。",
    ["Travel to Castle Oztroja. You do not need the three passwords to enter the Altar Room."] = "オズトロヤ城へ。祭壇の間に入るための3つの暗号は不要。",
    ["Trade the Yagudo Drink to the ??? to spawn Huu Xalmo the Savage."] = "???にヤグードドリンクを渡しHuu Xalmo the Savageを出現させる。",
    ["Huu Xalmo the Savage drops the Xalmo Feather. Trade the feather to Ayame for your Temple Hose."] = "Huu Xalmo the SavageのXalmo FeatherをAyameに渡しテンプルホーズ。",
    ["Speak with Selliste in Bastok Mines (K-7) to begin the quest. You need a Synergy skill of 5 or higher."] = "錬成5以上でバストゥーク鉱山区(K-7)のSellisteから受領。",
    ["To synergize Astral Matter you must gather six stones from ??? spots in the matching cloisters: Flamestone from the Cloister of Flames, Froststone from the Cloister of Frost, Galestone from the Cloister of Gales, Tremorstone from the Cloister of Tremors, Stormstone from the Cloister of Storms and Tidestone from the Cloister of Tides."] = "各回廊の???から6石を集める：灼熱の回廊のFlamestone、凍結の回廊のFroststone、突風の回廊のGalestone、震動の回廊のTremorstone、雷鳴の回廊のStormstone、海流の回廊のTidestone。",
    ["Synergize the stones into Astral Matter in a Synergy Furnace, then trade the result to Selliste for your reward, a Portafurnace."] = "錬成窯で石を星の煌きに錬成し、Sellisteに渡して携帯錬成窯を得る。",
    ["Speak with Titus on the second floor of the Alchemy Guild in Bastok Mines (L-7) for a cutscene that begins the quest. You receive the key item Corked ampoule."] = "バストゥーク鉱山区(L-7)錬金術ギルド2階のTitusからCorked ampouleを受領。",
    ["Go to the Riverbed in Grauberg (S) (F-13). To extract gold you must wash away as much sediment as possible without washing away any gold dust, so wash carefully."] = "Grauberg (S)(F-13)のRiverbedへ。砂金まで流さないよう砂礫を慎重に洗う。",
    ["Each wash gives you a random amount of gold dust grains, generally between 3 and 11. Repeat examining the Riverbed and the washing steps until you have at least 20 grains, which gives you the key item Ampoule of gold dust."] = "原文の採取目安は1回3〜11粒。Riverbedでの採取と洗浄を繰り返して20粒以上集め、Ampoule of gold dustを得る。",
    ["If you leave Grauberg (S), you lose any gold dust you have acquired and have to start over."] = "Grauberg (S)から出ると途中の砂金を失い、最初からになる。",
    ["Speak with Titus again for a cutscene and to receive your reward."] = "Titusに報告して報酬を受け取る。",
    ["Speak with the starting NPC at the Chocobo stables in Bastok Mines (J-9): Azette, Eulaphe or Quelle. You must be level 20 or higher, and you are asked to deliver a Chocobo to a distant stable."] = "レベル20以上でバストゥーク鉱山区(J-9)厩舎のAzette／Eulaphe／Quelleに話し、遠方の厩舎への配送を受ける。",
    ["You are placed on a Chocobo and must ride to the destination. If you dismount, the quest ends in failure."] = "チョコボに乗って目的地へ。途中で降りると失敗。",
    ["The standard riding time limit for a Chocobo is 30 minutes, which is not enough time to ride to Windurst unless you have equipped Orange Race Silks and/or a Chocobo Wand."] = "通常の騎乗制限は30分。Windurstまでは足りないため、原文はOrange Race SilksやChocobo Wandの延長装備を案内している。",
    ["Your reward depends on how quickly you deliver the Chocobo. To San d'Oria: Miratete's Memoirs at 27:00 to 28:36, a Chocobo Ticket at 28:37 to 29:59, Gysahl Greens at 30:00 or more."] = "San d'Oriaへの報酬：27:00〜28:36はMiratete's Memoirs、28:37〜29:59はChocobo Ticket、30:00以上はGysahl Greens。",
    ["To Windurst: Miratete's Memoirs at 31:00 to 32:29, a Chocobo Ticket at 32:30 to 34:43, Gysahl Greens at 34:44 or more. To Jeuno: a Bastok Mines Glyph at 16:00 to 18:49, Gysahl Greens at 18:50 or more."] = "Windurst：31:00〜32:29はMiratete's Memoirs、32:30〜34:43はChocobo Ticket、34:44以上はGysahl Greens。Jeuno：16:00〜18:49はバストゥーク鉱山区 Glyph、18:50以上はGysahl Greens。",
    ["Speak with Talib in Port Bastok (F-6) to start the quest. This quest follows Beauty and the Galka."] = "ガルカと少女後、バストゥーク港(F-6)のTalibから受領。",
    ["Obtain Zinc Ore x4. It can be bought from Teerth in Bastok Markets for 200 gil, from Celestina in Mhaura for 200 gil, or at the Auction House, or you can mine it from a Mineral Vein."] = "Zinc Ore4個を用意。バストゥーク商業区のTeerth、マウラのCelestinaで各200ギル、ほか競売や採掘でも入手可能。",
    ["Trade the Zinc Ore x4 to Talib to complete the quest and receive 350 gil. You do not have to zone to repeat it."] = "Zinc Ore4個をTalibに渡して350ギル。エリアチェンジ不要で反復できる。",
    ["Speak with Horatius inside the Trader's Home at (I-9) in Bastok Markets, who sends you to Dangruf Wadi. You need Bastok fame level 2."] = "バストゥーク名声2が必要。バストゥーク商業区(I-9)商人の家のHoratiusからダングルフの涸れ谷の調査を頼まれる。",
    ["Find the ??? in Dangruf Wadi to get a Dangruf Stone. The monsters around the ??? are level 90 to 95; only the Goblins are aggressive, and they can be avoided with just Invisible since they do not have pets. You lose Invisible when riding the geyser at (I-8) in Dangruf Wadi, so Field Support from the Grounds Tome will fail."] = "ダングルフの涸れ谷の???からDangruf Stoneを入手。周囲は90〜95の敵だが、攻撃的なのはゴブリンでインビジで回避可能。(I-8)の間欠泉で効果が消えるため本の支援だけでは不足する。",
    ["If there is weather when you attempt the quest, you have to wait for it to clear up to find the ???."] = "天候が付いている場合は晴れるまで待ち、???を探す。",
    ["Head back to Horatius to trade the Dangruf Stone and receive your reward, 400 gil."] = "HoratiusにDangruf Stoneを渡し400ギル。",
    ["Speak with Malene in Bastok Markets (I-5) to begin the quest."] = "バストゥーク商業区(I-5)のMaleneから受領。",
    ["Obtain a Steam Clock. You can buy one at the Auction House, or defeat Bubbly Bernie: get a Quus (a fish), from the Auction House or by fishing, travel to the lighthouse in South Gustaberg (M-10) and look for a ???, then trade the Quus to the ??? and Bubbly Bernie appears. Defeat him and loot his corpse for a Steam Clock."] = "蒸気時計を競売かBubbly Bernieから入手。後者はキュスを用意し南グスタベルグ(M-10)灯台の???に渡してNMを倒す。",
    ["Return to town and trade the Steam Clock to Malene to complete the quest and receive 500 gil."] = "Maleneに蒸気時計を渡して500ギル。",
    ["Speak with Salimah in Bastok Markets (L-8) to begin the quest."] = "バストゥーク商業区(L-8)のSalimahから受領。",
    ["Obtain Sleepshroom, Treant Bulb or Wild Onion and trade it to her depending on the time of day. Sleepshroom pays 200 gil from 18:00 to 5:59, Treant Bulb 200 gil from 6:00 to 11:59, and Wild Onion 350 gil from 12:00 to 17:59. If you trade an item that does not match the time of day, you only receive 100 gil."] = "時間に合う食材を納品。18:00〜5:59はネムリタケで200ギル、6:00〜11:59はトレントの球根で200、12:00〜17:59はワイルドオニオンで350。時間違いは100ギル。",
    ["All three items can be farmed (Sleepshroom from Funguar type enemies, Treant Bulb from Sapling type enemies, and Wild Onion from Goblin Thug enemies or by gardening) or bought at the Auction House. If you buy, avoid Wild Onion, which is a hugely popular item for cooks and always expensive."] = "食材は競売か採集。ネムリタケはキノコ族、トレントの球根はSapling、ワイルドオニオンはGoblin Thugや栽培。ワイルドオニオンは需要が高く割高になりやすい。",
    ["The quest can be repeated as many times as you want, but it requires zoning between each trade."] = "何度でも反復可能だが納品ごとにエリアチェンジが必要。",
    ["Speak with Michea in Bastok Markets (F-10) to start the quest."] = "バストゥーク商業区(F-10)のMicheaから受領。",
    ["Obtain a Copper Ingot from the Auction House, Goldsmithing guild shops, or by crafting it. To buy the Copper Ore for crafting at a guild shop, visit Teerth or Visala in Bastok Markets (H-8), or Yabby Tanmikey or Celestina in Mhaura (G-8)."] = "カッパーインゴットを競売、彫金ギルド、合成で用意。材料鉱石はバストゥーク商業区(H-8)のTeerth／Visalaやマウラ(G-8)のYabby Tanmikey／Celestinaで買える。",
    ["To craft the ingot, use a Fire Crystal with 4 Copper Ores."] = "合成する場合は炎のクリスタルとCopper Ore4個を使う。",
    ["Trade the Copper Ingot to Michea to complete the quest and receive 180 gil. You can repeat it by zoning out of the area, but it is no longer repeatable once you reach Bastok fame level 2."] = "Micheaにカッパーインゴットを渡して180ギル。エリアチェンジで反復できるが、原文ではバストゥーク名声2到達後は反復不可。",
    ["Speak with Aquillina in Bastok Markets (K-9); she asks for Flint Stones."] = "バストゥーク商業区(K-9)のAquillinaから火打石を頼まれる。",
    ["Obtain Flint Stone x4. It drops from worm type enemies such as Tunnel Worm, Carrion Worm and Stone Eater, and can also be found at the Auction House (Materials, Goldsmithing)."] = "Flint Stone4個をTunnel Worm／Carrion Worm／Stone Eaterなどのワーム族か競売（彫金材）で入手。",
    ["Trade the Flint Stone x4 to Aquillina to complete the quest and receive 100 gil. The page notes that the quest can be repeated but has a restriction of 15 Earth minutes that applies to everyone, so if another player completed it recently it will not be available."] = "Aquillinaに4個渡して100ギル。反復可能だが地球時間15分の待ち時間は全員で共有し、他人の直後は受け付けられない。",
    ["Speak with Arawn in Bastok Markets (J-10) to start the quest. You receive the Stamp sheet to collect stamps."] = "バストゥーク商業区(J-10)のArawnからStamp sheetを受領。",
    ["Speak to the following 7 guards to obtain the stamps. In Bastok Markets: Pavel (D-11), at the gate to Gustaberg. In Bastok Mines: Deadly Spider (G-8), on the 2nd floor of the Depot, and Tall Mountain (J-7), by going down the ramp toward the Alchemist Guild and turning right at the no-entrance area."] = "計7名からスタンプを集める。バストゥーク商業区のPavel(D-11)、バストゥーク鉱山区のDeadly Spider(G-8)倉庫2階とTall Mountain(J-7)立入禁止区域前。",
    ["In Metalworks: Romualdo (K-9), in the southeastern Cannonry, and Elayne (G-8), at the entrance to the Temple of the Goddess. In Port Bastok: Ehrhard (G-5), in the northeast corner outside Warehouse #1, and Latifah (J-8), north of the drawbridge."] = "大工房：Romualdo(K-9)南東砲室、Elayne(G-8)女神聖堂入口。バストゥーク港：Ehrhard(G-5)第1倉庫外、Latifah(J-8)跳ね橋北。",
    ["Speak to Arawn again once you have collected all the stamps to complete the quest and receive a Leather Gorget."] = "全て集めてArawnに報告しレザーゴルゲット。",
    ["Speak with Nbu Latteh on Gold Street in Bastok Markets (J-9) to start the quest. She gives you a Fire Crystal that you can use to craft your Copper Ring if you choose."] = "バストゥーク商業区(J-9)黄金通りのNbu Lattehから受領。カッパーリングの合成にも使える炎のクリスタルを渡される。",
    ["Obtain a Copper Ring, either at the Auction House, from merchants (Carmelide or Raghd in Bastok Markets) or by crafting it."] = "カッパーリングを競売、バストゥーク商業区のCarmelide／Raghd、または合成で入手。",
    ["Trade the Copper Ring to Roh Latteh in Bastok Mines (H-7), in the first-floor house on Ore Street. When her dialogue ends, you obtain the key item Letter from Roh Latteh. If you check (read) the letter from your key item menu, you get a penalty and only half of the actual reward."] = "バストゥーク鉱山区(H-7)鉱石通り1階の家のRoh Lattehにカッパーリングを渡し、Letter from Roh Lattehを受け取る。手紙を読むと報酬半減。",
    ["Return to Nbu Latteh to complete the quest and receive 100 or 200 gil. The quest is repeatable for players below Bastok fame level 2: zone out each time and you can redo it."] = "Nbu Lattehに報告して100か200ギル。名声2未満ならエリアチェンジして反復できる。",
    ["Speak with Nbu Latteh in Bastok Markets (J-9) to begin the quest. You need Bastok fame level 2 and to have completed Mom, the Adventurer?."] = "ママは冒険者？完了とバストゥーク名声2が必要。バストゥーク商業区(J-9)のNbu Lattehから受領。",
    ["Travel to Konschtat Highlands and inspect the signpost at the south edge of (G-4) and the north edge of (G-5). You receive a Painting of a windmill. Consider doing this together with the quest Past Perfect, since both click on a location in the Highlands."] = "コンシュタット高地(G-4)南端/(G-5)北端のSignpostを調べPainting of a windmillを得る。Past Perfectと並行する選択肢もある。",
    ["Return to Bastok Mines and speak with Roh Latteh at (H-7) to complete the quest and receive a Linen Robe."] = "バストゥーク鉱山区(H-7)のRoh Lattehに報告してリネンローブ。",
    ["Obtain a Bone Chip from the Auction House or by farming Skeleton type monsters."] = "骨くずを競売かスケルトン族から入手。",
    ["Speak with Degenhard in Bastok Markets (I-10) to begin the quest."] = "バストゥーク商業区(I-10)のDegenhardから受領。",
    ["Trade him the Bone Chip to complete the quest and receive the Map of the Dangruf Wadi."] = "骨くずを渡してMap of the ダングルフの涸れ谷を得る。",
    ["Start the quest by speaking with Foss in Bastok Markets (F-7)."] = "バストゥーク商業区(F-7)のFossから受領。",
    ["Once you accept, obtain Rusty Bucket x5, either by fishing for them or by buying them at the Auction House or from Kahah Hobichai in Al Zahbi."] = "Rusty Bucket5個を釣り、競売、アルザビのKahah Hobichaiなどで入手。",
    ["Trade the 5 Rusty Buckets to Foss for your reward, 300 gil."] = "Fossに5個渡して300ギル。",
    ["Speak with Zon-Fobun in Bastok Markets (G-5) to begin the quest. You receive the key item Cursepaper. You need Bastok fame level 4."] = "バストゥーク名声4が必要。バストゥーク商業区(G-5)のZon-FobunからCursepaperを受領。",
    ["Go to Beadeaux and proceed to one of the sets of machines. You need to visit an Afflictor, which curses whoever comes near it unless they are currently silenced, and a Mute, which silences whoever touches it. So get cursed first by coming near the Afflictor, then touch the Mute to become silenced."] = "ベドーで先にThe Afflictorへ近付き呪いを受け、次にThe Muteを調べて静寂を受ける。静寂中は呪いを受けないため順序に注意。",
    ["The first and easiest set of machines: go straight in when entering Beadeaux, then turn left (north) when you reach the wall at (F-7). Go north to the wall in (F-6), then due east to (H-6)."] = "入口から直進し(F-7)の壁で左折して北へ。(F-6)の壁まで行き東の(H-6)の装置を目指す。",
    ["The curse dramatically lowers your maximum HP and MP."] = "呪いで最大HPとMPが大幅に減るので注意。",
    ["Return to Zon-Fobun to complete the quest and receive your Poison Cesti."] = "Zon-Fobunに報告しポイズンセスタス。",
    ["You need Bastok fame level 3 and to have completed Father Figure. Obtain a Cinnamon from the Auction House or, if you have the Kazham Airship Pass, from the port shop in Kazham. You can reach the vendor without being on the airship side: take the Survival Guide or Home Point to Kazham and buy Cinnamon from Ghemi Sinterilo."] = "クラウツ橋の隣人完了とバストゥーク名声3が必要。シナモンを競売かカザム港のGhemi Sinteriloで購入。飛空艇側へ入らずともSurvival GuideやHome Pointから買いに行ける。",
    ["Speak with Gwill in Bastok Markets (E-11) to begin the quest."] = "バストゥーク商業区(E-11)のGwillから受領。",
    ["When the cutscene ends, trade him the Cinnamon to complete the quest and receive a Cotton Headband."] = "イベント後Gwillにシナモンを渡し木綿のヘッドバンド。",
    ["Speak with Zacc in Bastok Markets (G-9), who is standing next to Enu. You need Bastok fame level 5."] = "バストゥーク名声5が必要。バストゥーク商業区(G-9)、Enuの隣のZaccに話す。",
    ["Speak with Malene (I-5), more popularly known as the Steam Clock and Bubbly Bernie quest giver."] = "(I-5)のMaleneに話す。蒸気時計／Bubbly Bernieの依頼人。",
    ["Return to the fountain and speak with Enu. The quest now appears in your log."] = "噴水へ戻りEnuに話すとオファーリストに載る。",
    ["Acquire a Hatchet from the Auction House, NPC stores or crafting."] = "まさかりを競売、店、合成で用意。",
    ["Travel to Yuhtunga Jungle, on Elshimo Island and reached by airship, and locate a Logging Point. Start logging and you receive a Fallen Star."] = "飛空艇でエルシモ島へ渡りユタンガ大森林のLogging Pointで伐採し、星のかけらを入手。",
    ["Return to Enu and trade her the star on a clear starry night (clear weather, with stars visible in the sky) to complete the quest."] = "星が見える晴れた夜にEnuへ星のかけらを渡して完了。",
    ["Speak with Brygid in Bastok Markets (K-9). She tells you how bad your fashion sense is and wants you to come back wearing a Robe and a Bronze Subligar."] = "バストゥーク商業区(K-9)のBrygidに話す。ローブとブロンズサブリガへの着替えを頼まれる。",
    ["Acquire a Robe and a Bronze Subligar, both easy to find at the Auction House or from some armor merchants."] = "ローブとブロンズサブリガを競売か防具屋で用意。",
    ["Wear both pieces of equipment. Only some jobs can wear both items at the same time."] = "両方を同時に装備できるジョブへ着替える。",
    ["Speak with Brygid again to complete the quest and receive the Gloves. Completing it later unlocks Brygid the Stylist Returns."] = "Brygidに話してグローブ。後続ブリジッドのファッションチェックIIの条件にもなる。",
    ["Complete Brygid the Stylist first. Then speak with Brygid in Bastok Markets (K-9), on any job, while wearing any 1 to 5 pieces of Artifact Armor to begin the quest."] = "ブリジッドのファッションチェック完了後、AF防具1〜5部位を装備しバストゥーク商業区(K-9)のBrygidから受領。ジョブは不問。",
    ["Brygid asks for armor pieces from a list of ordinary body and leg armors, for example Banded Mail, Bishop's Robe, Pyro Robe or Silver Mail."] = "通常の胴・脚装備から指定品を求められる。例：Banded Mail、Bishop's Robe、Pyro Robe、Silver Mail。",
    ["Some pieces are job-specific armor that needs a matching subligar dropped by a Fomor enemy: for example Aikido Gi (MNK) needs an Aquarius Subligar from Fomor Monk, Gaudy Harness (BRD/BST) an Ophiuchus Subligar from Fomor Beastmaster, Gloom Breastplate (DRK) a Sagittarius Subligar from Fomor Dark Knight, Nokizaru Gi (NIN) a Taurus Subligar from Fomor Ninja, and Wyvern Mail (DRG) a Leo Subligar from Fomor Dragoon."] = "希望装備には対応するフォモルの星座サブリガが必要。例：Aikido Gi(MNK)はAquarius、Gaudy Harness(BRD/BST)は獣使いのOphiuchus、Gloom Breastplate(DRK)はSagittarius、Nokizaru Gi(NIN)はTaurus、Wyvern Mail(DRG)はLeo Subligar。",
    ["Bring Brygid what she requests to complete the quest and receive your reward."] = "指定品をBrygidに渡して報酬を受け取る。",
    ["Obtain a Silver Ingot from the Auction House or by crafting it. This quest follows The Elvaan Goldsmith."] = "エルヴァーンの彫金師の後続。シルバーインゴットを競売か合成で用意。",
    ["When the cutscene ends, trade her the Silver Ingot to complete the quest and receive 2,200 gil."] = "イベント後Micheaにシルバーインゴットを渡し2,200ギル。",
    ["Speak with Offa in Bastok Markets (F-10) to begin the quest."] = "バストゥーク商業区(F-10)のOffaから受領。",
    ["Travel to Bastok Markets (S) and speak with young Offa. You are given two options, which lead to two different paths through the quest."] = "バストゥーク商業区 (S)の少年Offaに話す。2つの選択肢で以降の経路が分岐する。",
    ["Return to Bastok Markets and Bastok Markets (S), speaking to Offa each time. In the longer path you go Bastok Markets, Bastok Markets (S), Bastok Markets, Bastok Markets (S), where you trade Offa the Fish Bones, then Bastok Markets, Bastok Markets (S) and Bastok Markets again; the last time he ends this part of the quest and gives you a Rolanberry. In the shorter path you trade the Fish Bones sooner, with fewer trips between the two zones."] = "両時代のOffaを往復する。長い経路は現代→過去→現代→過去で魚の骨を納品→現代→過去→現代。最後にロランベリーを受け取る。短い経路は骨を早めに渡すため往復が少ない。",
    ["Whichever way you completed the previous section, once you have the Rolanberry, travel to Bastok Markets (S) one more time and speak with young Offa, then return to Bastok Markets and speak with Offa there to complete the quest and obtain the Withered Berry."] = "ロランベリー入手後はどちらの経路でも過去のOffaに会い、再び現代のOffaへ戻るとオールドベリーを得る。",
    ["Speak with Marin in Bastok Markets (E-10) and accept the quest. You need Bastok fame level 2. She wants you to watch over her little brother Ken during his military academy exam."] = "バストゥーク名声2が必要。バストゥーク商業区(E-10)のMarinから弟Kenの試験中の見守りを依頼される。",
    ["Speak with the NPC Ken to initiate the escort. Buffs remain active, but you cannot cast anything on Ken before starting the quest."] = "Kenに話して護衛開始。自分の強化は持ち越すが、開始前のKenへの魔法は不可。",
    ["Ken engages all enemies that are in his line of sight, and he cannot be stopped like the NPCs used in the three nation escort quests. One way to make the quest easier is to have a higher level friend run slightly ahead of Ken and kill monsters before he attacks them."] = "Kenは視界内の敵に攻撃し、三国護衛NPCのようには停止させられない。高レベルの仲間が先回りして敵を倒すと安全。",
    ["After Ken despawns, Marin appears at the exit."] = "Kenが消えた後、出口にMarinが現れる。",
    ["Return to Bastok Markets and speak to Marin again to finish the quest and receive 1,500 gil."] = "バストゥーク商業区のMarinに報告し1,500ギル。",
    ["Speak with Grin in Port Bastok (G-7) and accept the quest."] = "バストゥーク港(G-7)のGrinから受領。",
    ["Grin shows you a picture of an NPC that you must memorize."] = "Grinが見せる落とし主の姿を覚える。",
    ["Board the next airship."] = "次の飛空艇に乗る。",
    ["Several NPCs that look very similar to the one Grin showed you appear on the ship."] = "船上の似た姿の乗客から本人を探す。",
    ["Speak to the NPCs to get the option of returning the key item Dropped item to them. You only have one chance to get it right."] = "乗客との会話でDropped itemを返す。選べるのは1回だけなので慎重に確認。",
    ["If you choose correctly, you are given 500 gil. If you choose incorrectly, you fail the quest."] = "正しい相手なら500ギル、間違うと失敗。",
    ["Speak with Hungry Wolf inside the Craftmen's Eatery in Metalworks (G-9) to start the quest; Home Point #1 is close. He wants a Galkan Sausage."] = "大工房(G-9)職人食堂のHungry Wolfからガルカンソーセージを頼まれる。Home Point #1が近い。",
    ["Optional: speak with Offa in Bastok Markets (F-10), on the second floor behind the door on the left, for instructions on how to make the sausage."] = "任意：バストゥーク商業区(F-10)2階左の部屋のOffaに作り方を聞く。",
    ["Obtain a Giant Sheep Meat from the Auction House or from Ornery Sheep in South Gustaberg."] = "大羊の肉を競売か南グスタベルグのOrnery Sheepから入手。",
    ["Travel to South Gustaberg (K-9) to find a Goblin campfire (???). To find it, look on your map for the small hill at (K-9); it blends in with the surroundings, so keep an eye open for it."] = "南グスタベルグ(K-9)の小高い丘の焚き火（???）を探す。背景に紛れて見つけにくい。",
    ["Trade the Giant Sheep Meat to the campfire to begin cooking it, then wait one minute (Earth time). Do not zone out, or you will have to repeat the steps."] = "焚き火に大羊の肉を渡し地球時間1分待つ。途中でエリアチェンジするとやり直し。",
    ["After the wait, check the campfire again and it drops a Galkan Sausage into your inventory, so make sure you have inventory room."] = "再度焚き火を調べガルカンソーセージを得る。持ち物を空けておく。",
    ["Trade the Galkan Sausage to Hungry Wolf to complete the quest and receive 300 gil."] = "Hungry Wolfにガルカンソーセージを渡し300ギル。",
    ["Obtain a Dog Collar, either at the Auction House or by farming Black Wolf enemies in North Gustaberg and South Gustaberg at night (game time 20:00 to 04:00)."] = "犬の首輪を競売か北グスタベルグ／南グスタベルグに夜20:00〜04:00に現れるBlack Wolfから入手。",
    ["Speak with Gudav in Port Bastok (H-5) to begin the quest."] = "バストゥーク港(H-5)のGudavから受領。",
    ["At the end of the cutscene, trade the Dog Collar to Gudav to complete the quest and receive the Map of the Gusgen Mines."] = "イベント後犬の首輪を渡しMap of the グスゲン鉱山。",
    ["Speak with Baldric inside the Darksteel Forge on the first floor of Metalworks (G-9) to begin the quest. You need Bastok fame level 2."] = "バストゥーク名声2が必要。大工房(G-9)1階黒鉄工房のBaldricから受領。",
    ["Obtain a Valkurm Sunsand, either at the Auction House or by traveling to Valkurm Dunes."] = "Valkurm Sunsandを競売かバルクルム砂丘で入手。",
    ["To collect it in its natural environment, locate the ??? on an overturned boat on the easternmost beach in Valkurm Dunes, called Siren Sands (H-9). You must first wait for dusty weather for the ??? to appear. Click it and you receive a Valkurm Sunsand."] = "バルクルム砂丘(H-9)、東のSiren Sands海岸の転覆船の???を土天候時に調べ、Valkurm Sunsandを得る。",
    ["Return to Baldric and trade him the Valkurm Sunsand to complete the quest and receive 300 gil."] = "Baldricに砂を渡し300ギル。",
    ["Speak with Unlucky Rat on the first floor of the Cermet Refinery in Metalworks (G-7). You need Bastok fame level 2. He is having a machine problem."] = "バストゥーク名声2が必要。大工房(G-7)1階サーメット精製室のUnlucky Ratに話す。",
    ["Although he does not ask for help, bring him a Slime Oil to solve his problem and obtain your reward, a Scroll of Warp."] = "スライムオイルを渡すと機械の問題が解決し、Scroll of Warpを得る。",
    ["Speak with Cid in Metalworks (H-8) to begin the quest. You need Bastok fame level 4."] = "バストゥーク名声4が必要。大工房(H-8)のCidから受領。",
    ["Travel to Port Bastok (Home Point #3) and visit the Steaming Sheep Restaurant."] = "バストゥーク港のHome Point #3から蒸気の羊亭へ。",
    ["Locate Hilda at (E-6) and speak with her. You can interact with her through the floor if you stand under her, near the bar, while she is upstairs."] = "(E-6)のHildaに話す。上階にいる場合もバー付近の真下から会話できる。",
    ["Obtain a Rolanberry 874, either at the Auction House (Food, Ingredients) or by defeating the Drone Crawler (G) in Crawlers' Nest (Survival Guide, Derfland Region)."] = "ロランベリー 874を競売（食材）かクロウラーの巣のDrone Crawler(G)から入手。Survival Guideはデルフラント。",
    ["Trade the Rolanberry 874 to Hilda to receive the Unfinished letter."] = "Hildaにロランベリー 874を渡してUnfinished letterを得る。",
    ["Return to Cid and speak with him to complete the quest."] = "Cidに報告して完了。",
    ["Speak with High Bear in Metalworks (I-8) to begin the quest. You need Bastok fame level 4. He needs a sample of polluted dirt from Beadeaux."] = "バストゥーク名声4が必要。大工房(I-8)のHigh Bearからベドーの土の調査を受ける。",
    ["Travel to Beadeaux. Upon entry, proceed straight in, then turn left (north) when you reach the wall at (F-7). Go north to the wall in (F-6), then due east to (H-6)."] = "ベドー入口から直進、(F-7)の壁で左折して北、(F-6)から東へ進み(H-6)へ。",
    ["From there head south and you will go into a cave that leads down. Take it down until it exits at (H-7) on the lower map."] = "南の洞窟を下り、下層マップ(H-7)へ出る。",
    ["From there go west and south as you can until you come to the tunnel at (F-8) that leads back to the surface; you pass one Afflictor that curses you as you proceed."] = "西と南へ進み(F-8)の地上へ続く通路へ。途中のThe Afflictorの呪いに注意。",
    ["Follow the surface path along, south past the Mute at (F-9). When the weather is raining, a ??? appears; take your sample of polluted dirt from it."] = "地上を進み(F-9)のThe Muteの南へ。雨天に現れる???から汚染土を採取。",
    ["Return to High Bear and speak with him to complete the quest and receive a Chakram."] = "High Bearに報告しチャクラム。",
    ["Obtain Darksteel Ore x2 from the Auction House, Mog Garden, mining or other sources."] = "Darksteel Ore2個を競売、モグガーデン、採掘等で入手。",
    ["Speak with Mighty Fist on the first floor of Metalworks (Home Point #2, G-9) to begin the quest. You need Bastok fame level 3."] = "バストゥーク名声3が必要。大工房(G-9)1階、Home Point #2付近のMighty Fistから受領。",
    ["Trade him the two ores to end the quest and receive 8,000 gil. You may immediately repeat the quest."] = "鉱石2個を渡し8,000ギル。すぐ反復可能。",
    ["You can only work on this quest after you have obtained an Airship Pass, as completing it requires a trip on the airship. You need Bastok fame level 3."] = "バストゥーク名声3と飛空艇パスが必要。攻略に乗船を伴う。",
    ["Speak with Agapito in Port Bastok (G-6) to begin the quest."] = "バストゥーク港(G-6)のAgapitoから受領。",
    ["On a Full Moon cycle, at night, board the Jeuno to San d'Oria airship."] = "満月の夜にJeuno→San d'Oriaの飛空艇へ乗る。",
    ["Search for an abnormal ???, which only appears during this specific time frame, and touch it to receive the key item Carrier pigeon letter."] = "その時間帯だけ現れる???を調べCarrier pigeon letterを得る。",
    ["Return to Agapito and speak to him to complete the quest and receive 2,100 gil."] = "Agapitoに報告し2,100ギル。",
    ["Speak with Izabele in Metalworks (G-8) to begin the quest. You must form a party with two or more people, all of level 15 or below."] = "大工房(G-8)のIzabeleから受領。全員15以下、2人以上のPTを組む。",
    ["Together with your party, travel to North Gustaberg and locate the Galka Hunting Bear at (F-8), near the waterfalls."] = "全員で北グスタベルグ(F-8)、滝付近のHunting Bearへ。",
    ["Speak with Hunting Bear to complete the quest and receive 500 gil."] = "Hunting Bearに話して500ギル。",
    ["Speak with Raibaht, Cid's assistant, in Cid's Lab in Metalworks (G-8) as a Dark Knight of level 40 or higher. After this point the rest of the quest can be completed on any job."] = "暗黒騎士40以上で大工房(G-8)研究室のRaibahtに話す。以後は他ジョブでも進行可能。",
    ["Speak with Mighty Fist in Metalworks (G-9), on the lower level inside the Darksteel Forge, to receive the key item Letter from the Darksteel Forge."] = "大工房(G-9)下層黒鉄工房のMighty FistからLetter from the Darksteel Forgeを受領。",
    ["Travel to Windurst Waters and speak with Cochal-Monchal at (F-8), at Home Point #1 on the north map, in the Optistery."] = "ウィンダス水の区北マップ(F-8)、Home Point #1付近の目の院のCochal-Monchalに話す。",
    ["Obtain a Yagudo Cherry from a vendor or the Auction House. One is enough for multiple people doing the quest."] = "ヤグードチェリーを店か競売で用意。複数人でも1個で足りる。",
    ["Travel to Giddeus and trade the Yagudo Cherry to the ??? at (H-14). This spawns the NM Vaa Huja the Erudite. You then obtain the key item Darksteel Formula."] = "ギデアス(H-14)の???にヤグードチェリーを渡しVaa Huja the Eruditeを出現させ、Darksteel Formulaを入手する。",
    ["Return to Raibaht and speak with him to complete the quest."] = "Raibahtに報告して完了。",
    ["Speak with Cid in Metalworks (G-8) as a Dark Knight of level 50 or higher to begin the quest."] = "暗黒騎士50以上で大工房(G-8)のCidから受領。",
    ["Obtain a Darksteel Ingot from the Auction House or by crafting it. One is enough for multiple people doing the quest."] = "ダークインゴットを競売か合成で用意。複数人でも1個で足りる。",
    ["Zone into Ordelle's Caves for a cutscene. The Survival Guide and the Voidwatch warp bring you to the same entrance."] = "オルデール鍾乳洞へ入りイベント。Survival Guideとヴォイドウォッチ転送は同じ入口へ着く。",
    ["Trade the Darksteel Ingot to the ??? at (I-8) on map 1 to spawn Gerwitz's Axe (NM). If you zoned in from La Theine Plateau or used the Survival Guide, take the east path (B on the wiki maps). If you are defeated you need another Darksteel Ingot to respawn the NM."] = "原文マップ1(I-8)の???にダークインゴットを渡しGerwitz's Axeを出す。ラテーヌ高原／Survival Guide側からは東経路（Wiki図B）。敗北時はインゴットが再度必要。",
    ["Defeat Gerwitz's Axe and it drops Gerwitz's Axe. Head south up the ramp (D on the wiki maps). At (H-11/12) drop down the hole (the southeast hole), then go east to reach map 3 (E on the wiki maps)."] = "Gerwitz's Axeを倒し同名の斧を入手。南の坂（図D）を上がり(H-11/12)南東の穴を落ち、東から原文マップ3（図E）へ。",
    ["Trade Gerwitz's Axe to the ??? at (H-8) on map 3 to spawn Gerwitz's Sword (NM). Defeat it and it drops Gerwitz's Sword."] = "マップ3(H-8)の???に斧を渡しGerwitz's Swordを出して倒し、同名の剣を入手。",
    ["Head south to enter a large square room and trade Gerwitz's Sword to the ??? at (H-10) to spawn Gerwitz's Soul."] = "南の大きな四角い部屋(H-10)の???に剣を渡し、Gerwitz's Soulを出す。",
    ["Defeat Gerwitz's Soul, then head for La Theine Plateau at (G-10) on the same map. You receive your reward after the cutscene. All party members in the zone receive credit for the defeat of Gerwitz's Soul, even if they are too far away to gain experience."] = "Gerwitz's Soulを倒し、同マップ(G-10)からラテーヌ高原へ出ると報酬。経験値範囲外でも同エリアのPT参加者に討伐判定がある。",
    ["Speak with Raibaht in Cid's lab in Metalworks (G-8) to begin the quest. You need Bastok fame level 3."] = "バストゥーク名声3が必要。大工房(G-8)研究室のRaibahtから受領。",
    ["Travel to Carpenters' Landing to obtain a Garhada Teak Lumber. It can be obtained from monsters that appear on the Phanauet Channel barge, or that spawn from fishing on the barge or on the Carpenters' Landing pier."] = "ギルド桟橋へ。ファノエ運河のバージの通常敵、船上や桟橋で釣り上げた敵からGarhada Teak Lumberを入手。",
    ["Return to Raibaht and trade him the lumber to complete the quest and receive 2,100 gil."] = "Raibahtに材木を渡し2,100ギル。",
    ["If you have just completed Teak Me to the Stars, you must zone before starting this quest. You need Bastok fame level 4."] = "美空を目指す直後はエリアチェンジが必要。バストゥーク名声4が必要。",
    ["Speak with Raibaht in Metalworks (G-8) to begin the quest. You receive a Molybdenum box."] = "大工房(G-8)のRaibahtからMolybdenum boxを受領。",
    ["Travel to Lower Delkfutt's Tower and proceed to the basement. A Delkfutt Key (or the key item version) is required."] = "デルクフの塔下層地下へ。Delkfutt Keyまたはだいじなもの版が必要。",
    ["Travel to (I-6) of the basement map and touch the Cermet Door to pop 3 NMs: Orna, the boss, and 2 Fomorian Spear."] = "地下(I-6)のCermet DoorでOrnaとFomorian Spear2体、計3体を出す。",
    ["Defeat Orna, which makes the other two despawn, and touch the Cermet Door again."] = "Ornaを倒すと護衛2体も消える。Cermet Doorを再調査する。",
    ["Travel to Lower Jeuno and inspect the Street Lamp targets until you find a Hyper altimeter."] = "ジュノ下層のStreet Lampを調べHyper altimeterを探す。",
    ["Return to Bastok and speak with Raibaht to complete the quest and receive 3,000 gil."] = "Raibahtに報告して3,000ギル。",
    ["Obtain an Ordrynite. Enter Pso'Xja from Beaucedine Glacier (G-9) and defeat Cryptonberry Plaguer or Cryptonberry Stalker enemies for it. You can use an Outpost Warp or the Survival Guide to Beaucedine Glacier, then go to (G-9), or use Home Point #1 in Pso'Xja, Escape and go to (G-9). With Rank 10 Chocobo Digging you can probably get 10 in a day, although they are Rare, so you have to turn each one in."] = "ボスディン氷河(G-9)からソ・ジヤへ入り、Cryptonberry Plaguer／Stalkerからオードリナイトを入手。アウトポストやSurvival Guide、ソ・ジヤのHome Point #1→エスケプ経由でも(G-9)へ行ける。原文はチョコボ掘りランク10で1日10個程度とも案内するがRareなので1個ずつ納品。",
    ["Speak with Raibaht in Metalworks (G-8) to begin the quest. You need Bastok fame level 5."] = "バストゥーク名声5が必要。大工房(G-8)のRaibahtから受領。",
    ["Trade the Ordrynite to Raibaht to complete the quest."] = "オードリナイトをRaibahtに渡して完了。",
    ["By completing this quest ten times, the fourth segment of the airship name is unlocked, and it can then be changed from the default, C.I.D."] = "10回完了すると飛空艇名の4番目の部分を初期値C.I.D.から変更可能になる。",
    ["Speak with Ayame in Metalworks (K-7) for a cutscene and agree twice to start the quest. You need Bastok fame level 3 and the Chains of Promathia pack."] = "バストゥーク名声3とプロマシア導入が必要。大工房(K-7)のAyameのイベントで2回承諾して開始。",
    ["Go to Port Bastok and speak with Ravorara at (E-7), outside the Steaming Sheep Restaurant, for a cutscene."] = "バストゥーク港(E-7)蒸気の羊亭外のRavoraraに話す。",
    ["Go to Oldton Movalpolos and speak with Brakobrik at (K-10). The closest warp is the Proto-Waypoint to the Geomagnetic Fount at (K-11), if you have it."] = "ムバルポロス旧市街(K-10)のBrakobrikに話す。開通済みなら(K-11)のProto-Waypointが近い。",
    ["Defeat Ancient Bomb enemies in Oldton Movalpolos to get Hoary Bomb Ash. You need 11 in total, which you trade to Brakobrik in exchange for key items."] = "ムバルポロス旧市街のAncient Bombから古代ボムの灰を合計11個集め、Brakobrikに渡してだいじなものと交換する。",
    ["Go to Bastok Mines and speak with Pavvke in his residence on the lower level (I-7) for a cutscene that completes the quest and gives you your reward."] = "バストゥーク鉱山区(I-7)下層の家のPavvkeに話して完了、報酬を得る。",
    ["Speak with Ayame in Metalworks (K-7) for a cutscene that starts the quest. You need Bastok fame level 4 and the Chains of Promathia pack."] = "バストゥーク名声4とプロマシア導入が必要。大工房(K-7)のAyameから受領。",
    ["Go to Bastok Mines and speak with Virnage at (I-5) for a cutscene. Agree to his proposal and you receive the Dawn talisman."] = "バストゥーク鉱山区(I-5)のVirnageの提案を承諾しDawn talismanを入手。",
    ["Go to Oldton Movalpolos and speak with Rakorok at (K-10). This spawns the NM Bugallug, which must be defeated. It has around 5,000 HP and uses the standard Bugbear attacks (Earthshock, Heavy Whisk, Flying Hip Press, etc.)."] = "ムバルポロス旧市街(K-10)のRakorokに話してBugallugを出し倒す。HP目安5,000、Earthshock／Heavy Whisk／Flying Hip Press等の技を使う。",
    ["After defeating Bugallug, speak with Rakorok for a cutscene in which you lose the Dawn talisman."] = "再度Rakorokに話すとイベントでDawn talismanを失う。",
    ["Return to Bastok Mines and speak with Virnage to complete the quest and receive 3,000 gil."] = "Virnageに報告して3,000ギル。",
    ["Speak with Ayame in Metalworks (K-7) for a cutscene that starts the quest. You need Bastok fame level 5 and the Chains of Promathia pack."] = "バストゥーク名声5とプロマシア導入が必要。大工房(K-7)のAyameから受領。",
    ["Go to Oldton Movalpolos for a cutscene upon zoning."] = "ムバルポロス旧市街へ入りイベントを見る。",
    ["You receive the 10,000 gil back at the end of the quest. Trading Magriffon the 10,000 gil continues this specific quest even if other quests that involve giving Magriffon gil are active."] = "Magriffonに渡す10,000ギルは終了時に返る。他の支払いクエストと同時進行でも、この10,000ギルのトレードは本件を進める。",
    ["Each person involved in the quest must trade a tear to Tarnotik to be teleported to the battlefield zone."] = "BFへの転送は参加者全員がそれぞれTarnotikに涙を渡す必要がある。",
    ["Return to Metalworks and speak with Ayame to receive the Bowyer Ring and end the quest."] = "大工房のAyameに報告してボウヤーリング。",
    ["Change your main job to Ninja (level 20 or above) and speak with Romualdo at (K-9), in the southern Cannonry in Metalworks, to begin the quest. You need Norg fame level 4 and to have completed Ayame and Kaede."] = "忍者20以上、ノーグ名声4、アヤメとカエデ完了が必要。大工房(K-9)南砲室のRomualdoから受領。",
    ["Speak with Ayame at (K-7), in the other Cannonry."] = "もう一方の砲室(K-7)のAyameに話す。",
    ["Obtain a Palborough Chest Key. It drops from Scimitar Scorpion, Brass Quadav, Copper Quadav and Old Quadav enemies in Palborough Mines, or can be bought from the Curio Vendor Moogle for 2,500 gil if you have the key item Rhapsody in White."] = "Palborough Chest KeyをScimitar Scorpion／Brass Quadav／Copper Quadav／Old Quadavから入手。星唄の煌めき【一奏】所持ならCurio Vendor Moogleで2,500ギル。",
    ["Travel to Palborough Mines and open a Treasure Chest to receive the key item Diary of Mukunda."] = "パルブロ鉱山のTreasure Chestを開けDiary of Mukundaを得る。",
    ["Return to Bastok and speak with Kagetora in Port Bastok at (F-6)."] = "バストゥーク港(F-6)のKagetoraに話す。",
    ["After that, speak with Ayame again."] = "Ayameに再度話す。",
    ["Finally, speak with Alois in the conference room of the President's Office in Metalworks (J-8) to complete the quest and receive the Fukuro."] = "大工房(J-8)大統領執務室の会議室のAloisに話して完了、梟。",
    ["Speak with Ferghus in the Craftsmen's Eatery in Metalworks (G-9), south of Cid's workshop, for a cutscene. Metalworks Home Point #1 is the closest. You need Bastok fame level 5 and the Wings of the Goddess pack."] = "バストゥーク名声5とアルタナ導入が必要。大工房(G-9)職人食堂のFerghusから受領。Home Point #1が近い。",
    ["Speak with Leonhardt for another cutscene."] = "Leonhardtに話してイベントを見る。",
    ["Go to Bastok Markets (S) and speak with Raginmund near Harmodio's Music Shop (L-10)."] = "バストゥーク商業区 (S)(L-10)、楽器店付近のRaginmundに話す。",
    ["Obtain a Red Oven Mitt from Copper Quadav and Onyx Quadav enemies in Grauberg (S)."] = "Grauberg (S)のCopper Quadav／Onyx Quadavから赤い鍋つかみを入手。",
    ["Trade the Red Oven Mitt to Leonhardt for a brief cutscene."] = "Leonhardtに赤い鍋つかみを渡してイベント。",
    ["Speak with Umberto in Bastok Markets, near Harmodio's Music Shop (L-10), for a cutscene and your reward."] = "バストゥーク商業区(L-10)楽器店付近のUmbertoに話して報酬。",
    ["Speak with Salim in Metalworks (G-7) to start the quest; he wants you to help get rid of someone. You need Bastok fame level 3."] = "バストゥーク名声3が必要。大工房(G-7)のSalimから受領。",
    ["Place Snares at the Cermet Refinery, the Kiln and the Metalworks Replica. The Costume kit only becomes available after you clear each of the first six items and the quest Chameleon Capers is cleared. You must use the Costume kit to get information and to avoid Salim at the switches."] = "サーメット精製室、窯、工房模型に罠を設置。最初の6道具とChameleon Capersを終えるとCostume kitが使える。変装して情報を聞き、スイッチ付近のSalimを避ける。",
    ["The goal is to find an NPC who tells you the switch order without talking to other NPCs who would call the guards to capture the Mithra and the Tarutaru friend. The following NPCs give clues about the switch order: Darha (ground floor, Galka near Home Point #2), Helmut (ground floor, Hume old man near Home Point #2), Hungry Wolf (upper floor, Craftsmen's Eatery, south of Cid's Lab) and Striking Snake (upper floor, Gunpowder Room, north of Cid's Lab)."] = "見張りを呼ぶ相手を避けてスイッチ順のヒントを聞く。Darha／Helmutは下階Home Point #2付近、Hungry Wolfは上階食堂、Striking Snakeは上階火薬室。",
    ["The small switch is at the Cermet Refinery (G-7). The medium switch is at the Replica (G-8) near the Metalworks entrance, next to the NPC Quasim. The large switch is at the kiln (F-8), just outside of the Blacksmithing Guild."] = "小スイッチ：サーメット精製室(G-7)。中：入口近くQuasimの横の模型(G-8)。大：鍛冶ギルド外の窯(F-8)。",
    ["If you activate an incorrect switch you have to start from the beginning. When you try to activate a switch, Salim may appear. If the same character gets captured twice, the quest ends."] = "順番を間違えると最初から。操作時Salimが現れる場合があり、同じ人物が2回捕まると終了。",
    ["You can repeat this quest once per Conquest Tally."] = "コンクェスト集計ごとに1回反復可能。",
    ["It is no longer possible to flag the original quest. Speak to a Synergy Engineer to obtain a Synergy Crucible if you did not activate this quest before March 27, 2012."] = "小売版では旧クエストの新規受領は終了。2012年3月27日以前に受領していなければSynergy EngineerからSynergy Crucibleを入手する。",
    ["Speaking to Hildolf in Metalworks (F-8) still triggers a quest under the same title. This time he asks for a vial of Slime Oil."] = "大工房(F-8)のHildolfに話すと同名の依頼としてスライムオイルを求められる、と原文に記載。Wikiでは錬成支援との区別がある。",
    ["Once you bring him the item, you are given the option to choose a Fewell element. He crafts it for you while explaining the crafting process."] = "品を渡しフュエルの属性を選ぶと、合成の説明をしながら作ってくれる。",
    ["After giving you the Fewell of your choosing, he no longer offers to craft it and instead encourages you not to give up if you are running low on Fewell."] = "フュエル受領後は再作成せず、燃料不足でも諦めないよう励ます会話になる。",
    ["Speak with Hildolf in Metalworks (F-8) to learn how to create your own Fewell."] = "大工房(F-8)のHildolfにフュエルの作り方を聞く。",
    ["Choose a type from the list and you are given three of that choice, which completes the quest."] = "属性を選び、そのフュエル3個を受け取って完了。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need Great Axe skill 240 or higher, level 71, and the Rise of the Zilart pack."] = "他WSクエスト進行中は先に取消。両手斧240以上、レベル71以上、ジラート導入が必要。",
    ["Speak with Iron Eater in Metalworks (J-8) to receive the Axe of Trials. You need to break the latent on the Axe of Trials before completing the rest of the quest."] = "大工房(J-8)のIron EaterからAxe of Trialsを受け取り潜在効果を消す。",
    ["With the Axe of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points: 7 points for a level 1 skillchain, 9 for level 2 and 11 for level 3. Your elemental resistances are listed underneath your equipped gear grid."] = "Axe of Trialsをメインに装備し経験値対象の敵で300ポイント。原文配点は連携レベル1で7、2で9、3で11とあるが小売版とは差がある。装備一覧下の属性耐性で潜在を確認。",
    ["Alternatively, for the fastest route, use the Unity Warp to Ro'Maeve (level 125), then zone into The Sanctuary of Zi'Tah."] = "移動を短縮するならユニティ転送のロ・メーヴ（レベル125）から聖地ジ・タへ出る。",
    ["Go back and speak with Iron Eater to receive your reward, the Steel Cyclone weapon skill."] = "Iron Eaterに報告してSteel Cycloneを習得。原文は間のNM攻略を省略している。",
    ["You cannot start this quest if you have another Weapon Skill quest active or if you are on the quest Cid's Secret. You need level 71 and the Rise of the Zilart pack."] = "他WSクエストや工房長の秘密進行中は開始不可。レベル71以上とジラート導入が必要。",
    ["Speak with Cid in Metalworks (H-8) to receive the Gun of Trials. You need to break the latent on the Gun of Trials before completing the rest of the quest."] = "大工房(H-8)のCidからGun of Trialsを受け取り潜在効果を消す。",
    ["With the Gun of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points: 7 points for a level 1 skillchain, 9 for level 2 and 11 for level 3. Your elemental resistances are listed underneath your equipped gear grid."] = "Gun of Trialsをメインに装備し経験値対象の敵で300ポイント。原文配点は連携レベル1で7、2で9、3で11とあるが小売版とは差がある。装備一覧下の属性耐性で潜在を確認。",
    ["Go back and speak with Cid to receive your reward, the Detonator weapon skill."] = "Cidに報告してDetonatorを習得。原文は間のNM攻略を省略している。",
    ["Travel to Beadeaux as a Dark Knight of level 50 or higher, and zone in from Pashhow Marshlands (this is important) to receive a cutscene that starts the quest. The quest follows Dark Puppet."] = "暗黒の虜囚後、暗黒騎士50以上でパシュハウ沼から徒歩でベドーへ入りイベント。入る経路が重要。",
    ["Farm Topaz Quadav enemies until you obtain a Quadav Mage Blood. Only one is needed if you are doing this with a group."] = "Topaz QuadavからQuadav Mage Bloodを入手。複数人でも1個で足りる。",
    ["Proceed to Qufim and enter Delkfutt's Tower. Climb to Floor 7 (Middle Delkfutt's Tower)."] = "QufimからDelkfutt's Towerへ入り、7階（デルクフの塔中層）へ登る。",
    ["Defeat the 3 NMs in Middle Delkfutt's Tower. You then receive the Chaos Burgeonet from Zeid in a cutscene, which completes the quest."] = "デルクフの塔中層のNM3体を倒すとZeidのイベントでカオスバーゴネットを得て完了。",
    ["Steps not added yet."] = "このクエストの手順は元データにまだ収録されていません。",
    ["Welcome to Bastok"] = "ようこそバストゥークへ",
    ["Beauty and the Galka"] = "ガルカと少女",
    ["The Quadav's Curse"] = "クゥダフの呪い",
    ["Guest of Hauteur"] = "待ち人来たらず",
    ["The Wisdom of Elders"] = "おばあちゃんの知恵袋",
