    -- San d'Oria quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Glenne in Southern San d'Oria (F-8) to receive an Ointment."] = "南サンドリア(F-8)のGlenneから手作りの軟膏を預かる。",
    ["Zone to West Ronfaure and look for Aaveleon at (G-6)."] = "西ロンフォール(G-6)のAaveleonを探す。",
    ["Trade the Ointment to Aaveleon, who gives you back an Ointment Case."] = "Aaveleonに手作りの軟膏を渡し軟膏の容器を受け取る。",
    ["Return to Glenne and trade her the Ointment Case to complete the quest and receive your reward."] = "Glenneに軟膏の容器を返して報酬を得る。",
    ["Speak with Rosel in Southern San d'Oria (K-8) to start the quest; you receive the receipt for the prince's cloak to deliver to the Chateau guards."] = "南サンドリア(K-8)のRoselから受領。王子のマントの領収書を城の門番に届ける。",
    ["Leave Rosel's Armour Shop and head west into Victory Square. Head north through Victory Arch into Northern San d'Oria, then straight north towards Chateau d'Oraguille."] = "防具店から西へ凱旋広場、北へ凱旋門を抜け北サンドリアへ。さらに北のドラギーユ城へ向かう。",
    ["Look for the guard Guilerme near the bridge into the Chateau. He takes the receipt but cannot read the intended recipient: tell him which prince it is for, Pieuje or Trion, and he runs into the Chateau to deliver it."] = "城の橋付近のGuilermeに領収書を渡す。宛先がPieujeかTrionかを正しく伝えると届けてくれる。",
    ["After the cutscene with Guilerme, return to Rosel for your reward: 200 gil if you named the right prince, only 100 gil if you named the wrong one."] = "イベント後Roselに報告。正しい王子なら200ギル、間違うと100ギル。",
    ["Obtain 3 Sheepskins."] = "大羊の毛皮を3枚用意する。",
    ["Speak with Hanaa Punaa on the second floor balcony of the Leathercraft guild in Southern San d'Oria (E-8) to start the quest, then trade her the 3 skins to complete it."] = "南サンドリア(E-8)、革工ギルド2階バルコニーのHanaa Punaaに話し、皮3枚を渡して完了。",
    ["Speak with Raimbroy in Southern San d'Oria (F-8) to start the quest."] = "南サンドリア(F-8)のRaimbroyから受領。",
    ["Obtain Honey x5. It drops from Maneating Hornet enemies in North Gustaberg and South Gustaberg, or can be bought from Chomo Jinjahl in Windurst Waters North (E-8) for 200 gil with Cooking Guild Recruit rank or higher."] = "Honey5個を用意。北グスタベルグ／南グスタベルグのManeating Hornetから入手するか、調理見習以上ならウィンダス水の区北(E-8)のChomo Jinjahlで200ギル。",
    ["Trade the Honey x5 to Raimbroy to complete the quest and receive 400 gil."] = "RaimbroyにHoney5個を渡し400ギル。",
    ["Obtain 3 Lizard Skins. They can be bought from Cletae in Southern San d'Oria (D-8) for 600 gil, but only with Leathercraft Recruit rank or higher."] = "Lizard Skin3枚を用意。革工見習以上なら南サンドリア(D-8)のCletaeで600ギル。",
    ["Speak with Hanaa Punaa in Southern San d'Oria (E-8) to start the quest and trade her the 3 skins to complete it."] = "南サンドリア(E-8)のHanaa Punaaに話し、皮3枚を渡して完了。",
    ["Speak with Andecia, in the middle house on the first floor of Squire's Alley in Southern San d'Oria (M-7), once to trigger the story text. Speak with her again to receive the Well Water."] = "南サンドリア(M-7)、従者横丁中央の民家1階のAndeciaに2回話し井戸水を得る。",
    ["Go to King Ranperre's Tomb (I-10) on the first map."] = "龍王ランペールの墓の最初のマップ(I-10)へ。",
    ["Trade the Well Water to the tombstone to receive a Tomb Waterskin."] = "Tombstoneに井戸水を渡し墓守の革袋を得る。",
    ["Return to Andecia and trade her the Tomb Waterskin to complete the quest."] = "Andeciaに墓守の革袋を返して完了。",
    ["If you lose the Well Water, touch the tombstone in King Ranperre's Tomb to receive a Tomb Waterskin, then trade it to the water well in Southern San d'Oria (F-6) to get a new Well Water."] = "井戸水を失った場合は墓石から墓守の革袋を回収し、南サンドリア(F-6)の井戸に渡して汲み直す、と原文に記載。Wikiの井戸座標とは差がある。",
    ["Speak with Balasiel on the upper walkways of Southern San d'Oria (F-7); he asks you for a Revival Tree Root. You must be level 10 or higher."] = "原文条件はレベル10以上。南サンドリア(F-7)上層通路のBalasielから反魂樹の根を頼まれる。",
    ["Obtain a Revival Tree Root. It can be bought at the Auction House (Materials, Alchemy) or dropped by Ghost-type enemies, and it does not need to come from King Ranperre's Tomb."] = "反魂樹の根を競売（錬金術材）かゴースト系の敵から入手。龍王ランペールの墓産に限らない。",
    ["Trade the root to Balasiel to complete the quest and receive your reward."] = "Balasielに根を渡し報酬。",
    ["Speak with Balasiel in Southern San d'Oria (F-7) to start the quest."] = "南サンドリア(F-7)のBalasielから受領。",
    ["Go to Ordelle's Caves. You can use the Abyssea La Theine Plateau warp and enter from La Theine Plateau (H-7), or the Survival Guide if you have picked it up."] = "オルデール鍾乳洞へ。アビセア転送でラテーヌ高原(H-7)から入るか、開通済みSurvival Guideを利用。",
    ["If you entered from La Theine Plateau (H-7) you arrive on map 1 (K-3): head to (I-5), a room with Fly Agaric enemies. If you used the Survival Guide you arrive on map 2 (G-2): go to map 1 (Point A, G-4), then to (I-5)."] = "(H-7)入口は原文マップ1(K-3)からFly Agaricの部屋(I-5)へ。Survival Guideはマップ2(G-2)からPoint A(G-4)経由でマップ1(I-5)へ。",
    ["From the Fly Agaric room, take the southwest passage (to Point C, G-6/H-6) to reach map 2, and proceed to the large room at (G-7)."] = "Fly Agaricの部屋から南西（Point C、G-6/H-6）へ進み、原文マップ2の大部屋(G-7)へ。",
    ["Examine the ??? to get the Stalactite dew."] = "???を調べ鍾乳石のしずくを入手。Wikiでは滝つぼと近くの別の???を続けて調べる手順がある。",
    ["Speak with Balasiel to complete the quest."] = "Balasielに報告して完了。",
    ["Speak with Balasiel in Southern San d'Oria (F-7), who gives you the Book of Tasks with hints on how to proceed. You must be level 30."] = "レベル30以上で南サンドリア(F-7)のBalasielに話し課題の書を得る。",
    ["Speak with Cahaurme (J-9), reached from (L-8) in the tower above the East Gate, to receive the Book of the East."] = "(L-8)から東門上の塔(J-9)へ行き、Cahaurmeから東の書を得る。",
    ["Speak with Baunise (H-9), reached from (F-8) in the tower above the West Gate, to receive the Book of the West."] = "(F-8)から西門上の塔(H-9)へ行き、Bauniseから西の書を得る。",
    ["Go to the dead end at (E-10) in Davoi and examine the Disused Well to receive the Knight's soul. To get there, follow the river west from (J-10), then head south after reaching (D-8)."] = "ダボイ(J-10)から川を西へ、(D-8)から南へ進む。(E-10)行き止まりのDisused Wellで騎士の魂を入手。",
    ["Beware of Orcish Farkiller enemies on top of the ledge, which can aggro even at level 99, and of Pugil enemies in the river, which aggro by sound to characters near level 30."] = "崖上のOrcish Farkillerは99でも絡む。川のPugilは30前後なら聴覚感知に注意。",
    ["Return to Balasiel to complete the quest."] = "Balasielに報告して完了。",
    ["Speak with Nenne in Southern San d'Oria (F-6). The quest does not appear in your quest log until the item hunt part has been activated."] = "南サンドリア(F-6)のNenneに話す。元データでは採集段階を有効にするまでオファーに載らないと説明している。",
    ["After hearing Nenne's story, go into the first house on Watchdog Alley (G-7), go upstairs to a bedroom and examine the ??? on the table. Click it to get the option to read a diary."] = "話を聞いたら猟犬横丁(G-7)最初の家の2階寝室へ。机の???から日記を読む。",
    ["Speak with Amaura (G-6), who asks for Thyme Moss."] = "(G-6)のAmauraからタチジャコウゴケを頼まれる。",
    ["Obtain Thyme Moss and return it to Amaura, who gives you Cough Medicine."] = "タチジャコウゴケをAmauraに渡し咳止めの薬を得る。",
    ["Speak with Nenne, who gives you a Scroll of Treasure as your reward."] = "Nenneに話して財宝の書を得る。",
    ["Obtain Black Tiger Fang x3. It can be found at the Auction House (Materials, Bonecraft) or bought from Retto-Marutto in Windurst Woods (H-13) for 2,000 gil."] = "Black Tiger Fang3個を競売（骨細工材）かウィンダス森の区(H-13)のRetto-Marutto（2,000ギル）で用意。",
    ["Trade the Black Tiger Fang x3 to Taumila in Southern San d'Oria (E-9) to complete the quest and receive 2,100 gil."] = "南サンドリア(E-9)のTaumilaに牙3個を渡し2,100ギル。",
    ["Obtain 3 Black Tiger Hides."] = "黒虎の毛皮を3枚用意。",
    ["Speak with Hanaa Punaa in Southern San d'Oria (E-8) to start the quest and trade her the 3 hides to complete it."] = "南サンドリア(E-8)のHanaa Punaaに話し、毛皮3枚を渡して完了。",
    ["Speak with Parvipon, the tanner, in Southern San d'Oria (E-8) outside the Leathercraft Guild to begin the quest. The first time you must answer \"I shall help.\" before you can proceed; speaking to him again is not needed for later trade-ins."] = "南サンドリア(E-8)、革工ギルド外のParviponに話す。初回は「I shall help.」を選び、反復時は再会話不要。",
    ["Trade Rabbit Hide x3 to Parvipon for your reward. Rabbit Hide is sold upstairs in the Leathercraft guild by Cletae (D-8)."] = "ParviponにRabbit Hide3枚を渡す。皮は革工ギルド上階(D-8)のCletaeでも購入可能。",
    ["You can repeat this quest as often as you like."] = "何度でも反復可能。",
    ["Speak with Femitte in Southern San d'Oria (I-8), who needs a goldsmithing order fulfilled and asks for an Elvaan specifically. She gives you a Goldsmithing order."] = "南サンドリア(I-8)のFemitteからエルヴァーン彫金師へのGoldsmithing orderを預かる。",
    ["Go to Bastok Markets (Home Point #1) and look for Michea at (F-10), upstairs inside Brunhilde the Armorer's shop."] = "バストゥーク商業区のHome Point #1から(F-10)、防具店上階のMicheaへ。",
    ["Michea asks for a Mythril Ingot. Trade it to her, then zone out of Bastok Markets once."] = "Micheaにミスリルインゴットを渡し、一度バストゥーク商業区から出る。",
    ["Zone back into Bastok Markets and return to Michea to receive the key item Mythril hearts."] = "バストゥーク商業区に戻り、Micheaからミスリルハーツを受け取る。",
    ["Travel back to Southern San d'Oria and speak with Femitte to complete the quest."] = "南サンドリアのFemitteに報告して完了。",
    ["Speak with Legata in the Lion Spring's Tavern in Southern San d'Oria (K-6) to begin the quest."] = "南サンドリア(K-6)、獅子の泉のLegataから受領。",
    ["Obtain Flint Stone x4. It can be found at the Auction House (Materials, Goldsmithing) or dropped by worm enemies such as Tunnel Worm in East Ronfaure, West Ronfaure, North Gustaberg and South Gustaberg."] = "Flint Stone4個を競売（彫金材）か東ロンフォール／西ロンフォール／北グスタベルグ／南グスタベルグのTunnel Worm等から入手。",
    ["Trade the 4 Flint Stones to Legata for your reward."] = "LegataにFlint Stone4個を渡して報酬。",
    ["Speak with Paouala in Southern San d'Oria (M-8); she asks for Mary's Milk."] = "南サンドリア(M-8)のPaoualaからメリーのミルクを頼まれる。",
    ["Obtain a Mary's Milk. It drops from Stray Mary in Konschtat Highlands, and can also be bought at the Auction House."] = "コンシュタット高地のStray Maryか競売からメリーのミルクを入手。",
    ["Trade the Mary's Milk to Paouala to complete the quest and receive 5,000 gil."] = "Paoualaにミルクを渡し5,000ギル。",
    ["Speak with Maugie in Southern San d'Oria (L-9) to start the quest."] = "南サンドリア(L-9)のMaugieから受領。",
    ["Travel to Jugner Forest and click on the signposts at the following spots to clean them: (E-11), (G-8), (H-7) and (J-5)."] = "ジャグナー森林(E-11)、(G-8)、(H-7)、(J-5)のSignpostを調べて清掃。",
    ["Speak with Maugie again after cleaning them to receive your reward, 1,500 gil."] = "Maugieに報告し1,500ギル。",
    ["Speak with Sharzalion in the Lion Springs Tavern in Southern San d'Oria (K-6) with Red Mage as your main job, level 40 or higher. You only have to be on Red Mage to start the quest, and you must answer \"Yes\" for it to start."] = "赤魔道士40以上で南サンドリア(K-6)、獅子の泉のSharzalionに話し「Yes」で受領。以後は他ジョブでも進行可能。",
    ["Go to Davoi and defeat Purpleflash Brukdok (BLM) at (E-9)/(F-9) to obtain a Davoi Storage Key. It drops one key and respawns after about 10 minutes; each Red Mage doing the quest needs a key. To get there, run along the creekbed from (J-10) to (D-8)."] = "ダボイの川(J-10)から(D-8)経由で(E-9)/(F-9)のPurpleflash Brukdok（黒）を倒しダボイ貯蔵庫のカギを得る。1体1個、再出現約10分、参加赤魔道士ごとにカギが必要。",
    ["Trade the Davoi Storage Key to the targetable Storage Hole, which moves randomly around the zone at the start or end of each game day and is usually in open areas. Known locations: (E-10), (F-6), (F-7), (F-9), (G-9), (G-10), (H-8), (I-7), (I-8), (J-7), (J-8), (K-7), (K-8), (K-9) and (K-10). The center island Storage Hole at (H-8) can be reached from the river."] = "移動するStorage Holeにカギを渡す。原文の候補は(E-10)、(F-6)、(F-7)、(F-9)、(G-9)、(G-10)、(H-8)、(I-7)、(I-8)、(J-7)、(J-8)、(K-7)、(K-8)、(K-9)、(K-10)。日付の切替前後に移動し、(H-8)中央島へは川から行ける。",
    ["You obtain the key item Orcish dried food after trading the key."] = "カギを渡すとオーキシュ・ドライフードを得る。",
    ["Return to Sharzalion to receive your Fencing Degen."] = "Sharzalionに報告してフェンスデーゲン。",
    ["Speak with Deraquien in Southern San d'Oria (G-8) for a cutscene."] = "南サンドリア(G-8)のDeraquienに話してイベント。",
    ["Go to La Theine Plateau and speak with Narvecaint (F-7) for another cutscene."] = "ラテーヌ高原(F-7)のNarvecaintに話す。",
    ["Return to Deraquien and speak with him again."] = "Deraquienに再度話す。",
    ["Go to Chateau d'Oraguille and speak with Halver. If you have just cleared The Voracious Resurgence, you will have to rezone after the cutscene and speak with him again."] = "ドラギーユ城のHalverに話す。蝕世を終えた直後はイベント後エリアチェンジして再会話が必要な場合がある。",
    ["Speak with Deraquien again."] = "Deraquienに話す。",
    ["Speak with Phillone (D-7)."] = "(D-7)のPhilloneに話す。",
    ["Go back and speak with Deraquien."] = "Deraquienへ戻る。",
    ["Head to Jugner Forest through King Ranperre's Tomb. If you have access to the Proto-Waypoint, it is the fastest way to reach the location."] = "龍王ランペールの墓経由でジャグナー森林へ。開通済みならProto-Waypointが早い。",
    ["Click the ??? at (F-5) between 18:00 and 4:00 to spawn two NMs, Giollemitte B Feroun and Skeleton Esquire. Both must be defeated to proceed."] = "18:00〜04:00に(F-5)の???を調べ、Giollemitte B FerounとSkeleton Esquireを出して両方倒す。原文はその後の手順を省略している。",
    ["Speak with Sobane in Southern San d'Oria (D-6); she asks you to bring her a Cathedral Tapestry."] = "南サンドリア(D-6)のSobaneから国教会認定聖布を頼まれる。",
    ["Obtain a Cathedral Tapestry. It drops from Orcish Fighter enemies in Fort Ghelsba or the Yughott Grotto. Trade it to Sobane."] = "ゲルスバ砦／ユグホトの岩屋のOrcish Fighterから国教会認定聖布を入手しSobaneに渡す。",
    ["Travel to Selbina and speak with Abelard (G-9)."] = "セルビナ(G-9)のAbelardに話す。",
    ["Go to Ordelle's Caves and obtain an Ordelle Chest Key from the monsters inside. Certain monsters in the cave drop it; to reach that area take path D on map 1, drop into the southeastern hole shown on map 2, then take path E. The high-level monsters Buds Bunny, Swagger Spruce and Targe Beetle do not aggro."] = "オルデール鍾乳洞の敵からOrdelle Chest Keyを入手。原文の経路はマップ1のD→マップ2南東の穴→E。高レベルのBuds Bunny／Swagger Spruce／タージェ Beetleは非アクティブ。",
    ["Use the key on a chest inside to receive the key item Torn-out pages."] = "Treasure Chestをカギで開け幻の数ページを入手。",
    ["Return to Abelard."] = "Abelardに戻る。",
    ["Speak with Sobane to complete the quest."] = "Sobaneに報告して完了。",
    ["Speak with Sobane in Southern San d'Oria (D-6) to begin the quest. You must zone after finishing Signed in Blood."] = "貴き血流れて後にエリアチェンジし、南サンドリア(D-6)のSobaneから受領。",
    ["Obtain an Attohwa Ginseng, which drops from Gallinipper, Ogrefly and Monarch Ogrefly enemies in Attohwa Chasm."] = "アットワ地溝のGallinipper／Ogrefly／Monarch Ogreflyからアットワジンセンを入手。",
    ["Enter Carpenters' Landing from the entrance in Jugner Forest (J-8)."] = "ジャグナー森林(J-8)からギルド桟橋へ。",
    ["Speak with Anguenet (J-10) and trade him the Attohwa Ginseng."] = "(J-10)のAnguenetにアットワジンセンを渡す。",
    ["Return to Sobane for your reward."] = "Sobaneに戻り報酬。原文ではバージでの聞き込みや王国認定ゴールド調達等の中間手順が省略されている。",
    ["Speak with Rouva on the west side of Victory Square in Southern San d'Oria (I-8) to begin the quest. She asks you to bring her a sprig of Rivernewort. This quest requires the Chains of Promathia pack."] = "プロマシア導入が必要。南サンドリア(I-8)凱旋広場西のRouvaからリヴェーヌワートを頼まれる。",
    ["The key item Rivernewort is found at a ??? in either Riverne - Site #B01 or Riverne - Site #A01. To reach either you need Giant Scale(s), or the Home Point warps, to teleport through the Unstable Displacements."] = "リヴェーヌ岩塊群サイトB01か#A01の???でリヴェーヌワートを入手。Unstable Displacement通過には巨大な鱗、またはHome Point転送を利用。",
    ["In Riverne - Site #A01 the ??? is on the island at (E-8) that holds the zone to Monarch Linn. Two Giant Scales are required, and the Home Point warp places you at (I-9)."] = "#A01の???は帝龍の飛泉入口の島(E-8)。通常経路はGiant Scale2枚が必要。Home Point転送先は(I-9)。",
    ["In Riverne - Site #B01 the ??? is on the island at (E-7), just before the final Stable Displacement heading toward Monarch Linn. One Giant Scale, or the Home Point warp, is required."] = "#B01の???は帝龍の飛泉方面の最後のStable Displacement直前(E-7)。Giant Scale1枚かHome Point転送を使う。",
    ["Once you have the Rivernewort, return to Rouva for your reward, a Page from Miratete's Memoirs. Like other Experience Points scroll quests, it can be completed once per Conquest tally."] = "Rouvaに報告してミラテテ様言行録。コンクェスト集計ごとに1回。",
    ["Speak with Amutiyaal in Southern San d'Oria (L-6) to receive a Red Sentinel badge and begin the quest. This quest requires the Treasures of Aht Urhgan pack."] = "アトルガン導入が必要。南サンドリア(L-6)のAmutiyaalから赤色の山猫バッジを受け取る。",
    ["Speak with 20 people around the kingdom's cities; for example Daggao in Southern San d'Oria (K-5), Rouva in Southern San d'Oria (I-8), Giaunne in Northern San d'Oria (I-9) and Perdiouvilet in Port San d'Oria (G-7)."] = "国内20人に話す。例：南サンドリア(K-5)のDaggao、(I-8)のRouva、北サンドリア(I-9)のGiaunne、サンドリア港(G-7)のPerdiouvilet。原文は全員分の一覧を収録していない。",
    ["Once you have spoken to all 20 people, return to Amutiyaal, who takes your Red Sentinel badge and gives you a Red invitation card."] = "20人全員に話したらAmutiyaalへ戻り、バッジと引換えに赤色の招待券を得る。",
    ["After joining Salaheem's Sentinels, speak with Naja Salaheem with the invitation card to be rewarded with Imperial currency; the more Lure of the Wildcat quests you have completed, the greater the reward."] = "サラヒム・センチネル入社後、招待券を持ちNaja Salaheemに話すと皇国貨幣。各国の山猫クエスト完了数で報酬が増える。",
    ["Speak with Atelloune in Southern San d'Oria (L-6) for a cutscene that starts the quest. This quest requires the Wings of the Goddess pack and follows Seeing Spots."] = "Seeing Spots完了とアルタナ導入が必要。南サンドリア(L-6)のAtellouneから受領。",
    ["Trade her a Ladybug Wing for a cutscene and to receive your reward."] = "レディバグの上翅をAtellouneに渡して報酬。",
    ["You cannot start this quest while another Weapon Skill quest is active; return to the person who gave it and quit it first. You need Polearm skill 240 or higher, level 71 and the Rise of the Zilart pack."] = "他WSクエスト進行中は先に取消。両手槍240以上、レベル71以上、ジラート導入が必要。",
    ["Speak with Balasiel in Southern San d'Oria (F-7) to receive the key item Weapons Training Guide and the Spear of Trials."] = "南サンドリア(F-7)のBalasielからWeapons Training Guideとトライアルスピアを得る。",
    ["Break the latent on the Spear of Trials before doing the rest of the quest. Each skillchain gives points: 5 with no skillchain, 7 at level 1, 9 at level 2 and 11 at level 3."] = "トライアルスピアの潜在を消す。原文配点は連携なし5、レベル1で7、2で9、3で11。小売版とは配点差がある。",
    ["Trade the Spear of Trials back to Balasiel."] = "トライアルスピアをBalasielに返す。",
    ["Obtain a Sahagin Key, which the quest requires."] = "必要なサハギンのカギを入手。",
    ["Go back and speak with Balasiel to receive your reward."] = "Balasielに報告して報酬。原文は海蛇の岩窟での中間NM戦を省略している。",
    ["Speak with Norejaie in Southern San d'Oria (K-6) to begin the quest. You must be level 25 or higher, and you cannot get it while the quest Eco-Warrior (Bastok) or Eco-Warrior (Windurst) is active."] = "25以上で南サンドリア(K-6)のNorejaieから受領。他国のEco-Warriorと同時受領不可。",
    ["Enter Ordelle's Caves from the (F-7) entrance in La Theine Plateau; the Survival Guide warp takes you right there."] = "ラテーヌ高原(F-7)入口からオルデール鍾乳洞へ。Survival Guideでも入口付近に着く。",
    ["Speak with Rojaireaut (G-3) to have your level capped at 25. Everyone in your party or alliance needs the level cap applied to them, and it has no timer."] = "(G-3)のRojaireautに話し25制限を受ける。原文ではPT・アライアンス全員に制限が必要で、制限自体に時間切れはないと説明。",
    ["Stink Bat enemies link to Hognosed Bat enemies."] = "Stink BatはHognosed Batにリンクするので注意。",
    ["Go to the ??? at the northeast corner of (G-9)."] = "(G-9)北東角の???へ。原文はNM討伐・証拠回収の説明を省略している。",
    ["Return to Norejaie to complete the quest. You can only complete one Eco-Warrior quest a week; wait until the next Conquest tally before accepting another."] = "Norejaieに報告。退魔クエストは各国合わせ週1回、次のコンクェスト集計を待って再受領。",
    ["Speak with Miageau at (L-7) in Northern San d'Oria, just past the entrance to the Cathedral."] = "北サンドリア(L-7)、大聖堂入口奥のMiageauに話す。",
    ["Trade 10 gil to Nouveil nearby to receive a Blessed Waterskin."] = "近くのNouveilに10ギルを渡し祝福された革袋を得る。",
    ["Travel to East Ronfaure."] = "東ロンフォールへ。",
    ["Reach the Cheval River target at (H-5)."] = "(H-5)のCheval Riverへ。",
    ["Trade the Blessed Waterskin to the Cheval River to obtain Cheval Water."] = "祝福された革袋をCheval Riverに渡しシュヴァル川の水を汲む。",
    ["Return to Miageau in Northern San d'Oria."] = "北サンドリアのMiageauへ戻る。",
    ["Trade the Cheval Water to Miageau to receive the Wing Pendant."] = "シュヴァル川の水を渡しウィングペンダント。",
    ["Speak with Ailbeche in Northern San d'Oria (J-9) for a cutscene that starts the quest. You must be level 10 or higher."] = "原文条件は10以上。北サンドリア(J-9)のAilbecheに話して開始。",
    ["Find his father, Exoroche, in Southern San d'Oria at (K-7) in Helbort's Blade."] = "南サンドリア(K-7)の武器店で父Exorocheを探す。",
    ["Return to Ailbeche and speak with him again for a cutscene. You receive the Willow Fishing Rod as your reward."] = "Ailbecheに戻りイベント。ヤナギの釣竿を得る。",
    ["To activate the Paladin quest Sharpening the Sword, trade the fishing rod back to Ailbeche. Doing so also changes your title to Family Counselor."] = "剣に磨きをかけての条件を満たすには釣竿をAilbecheに返す。称号もFamily Counselorへ変わる。",
    ["Speak with Abeaule in Northern San d'Oria (F-8); he needs someone to fill an order. Accept the task and he gives you a Supplies Order."] = "北サンドリア(F-8)のAbeauleからSupplies Orderを預かる。",
    ["Take the Supplies Order to the tower at (I-11) in West Ronfaure and trade it to Phairet to receive the Batagreens. Trading him 50 gil also gets you the Batagreens, as long as the quest has been flagged."] = "西ロンフォール(I-11)の塔のPhairetへ注文書を届けバタリア菜を得る。受領後なら50ギルを渡しても入手可能。",
    ["Take the Batagreens back to Abeaule for your reward."] = "Abeauleにバタリア菜を届けて報酬。",
    ["Speak with Abioleget in Northern San d'Oria (M-7); he needs you to deliver Blue Peas."] = "北サンドリア(M-7)のAbiolegetからブルーピースの配達を受ける。",
    ["Trade him 70 gil to receive the Blue Peas."] = "Abiolegetに70ギルを渡しブルーピースを得る。",
    ["Look for Andelain in East Ronfaure at (J-11) and give him the peas."] = "東ロンフォール(J-11)のAndelainへ豆を届ける。",
    ["Return to Abioleget for your reward."] = "Abiolegetに報告して報酬。",
    ["Speak with Pagisalis in Northern San d'Oria (M-6) to start the quest; he wants two lumps of beeswax to make candles."] = "北サンドリア(M-6)のPagisalisからロウソク用のBeeswax2個を頼まれる。",
    ["Obtain Beeswax x2."] = "Beeswax2個を用意。",
    ["Trade the Beeswax x2 to Pagisalis for your reward."] = "PagisalisにBeeswax2個を渡して報酬。",
    ["Speak with Helbort at the weapon shop in Southern San d'Oria (K-7) after completing Father and Son; you receive the key item Weapons order."] = "父と子後、南サンドリア(K-7)の武器店のHelbortからWeapons orderを受け取る。",
    ["Bring the Weapons order to Alexius in Jugner Forest (I-6), near the lake; you receive the key item Weapons receipt."] = "ジャグナー森林(I-6)湖付近のAlexiusにWeapons orderを渡しWeapons receiptを得る。Wikiの座標は(I-5)。",
    ["Return to Helbort to complete the quest and receive your reward."] = "Helbortへ戻って報酬。",
    ["Speak with Abeaule in Northern San d'Oria (F-8)."] = "北サンドリア(F-8)のAbeauleに話す。",
    ["Go to Southern San d'Oria (G-6) and speak with Amaura. She needs certain ingredients to brew the medicine and gives you Amaura's formula, which lists them: 1 Insect Wing, 1 Malboro Vine and 1 Zinc Ore."] = "南サンドリア(G-6)のAmauraからAmaura's formulaを得る。材料は虫の翅、モルボルのつる、亜鉛鉱各1個。",
    ["Gather those items and trade them to Amaura to receive the key item Cold medicine."] = "材料を集めAmauraに渡しCold medicineを得る。",
    ["Deliver the Cold medicine to Abeaule for your reward, 2,100 gil."] = "AbeauleへCold medicineを届け2,100ギル。",
    ["Optional: speak with Kuu Mohzolhi in Northern San d'Oria (F-8). She does not say it at first, but she would like a Marguerite."] = "任意：北サンドリア(F-8)のKuu Mohzolhiに話す。希望する花はマーガレット。",
    ["Obtain a Marguerite. It can be bought at the Auction House, or from Areebah in Upper Jeuno (H-6) for 120 gil."] = "マーガレットを競売かジュノ上層(H-6)のAreebah（120ギル）で用意。",
    ["Trade the Marguerite to Kuu Mohzolhi to complete the quest."] = "Kuu Mohzolhiにマーガレットを渡して完了。",
    ["If you trade her the wrong flower, such as one meant for the other two Mog House exit quests, she keeps it and you will have to get another."] = "他国の出口拡張用など、別の花を渡すと回収されるので用意し直す。",
    ["Speak with Belgidiveau in Northern San d'Oria (G-8) to begin the quest."] = "北サンドリア(G-8)のBelgidiveauから受領。",
    ["Speak with Novalmauge in Bostaunieux Oubliette (G-8)."] = "ボストーニュ監獄(G-8)のNovalmaugeに話す。",
    ["Trade Novalmauge a Dahlia to receive a Neutralizer."] = "Novalmaugeにダリアを渡しNeutralizerを得る。",
    ["Return to Belgidiveau to complete the quest."] = "Belgidiveauに戻って完了。",
    ["Buy a Cupboard from the furniture shop in Northern San d'Oria (F-8) and put it in your Mog House."] = "北サンドリア(F-8)の家具店でカップボードを買いモグハウスに設置。",
    ["Zone out of and back into your Mog House, then wait some time (between 10 and 15 real-world minutes)."] = "モグハウスを出入りし、地球時間10〜15分ほど待つ、と原文に記載。",
    ["Talk to your Moogle. He says he found something and gives you a Small teacup. If he does not give it to you, you may not have waited long enough."] = "Moogleに話しSmall teacupを得る。もらえなければ待ち時間を確認。",
    ["Return to the furniture shop and speak with Morunaude twice."] = "家具店のMorunaudeに2回話す。",
    ["Speak with Calovour in the Cathedral (M-6)."] = "大聖堂(M-6)のCalovourに話す。",
    ["Bring Calovour a Mistletoe to complete the quest."] = "Calovourへ宿木を渡して完了。",
    ["Speak with Dauperiat in Northern San d'Oria (I-10) to obtain a Suspicious envelope, and deliver it to Halver in Chateau d'Oraguille."] = "北サンドリア(I-10)のDauperiatからSuspicious envelopeを預かり、ドラギーユ城のHalverに届ける。",
    ["Return to Dauperiat, who now asks you to do a second job for him. If you choose to keep helping him you lose fame; if you choose no, you can proceed to the next quest, The Setting Sun."] = "Dauperiatへ戻り次の仕事を選ぶ。原文は承諾で名声低下、断ると斜陽へ進めるとするが、Wikiでは名声は上昇し別依頼との関連も異なる。実装差に注意。",
    ["If you say yes, he asks you to get the floor plans back from the Orcs. Orcish Serjeant enemies in Fort Ghelsba and Batallia Downs can drop the Castle Floor Plans."] = "承諾したらOrcish Serjeantから王城の設計図を回収。原文の生息地はゲルスバ砦／バタリア丘陵。",
    ["Trade the Castle Floor Plans back to Dauperiat for your reward."] = "Dauperiatに王城の設計図を渡して報酬。",
    ["Speak with Vamorcote in Northern San d'Oria (F-5) to begin the quest."] = "北サンドリア(F-5)のVamorcoteから受領。",
    ["Head to the island in Batallia Downs (J-11). The only way to get there is through The Eldieme Necropolis: enter it from (I-10) in Batallia Downs. The Survival Guide puts you in the correct part of the Eldieme for this quest."] = "バタリア丘陵(I-10)からエルディーム古墳を抜け、孤島(J-11)へ。Survival Guideでも目的の古墳区画へ着く。",
    ["Once inside, hug the south side until you reach a large room at (G-9), and fall through the grave in the center of the room. To reach the room at (G-9) you need someone to operate the gates for you, or the Magicked astrolabe."] = "古墳内を南壁沿いに進み(G-9)の大部屋中央の墓穴から下へ。扉操作の協力者かMagicked astrolabeが必要。",
    ["Defeat Ahtu to obtain an Engraved Key."] = "Ahtuを倒し紋章の刻まれたカギを得る。",
    ["Trade the Engraved Key to Vamorcote to complete the quest and receive 10,000 gil."] = "Vamorcoteへカギを渡し10,000ギル。",
    ["Speak with Secodiand in Northern San d'Oria (F-6) to start the quest; he wants two bat wings."] = "北サンドリア(F-6)のSecodiandからBat Wing2個を頼まれる。",
    ["Obtain Bat Wing x2."] = "Bat Wing2個を用意。",
    ["Trade the Bat Wing x2 to Secodiand to complete the quest and receive 200 gil."] = "SecodiandにBat Wing2個を渡し200ギル。",
    ["Speak with Maloquedil in Northern San d'Oria (J-8) to begin the quest."] = "北サンドリア(J-8)のMaloquedilから受領。",
    ["Obtain Shaman Garlic x2, which drops from Orcish Cursemaker enemies."] = "Orcish CursemakerからShaman Garlic2個を入手。",
    ["Trade him the 2 Shaman Garlic to complete the quest and receive 900 gil."] = "MaloquedilにShaman Garlic2個を渡し900ギル。",
    ["Speak with Eperdur at (M-7) in Northern San d'Oria. He gives you the Seal of banishing, which you must place on a ??? target. You must be level 10 or higher."] = "10以上で北サンドリア(M-7)のEperdurからSeal of banishingを預かり、指定の???に置く。",
    ["Travel to Gusgen Mines from Konschtat Highlands. The fastest way is the Survival Guide, then Zulkheim, then Gusgen Mines."] = "コンシュタット高地からグスゲン鉱山へ。Survival Guideのザルクヘイム→グスゲン鉱山が早い。",
    ["Head north, down the stairs, and hit the lever to go through the middle door at (H-6). Then north again, down the stairs, and hit the lever for the left door this time."] = "北へ階段を下り、(H-6)のレバーで中央の扉を開ける。さらに北へ下り、次は左の扉のレバーを使う。",
    ["Take a left at the T intersection, then head north. Go west until another split."] = "T字路を左、北へ進み、次の分岐まで西へ。",
    ["Check the ???."] = "???を調べる。",
    ["Speak with Eperdur again for your reward. You must zone before you can be offered the follow-up quest, Sorcery of the North."] = "Eperdurに報告して報酬。後続北の地の秘法はエリアチェンジ後に受領。",
    ["Zone after completing Healing the Land to begin this quest."] = "あまねく地に祝福を後にエリアチェンジする。",
    ["Speak with Eperdur in Northern San d'Oria (M-7), on the second level of the Cathedral."] = "北サンドリア(M-7)、大聖堂2階のEperdurに話す。",
    ["Obtain a Fei'Yin Chest Key by defeating Shadow, Underworld Bat and Ore Golem enemies in that area."] = "フェ・インのShadow／Underworld Bat／Ore Golemからフェ・イン Chest Keyを入手。",
    ["Open a treasure chest using either the key or Thief's Tools to obtain the key item Fei'Yin magic tome."] = "カギまたはThief's ToolsでTreasure Chestを開け、フェ・イン magic tomeを得る。",
    ["Return to Eperdur to receive your reward."] = "Eperdurに戻って報酬。",
    ["As a White Mage, level 40 or higher, speak with Narcheral upstairs in the Cathedral in Northern San d'Oria (M-6) to get the quest. You can do the rest of the quest on any job."] = "白魔道士40以上で北サンドリア(M-6)、大聖堂上階のNarcheralから受領。以後は他ジョブでも進行可能。",
    ["Head to (B-8), the Secret Beach, in Valkurm Dunes. The Survival Guide teleport to Gustav Tunnel, then walking out, leaves you right next to the spawn point."] = "バルクルム砂丘(B-8)隠し海岸へ。グスタフの洞門のSurvival Guideから外へ出ると近い。",
    ["Between 18:00 and 5:00 a ??? appears near the Song Runes. Click it to spawn Marchelute."] = "18:00〜05:00にSong Runes付近に現れる???を調べMarcheluteを出す。",
    ["Marchelute drops a Tavnazia Pass."] = "Marcheluteからタブナジア通行手形を入手。",
    ["Take the Tavnazia Pass back to Narcheral to complete the quest and receive your Blessed Hammer."] = "Narcheralにタブナジア通行手形を渡しブレスドハンマー。",
    ["To start this quest you must first trade the fishing rod from Father and Son back to Ailbeche. You need to be a Paladin of level 40 or higher, and to have completed A Knight's Test."] = "父と子の釣竿をAilbecheに返し、騎士登用試験を完了しておく。ナイト40以上が必要。",
    ["Speak with Ailbeche near Home Point #2 in Northern San d'Oria (J-8) to begin the quest; he asks you for an Ordelle whetstone."] = "北サンドリア(J-8)、Home Point #2付近のAilbecheからオルデール砥石を頼まれる。",
    ["Speak with Sobane in Southern San d'Oria (D-6). Be sure to speak with her twice if you get a cutscene the first time."] = "南サンドリア(D-6)のSobaneに話す。初回に別イベントが出たら2回話す。",
    ["Enter Ordelle's Caves from the entrance in La Theine Plateau (F-7), which puts you on map 2. Taking the Survival Guide to Ordelle's Caves is the fastest route."] = "ラテーヌ高原(F-7)からオルデール鍾乳洞の原文マップ2へ。Survival Guideが早い。",
    ["Take the first left and walk toward (I-6) on map 2 to use exit B, which puts you on map 1."] = "最初を左折し、原文マップ2(I-6)の出口Bからマップ1へ。",
    ["Return to Ailbeche to end the quest and receive your reward."] = "Ailbecheへ戻って報酬。原文は砥石のNM戦と回収の説明を省略している。",
    ["Speak with Ailbeche in Northern San d'Oria (J-8)."] = "北サンドリア(J-8)のAilbecheに話す。",
    ["Return to Ailbeche and speak with him again."] = "Ailbecheにもう一度話す。",
    ["Trade Ailbeche a Giant Shell Bug. You can buy one at the Auction House, or go to Crawlers' Nest and defeat Dreadbug through the ???. Dreadbug can be spawned again once per game day while the quest is active."] = "Ailbecheに大ヨロイ蟲を渡す。競売かクロウラーの巣の???で出すDreadbugから入手。原文では受領中ヴァナ1日ごとに再出現可能と説明。",
    ["Be careful to do the NPC interactions above: if you skip them, you use up the Giant Shell Bug you get in the next step."] = "上記NPC会話を省くと、次に使う大ヨロイ蟲を消費するので先に済ませる。",
    ["Fish in Castle Oztroja with a rod used for catching big fish, using the Giant Shell Bug as bait. Bring more than one Giant Shell Bug."] = "オズトロヤ城で大物用の竿と大ヨロイ蟲を餌に釣る。餌は複数用意。",
    ["The Odontotyrannus monster is fished up; defeat it and it drops Odontotyrannus."] = "釣り上げたオドントティラヌスを倒し、同名の魚を入手。",
    ["Return to Ailbeche and trade him the Odontotyrannus."] = "Ailbecheにオドントティラヌスを渡す。",
    ["Trade the Odontotyrannus to Zaldon, inside the Fisherman's Guild in Selbina (H-9), to receive the Knight's boots."] = "セルビナ(H-9)漁師ギルドのZaldonに魚を渡しKnight's bootsを得る。原文は以降の報告手順を省略している。",
    ["Make sure your main job is Dragoon, level 40 or higher, when you speak with Miaux in Northern San d'Oria (E-6). She asks you to obtain an Altepa polishing stone. After speaking to her you can change to another job to do the rest of the quest."] = "竜騎士40以上で北サンドリア(E-6)のMiauxからアルテパ砥石を頼まれる。以後は他ジョブでも進行可能。",
    ["Examine the ??? in Eastern Altepa Desert, in the lower part of (H-8), to spawn Decurio I-III. The Survival Guide warp puts you very near; Teleport-Altep is another good option."] = "東アルテパ砂漠(H-8)南部の???でDecurio I-IIIを出す。Survival Guideかテレポルテを利用。",
    ["Defeat Decurio I-III, then examine the ??? again to receive the Altepa polishing stone."] = "Decurio I-IIIを倒して???を再調査し、アルテパ砥石を得る。",
    ["Speak with Miaux again to receive your reward."] = "Miauxに報告して報酬。",
    ["Speak with Aurege in Northern San d'Oria (F-3), near Home Point #4 outside the Carpenter's Guild, to start the quest."] = "北サンドリア(F-3)、木工ギルド外のHome Point #4付近のAuregeから受領。",
    ["Optional: speak with Nonterene (I-10) at the Parade Grounds near Victory Arch."] = "任意：凱旋門近くの閲兵場(I-10)のNontereneに話す。",
    ["Find Varchet in Southern San d'Oria at (L-6), right next to the fountains. You need to gamble against him; each attempt costs 5 gil, so keep trying until you win. You can still gamble with him after the quest is complete."] = "南サンドリア(L-6)噴水横のVarchetと賭け勝負。1回5ギル、勝つまで挑む。完了後も勝負は可能。",
    ["After winning, return and speak with Aurege for your reward. The quest does not appear in your log until it is completed."] = "勝ったらAuregeに報告。完了までオファーリストに載らない。",
    ["Speak with Rondipur in Northern San d'Oria (F-6) to begin the quest. Only one Escort for Hire quest can be active at a time, and only one can be completed each Conquest Tally."] = "北サンドリア(F-6)のRondipurから受領。護衛は各国合わせ同時1件、コンクェスト集計ごとに1回。",
    ["Head to Eldieme Necropolis from Batallia Downs (I-10). As soon as you zone in you receive a cutscene, after which the NPC Cannau appears. You can summon Trusts, but zoning in with an Adventuring Fellow makes the escort NPC disappear."] = "バタリア丘陵(I-10)からEldieme Necropolisに入るとイベントでCannauが現れる。フェイスは呼べるが、フェロー連れで入ると護衛NPCが消える。",
    ["You have 30 minutes to complete the quest."] = "制限時間は30分。",
    ["Return to Rondipur for your reward."] = "Rondipurに戻って報酬。原文は護衛中の操作や終了証の説明を省略している。",
    ["You must already have signed up with the Woodworking Guild: speak to the Guild Master, Cheupirudaux, in Northern San d'Oria (F-3)."] = "北サンドリア(F-3)の木工ギルド長Cheupirudauxに話し、先にギルドへ入門。",
    ["Speak with Ramua in Northern San d'Oria (E-3) for a cutscene that begins the quest. She gives you the Timber survey checklist and a Hatchet."] = "(E-3)のRamuaからTimber survey checklistとまさかりを受け取る。",
    ["Travel to Jugner Forest and log the five items on the checklist: Arrowwood Log, Ash Log, Yew Log, Willow Log and Walnut Log. Each one you log shows a message that data was recorded; you must log them yourself and cannot buy them from shops or the Auction House."] = "ジャグナー森林でアローウッド原木、アッシュ原木、ユー原木、ウィロー原木、ウォルナット原木を自分で伐採し、調査記録をつける。購入だけでは記録にならない。",
    ["Trade the logs to Ramua for your reward. She also returns the logs to you."] = "Ramuaに原木を渡して報酬。原木も返却される。",
    ["You must be a Summoner of level 20 or higher. Speak with Castilchat in Northern San d'Oria (E-7) to begin the quest and obtain a Mini tuning fork of ice."] = "原文条件は召喚士20以上。北サンドリア(E-7)のCastilchatから氷の音叉・改を得る。小売版の開始条件は15以上。",
    ["Prepare for the battle. Whenever you are ready, trade the tuning fork to Castilchat to be transported to the arena."] = "準備ができたらCastilchatに音叉を渡して転送してもらう。",
    ["Trade the fork to the Ice Protocrystal to enter the fighting arena."] = "Ice Protocrystalに音叉を渡してBFへ入る。",
    ["Defeat Shiva Prime to complete the quest."] = "Shiva Primeを倒して完了。",
    ["You can get the Mini tuning fork again from Castilchat at any time and repeat the fight, but he will no longer teleport you to the Cloister."] = "Mini tuning forkは再入手・再戦できるが、完了後はCastilchatから回廊へ転送してもらえなくなる。",
    ["Speak with Gulmama in Northern San d'Oria (E-7) to get the quest. If you are sure you have the required fame but she does not offer it, keep speaking with her until her text changes. Once you receive the key item Tuning fork of ice you can safely undertake the quest."] = "北サンドリア(E-7)のGulmamaから氷の音叉を得る。名声が足りているのに受領できなければ会話を繰り返す。",
    ["Go to Fei'Yin. In the basement (map B) travel to (I-5) to find the entrance to the Cloister of Frost. Each party member must have their own Tuning fork of ice."] = "フェ・イン地下（原文マップB）(I-5)から凍結の回廊へ。参加者全員にそれぞれ氷の音叉が必要。",
    ["Defeat Shiva Prime to receive the key item Whisper of frost."] = "Shiva Primeを倒し氷の息吹を得る。",
    ["Return to Gulmama with the whisper and she offers several rewards, including the ability to summon Shiva. You can only select one reward at a time, and you can repeat the quest once per Earth day."] = "Gulmamaに息吹を持ち帰り、シヴァとの契約等から1つ選ぶ。地球時間の日付が変わると再受領できる。",
    ["To save travel time to the Cloister of Frost, you can use the Mini tuning fork of ice from the quest Trial-Size Trial by Ice. You must be on Summoner as your main job: get the Mini tuning fork from Castilchat, trade the fork back to Castilchat, and enter the Protocrystal normally. As long as you do not clear the level 20 version, you may warp to the Cloister as many times as you like."] = "回廊への近道に氷の試練・改のMini tuning forkを使える。召喚士でCastilchatから受け取り渡して転送後、通常のクリスタルから入る。20制限版をクリアしない限り繰り返し転送可能。",
    ["You may also keep the whisper to meet the requirements of the quest The Moonlit Path."] = "The Moonlit Pathの条件用に息吹を保持してもよい。",
    ["Speak with Olbergieut in the Cathedral in Northern San d'Oria (L-7) to begin the quest; you receive the Scripture of Wind."] = "北サンドリア(L-7)、大聖堂のOlbergieutから風の教典を受け取る。",
    ["Travel to (K-8) in La Theine Plateau, at the tail end wall of the Crag of Holla, and look for the NPC Faurbellant."] = "ラテーヌ高原(K-8)、ホラの岩の端の壁際のFaurbellantを探す。",
    ["Speak with Faurbellant, who gives you the Scripture of Water."] = "Faurbellantに話しScripture of Waterを受け取る。",
    ["Return to Olbergieut and speak with him to end the quest."] = "Olbergieutに戻り報告。",
    ["Speak with Miene by the water in Port San d'Oria (I-8); a cutscene reveals a burglary in progress."] = "サンドリア港(I-8)水辺のMieneに話して盗難イベントを見る。",
    ["Speak with Altiret, who asks you to retrieve the stolen item."] = "Altiretから盗品の回収を依頼される。",
    ["Speak with Miene again to obtain a clue, an Eagle Button."] = "Mieneに再度話し、手がかりのワシ印の銀ボタンを得る。",
    ["Head to West Ronfaure and look for Esca inside a tower at (F-6)."] = "西ロンフォール(F-6)の塔のEscaへ。",
    ["Trade the Eagle Button to her, which prompts her to admit she was the thief."] = "Escaにワシ印の銀ボタンを渡して話を聞く。",
    ["After receiving the Gilt Glasses, return them to Altiret for your reward."] = "形見の金縁めがねを受け取りAltiretへ返して報酬。",
    ["Speak with Gulemont in Port San d'Oria (G-7) to begin the quest. This quest follows A Taste For Meat."] = "肉料理後、サンドリア港(G-7)のGulemontから受領。",
    ["Travel to West Ronfaure and locate a ???. It appears in one of three places: the border of (G-10) and (G-11), (G-9) at the outpost, or (F-11) in the south part of the square, close to a wall."] = "西ロンフォールの???を探す。原文候補は(G-10)/(G-11)境、(G-9)アウトポスト、(F-11)南側の壁付近。",
    ["Touch the ??? to obtain Gulemont's document."] = "???を調べギュルモンの証文を得る。",
    ["Return to Gulemont and speak with him to end the quest."] = "Gulemontに戻って完了。",
    ["Speak with Regine in Port San d'Oria (J-8) to begin the quest, and choose the option to look for work."] = "サンドリア港(J-8)のRegineに仕事を探す選択肢で受領。",
    ["Hand out the 15 Magicmart Flyers, only to townsfolk and not to adventurers. While the quest is active, when you come close to an NPC who should get a flyer, a message in /say tells you that the NPC looks over curiously for a moment."] = "冒険者ではなく街のNPCに魔法用品店のチラシを15枚配る。受領中は対象に近づくと/sayに「こちらを見た」旨のヒントが出る。",
    ["You must hand out all 15 flyers or the quest will not be completed. If you lose them, you can buy more from Regine for 10 gil each."] = "15枚すべて配る必要がある。失くした分はRegineから1枚10ギルで買い直せる。",
    ["Once all 15 Magicmart Flyers have been distributed, return to Regine and speak with her to end the quest."] = "配り終えたらRegineに報告。",
    ["Speak with Fontoumant in Port San d'Oria (H-9). He asks you to deliver parcels to various NPCs in Port San d'Oria. You can only hold one parcel at a time, so deliver it and then return to him for another."] = "サンドリア港(H-9)のFontoumantから小包配達を受ける。同時に持てるのは1個、届けるたびに戻って次を受け取る。",
    ["Deliver the Magic Shop Parcel to Regine (J-8)."] = "魔法屋宛の小包を(J-8)のRegineに届ける。",
    ["Deliver the Auction Parcel to Apstaule, who is upstairs (H-10)."] = "競売所宛の小包を(H-10)上階のApstauleに届ける。",
    ["Deliver the Pub Parcel to Thierride (G-7)."] = "酒場宛の小包を(G-7)のThierrideに届ける。",
    ["Once all parcels are delivered, speak with Fontoumant again for your reward."] = "すべて届けたらFontoumantに報告。",
    ["Speak with Portaure in Cargo Room B, near Home Point #1 in Port San d'Oria (H-9), to accept the quest and obtain the Brugaire goods. Nighttime is the safest option."] = "サンドリア港(H-9)、Home Point #1付近の倉庫BのPortaureからブルゲール商会のブツを預かる。通関は夜が安全。",
    ["Take the next airship to Jeuno. You must go through Jeuno's Air Travel Agency before delivering to the Tenshodo, or the package will be damaged and the quest failed."] = "次の飛空艇でJeunoへ。必ず到着口のAir Travel Agencyを通過してから天晶堂へ届ける。省くと荷物破損で失敗する、と原文に記載。",
    ["If you pass through undetected, speak with Yin Pocanakhu in Lower Jeuno (J-8). If you are caught, your airship pass is revoked until midnight Japan time and the quest is failed."] = "見つからず通れたらジュノ下層(J-8)のYin Pocanakhuに届ける。発覚すると日本時間JSTの0時まで飛空艇利用制限を受け失敗。小売版では制限はJeuno発の便のみ。",
    ["Return to Portaure for your reward. Completing this quest raises your fame in Norg."] = "Portaureに報告して報酬。ノーグ名声も上がる。",
    ["Speak with Nogelle in Port San d'Oria (G-7) to start the quest; she wants three chunks of salt from Lufet's Lake."] = "サンドリア港(G-7)のNogelleからLufet Salt3個を頼まれる。",
    ["Obtain Lufet Salt x3."] = "Lufet Salt3個を用意。",
    ["Trade the Lufet Salt x3 to Nogelle to complete the quest and receive 600 gil."] = "NogelleにLufet Salt3個を渡し600ギル。",
    ["Speak with Antreneau and then Thierride, both in the Rusty Anchor Pub (G-7) in Port San d'Oria, to begin the quest."] = "サンドリア港(G-7)錆びた錨亭のAntreneau、Thierrideの順に話して開始。",
    ["Obtain Hare Meat x5. For low-level players, Wild Rabbit and Forest Hare enemies can be defeated for experience points and have a chance to drop it."] = "Hare Meat5個を用意。低レベルならWild Rabbit／Forest Hareで経験値と肉を狙える。",
    ["Trade the 5 Hare Meat to Thierride to complete the quest."] = "ThierrideにHare Meat5個を渡して完了。",
    ["Afterwards, speak with Antreneau and he gives you a Grilled Hare."] = "その後Antreneauに話し野兎のグリルを得る。",
    ["Speak with Vounebariont in Port San d'Oria (I-10) to begin the quest."] = "サンドリア港(I-10)のVounebariontから受領。",
    ["Trade Vounebariont 5 Beetle Shells to complete the quest and receive 750 gil. About 5 to 6 stacks of Beetle Shells raise your fame from around 1 up to the maximum of 9."] = "Beetle Shell5個を渡し750ギル。原文は5〜6ダースで名声1付近から最大9へ上がる目安を示すが、名声緩和やサーバー実装で異なる。",
    ["Speak with Arminibit and Ceraulian inside Cargo Room A in Port San d'Oria (I-9). You must be level 30 or higher and have the Rise of the Zilart pack."] = "レベル30以上とジラート導入が必要。サンドリア港(I-9)倉庫AのArminibitとCeraulianに話す。",
    ["If you have not yet completed the quest The Rumor, you can speak to Novalmauge a second time to accept it. You no longer need to complete The Rumor before advancing the job quest."] = "地下牢番人の噂未完了ならNovalmaugeに2回目の会話で受領できる。竜騎士取得の前に地下牢番人の噂を完了する必要はない。",
    ["The quest now shows up in your quests tab. Go to the Maze of Shakhrami and trade a Pickaxe to an Excavation Point to receive a Wyvern Egg."] = "オファーに載ったらシャクラミの地下迷宮のExcavation Pointにつるはしを使い飛竜の卵を入手。",
    ["Only people who have reached this point in the quest, or who have already completed it, may enter the battlefield."] = "BFへ入れるのはここまで進めた人かクリア済みの人。原文は卵入手からBFまでの中間手順を省略している。",
    ["Speak with Ceraulian inside Cargo Room A in Port San d'Oria (I-10) to begin the quest; you must be a Dragoon of level 50 or higher. Agree to help him obtain a Gold Hairpin. From this point on you can change to any other job."] = "竜騎士50以上でサンドリア港(I-10)倉庫AのCeraulianから金の髪飾りの依頼を受ける。以後は他ジョブでも進行可能。",
    ["Trade him a Gold Hairpin for a cutscene. A Gold Hairpin +1 will not work."] = "金の髪飾りを渡してイベント。+1品は不可。",
    ["Wait one minute, then speak to Ceraulian again."] = "地球時間1分待ちCeraulianに再度話す。",
    ["Speak with Miaux in Northern San d'Oria (E-6) to receive a Shiny earring."] = "北サンドリア(E-6)のMiauxから片方のピアスを得る。",
    ["Speak with Ardea in Bastok Markets (H-8), in front of the Goldsmithing Guild next to Home Point #4. If you have started the quest Rock Racketeer, you must finish it before Ardea lets you continue."] = "バストゥーク商業区(H-8)、彫金ギルド前Home Point #4付近のArdeaへ。Rock Racketeerを受領中なら先に終える必要がある。",
    ["Next, speak with Esca in West Ronfaure (F-6)."] = "西ロンフォール(F-6)のEscaに話す。",
    ["Return to Ceraulian for your reward."] = "Ceraulianに報告して報酬。原文はバタリア孤島での中間NM戦を省略している。",
    ["The quest begins with either Joulet (for The Competition) or Gallijaux (for The Rivalry) in Port San d'Oria (H-8)."] = "サンドリア港(H-8)のJoulet（根性）かGallijaux（意地）から受領。",
    ["Trade whichever brother you want to help Moat Carp and/or Forest Carp x10,000."] = "協力したい兄弟の片方に堀ブナ／森ブナを合計10,000匹渡す。",
    ["Ufanne in Port San d'Oria (H-8) keeps track of how many fish you have turned in, and to which brother. You may need to speak to her multiple times."] = "サンドリア港(H-8)のUfanneに納品数と相手を確認できる。会話を繰り返す必要がある場合がある。",
    ["Speaking to either brother tells you how many carp he has been traded by all players since the last server maintenance."] = "兄弟に話すと、前回サーバーメンテナンス以降に全プレイヤーが渡した総数を聞ける。",
    ["First go to the second floor of the house at (G-7) in Southern San d'Oria and read the diary there until you have read up to Page 4. This quest requires the Chains of Promathia pack, and follows A Squire's Test II."] = "プロマシア導入が必要。南サンドリア(G-7)民家2階の日記を4ページまで読む。原文は見習い登用試験2を前提とするが、Wikiでは同依頼の完了は不要。",
    ["Speak with Antreneau in Port San d'Oria (G-7) to flag the quest."] = "サンドリア港(G-7)のAntreneauから受領。",
    ["Head to Oldton Movalpolos and defeat Moblin Ashman and Moblin Gurneyman enemies until one drops a Moblin Hotrok. Alternatively, go to Newton Movalpolos and defeat Moblin Groundman enemies."] = "ムバルポロス旧市街のMoblin Ashman／Gurneymanか、ムバルポロス新市街のMoblin Groundmanからモブリンの温石を入手。",
    ["Head to Uleguerand Range and climb to the top, where Jormungand spawns."] = "ウルガラン山脈のJormungand出現地点の山頂まで登る。",
    ["Trade the Moblin Hotrok to the ??? to complete the quest."] = "???にモブリンの温石を渡して完了。原文は山頂から崖を滑り下り洞窟へ入る経路を省略している。",
    ["Speak with Eddy in Port San d'Oria (H-6) and accept the quest."] = "サンドリア港(H-6)のEddyから受領。",
    ["Eddy shows you a picture of an NPC that you must memorize."] = "Eddyが見せる落とし主の姿を覚える。",
    ["Several NPCs that look very similar to the one Eddy showed you appear on the ship."] = "船上のよく似た乗客から本人を探す。",
    ["Speak with Curilla in Chateau d'Oraguille (I-9) and agree to help her; you receive the key item Curilla's bottle."] = "ドラギーユ城(I-9)のCurillaの依頼を承諾しCurilla's bottleを受け取る。",
    ["Head to Horlais Peak by going through Yughott Grotto."] = "ユグホトの岩屋を抜けホルレーの岩峰へ。",
    ["Once in Horlais Peak, go to the Hot Springs and check them to fill the bottle. The name does not change, so to confirm you filled it, read the description of the item under Temporary Items: it should say it is full of water from the hot spring that flows from Horlais Peak."] = "Hot Springsを調べ瓶に水を汲む。名前は変わらないので、だいじなもの欄の説明が温泉水入りになったことを確認。",
    ["Return to Curilla for your reward."] = "Curillaに報告して報酬。",
    ["Speak with Chalvatot in Chateau d'Oraguille (F-7) to begin the quest."] = "ドラギーユ城(F-7)のChalvatotから受領。",
    ["Obtain a Derfland Humus. It drops from Doom Scorpion enemies in Crawlers' Nest, and can also be purchased at the Auction House."] = "クロウラーの巣のDoom Scorpionか競売からデルフの腐葉土を入手。",
    ["Trade the Derfland Humus to Chalvatot to complete the quest and receive the Map of the Northlands area."] = "Chalvatotにデルフの腐葉土を渡しMap of the Northlands area。",
    ["After completing The Crimson Trial and reaching level 50 or higher as a Red Mage, speak with Curilla (I-9) in Chateau d'Oraguille. You no longer have to be on Red Mage after starting the quest."] = "赤き試練完了後、赤魔道士50以上でドラギーユ城(I-9)のCurillaから受領。以後は他ジョブでも進行可能。",
    ["Depending on your character's progress, you may get the Savage Blade quest and The General's Secret first."] = "進行状況次第で先にサベッジブレードのクエストや女将軍の秘密が始まる場合がある。",
    ["The NPC you are sent to requests a Velvet Cloth. Trade him a Velvet Cloth."] = "紹介先NPCに求められるビロードを渡す。",
    ["Speak with Curilla again."] = "Curillaに再度話す。",
    ["Head to Crawlers' Nest and open a Treasure Chest with a Nest Chest Key to obtain the key item Crawler blood. The chest has a 3 minute respawn time."] = "クロウラーの巣のTreasure ChestをNest Chest Keyで開けクロウラーの体液を入手。原文の箱の再出現目安は3分。",
    ["You can buy a Nest Chest Key from the Curio Vendor Moogle for 2,500 gil if you have the key item Rhapsody in White, from completing Rhapsodies of Vana'diel Mission 1-6."] = "星唄1-6で星唄の煌めき【一奏】を得ていれば、Curio Vendor MoogleからNest Chest Keyを2,500ギルで購入可能。",
    ["If you get the message \"Someone has been digging here\", you forgot to speak to Curilla after trading the Velvet Cloth."] = "「誰かが掘った跡」の表示が出た場合は、ビロード納品後のCurillaとの会話忘れを確認。原文は埋める・掘り返す操作の説明を省略している。",
    ["Speak with Curilla in Chateau d'Oraguille (I-9) to start the quest; you must be a Red Mage of level 50 or higher and able to enter Chateau d'Oraguille."] = "赤魔道士50以上、城への入場資格を満たし、ドラギーユ城(I-9)のCurillaから受領。",
    ["Go to Southern San d'Oria and speak with Sharzalion in the Lion Springs Tavern (K-6)."] = "南サンドリア(K-6)獅子の泉のSharzalionに話す。",
    ["Go to Fei'Yin and defeat Miser Murphy for an Antique Coin. He appears at (H-8) on map 1 if the quest is active."] = "フェ・インマップ1(H-8)に受領中現れるMiser Murphyを倒し古のコインを得る。",
    ["Trade the Antique Coin to the Dry Fountain at (H-8) for a cutscene."] = "(H-8)のDry Fountainに古のコインを渡してイベント。",
    ["Head to Southern San d'Oria and speak with Sharzalion, and then with Daggao, who is in the bar as well."] = "南サンドリアのSharzalion、酒場のDaggaoの順に話す。原文は以降の要塞での攻略を省略している。",
    ["As a White Mage of level 50 or higher, examine the Door: Prince Regent's Rm in Chateau d'Oraguille at (H-8) to start the quest. You must be able to enter Chateau d'Oraguille."] = "白魔道士50以上、城へ入れる状態でドラギーユ城(H-8)のDoor: Prince Regent's Rmを調べる。",
    ["Go to Castle Oztroja or Castle Zvahl Keep and defeat Yagudo Abbot enemies until a Yagudo Holy Water drops."] = "オズトロヤ城／ズヴァール城内郭のYagudo Abbotからヤグードの聖水を入手。",
    ["Find a pair of Moccasins."] = "モカシンを用意。",
    ["Take the Moccasins and the Yagudo Holy Water to Narcheral (M-6) in Northern San d'Oria to complete the quest and obtain your Healer's Duckbills."] = "北サンドリア(M-6)のNarcheralにモカシンとヤグードの聖水を渡しヒーラーダックビル。",
    ["Open the Door: Prince Regent's Rm in Chateau d'Oraguille at (H-8) to start the quest. You can continue as any job from this point."] = "ドラギーユ城(H-8)のDoor: Prince Regent's Rmを調べて開始。以後は他ジョブでも進行可能。",
    ["Go to Eldieme Necropolis and defeat Dark Stalker enemies until a Tavnazia Bell drops."] = "Eldieme NecropolisのDark Stalkerからタブナジアの呼び鈴を入手。",
    ["Travel to Fei'Yin and zone in for a cutscene."] = "フェ・インへ入りイベントを見る。",
    ["Trade the Tavnazia Bell to the ???."] = "???にタブナジアの呼び鈴を渡す。",
    ["Defeat the monster that appears to obtain a Tavnazian Mask. If more than one character is doing this quest, you will have to wait a few minutes before popping it again."] = "現れた敵を倒しタブナジアマスクを得る。複数人で進める場合は再出現まで数分待つ。",
    ["Trade the Tavnazian Mask to Narcheral in the Cathedral, upstairs in Northern San d'Oria (M-6), to receive your reward."] = "北サンドリア(M-6)大聖堂上階のNarcheralにタブナジアマスクを渡し報酬。",
    ["Examine the door to Prince Trion's room (Door: Prince Royal's Rm) at Chateau d'Oraguille (H-7) while you are a Paladin, for a cutscene. Check your active quests: you should see Under Oath. The rest of the quest can be completed as any job."] = "ナイトでドラギーユ城(H-7)のDoor: Prince Royal's Rmを調べ、誓いの剣がオファーに載ったことを確認。以後は他ジョブでも進行可能。",
    ["Obtain a Zvahl Coffer Key and trade it to a Treasure Coffer in Castle Zvahl Baileys to get the key item Mique's paintbrush. You can buy the key from the Curio Vendor Moogle for 5,000 gil if you have the key item Rhapsody in Umber. It also drops from Ahriman, Abyssal Demon, Arch Demon, Blood Demon and Doom Demon, or a Thief can pick the coffer's lock with Thief's Tools, a Living Key or a Skeleton Key."] = "ズヴァール城外郭のTreasure CofferをZvahl Coffer Keyで開けミックの絵筆を得る。Rhapsody in Umber所持ならCurio Vendor Moogleでカギ5,000ギル。Ahriman／Abyssal Demon／Arch Demon／Blood Demon／Doom Demonも落とす。シーフならThief's Tools／Living Key／Skeleton Keyで解錠も可能。",
    ["Look behind the painting and read the letter to get the key item Strange sheet of paper."] = "絵の裏の手紙を調べ不思議な紙を得る。原文は途中の聞き込みと民家への移動を省略している。",
    ["Defeat One-eyed Gwajboj (PLD), which drops the Well Weight you need to continue the quest."] = "One-eyed Gwajboj（ナ）を倒しWell Weightを得る。",
    ["Trade the Well Weight to the Village Well for a cutscene and the key item Knight's confession."] = "Village WellにWell Weightを渡してイベント、騎士の告白文を入手。",
    ["Head back to Chateau d'Oraguille and speak with Prince Trion for your reward."] = "ドラギーユ城のTrionに報告して報酬。",
    ["You may additionally speak with Ailbeche, Exoroche and Vemalpeau for more quest-related dialogue. Vemalpeau takes your Knight's confession key item."] = "追加でAilbeche、Exoroche、Vemalpeauに関連会話を聞ける。Vemalpeauは騎士の告白文を回収する。",
    ["Speak with Rahal in Chateau d'Oraguille (H-9), inside the Royal Knight Quarters, as a Dragoon of level 50 or higher to begin the quest."] = "竜騎士50以上でドラギーユ城(H-9)、王立騎士団部屋のRahalから受領。",
    ["Speak with Ceraulian in Port San d'Oria (I-10), inside Cargo Room A, for a cutscene."] = "サンドリア港(I-10)倉庫AのCeraulianに話す。",
    ["Speak with Ceraulian once more after the cutscene."] = "イベント後Ceraulianにもう一度話す。",
    ["Obtain a Kuftal Coffer Key and use it to open any coffer in Kuftal Tunnel. This gives you the key item Challenge to the Royal Knights."] = "Kuftal Coffer Keyでクフタルの洞門のTreasure Cofferを開け王立騎士団への挑戦状を得る。",
    ["Return to Rahal and speak to him again."] = "Rahalに戻って話す。",
    ["Speak with Balasiel in Southern San d'Oria (F-7)."] = "南サンドリア(F-7)のBalasielに話す。",
    ["Speak with Rahal again."] = "Rahalに再度話す。原文は以降のウガレピでの子竜を伴うNM攻略を省略している。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first."] = "他WSクエスト進行中は依頼人へ戻り先に取消。",
    ["Speak with Curilla in Chateau d'Oraguille (I-9) to receive the Sapara of Trials. You need to break the latent on the Sapara of Trials before completing the rest of the quest."] = "ドラギーユ城(I-9)のCurillaからトライアルサパラを受け取り、潜在を消してから先へ進む。",
    ["With the Sapara of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points."] = "トライアルサパラをメインに装備し、経験値対象の敵にWSや連携締めで300ポイントを蓄積。",
    ["You know the latent is broken when the elemental resistances listed in the Sapara of Trials description have disappeared from the elemental resistances in the equipment window."] = "装備画面の属性耐性からトライアルサパラの補正が消えたら潜在消し完了。",
    ["Trade the Sapara of Trials back to Curilla."] = "トライアルサパラをCurillaに返す。",
    ["Before you go on, speak with Lokpix in Eastern Altepa Desert (G-7) and complete the quest Open Sesame."] = "先へ進む前に東アルテパ砂漠(G-7)のLokpixのOpen Sesameを完了する。",
    ["Go back and speak with Curilla to receive your reward."] = "Curillaに報告して報酬。原文は流砂洞での中間NM戦を省略している。",
    ["Speak with Halver in Chateau d'Oraguille (I-9) for a cutscene. In it you are told the description of the type of female Prince Trion is attracted to."] = "ドラギーユ城(I-9)のHalverから、Trionの好みの女性像を聞く。",
    ["Find a player who matches the description and make a party with them. Then return to Halver while in the same party as the match. Having a female character in the party does not force Halver to ask for that character; the choice is random."] = "指定条件に合う女性キャラクターとPTを組み、Halverに報告する。女性がPTにいてもその人が指定されるとは限らず、条件はランダム。",
    ["Both players must speak to Halver, and each one receives the same cutscene. The player who started the quest gains the title Royal Wedding Planner as well as Castor's Ring. The player who matches the description gains the title Consort Candidate and Pollux's Ring."] = "2人ともHalverに話す。受領者はカストルリングと称号Royal Wedding Planner、候補者はポルックスリングとConsort Candidateを得る。",
    ["The rings can be synthesized with a Wind Crystal, and can also be signed with a Cyclone Crystal. Doing so with either removes the Rare and Exclusive attributes, and the rings can then be traded to another person, acting like a Wedding Ring."] = "指輪はWind Crystalで加工でき、Cyclone Crystalなら銘入れも可能。加工後はRare／Exが外れて他の人へ渡せる。",
    ["The quest can be abandoned and re-accepted every minute without zoning. To be given a different female description, you must accept and then cancel the quest. It resets every minute at XX:XX:00 Earth time, not when you actually cancel it."] = "エリアチェンジ不要で毎分受け直せる。別の条件を引くには一度承諾して取消。原文では取消から1分ではなく地球時間XX:XX:00で更新と説明。",
    ["Speak with Novalmauge in Bostaunieux Oubliette (G-8) to begin the quest. You must be level 10 or higher."] = "原文条件は10以上。ボストーニュ監獄(G-8)のNovalmaugeから受領。Wikiの条件は5以上。",
    ["Trade Novalmauge a vial of Beastman Blood to complete the quest."] = "Novalmaugeに獣人の血を渡して完了。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need Scythe skill 240 or higher and level 71."] = "他WSクエスト進行中は先に取消。両手鎌240以上、71以上が必要。",
    ["Speak with Novalmauge in Bostaunieux Oubliette (G-8) to receive the key item Weapons Training Guide and the Scythe of Trials. You need to break the latent on the Scythe of Trials before completing the rest of the quest."] = "ボストーニュ監獄(G-8)のNovalmaugeからWeapons Training Guideとトライアルサイズを得る。潜在を消してから先へ進む。",
    ["With the Scythe of Trials equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains to accumulate 300 Trial Points."] = "トライアルサイズをメインに装備し、経験値対象の敵にWSや連携締めで300ポイントを蓄積。",
    ["You know the latent is broken when the elemental resistances listed in the Scythe of Trials description have disappeared from the elemental resistances in the equipment window."] = "装備画面の属性耐性からトライアルサイズの補正が消えたら潜在消し完了。",
    ["Trade the Scythe of Trials back to Novalmauge."] = "トライアルサイズをNovalmaugeに返す。",
    ["Make sure that you, or someone in your party, has a Paintbrush of Souls. Use it to open the Granite Door at (I-7) and head into the Den of Rancor."] = "自分かPTの誰かが魂の絵筆を用意し、(I-7)のGranite Doorを開けて怨念洞へ。",
    ["Go back and speak with Novalmauge to receive your reward."] = "Novalmaugeに報告して報酬。原文は怨念洞での中間NM戦を省略している。",
    ["You must be level 10 or higher. First, zone at (C-7) in Northern San d'Oria."] = "原文条件は10以上。まず北サンドリア(C-7)から移動する。",
    ["You should now be in a watchtower in West Ronfaure, and Vilatroire should be up ahead after zoning in (H-5). Speak with him to activate the quest."] = "西ロンフォール(H-5)の見張り塔に着いたら、奥のVilatroireに話して受領。",
    ["Form a party of two, yourself and one other player, with the same allegiance, then speak with him again to complete the quest."] = "同じ所属国の自分と他プレイヤー、計2人でPTを組み、Vilatroireに話して完了。",
    ["Form a party of two, yourself and one other player, with the same race, then speak with him again to complete the quest."] = "同じ種族の自分と他プレイヤー、計2人でPTを組み、Vilatroireに話して完了。",
    ["Form a party of two, yourself and one other player, with the same job, then speak with him again to complete the quest."] = "同じメインジョブの自分と他プレイヤー、計2人でPTを組み、Vilatroireに話して完了。",
