    -- Windurst quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Chumimi in the basement of Heavens Tower (the bottom floor). You must be on Black Mage, level 40 or higher, to start this quest."] = "黒魔道士40以上で天の塔地下のChumimiから受領。",
    ["During the cutscene you are asked to agree with one of the three NPCs. Whoever you pick decides your title, but it does not affect the quest. After the cutscene you can continue on any job."] = "イベントで同意する博士によって称号が変わるが攻略には影響しない。以後は他ジョブでも進行可能。",
    ["Go to any Telepoint and trade a synthesis crystal to receive a Faded Crystal."] = "任意のTelepointに合成用クリスタルを渡し変色クリスタルを得る。",
    ["Travel to Xarcabard and head toward (E-8). Trade the Faded Crystal there to spawn the Chaos Elemental."] = "ザルカバード(E-8)の対象に変色クリスタルを渡しChaos Elementalを出す。",
    ["If several people are doing the quest, wait 3 minutes after it dies for it to appear again."] = "複数人で進める場合は討伐後の再出現まで3分待つ。",
    ["Take the Glowstone that drops from the Chaos Elemental and return to Chumimi to complete the quest and receive a Casting Wand."] = "Chaos ElementalからGlowstoneを得てChumimiへ戻り、キャストワンドを受け取る。",
    ["Zone out of Heavens Tower first if you have just completed The Three Magi."] = "3賢者直後なら一度天の塔から出る。",
    ["Speak with Chumimi in the basement of Heavens Tower to start the quest. You must be a Black Mage, level 50 or higher."] = "黒魔道士50以上で天の塔地下のChumimiから受領。",
    ["Go to the basement of Crawlers' Nest and obtain a Bag of Seeds, which drops from a Fire Elemental or a Water Elemental."] = "クロウラーの巣地下のFire Elemental／Water Elementalから種が入った袋を入手。",
    ["Return to Chumimi and trade her the Bag of Seeds."] = "Chumimiに種が入った袋を渡す。",
    ["Go to the Ore Door at (H-7) and trade the Whine Cellar Key to it for a cutscene and the key item Foe Finder Mk. I."] = "(H-7)のOre Doorにヤカマシ部屋のカギを渡しFoe Finder Mk. Iを得る。原文はカギの入手や城への移動を省略し、素材欄ではヤカマシ部屋のカギと表記している。",
    ["Return to Chumimi after the cutscene in the Keep. After another short sequence the quest is completed and you receive Wizard's Sabots."] = "城内郭のイベント後Chumimiへ戻り、ウィザードサボを得る。",
    ["Zone out of Heavens Tower first if you have just completed Recollections."] = "思ひ出直後なら一度天の塔から出る。",
    ["Speak with Chumimi in the basement of Heavens Tower to start the quest. You must be on Black Mage."] = "黒魔道士で天の塔地下のChumimiから受領。",
    ["After the cutscene, trade a Silk Cloth to Koru-Moru in Windurst Walls (E-7)."] = "イベント後ウィンダス石の区(E-7)のKoru-Moruに絹布を渡す。",
    ["Return to Chumimi to receive the key item Sluice Surveyor Mk. I."] = "ChumimiからSluice Surveyor Mk. Iを受け取る。",
    ["Go to Toraimarai Canal and locate the two ???. Black Mage is needed to investigate them; the rest of the quest does not require it."] = "トライマライ水路の2つの???を調べる。この調査は黒魔道士が必要だが、他の工程はジョブ不問。",
    ["Go to (J-8) and examine the ??? again for another cutscene."] = "(J-8)の???を再調査してイベント。原文は途中の調査やNM戦の説明を省略している。",
    ["Return to Chumimi for the final cutscene and your reward, Wizard's Petasos."] = "Chumimiに報告しウィザードペタソス。",
    ["Optional: speak with Kupipi in Heavens Tower to receive an Earthen Charm."] = "任意：天の塔のKupipiからEarthen Charmを得る。",
    ["Speak with Pygmalion in Port Windurst (M-7) and accept the quest."] = "ウィンダス港(M-7)のPygmalionから受領。",
    ["Pygmalion shows you a picture of an NPC that you must memorize."] = "Pygmalionが見せる落とし主の姿を覚える。",
    ["Several NPCs that look very similar to the one in the picture appear on the ship."] = "船上の似た姿の乗客から本人を探す。",
    ["If you choose correctly, you receive 500 gil. If you choose incorrectly, you fail the quest."] = "正しい相手なら500ギル、間違うと失敗。",
    ["Speak with Kohlo-Lakolo behind warehouse #1 at (G-5) in Port Windurst for a cutscene."] = "ウィンダス港(G-5)、倉庫1裏のKohlo-Lakoloに話す。",
    ["Obtain a Rarab Tail. It can be bought from the Sarutabaruta regional vendor, for example Baehu-Faehu in Windurst Waters North (G-5), for about 22 gil."] = "ララブのしっぽを用意。サルタバルタ特産品店、例：ウィンダス水の区北(G-5)のBaehu-Faehuで約22ギル。",
    ["Trade the Rarab Tail to Kohlo-Lakolo for a cutscene and your reward, which completes the quest."] = "Kohlo-Lakoloにしっぽを渡してイベント、報酬を得る。",
    ["Speak with Tokaka in Port Windurst (C-8) to start the quest. Home Point #1 in Port Windurst is extremely close to her."] = "ウィンダス港(C-8)、Home Point #1近くのTokakaから受領。",
    ["Trade Tokaka a Bastore Sardine to complete the quest and receive 70 gil."] = "Tokakaにバストアサーディンを渡し70ギル。",
    ["To repeat it, you must zone each time you finish before the quest is offered to you again."] = "反復には完了ごとにエリアチェンジが必要。",
    ["Zone first if you have just completed the quest Truth, Justice, and the Onion Way!"] = "正義の一味直後ならエリアチェンジ。",
    ["Speak with Kohlo-Lakolo behind the warehouse at (G-5) in Port Windurst."] = "ウィンダス港(G-5)倉庫裏のKohlo-Lakoloに話す。",
    ["Obtain Wild Onion x4 and trade them to him."] = "Wild Onion4個を渡す。",
    ["In some cases the quest ends here, with a cutscene and your reward. The exact trigger is unknown; it seems related to your progress in the Windurst missions or to having the key item Old ring."] = "進行状況によってはここで完了し報酬。原文ではウィンダスミッションや古い指輪所持との関係が推測されるが、正確な分岐条件は不明。",
    ["Otherwise, go to the House of the Hero in Windurst Walls (G-3) and try to enter it for a cutscene."] = "ここで終わらなければウィンダス石の区(G-3)のHouse of the Heroを調べてイベント。",
    ["Return to Kohlo-Lakolo to complete the quest and receive your reward."] = "Kohlo-Lakoloへ戻り報酬。",
    ["Speak with Sigismund on top of the Orastery in Port Windurst (E-7); he tells you about the elusive Starfall Tear."] = "ウィンダス港(E-7)、口の院屋上のSigismundからStarfall Tearの話を聞く。",
    ["Speak with Tohopka, who stands right next to Sigismund (E-7). Tohopka explains how to collect the tears and that you need Pugil Scales. Pugil enemies drop them, or you can find them at the Auction House under Bonecrafting."] = "隣のTohopka(E-7)に採集法を聞く。陸魚の鱗は陸魚系の敵か競売（骨細工材）で用意。",
    ["Wait until 0:00 to 3:00 game time. At any other time the tree says nothing is out of the ordinary; during those hours you get the message \"A frost deposit at the base of the tree twinkles in the starlight.\""] = "ヴァナ時間00:00〜03:00を待つ。木の根元の霜が星明かりに輝く旨の表示を確認する。",
    ["At that point trade the Pugil Scales to the tree to receive your Starfall Tear."] = "その時間に木へ陸魚の鱗を渡しStarfall Tearを得る。原文は木の場所を省略している。",
    ["Take the Starfall Tear back to Sigismund to complete the quest and receive a Fish Scale Shield."] = "SigismundにStarfall Tearを渡し魚鱗の盾。",
    ["This quest cannot be completed while you are on Windurst Mission 8-1 or the quest Orastery Woes, so finish those first."] = "ウィンダス8-1や口の院の悲劇進行中は先に終える必要がある。",
    ["Speak with Kuroido-Moido in Port Windurst (E-7) to start the quest; zone first if you have just completed Making Amends."] = "ウィンダス港(E-7)のKuroido-Moidoから受領。壊れた世界直後はエリアチェンジ。",
    ["Go to Garlaige Citadel."] = "ガルレージュ要塞へ。",
    ["Inside, defeat Fallen Evacuee enemies in the small rooms near the entrance until one drops a Garlaige Key."] = "入口近くの小部屋のFallen Evacueeからガルレージュのカギを入手。",
    ["To pass the Banishing Gates alone, take a Pouch of weighted stones from the ??? on the ground on map 1 (G-8)."] = "1人で魔防門を通るならマップ1(G-8)の???からPouch of weighted stonesを得る。",
    ["Go through Banishing Gate #1 at (I-9) on map 1, then Banishing Gate #2 at (H-10) on map 2."] = "原文マップ1(I-9)のBanishing Gate #1、マップ2(H-10)の#2の順に通る。",
    ["Use the Garlaige Key to enter the Incinerator room at (I-7) on map 3. The quest Rubbish Day also sends you there, so it is recommended to do both at the same time."] = "原文マップ3(I-7)焼却室へガルレージュのカギで入る。Rubbish Dayでも訪れるので同時進行が便利。",
    ["Speak with Mashira, who hands you a Broken wand."] = "MashiraからBroken wandを受け取る。",
    ["Return to Kuroido-Moido to complete the quest and receive 6,000 gil."] = "Kuroido-Moidoに報告し6,000ギル。",
    ["Speak with Chipmy-Popmy in Port Windurst (C-8) to start the quest. This quest requires the Chains of Promathia pack."] = "プロマシア導入が必要。ウィンダス港(C-8)のChipmy-Popmyから受領。",
    ["Go to the Manaclipper in Bibiki Bay and take the tour that goes to Purgonorgo Isle; the clipper does three tours."] = "ビビキー湾からマナクリッパーのPurgonorgo Isle行きへ乗る。遊覧便を含め3航路あるので行先を確認。",
    ["On the isle, follow the path to (H-9), near the center. There is a ??? that spawns 6 to 8 Peerifool enemies (Mandragora). Defeat them, then examine the ??? again."] = "島中央(H-9)の???で原文ではPeerifool6〜8体を出し倒して再調査。Wiki記載は6体。",
    ["Go to Attohwa Chasm, which you can enter from the Maze of Shakhrami, and make your way through it to the Boneyard Gully zone, in the eastern part of (G-6)."] = "シャクラミの地下迷宮からアットワ地溝へ入り、(G-6)東部の千骸谷入口へ。",
    ["After the cutscene you receive the key item Map of the Attohwa Chasm."] = "イベントでMap of the アットワ地溝を得る。",
    ["Return to Chipmy-Popmy for another cutscene and your gil reward."] = "Chipmy-Popmyに報告してギル報酬。原文は島の調査後の中間報告を省略している。",
    ["Speak with Dehn Harzhapan in Port Windurst (G-6) to start the quest. Only one Escort for Hire quest can be active at a time, and only one can be completed each Conquest Tally."] = "ウィンダス港(G-6)のDehn Harzhapanから受領。護衛は各国合わせ同時1件、コンクェスト集計ごとに1回。",
    ["Go to Garlaige Citadel. As soon as you zone in you get a cutscene, after which the NPC Wanzo-Unzozo appears. You can summon Trusts, but zoning in with an Adventuring Fellow makes the escort NPC disappear."] = "ガルレージュ要塞に入るとイベント後Wanzo-Unzozoが現れる。フェイスは呼べるが、フェロー連れで入ると護衛NPCが消える。",
    ["You have 30 minutes. Escort Wanzo-Unzozo until he stops on his own, then speak with him to receive the key item Completion certificate. If he vanishes before you speak with him, you do not get the key item and must do the quest again."] = "30分以内に護衛し、本人が停止したらすぐ話してCompletion certificateを得る。話す前に消えるとやり直し。",
    ["Return to Dehn Harzhapan for your reward."] = "Dehn Harzhapanに報告して報酬。",
    ["You cannot start this quest while another Weapon Skill quest is active; return to the person who gave it and quit it first. You need Club skill 230 or higher, level 71 and the Rise of the Zilart pack, and your main job must be WAR, MNK, WHM, BLM, PLD, SMN, BLU, SCH or GEO."] = "他WSクエスト進行中は先に取消。片手棍230以上、71以上、ジラート導入、メインWAR／MNK／WHM／BLM／PLD／SMN／BLU／SCH／GEOが必要。",
    ["Speak with Kuroido-Moido in Port Windurst (E-7) to receive the key item Weapons Training Guide and the Club of Trials."] = "ウィンダス港(E-7)のKuroido-MoidoからWeapons Training GuideとClub of Trialsを得る。",
    ["Break the latent on the Club of Trials before doing the rest of the quest. Each skillchain gives trial points: 5 with no skillchain, 7 at level 1, 9 at level 2 and 11 at level 3."] = "Club of Trialsの潜在を消す。原文配点は連携なし5、レベル1で7、2で9、3で11。小売版との配点差に注意。",
    ["The latent is broken when the elemental resistances listed in the Club of Trials description disappear from the elemental resistances shown under the equipped gear grid in the equipment window."] = "装備画面の属性耐性からClub of Trialsの補正が消えたら潜在消し完了。",
    ["Inside Ro'Maeve, go down the northeastern stairs and turn immediately east. Go through the hallway to the right, turn left, drop down the ledge and go through the door to the northeast. The Ro'Maeve page lists the notorious monster Eldhrimnir, a Magic Pot, for this quest."] = "ロ・メーヴ北東の階段を下り、すぐ東、右の通路から左折して段差を下り北東の扉へ。原文ではNM名をEldhrimnir（マジックポット）と表記。戦闘・証拠回収の説明は省略されている。",
    ["Go back and speak with Kuroido-Moido to receive your reward, the Black Halo weapon skill."] = "Kuroido-Moidoに報告しBlack Haloを習得。",
    ["Zone first if you have just completed Know One's Onions."] = "オバケの家直後ならエリアチェンジ。",
    ["Speak with Kohlo-Lakolo in Port Windurst for a cutscene, then speak with Pichichi near him, who sends you to her mother."] = "ウィンダス港のKohlo-Lakoloに話し、近くのPichichiから母を紹介される。",
    ["Go to Windurst Waters and speak with Chamama at (F-10) (Home Point #4). She asks for Saruta Cotton x4 to make a Fake moustache."] = "ウィンダス水の区(F-10)、Home Point #4付近のChamamaからFake moustache用のSaruta Cotton4個を頼まれる。",
    ["Saruta Cotton can be bought from Kuzah Hpirohpon (79 gil) or Meriri (500 gil, Clothcraft Guild Recruit rank or higher) in Windurst Woods (F-12), or found at the Auction House under Materials, Clothcraft."] = "サルタ綿花はウィンダス森の区(F-12)のKuzah Hpirohpon（79ギル）、裁縫見習以上ならMeriri（500ギル）、または競売（裁縫材）で用意。",
    ["Trade the Saruta Cotton x4 to Chamama, then return to Kohlo-Lakolo for a cutscene to complete the quest and receive a Heko Obi."] = "ChamamaにSaruta Cotton4個を渡し、Kohlo-Lakoloへ戻って兵児帯。",
    ["Zone first if you have just completed Inspector's Gadget!"] = "名探偵誕生？直後ならエリアチェンジ。",
    ["Speak with Kohlo-Lakolo in Port Windurst (G-5) for a story cutscene that starts the quest. If you already have the key item Old ring, you skip ahead to the final cutscene."] = "ウィンダス港(G-5)のKohlo-Lakoloから受領。古い指輪所持なら終盤のイベントへ進む。",
    ["Go to Castle Oztroja and head to the door at (I-8) on the first map."] = "オズトロヤ城の最初のマップ(I-8)の扉へ。",
    ["Use the handles in front of the door to activate the trap door on purpose and fall down it."] = "扉前のハンドルでわざと落とし穴を作動させ落ちる。",
    ["Check the Blank Target in that room to receive the key item Old ring."] = "落下先の名前のない対象を調べ古い指輪を得る。",
    ["Return to Kohlo-Lakolo, who sends you to the House of the Hero in Windurst Walls (G-3) for your reward. If you take too long to return the ring, the quest ends when you return to him and you do not need to go to the House of the Hero; it still counts as complete."] = "Kohlo-Lakoloに報告し、ウィンダス石の区(G-3)のHouse of the Heroへ。原文では帰還が遅い場合は報告だけで完了する分岐もあると説明。",
    ["Zone and return to Kohlo-Lakolo to receive your reward."] = "エリアチェンジしてKohlo-Lakoloへ戻り報酬。",
    ["You must zone again if you have not done so since receiving the Bouncer Club."] = "バウンサークラブ受領後まだ移動していなければエリアチェンジ。",
    ["Speak with Kohlo-Lakolo in Port Windurst (G-5) for a cutscene that starts the quest."] = "ウィンダス港(G-5)のKohlo-Lakoloから受領。",
    ["Go to Windurst Waters South (a short walk away, or use Home Point #3) and speak with Honoi-Gomoi (E-7) for a cutscene. He is upstairs in his house, reached by a back stairway."] = "隣のウィンダス水の区南(E-7)、家の裏階段を上がりHonoi-Gomoiに話す。Home Point #3も利用可。",
    ["Obtain a Star Spinel from Spelunking Sabotender enemies in Quicksand Caves. Enter from Western Altepa Desert at (G-5); they are in the passageway near (F-7), and a couple spawn by Home Point #1. Sneak is required even at level 99. The weight sensors need one Galka or any two of Hume, Elvaan or Mithra."] = "西アルテパ砂漠(G-5)から流砂洞へ入り、(F-7)の通路やHome Point #1付近のSpelunking Sabotenderからスタースピネルを得る。99でもスニーク推奨。重量扉はガルカ1人、またはヒューム／エルヴァーン／ミスラの2人が必要と原文に記載。",
    ["Bring the Star Spinel to Honoi-Gomoi, who gives you the Star Necklace after a cutscene."] = "Honoi-Gomoiにスタースピネルを渡しスターズネックレス。",
    ["Speak with Kohlo-Lakolo for a cutscene, then speak with Honoi-Gomoi again for a cutscene that completes the quest."] = "Kohlo-Lakolo、Honoi-Gomoiの順にイベントを見て完了。",
    ["Speak with Kohlo-Lakolo in Port Windurst (G-5) to start the quest."] = "ウィンダス港(G-5)のKohlo-Lakoloから受領。",
    ["Speak with Chamama in Windurst Waters (F-10)."] = "ウィンダス水の区(F-10)のChamamaに話す。",
    ["She makes you the Invisible man sticker you need, but only if you first bring her Shoalweed. Shoalweed drops from Recluse Spider enemies in Kuftal Tunnel."] = "クフタルの洞門のRecluse Spiderから遠浅の苔を入手しChamamaへ。Invisible man stickerを作ってもらう。",
    ["Return to Kohlo-Lakolo for your reward, the Promise Badge."] = "Kohlo-Lakoloに戻って約束バッジ。",
    ["Final cutscene: if you have killed Fenrir after reaching Windurst Rank 10, you have the Dark Mana Orb among your temporary key items. Zone, then speak with Kohlo-Lakolo again with that key item for a final, concluding cutscene."] = "後日談：ウィンダスランク10到達後にFenrirを倒してDark Mana Orbを得たら、エリアチェンジ後Kohlo-Lakoloに話す。",
    ["Speak with Paytah at the pier near the shopping piers in Port Windurst (I-7)."] = "ウィンダス港(I-7)、店のある桟橋近くのPaytahに話す。",
    ["Fish a Ripped Cap out of the water and trade it to Paytah."] = "釣った破れた帽子をPaytahに渡す。",
    ["Take the Ripped Cap to Baren-Moren in Windurst Waters South (H-7)."] = "ウィンダス水の区南(H-7)のBaren-Morenへ破れた帽子を持参。",
    ["Bring Baren-Moren Dhalmel Hide x4 so he can repair the cap."] = "Dhalmel Hide4枚をBaren-Morenに渡して修理してもらう。",
    ["Return the repaired cap to Paytah to complete the quest and receive your reward."] = "直った帽子をPaytahに返して報酬。",
    ["Speak with Ohruru in Port Windurst (E-7) to start the quest."] = "ウィンダス港(E-7)のOhruruに話す。",
    ["Return to her while you are under the effect of Bane, Mute or Plague."] = "Bane／Mute／Plagueのいずれかを受けたまま戻る、と原文に記載。Wikiでは呪詛／沈黙／悪疫で、沈黙薬の静寂は対象外と説明。",
    ["Bane is inflicted by Lost Soul enemies in The Eldieme Necropolis, and pays 1,200 gil."] = "エルディーム古墳のLost SoulからBaneを受ける場合は1,200ギル。",
    ["Mute is inflicted through the additional effect of the weapon of Eight of Cups in the Outer Horutoto Ruins (enter from (F-11) in West Sarutabaruta), and pays 1,000 gil."] = "西サルタバルタ(F-11)から外ホルトト遺跡へ入り、Eight of Cupsの通常攻撃追加効果を受ける方法。原文名はMuteで、報酬1,000ギル。",
    ["Plague is inflicted by Bloodsucker enemies in Toraimarai Canal, by Deathmaw Orobon enemies in the Ceizak Battlegrounds with Vile Belch (which also inflicts Silence, so use an item or Echo Drops first if you plan to warp back to Ohruru), and by the Devouring Mosquito in Reisenjima with Infected Leech, which lasts 45 seconds."] = "Plagueはトライマライ水路のBloodsucker、ケイザック古戦場のDeathmaw OrobonのVile Belch、醴泉島のDevouring MosquitoのInfected Leech等。後者は45秒。Vile Belchは沈黙も付くため帰還魔法を使うなら先にやまびこ薬等で対処。",
    ["Once the quest is complete, she removes the status ailment from you."] = "完了時に状態異常を治してもらえる。",
    ["If you are on the mission The Horutoto Ruins Experiment, complete it first. If you are on Saintly Invitation, finish the fight against the Yagudo first, or the quest will not start."] = "The Horutoto Ruins Experimentは先に完了。Saintly Invitation進行中なら先にヤグード戦を終える。",
    ["Speak with Hakkuru-Rinkuru in the Orastery in Port Windurst (E-7); he needs glue to patch Minister Ajido-Marujido's broken wand."] = "ウィンダス港(E-7)口の院のHakkuru-Rinkuruから院長の杖を直すにかわを頼まれる。",
    ["Obtain an Animal Glue."] = "にかわを用意。",
    ["Trade the Animal Glue to Hakkuru-Rinkuru to complete the quest and receive 1,500 gil."] = "Hakkuru-Rinkuruににかわを渡し1,500ギル。",
    ["Speak with Hakkuru-Rinkuru in the Orastery in Port Windurst (E-7) to start the quest."] = "ウィンダス港(E-7)口の院のHakkuru-Rinkuruから受領。",
    ["Speak with the War Warlock Captains in the Orastery: Ohruru, just south of Hakkuru-Rinkuru on the stage; Goltata, against the west wall; and Yaman-Hachuman, against the wall to the northeast."] = "口の院の団長に話す。Ohruruは南の壇上、Goltataは西壁、Yaman-Hachumanは北東壁付近。",
    ["Obtain a Rose Wand, an Oak Staff and a Mythril Rod. All three can be bought with sparks: the Oak Staff and the Mythril Rod are in the level 30-39 category, the Rose Wand in the level 40-49 category."] = "ローズワンド、オークスタッフ、ミスリルロッドを用意。エミネンス交換なら後2本は30〜39、ローズワンドは40〜49の区分。",
    ["Trade the Rose Wand, the Oak Staff and the Mythril Rod to Hakkuru-Rinkuru for the cutscene that completes the quest. Two of the items are returned to you at the end, together with your reward and a new title."] = "3本をHakkuru-Rinkuruに渡して完了。うち2本が返却され、報酬と称号を得る。",
    ["Defeat Savanna Rarab in West Sarutabaruta until one drops a Torn Epistle."] = "西サルタバルタのSavanna Rarabから破れたラブレターを入手。",
    ["Speak with Koru-Moru in Windurst Walls (E-7) while the Torn Epistle is in your inventory."] = "手紙を持ちウィンダス石の区(E-7)のKoru-Moruに話す。",
    ["Optional: trade the Torn Epistle to Koru-Moru for 50 gil, although it is not necessary."] = "任意：破れたラブレターをKoru-Moruへ渡すと50ギル、と原文に記載。必須ではない。",
    ["Go to West Sarutabaruta and defeat Crawler enemies there until one drops a Meteorite."] = "西サルタバルタのCrawlerから隕石を入手。",
    ["Trade the Meteorite to Koru-Moru to complete the quest and receive your reward."] = "Koru-Moruに隕石を渡して報酬。",
    ["Speak with Ambrosius in Windurst Walls (J-12) to start the quest."] = "ウィンダス石の区(J-12)のAmbrosiusから受領。",
    ["Collect Muddy Bar Tab, which drops from Savanna Rarab in East Sarutabaruta."] = "東サルタバルタのSavanna Rarabから泥だらけの請求書を得る。",
    ["Collect Torn Epistle, which drops from Savanna Rarab in West Sarutabaruta."] = "西サルタバルタのSavanna Rarabから破れたラブレターを得る。",
    ["Collect Odd Postcard and Damp Envelope, which drop from Canyon Rarab in Tahrongi Canyon."] = "タロンギ大峡谷のCanyon Rarabから怪しいカードとしめった封筒を得る。",
    ["Trade one to four of these items to Ambrosius in a single trade to complete the quest: 1 gives 50 gil, 2 give 150 gil, 3 give 250 gil and 4 give 500 gil."] = "Ambrosiusに1〜4通まとめて渡す。1通50、2通150、3通250、4通500ギル。",
    ["While you are on Summoner as your main job, examine the House of the Hero in Windurst Walls (Home Point #1) to speak with Carbuncle. You must be level 40 or higher and have the Rise of the Zilart pack."] = "召喚士40以上とジラート導入が必要。ウィンダス石の区のHome Point #1近くのHouse of the HeroでCarbuncleの話を聞く。",
    ["Speak with Juroro in Port Bastok (I-8), near Home Point #1. Ildy-Goldy gives you an Earth Pendulum."] = "バストゥーク港(I-8)、Home Point #1近くのJuroroに話す。原文ではIldy-Goldyから土の振子を受領と説明。",
    ["Make your way through Quicksand Caves to the Cloister of Tremors. Home Point #2 is at the entrance. If it is your first visit, enter Quicksand Caves via Eastern Altepa Desert at (K-7); some of the drops on the way are one-way."] = "東アルテパ砂漠(K-7)から流砂洞を抜け震動の回廊へ。途中に一方通行の段差あり。回廊入口はHome Point #2。",
    ["Trade the Earth Pendulum to the Protocrystal to enter the battlefield."] = "Protocrystalに土の振子を渡してBFへ。原文は戦闘や中間報告を省略している。",
    ["Speak with Koru-Moru in Windurst Walls (E-7) to complete the quest and receive your reward. You can drop the Earth Pendulum afterwards, as it serves no further purpose."] = "ウィンダス石の区(E-7)のKoru-Moruに報告して報酬。完了後土の振子は用途がないので処分可。",
    ["While your main job is Summoner, examine the House of the Hero in Windurst Walls for a cutscene with Carbuncle, who gives you the key item Carbuncle's Tear."] = "召喚士でウィンダス石の区のHouse of the Heroを調べ、Carbuncle's Tearを得る。",
    ["Speak with Koru-Moru in Windurst Walls (E-7)."] = "ウィンダス石の区(E-7)のKoru-Moruに話す。",
    ["Obtain Astragalos x4 and trade them to Koru-Moru. Astragalos can be bought from Shih Tayuun at the Bonecraft Guild in Windurst Woods (H-12) for 2,439 gil, but it is only restocked if players sell it to the guild."] = "Astragalos4個を渡す。ウィンダス森の区(H-12)骨細工ギルドのShih Tayuunでは2,439ギルだが、売却による入荷時だけ購入可能。",
    ["Fuepepe may need to be spoken to several times, repeating the same unrelated text before giving the text that continues the quest."] = "Fuepepeは無関係な台詞が続く場合も、進行するまで数回話す。",
    ["Speak with Shantotto at her manor in Windurst Walls (K-7)."] = "ウィンダス石の区(K-7)のShantottoに話す。原文はもう1人の同窓生との会話を省略している。",
    ["Speak with Gulmama in Northern San d'Oria (E-7) to receive an Ice Pendulum."] = "北サンドリア(E-7)のGulmamaから氷の振子を得る。",
    ["Trade the Ice Pendulum to the Protocrystal to enter the battlefield."] = "Protocrystalに氷の振子を渡してBFへ。原文は回廊への移動・戦闘・終了報告を省略している。",
    ["You can toss the Ice Pendulum after completing the quest, as it serves no further purpose."] = "完了後氷の振子は用途がないので処分可。",
    ["Speak with Shantotto in Windurst Walls (K-7) to start the quest. The quest Blood and Glory may prevent you from starting it: come back with a job that does not meet the prerequisites for Blood and Glory."] = "ウィンダス石の区(K-7)のShantottoから受領。血塗られた道が優先されるなら、その条件を満たさないジョブで話す。",
    ["Obtain Bone Chip x2 and a Bomb Ash; both can be bought from NPCs."] = "Bone Chip2個とBomb Ash1個を用意。店でも購入可能。",
    ["Trade the Bone Chip x2 and the Bomb Ash to Shantotto to complete the quest and receive a Brass Rod."] = "Shantottoに材料を渡しブラスロッド。",
    ["Optional: speak with Ojha Rhawash in Windurst Walls (C-13). She does not say it at first, but she would like a Lilac."] = "任意：ウィンダス石の区(C-13)のOjha Rhawashに話す。希望する花はライラック。",
    ["Obtain a Lilac. It can be bought at the Auction House, or from Areebah in Upper Jeuno (H-6) for 120 gil."] = "ライラックを競売かジュノ上層(H-6)のAreebah（120ギル）で用意。",
    ["Trade the Lilac to Ojha Rhawash to complete the quest."] = "Ojha Rhawashにライラックを渡して完了。",
    ["Speak with Yoran-Oran in Windurst Walls (E-5); he asks for one of several items."] = "ウィンダス石の区(E-5)のYoran-Oranから研究用の品を頼まれる。",
    ["Trade a Four-Leaf Mandragora Bud for 120 gil. It drops from Mandragora enemies in West Sarutabaruta, Pygmaioi enemies in Tahrongi Canyon and Sylvestre enemies in Buburimu Peninsula."] = "マンドラゴラの四葉なら120ギル。西サルタバルタのMandragora、タロンギ大峡谷のPygmaioi、ブブリム半島のSylvestreから入手。",
    ["Trade a Cornette for 200 gil. It drops from the Mandragora and Pygmaioi enemies above, and can also be bought for 50 sparks from the Records of Eminence NPCs, or from Harmodios in Bastok Markets (K-10) when Bastok is 1st or 2nd in Conquest."] = "コルネットなら200ギル。同じ敵のほかエミネンス50ポイント、またはバストゥークがコンクェスト1・2位時にバストゥーク商業区(K-10)のHarmodiosで購入可。",
    ["Trade a Yuhtunga Sulfur for 250 gil. It drops from the same enemies as the Four-Leaf Mandragora Bud."] = "ユタンガの硫黄なら250ギル。マンドラゴラの四葉と同じ敵から入手。",
    ["Trade a Three-Leaf Mandragora Bud for 1,200 gil. It drops from Yuhtunga Mandragora enemies in Yuhtunga Jungle."] = "マンドラゴラの三葉なら1,200ギル。ユタンガ大森林のYuhtunga Mandragoraから入手。",
    ["He also accepts a Snobby Letter. In total the quest pays between 120 and 5,500 gil, depending on the item."] = "偉そうな手紙も対象。渡す品に応じて120〜5,500ギル。",
    ["If Zayhi-Bauhi speaks normally instead of coughing, speak with Kalupa-Tawalupa and Rutango-Botango in front of him to receive the quest."] = "Zayhi-Bauhiが普通に話す場合は、前のKalupa-TawalupaとRutango-Botangoに話して進める。",
    ["Speak with Raamimi in Windurst Walls (F-7) to receive Honey."] = "ウィンダス石の区(F-7)のRaamimiから蜂蜜を受け取る。",
    ["Trade the Honey to Zayhi-Bauhi, the speaker by the bridge to Heavens Tower, then speak with Kalupa-Tawalupa and Rutango-Botango."] = "天の塔への橋近くの演説者Zayhi-Bauhiに蜂蜜を渡し、Kalupa-TawalupaとRutango-Botangoに話す。",
    ["Trade 4 more Honey, one at a time, to Zayhi-Bauhi."] = "さらにHoney4個を1個ずつZayhi-Bauhiに渡す。",
    ["Return to Raamimi to complete the quest and receive Mulsum x3."] = "Raamimiに報告してMulsum3個。",
    ["If the quest Class Reunion is active, finish it first: you cannot start this quest until it is complete."] = "同窓の輪進行中は先に終える。",
    ["Zone in and out if you have just completed Star Struck."] = "天からの贈り物直後ならエリアチェンジ。",
    ["Speak with Koru-Moru in Windurst Walls (E-7) to start the quest."] = "ウィンダス石の区(E-7)のKoru-Moruから受領。",
    ["Go to the Maze of Shakhrami."] = "シャクラミの地下迷宮へ。",
    ["Examine the Fossil Rock at (F-8) on map 2 to spawn the NM Ichorous Ire, which drops a Burnite Shell."] = "原文マップ2(F-8)のFossil Rockを調べIchorous Ireを出し、ブルナイト貝石を得る。",
    ["Trade the Burnite Shell to Koru-Moru to complete the quest."] = "Koru-Moruにブルナイト貝石を渡して完了。",
    ["Speak with Shantotto in Windurst Walls (K-7) to start the quest."] = "ウィンダス石の区(K-7)のShantottoから受領。",
    ["Collect Bomb Arm x2, a Revival Tree Root and Hiwon's Hair. Bomb Arm can be bought from Nogga on the top floor of Metalworks (G-7) for 690 gil when Bastok is at least 2nd place in Conquest."] = "Bomb Arm2個、反魂樹の根、ヒウォンの髪を用意。ボムのうではバストゥークがコンクェスト2位以上なら大工房最上階(G-7)のNoggaで690ギル。",
    ["Trade the items to Shantotto to complete the quest and receive a Misery Staff."] = "Shantottoに材料を渡して不幸の杖。",
    ["Speak with Torino-Samarino in Beaucedine Glacier to obtain the temporary key item Shantotto's new spell."] = "ボスディン氷河のTorino-SamarinoからShantotto's new spellを受け取る。",
    ["Turn Shantotto's new spell in to Rukususu. If you kill too many monsters while carrying it, it breaks and is replaced by Shantotto's ex-spell; return to Torino-Samarino to get another scroll."] = "Rukususuへ届ける。所持中に敵を倒し過ぎると壊れてShantotto's ex-spellになるので、Torino-Samarinoから再入手。",
    ["Return to Shantotto in Windurst Walls to receive the Scroll of Warp II."] = "ウィンダス石の区のShantottoに報告して魔法のスクロール：デジョンII。",
    ["Zone in and out if you have just completed Blast from the Past."] = "過去からの呼び声直後ならエリアチェンジ。",
    ["Optional: speak with Yoran-Oran (E-5) about the author of the thesis on alchemy, and with Shantotto (K-7) about alchemy."] = "任意：Yoran-Oran(E-5)に論文著者、Shantotto(K-7)に錬金術の話を聞く。",
    ["Speak with Fuepepe in Windurst Waters North (L-6)."] = "ウィンダス水の区北(L-6)のFuepepeに話す。",
    ["Go north to the Acolyte Hostel (K-6) and interact with each of the six doors on the ground floor to play Quiz de Vana'diel. Answer a question correctly, then go to another door, until you have 4 to 6 correct answers."] = "北のAcolyte Hostel(K-6)1階の6扉でヴァナ・ディールクイズ。正解するたび別の扉へ移り4〜6問正解を目指す。",
    ["After the questions, go to the western Acolyte Hostel building (K-5) for a cutscene and receive the Thesis on alchemy."] = "回答後、西側の建物(K-5)でイベントを見てThesis on alchemyを得る。",
    ["Answering all 6 questions correctly also gives you a Vile Elixir. If you already have one you cannot complete the quest: zone out, get rid of it, then come back to continue. With 4 correct answers the quest continues, but you get no Vile Elixir."] = "6問正解ならVile Elixirも得る。既に所持していると進まないので、エリアチェンジして整理後戻る。4問正解でも進行できるが薬はもらえない。",
    ["Return to Koru-Moru for a cutscene."] = "Koru-Moruに戻ってイベントを見る。",
    ["Obtain a Cold Bone, which can be bought at the Auction House or dropped by Doom Soldier enemies that appear at night in Cape Teriggan."] = "冷たい骨を競売かテリガン岬の夜間のDoom Soldierから用意。",
    ["Obtain a Warm Egg, which can be bought at the Auction House or dropped by Anemone enemies in Yhoator Jungle."] = "温かい卵を競売かヨアトル大森林のAnemoneから用意。",
    ["Trade the Cold Bone and Warm Egg to Koru-Moru for a cutscene."] = "Koru-Moruに冷たい骨と温かい卵を渡してイベント。",
    ["Return to Koru-Moru in a few days (after Japanese midnight) to complete the quest and receive your reward."] = "原文では数日後、日本時間の午前0時をまたいでKoru-Moruに戻ると完了。",
    ["Obtain a Carbuncle's Ruby from a Leech enemy."] = "Leech系の敵からカーバンクルの紅玉を入手。",
    ["Go to Windurst Walls (G-3) and examine the door of the House of the Hero for a cutscene."] = "ウィンダス石の区(G-3)のHouse of the Heroを調べる。",
    ["With the Carbuncle's Ruby in your inventory, zone into areas while each weather is occurring to get a cutscene for each color. You cannot just idle in a zone, and the Storm spells of a Scholar do not count. You can check the Weather Forecast for the current weather and the next 2 game days."] = "カーバンクルの紅玉を所持して対象天候のエリアへ入り各色のイベントを見る。同じ場所で待つだけでは不可、学者の陣も対象外。天気予報は現在と翌々日まで確認可能。原文は必要な7種の天候一覧を省略している。",
    ["If you drop the Carbuncle's Ruby before completing the quest, you do not lose progress; simply obtain another one."] = "完了前にカーバンクルの紅玉を捨てても進行は残る。再入手すれば続行可。",
    ["Go to La Theine Plateau (G-6) and trade the Carbuncle's Ruby to the ??? for a cutscene that completes the quest."] = "ラテーヌ高原(G-6)の???にカーバンクルの紅玉を渡して完了。",
    ["You cannot start this quest while another Weapon Skill quest is active; return to the person who gave it and quit it first. It requires Staff skill 230 or higher and level 71."] = "他のWSクエスト進行中なら先に取消。両手棍230以上、71以上が必要。",
    ["Speak with Shantotto in Windurst Walls (K-7) to receive the key item Weapons Training Guide and the Pole of Trials."] = "ウィンダス石の区(K-7)のShantottoからWeapons Training GuideとPole of Trialsを得る。",
    ["Break the latent on the Pole of Trials. With it equipped in your main hand, fight enemies rated Extremely Easy Prey or higher and use weapon skills or close skillchains until you accumulate 300 Trial Points: 5 points with no skillchain, 7 at level 1, 9 at level 2 and 11 at level 3."] = "Pole of Trialsをメインに装備し、経験値の入る強さの敵へのWSや連携で潜在を消す。原文は300ポイント、単発5・連携レベル1で7・2で9・3で11と記載。小売版との配点差に注意。",
    ["The latent is broken when the elemental resistances listed in the Pole of Trials description disappear from the elemental resistances shown under the equipped gear grid in the equipment window."] = "装備画面の属性耐性からPole of Trialsの補正が消えたら潜在消し完了。",
    ["Trade the Pole of Trials back to Shantotto. You are instructed to travel to Ifrit's Cauldron."] = "Pole of TrialsをShantottoに返しイフリートの釜行きを指示される。",
    ["Take the Ifrit's Cauldron Home Point #1 to map 7. Run south, then north, to fall off the lip at (J-4). Enter Ifrit's Cauldron directly to the north."] = "イフリートの釜のHome Point #1から原文マップ7へ。南、その後北へ進み(J-4)の縁から下り、北の入口から入り直す。",
    ["Inside Ifrit's Cauldron, follow the path to the first junction and go north. The fight there is against Cailleach Bheur, a skeleton."] = "中の最初の分岐を北へ。対象NMは骨のCailleach Bheur。原文は証拠回収・終了報告を省略している。",
    ["Examine the House of the Hero in Windurst Walls while your job is set to Summoner to start the quest."] = "召喚士でウィンダス石の区のHouse of the Heroを調べて受領。",
    ["Speak with Koru-Moru (E-7). His reference to a Rhinostery Researcher means Ripapa."] = "Koru-Moru(E-7)に話す。鼻の院の研究員とはRipapaのこと。",
    ["Go to Mhaura and speak with Ripapa (I-9) to obtain a Lightning Pendulum."] = "マウラ(I-9)のRipapaから雷の振子を得る。",
    ["Return to Windurst Walls and speak with Koru-Moru to obtain the key item Daze-breaker charm."] = "ウィンダス石の区のKoru-Moruから夢幻破りの札を得る。原文は雷の回廊での工程を省略している。",
    ["Go to Rabao and speak with Agado-Pugado (G-9) to receive a Wind Pendulum."] = "ラバオ(G-9)のAgado-Pugadoから風の振子を得る。",
    ["The Cloister is at (F-5) in Cape Teriggan. Defeat Ogmios, who is a Manticore."] = "テリガン岬(F-5)の回廊でマンティコアのOgmiosを倒す。",
    ["Return to Windurst Walls and speak with Koru-Moru to receive your Evoker's Horn and complete the quest. You can toss the Lightning Pendulum and the Wind Pendulum afterwards, as they serve no further purpose."] = "ウィンダス石の区のKoru-Moruに報告してエボカーホーン。完了後雷の振子と風の振子は処分可。",
    ["Speak with Baren-Moren in the hat shop in Windurst Waters South (H-7) to start the quest and receive the New Model Hat."] = "ウィンダス水の区南(H-7)の帽子屋Baren-MorenからNew Model Hatを受け取る。",
    ["Stay in Windurst Waters until the quest is finished, and show the hat off by talking to the townsfolk."] = "完了までウィンダス水の区から出ず、町の人々に話して帽子を宣伝。",
    ["Talk to Bondada in the hat shop, Honoi-Gomoi in Gingerberry Grove (E-7) and Kenapa-Keppa in the Rhinostery (South map), since they react to the hat."] = "帽子屋のBondada、南マップ(E-7)のHonoi-Gomoi、鼻の院のKenapa-Keppaに話す。",
    ["On the North map, talk to Clais near the bridge to the Rarab's Tail Hostelery (G-10), Kyume-Romeh in the Timbre Timbers Tavern (F-10), Tosuka-Porika in the east Optistery (G-8), Pechiru-Mashiru in the east Aurastery (L-6) and Machitata near the Mog House (L-11)."] = "北マップでは(G-10)ララブのしっぽ亭への橋近くのClais、(F-10)酒場のKyume-Romeh、(G-8)目の院のTosuka-Porika、(L-6)耳の院のPechiru-Mashiru、(L-11)モグハウス付近のMachitataに話す。",
    ["Keep talking to as many other NPCs as you can: too few gives no credit, and the reward grows with the number you speak to."] = "さらにできるだけ多くの人に話す。人数不足は不成立、宣伝数で報酬が増えると原文に記載。",
    ["Return to Baren-Moren and choose \"Hang up your hat\" to complete the quest and receive your reward."] = "Baren-Morenに戻り「Hang up your hat」を選んで完了。",
    ["Make sure you are wearing a body armor piece, or the quest cannot start."] = "胴装備を着てから受領。未装備では開始できない。",
    ["Speak with Angelica in Windurst Waters (F-10); she asks for a piece of body armor that depends on your job."] = "ウィンダス水の区(F-10)のAngelicaに話すとジョブ別の胴装備を指定される。",
    ["Bring the item she asks for: Bronze Harness (Warrior, Paladin, Dark Knight, Dragoon, Corsair), Robe (Monk, Bard, Blue Mage), Leather Vest (Thief, Beastmaster, Ranger, Dancer), Tunic (White Mage, Red Mage, Black Mage, Summoner, Puppetmaster) or Kenpogi (Ninja, Samurai). The +1 versions do not work."] = "指定品を着る。ブロンズハーネス：戦・ナ・暗・竜・コ、ローブ：モ・吟・青、レザーベスト：シ・獣・狩・踊、チュニック：白・赤・黒・召・か、拳法着：忍・侍。HQ品は不可。",
    ["The quest is timed: if you take too long to return dressed in the requested item, it ends without success. You can try again by zoning out and back in."] = "時間制限あり。指定装備で戻るのが遅いと失敗するが、エリアチェンジで再挑戦できる。",
    ["Talk to Angelica and stand still for 10 seconds."] = "Angelicaに話し、動かず10秒待つ。",
    ["Talk to Angelica again; she tells you to wear your item."] = "再び話し、装備を戻すよう言われる。",
    ["Talk to Angelica one last time to complete the quest and receive Ancient Blood and Angelica's autograph."] = "最後にもう一度話して完了。原文報酬は太古の血潮とアンジェリカのサイン。",
    ["Speak with Hariga-Origa in Windurst Waters North (F-8); you receive the key item Note from Hariga-Origa, to be delivered to Ipupu."] = "ウィンダス水の区北(F-8)のHariga-OrigaからNote from Hariga-Origaを受け取りIpupuへ届ける。",
    ["Take the note to Ipupu in West Sarutabaruta (I-8/J-8), near the entrance to Windurst Waters."] = "西サルタバルタ(I-8/J-8)、ウィンダス水の区入口付近のIpupuに渡す。",
    ["Ipupu accepts it and gives you the key item Note from Ipupu in return."] = "IpupuからNote from Ipupuを受け取る。",
    ["Deliver the Note from Ipupu to Hariga-Origa to complete the quest and receive your rewards."] = "Hariga-Origaに返答を届けて報酬。",
    ["Speak with Lumomo in the Timbre Timbers Tavern in Windurst Waters (F-10). You must be level 25 or higher."] = "25以上でウィンダス水の区(F-10)の酒場のLumomoから受領。",
    ["Go to the Maze of Shakhrami and speak with Ahko Mhalijikhari (C-9) to receive the level cap status. The level cap is 25, Trust magic is usable and buffs do not wear off."] = "シャクラミの地下迷宮(C-9)のAhko Mhalijikhariに話して25制限を受ける。原文ではフェイス使用可、強化は消えないと記載。",
    ["Go to (H-8) on map 1 to reach map 2."] = "原文マップ1(H-8)からマップ2へ。",
    ["Go to (I-10) on map 2 and examine the ??? to spawn three Wyrmfly (Fly NMs)."] = "マップ2(I-10)の???を調べWyrmfly3体を出す。",
    ["After defeating all three, examine the ??? once more to receive the key item Indigested meat."] = "3体を倒して???を再調査しIndigested meatを得る。",
    ["Report to Lumomo to receive your reward."] = "Lumomoに報告して報酬。",
    ["The quest Cook's Pride must be active."] = "Cook's Prideを進行中にしておく。",
    ["Obtain a Royal Jelly. Death Jacket enemies are common near the main entrance of Crawlers' Nest."] = "ロイヤルゼリーを入手。クロウラーの巣の正面入口付近のDeath Jacket等が対象。",
    ["Trade the Royal Jelly to Maysoon in Windurst Waters (E-9) to complete the quest and receive the key item Super soup pot."] = "ウィンダス水の区(E-9)のMaysoonにロイヤルゼリーを渡しSuper soup potを得る。",
    ["Speak with Chamama in Windurst Waters (F-10) to start the quest."] = "ウィンダス水の区(F-10)のChamamaから受領。",
    ["Obtain a Smooth Stone, which drops from Crawler enemies in East Sarutabaruta and West Sarutabaruta."] = "東サルタバルタ／西サルタバルタのCrawlerから円石を入手。",
    ["Trade the Smooth Stone to Chamama."] = "Chamamaに円石を渡す。",
    ["Chamama does not always accept the stone: if she refuses it, get another Smooth Stone and bring it to her. It can be rejected several times in a row."] = "石が気に入らないと受け取らないので、別の円石を取り直す。何度か断られることもある。",
    ["Speak with Moreno-Toeno in the east Aurastery in Windurst Waters North (L-6). You may need to speak with him twice."] = "ウィンダス水の区北(L-6)、耳の院のMoreno-Toenoに話す。2回会話が必要な場合もある。",
    ["Obtain a Bird Feather. It can be bought at the Auction House, or dropped by Carrion Crow enemies outside Windurst."] = "鳥の羽根を競売かウィンダス周辺のCarrion Crowから用意。",
    ["Obtain a Two-Leaf Mandragora Bud, which only drops from Mandragora enemies such as Tiny Mandragora in East and West Sarutabaruta."] = "東サルタバルタ／西サルタバルタのTiny Mandragora等からマンドラゴラの双葉を得る。",
    ["Trade the Bird Feather and the Two-Leaf Mandragora Bud to Moreno-Toeno to complete the quest and receive 250 gil."] = "Moreno-Toenoに鳥の羽根とマンドラゴラの双葉を渡し250ギル。",
    ["Speak with Ranpi-Monpi in the Culinarians' Guild in Windurst Waters North (D-9); he accidentally spoiled the food offering meant for the Yagudo."] = "ウィンダス水の区北(D-9)調理ギルドのRanpi-Monpiから、ヤグードへの供物を傷めた話を聞く。",
    ["Travel to Giddeus."] = "ギデアスへ。",
    ["Go down into the underground cave area behind the food or drink altar and examine the altar to receive the key item Off Offering."] = "食料／飲料の祭壇の奥から地下へ下り、奥の祭壇を調べてOff Offeringを得る。",
    ["Return to Ranpi-Monpi and speak with him again to complete the quest and receive 400 gil."] = "Ranpi-Monpiに報告して400ギル。",
    ["Speak with Tosuka-Porika in Windurst Waters North (G-8) to start the quest; you are sent to Furakku-Norakku, who gives you the Overdue book notification for Orn."] = "ウィンダス水の区北(G-8)のTosuka-Porikaから受領しFurakku-Norakkuへ。Orn宛Overdue book notificationを得る。",
    ["Deliver it to Orn at (F-10), in the Rarab Tail Hostelry room above the Timbre Timbers Tavern."] = "(F-10)酒場上階のララブのしっぽ亭にいるOrnへ届ける。",
    ["Optional: speak with Furakku-Norakku again at Orn's request."] = "任意：Ornの依頼でFurakku-Norakkuに再び話す。",
    ["Go to Giddeus and speak with Quu Bokye, then trade a Silver Beastcoin to receive \"Art for Everyone\"."] = "ギデアスのQuu Bokyeに話し、獣人銀貨を渡してArt for Everyoneを得る。",
    ["Quu Bokye is in the Treasure Room on the underground map of Giddeus: the northwest room at the end of a U-turn on the map."] = "Quu Bokyeはギデアス地下マップ北西、折返し通路の先の宝物庫にいる。",
    ["Speak with Furakku-Norakku with the key item to complete the quest."] = "本を持ちFurakku-Norakkuに話して完了。",
    ["Speak with Moari-Kaaori in Windurst Waters South (C-9) to start the quest. Home Point #3 is the closest."] = "ウィンダス水の区南(C-9)のMoari-Kaaoriから受領。Home Point #3が近い。",
    ["If you answer all the questions correctly, you are sent after a Tahrongi Cactus."] = "質問にすべて正答するとタロンギカクタスを頼まれる、と原文に記載。",
    ["Go to Tahrongi Canyon (F-6) and examine the Tahrongi Cacti there to get a Tahrongi Cactus."] = "タロンギ大峡谷(F-6)のTahrongi Cactiを調べタロンギカクタスを得る。",
    ["Give the flower to Moari-Kaaori to receive your reward: an Iron Sword the first time and 400 gil on later completions."] = "Moari-Kaaoriに花を渡す。原文では初回アイアンソード、反復400ギル。",
    ["Alternatively, buy a Carnation in Upper Jeuno for 60 gil and trade it to Moari-Kaaori after speaking with him, which skips the trip."] = "代わりにジュノ上層でCarnationを60ギルで買い、会話後に渡すと旅を省略可、と原文に記載。",
    ["You must zone after completing Food for Thought before you can start this quest."] = "買出し部隊完了後はエリアチェンジしてから受領。",
    ["Speak with Kenapa-Keppa in Windurst Waters South (J-9) after 7:00 Vana'diel time; you need to speak with him four times to officially begin the quest."] = "ヴァナ時間07:00以降、ウィンダス水の区南(J-9)のKenapa-Keppaに4回話して正式受領。",
    ["Go to Mhaura and speak with Kotan-Purutan at (I-9), near the ferry ticket area, after 18:00 Vana'diel time to obtain a Small bag."] = "18:00以降、マウラ(I-9)乗船券売場付近のKotan-PurutanからSmall bagを受け取る。",
    ["Return to Kenapa-Keppa before 6:00 to complete the quest."] = "06:00までにKenapa-Keppaへ届けて完了。",
    ["Zone first if you have just completed Overnight Delivery."] = "夜に隠れて直後ならエリアチェンジ。",
    ["Speak with Ohbiru-Dohbiru in Windurst Waters South (J-9) to receive a Rhinostery Canteen."] = "ウィンダス水の区南(J-9)のOhbiru-DohbiruからRhinostery Canteenを受け取る。",
    ["Trade the Rhinostery Canteen to the Giddeus Spring at (K-12) or (E-12) in Giddeus to receive a Canteen of Giddeus water."] = "ギデアス(K-12)または(E-12)のギデアス Springに水筒を渡しギデアスの名水を得る。",
    ["Return to Ohbiru-Dohbiru and trade him the Canteen to complete the quest and receive 900 gil."] = "Ohbiru-Dohbiruに水を渡し900ギル。",
    ["This quest is repeatable, but it cannot be repeated if you have activated the quest Curses, Foiled A-Golem!?."] = "反復可能だが、ゴーレムのまなざし受領中は繰り返せない。",
    ["Complete Hat in Hand first, then zone before taking this quest."] = "帽子屋の宣伝を先に完了し、エリアチェンジして受領。",
    ["Speak with Baren-Moren in the hat shop in Windurst Waters South (H-7); he asks you to bring him Giant Bird Feather x3."] = "ウィンダス水の区南(H-7)の帽子屋Baren-MorenからGiant Bird Feather3枚を頼まれる。",
    ["Collect Giant Bird Feather x3, which drop from Tabar Beak and Axe Beak enemies in the Meriphataud Mountains and Sauromugue Champaign."] = "メリファト山地／ソロムグ原野のTabar BeakやAxe BeakからGiant Bird Feather3枚を得る。",
    ["Trade Giant Bird Feather x3 to Baren-Moren in a single trade to complete the quest and receive 1,500 gil."] = "Baren-Morenに3枚まとめて渡し1,500ギル。",
    ["Zone first if you have just completed Early Bird Catches the Bookworm."] = "知識の守り手直後ならエリアチェンジ。",
    ["Speak with Tosuka-Porika in Windurst Waters (G-8)."] = "ウィンダス水の区(G-8)のTosuka-Porikaに話す。",
    ["Speak with Furakku-Norakku behind the counter in the same room. He says that Hae Jakkya at the Windurst Woods Auction House has an overdue romance novel, \"A Song of Love\", and gives you an Overdue book notification."] = "同室カウンター奥のFurakku-NorakkuからHae Jakkya宛Overdue book notificationを得る。延滞本はA Song of Love。",
    ["Deliver the notification to Hae Jakkya at (I-12) in Windurst Woods."] = "ウィンダス森の区(I-12)競売のHae Jakkyaに通知を届ける。",
    ["Return to Furakku-Norakku."] = "Furakku-Norakkuへ戻る。",
    ["Go to Southern San d'Oria and speak with Hae Jakhya (G-9) to receive the overdue library book, \"A Song of Love\". She is on top of the wall, so take the passage at (F-8) to get up there."] = "南サンドリア(G-9)のHae JakhyaからA Song of Loveを得る。城壁上へは(F-8)の通路から上がる。2人のNPC名の綴りの違いに注意。",
    ["Return the book to Furakku-Norakku to complete the quest and receive 2,800 gil."] = "Furakku-Norakkuに本を返し2,800ギル。",
    ["Make sure Let Sleeping Dogs Lie is not active, and zone first if you have just finished it."] = "暁を覚えず受領中は先に終え、直後ならエリアチェンジ。",
    ["Speak with Fuepepe in the Aurastery in Windurst Waters North (L-6); the students' exam answer sheets have been stolen."] = "ウィンダス水の区北(L-6)耳の院のFuepepeから答案盗難の話を聞く。",
    ["Obtain the Test Answers, which drop from Wendigo enemies inside Inner Horutoto Ruins and can also be bought at the Auction House."] = "内ホルトト遺跡のWendigoから魔法試験の答案の束を得る。競売でも購入可。",
    ["Trade the Test Answers to Fuepepe, who tells you to take them to Koru-Moru in Windurst Walls."] = "Fuepepeに魔法試験の答案の束を渡し、Koru-Moruへ届けるよう頼まれる。",
    ["Trade the Test Answers to Koru-Moru in Windurst Walls."] = "ウィンダス石の区のKoru-Moruに魔法試験の答案の束を渡す。",
    ["Return to Fuepepe to complete the quest and receive the Scroll of Aspir."] = "Fuepepeに報告し魔法のスクロール：アスピル。",
    ["Trust magic cannot be used in this battlefield."] = "このBFではフェイス使用不可。",
    ["Speak with Kerutoto in Windurst Waters South (J-8), near Home Point #3, for a cutscene that starts the quest and gives you the key item Vial of dream incense."] = "ウィンダス水の区南(J-8)、Home Point #3付近のKerutotoからVial of dream incenseを受け取る。",
    ["Go to Pso'Xja Home Point #1. Alternatively, travel to Beaucedine Glacier (H-8) and enter Pso'Xja; the Beaucedine Glacier Survival Guide brings you to (H-9), just south of the entrance."] = "ソ・ジヤのHome Point #1へ。初回はボスディン氷河(H-8)から入る。Survival Guideは入口の南(H-9)に到着。",
    ["Once inside, the correct displacement sequence is red, purple, red, purple."] = "中の転送床は赤→紫→赤→紫。",
    ["Select the Memento Circle and pick Waking Dreams."] = "Memento Circleで笑み曲ぐ夢魔とを選択。",
    ["Defeat Diabolos Prime to receive the key item Whisper of dreams."] = "Diabolos Primeを倒しWhisper of dreamsを得る。",
    ["Return to Kerutoto with the whisper. She offers several rewards, including the ability to summon Diabolos; you can only select one reward at a time."] = "Kerutotoに息吹を渡し報酬を1つ選ぶ。Diabolos召喚契約も選択肢。",
    ["You can repeat this quest once per Earth day."] = "地球時間1日1回反復可能。",
    ["If your Windurst fame is level 4 or higher, you are assigned Let Sleeping Dogs Lie instead, and you cannot start this quest until you complete that one."] = "ウィンダス名声4以上では暁を覚えずが優先され、そちらを終えるまで受領不可。",
    ["Speak with Mashuu-Ajuu in Windurst Waters North (K-6); he gives you a bag of Herb Seeds and asks you to plant them."] = "ウィンダス水の区北(K-6)のMashuu-AjuuからHerb Seedsを受け取る。",
    ["Plant the seeds to grow a Deathball or a Sobbing Fungus, or buy one at the Auction House. A Sobbing Fungus can also be bought from Soupox in Leafallia for 60 gil."] = "栽培してデスボール／シャクリタケを得るか競売で購入。シャクリタケはリファーリアのSoupoxでも60ギル。",
    ["Trade a Deathball to Mashuu-Ajuu to receive a Stationery Set and 700 gil, or a Sobbing Fungus to receive a Stationery Set and 500 gil."] = "Mashuu-Ajuuにデスボールなら文房具一式と700ギル、シャクリタケなら文房具一式と500ギル。",
    ["To repeat the quest you must trade a Sobbing Fungus."] = "反復時はシャクリタケを渡す。",
    ["Completing Reap What You Sow is not required to start this quest. It cannot be started while Making the Grade is active."] = "トップを目指すタイプの完了は不要。間違いと過ち進行中は開始不可。",
    ["Speak with Mashuu-Ajuu (K-6) and then Paku-Nakku to start the quest."] = "Mashuu-Ajuu(K-6)、Paku-Nakkuの順に話す。",
    ["Speak with Maabu-Sonbu in Port Windurst (E-7), near Home Point #1."] = "ウィンダス港(E-7)、Home Point #1付近のMaabu-Sonbuに話す。",
    ["Harvest at the ??? at (E-5) to obtain the Blazing Pepper."] = "(E-5)の???でBlazing Pepperを採る。原文では採集エリアの説明が省略されている。",
    ["Trade the Blazing Pepper to Paku-Nakku, then speak with Paku-Nakku again."] = "Paku-NakkuにBlazing Pepperを渡し、再度話す。",
    ["The quest can also be completed without the Blazing Pepper: trade Paku-Nakku a remedy, go back to Maabu-Sonbu, who points you to Pechiru-Mashiru for advice, then go back to Paku-Nakku, choose \"The automaton butler did it!\" and get the reward from Pechiru-Mashiru. Trading the remedy locks you out of trading the Blazing Pepper."] = "別ルート：Paku-Nakkuに万能薬→Maabu-Sonbu→Pechiru-Mashiruの助言→Paku-Nakkuで「The automaton butler did it!」を選択→Pechiru-Mashiruから報酬。万能薬を渡すとBlazing Pepperのルートには戻れない。",
    ["Speak with Gantineux on the second floor of the Rarab Tail Hostelry in Windurst Waters (E-10); Home Point #4 is the closest. He gives you the key item Spirit incense and asks you to go to The Eldieme Necropolis."] = "ウィンダス水の区(E-10)ララブのしっぽ亭2階のGantineuxから鎮魂香を得る。Home Point #4が近い。",
    ["Go to The Eldieme Necropolis and look for a ??? that spawns in one of four locations. It can be reached via Beaucedine Glacier, the Lycopodium warps or the Unity warp to the zone."] = "エルディーム古墳内4候補のどこかにある???を探す。ボスディン氷河側、リコポディウム転送、ユニティ転送などを利用。",
    ["Click the ???; the incense always fails to light. If others are also doing the quest, the ??? remains after you click it."] = "???を調べると香には必ず着火しない。他の同行者も調べられる。",
    ["Go back to Gantineux, who gives you the key item Gantineux's letter and tells you to deliver it to Eperdur."] = "GantineuxからGantineux's letterを得てEperdurへ届ける。",
    ["Go to Northern San d'Oria and speak with Eperdur (M-7) upstairs in the Cathedral to complete the quest and receive a Scroll of Teleport-Mea."] = "北サンドリア(M-7)、大聖堂上階のEperdurに話し魔法のスクロール：テレポメア。",
    ["You must zone after completing Chasing Tales before you can start this quest."] = "ある愛のうた完了後はエリアチェンジしてから受領。",
    ["Speak with Hariga-Origa in Windurst Waters (F-8)."] = "ウィンダス水の区(F-8)のHariga-Origaに話す。",
    ["Obtain a Slime Oil and a Frost Turnip."] = "スライムオイルとシモカブを用意。",
    ["Trade the Slime Oil and the Frost Turnip to Hariga-Origa at the same time to complete the quest and receive your reward."] = "2品をHariga-Origaに同時に渡して報酬。",
    ["Speak with Leepe-Hoppe on top of the Rhinostery in Windurst Waters South (J-9) to start the quest."] = "ウィンダス水の区南(J-9)、鼻の院屋上のLeepe-Hoppeから受領。",
    ["Leepe-Hoppe needs 3 items, all of which must be farmed in Chains of Promathia areas."] = "プロマシアエリアの敵が落とす3品を集める。",
    ["An Extra-Fine File drops from Fomor enemies in Lufaise Meadows: Fomor Warrior, Fomor Monk, Fomor Dark Knight, Fomor Paladin and Fomor Samurai."] = "ルフェーゼ野のFomor Warrior／Monk／Dark Knight／Paladin／Samuraiから油目ヤスリ。",
    ["A Spruce Lumber drops from Taurus enemies in Phomiuna Aqueducts; 3 Taurus can be found at (G-6) of Map 1. Enter Phomiuna Aqueducts from Tavnazian Safehold, or use the Survival Guide and head northwest."] = "フォミュナ水道のTaurusからスプルース材。原文マップ1(G-6)に3体。タブナジア地下壕経由、またはSurvival Guideから北西へ。",
    ["A Magicked Steel is found on various Goblin enemies in Oldton Movalpolos. It is advised to farm Goblin Oilman, which seem to have a higher drop rate: use the Proto-Waypoint, drop down the ledge and head west."] = "ムバルポロス旧市街のゴブリンから魔炉鋼。原文推奨はGoblin Oilmanで、Proto-Waypointから段差を下り西へ。",
    ["Trade all 3 items to Leepe-Hoppe at once to complete the quest and receive 4,000 gil. Speak with Leepe-Hoppe again to start the quest Tuning Out."] = "Leepe-Hoppeに3品同時に渡して4,000ギル。さらに話すと仮面同盟へ。",
    ["To get a Purple Ribbon, first speak with Roberta in the Nchaa's Good Goods shop in Windurst Woods (I-13)."] = "ウィンダス森の区(I-13)雑貨屋のRobertaに話しパープルリボンを得る。",
    ["Give the Purple Ribbon to Kerutoto in the northern Rhinostery building in Windurst Waters South (J-8)."] = "ウィンダス水の区南(J-8)、鼻の院北側建物のKerutotoにパープルリボンを渡す。",
    ["Wait one Earth minute, then speak with Kerutoto again; she gives the ribbon back."] = "地球時間1分後、Kerutotoに話してリボンを返してもらう。",
    ["Trade the Purple Ribbon to the Hume Bones at (M-10) to spawn the NM Lich C Magnus."] = "(M-10)のHume Bonesにパープルリボンを渡しLich C Magnusを出す。原文ではエルディーム古墳への移動説明を省略。",
    ["If the rod does not drop, rezone without touching the Hume Bones and repeat the quest from the beginning for another chance."] = "原文の「杖」が出なければHume Bonesに触れずエリアチェンジし最初から再挑戦、との説明。必要品か追加ドロップかは原文で明示されていない。",
    ["If you lose the Purple Ribbon, you must wait until the next Conquest Tally to get it back. If several party members need the quest, wait 5 minutes after the defeat between each spawn."] = "パープルリボンを失うと次のコンクェスト集計まで再取得不可。複数人なら討伐後5分待って次の出現へ。",
    ["After the NM is defeated, check the Hume Bones again to receive a Blue Ribbon."] = "NM討伐後Hume Bonesを再調査してBlue Ribbonを得る。",
    ["Return to Kerutoto to complete the quest."] = "Kerutotoに報告して完了。",
    ["In Windurst Waters North, enter the Timbre Timbers tavern (F-10) and speak with Yuli Yaam, then Yung Yaam, then Jatan-Paratan."] = "ウィンダス水の区北(F-10)酒場でYuli Yaam→Yung Yaam→Jatan-Paratanの順に話す。",
    ["Answer \"I have no recollection at all\" to continue, then speak with Jatan-Paratan again; the quest now appears in your quest log."] = "「I have no recollection at all」を選び、Jatan-Paratanに再度話して正式受領。",
    ["Speak with Aramu-Paramu."] = "Aramu-Paramuに話す。",
    ["Go to Lower Jeuno and speak with Ruslan (I-8) in the Merry Minstrel tavern."] = "ジュノ下層(I-8)、吟遊詩人の酒場のRuslanに話す。",
    ["Trade a piece of Rosewood Lumber to Jatan-Paratan to complete the quest and receive your reward."] = "Jatan-Paratanにローズウッド材を渡して報酬。",
    ["If you have just completed Blue Ribbon Blues, zone first."] = "呪われたリボン直後ならエリアチェンジ。",
    ["Speak with Ohbiru-Dohbiru in Windurst Waters South (J-9) for a cutscene. You receive the key item Rhinostery certificate, which gives access to Toraimarai Canal through Windurst Walls (H-3)."] = "ウィンダス水の区南(J-9)のOhbiru-DohbiruからRhinostery certificateを得る。ウィンダス石の区(H-3)からトライマライ水路に入れるようになる。",
    ["To find Starmites, enter Toraimarai Canal by speaking with Seven of Diamonds in Windurst Walls (H-3). Go up the stairs at (I-9), then head west to (G-9), where the Starmites spawn."] = "ウィンダス石の区(H-3)のSeven of Diamondsからトライマライ水路へ入り、(I-9)の階段を上がり西の(G-9)へ。",
    ["Starmite Shell drops from Starmite enemies. Get Starmite Shell x3."] = "StarmiteからStarmite Shell3個を得る。",
    ["Return to Ohbiru-Dohbiru and trade him the shells to complete the quest and receive 4,500 gil."] = "Ohbiru-Dohbiruに甲殻を渡し4,500ギル。",
    ["Warning: Trust magic cannot be used in the final battle at the Full Moon Fountain."] = "注意：満月の泉の最終BFではフェイス使用不可。",
    ["Speak with Leepe-Hoppe in Windurst Waters South (J-9) to start the quest. If the quest Tuning In is offered instead (cutscene with Shikaree Y), zone and speak with Leepe-Hoppe again to get the right cutscene."] = "ウィンダス水の区南(J-9)のLeepe-Hoppeから受領。スカリーY（Shikaree Yのイベント）が先ならエリアチェンジして再度話す。",
    ["Defeat the six avatar primes to collect their whispers. Do not give the whispers to the NPCs who grant access to those battles, or you will lose them."] = "6属性の召喚獣を倒し息吹を集める。各試練の依頼NPCに渡すと失うので渡さない。",
    ["Turn the whispers in to Leepe-Hoppe to receive a Moon bauble."] = "6つの息吹をLeepe-Hoppeに渡しMoon baubleを得る。",
    ["Go to the Full Moon Fountain. It helps to home point at Toraimarai Canal #1 beforehand, or you can warp to Toraimarai Canal with the Survival Guide."] = "満月の泉へ。トライマライ水路 #1のHome PointやSurvival Guideを登録しておくと便利。",
    ["With the Moon bauble key item, interact with the fountain to enter the battlefield. Up to 6 party members can enter, each needs their own Moon bauble, and the time limit is 30 minutes."] = "Moon bauble所持で泉を調べBFへ。最大6人、全員がMoon baubleを所持、制限30分。",
    ["Defeat Fenrir Prime to receive the key item Whisper of the moon."] = "Fenrir Primeを倒しWhisper of the moonを得る。",
    ["Return to Leepe-Hoppe and turn in the whisper to receive your reward; you can only choose one of the rewards offered."] = "Leepe-Hoppeに息吹を渡し、提示された報酬から1つ選ぶ。",
    ["You can repeat this quest once per Earth day: after completing it, speak with Leepe-Hoppe again for another Moon bauble, without collecting the whispers again."] = "地球時間1日1回。以後は6つの息吹を集め直さず、Leepe-HoppeからMoon baubleを再受領可。",
    ["Speak with Leepe-Hoppe in Windurst Waters South (J-9) to start the quest. You must wait one Earth minute after completing Tuning In."] = "スカリーY完了から地球時間1分待ち、ウィンダス水の区南(J-9)のLeepe-Hoppeから受領。",
    ["Speak with Jakoh Wahcondalo in Kazham (J-9)."] = "カザム(J-9)のJakoh Wahcondaloに話す。",
    ["Speak with Romaa Mihgo in Kazham (H-11)."] = "カザム(H-11)のRomaa Mihgoに話す。",
    ["Return to Kazham and speak with Romaa Mihgo again."] = "カザムに戻ってRomaa Mihgoに再度話す。原文は途中の調査を省略している。",
    ["To progress further you need a Mutton Tortilla, Habaneros and a serving of Black Curry."] = "マトントルティーヤ、ハバネロ、ブラックカレーを用意。",
    ["Habaneros can be bought at the Auction House (Food, Ingredients) or from regional vendors, grown from Herb Seeds in your Mog Garden, or farmed from Mantrap enemies in Misareaux Coast."] = "ハバネロは競売（食材）・特産品店・Herb Seedsの栽培・ミザレオ海岸のMantrapなどで用意。原文はモグガーデンでの栽培と表現。",
    ["Black Curry can be bought at the Auction House (Food, Meals, Soups)."] = "ブラックカレーは競売（食品・汁物）で購入可。",
    ["Mutton Tortilla can be bought at the Auction House (Food, Meals, Breads & Rice), or from Taajiji at the Timbre Timbers Tavern in Windurst Waters North if Windurst is at least 2nd place in Conquest."] = "マトントルティーヤは競売（パン・米料理）、またはウィンダスがコンクェスト2位以上ならウィンダス水の区北の酒場のTaajijiで購入可。",
    ["The quest is marked complete after the cutscene. Speak with Leepe-Hoppe afterwards to receive a Cache-nez."] = "イベントで完了扱いになる。後でLeepe-Hoppeに話してカシュネを受け取る。原文は準備後の移動・交換を省略している。",
    ["Speak with Ropunono in Windurst Waters (F-7) to start the quest."] = "ウィンダス水の区(F-7)のRopunonoから受領。",
    ["Obtain an Ahriman Lens and trade it to Ropunono."] = "アーリマンのレンズをRopunonoに渡す。",
    ["Go to the Maze of Shakhrami and defeat Wight enemies to obtain a Rusty Key."] = "シャクラミの地下迷宮のWightからぼろぼろのカギを得る。",
    ["Trade the Rusty Key to the Iron Door at (K-9) on the second map."] = "原文マップ2(K-9)のIron Doorにぼろぼろのカギを渡す。",
    ["Inside there are several chests, and three of them hold coins that depict the constellations. The correct coins are Odin to the north, Alexander to the northeast, Shiva to the east and Garuda to the southeast."] = "室内の箱から星座に合う硬貨を選ぶ。原文は硬貨入りが3箱とする一方、正解例として北Odin・北東Alexander・東Shiva・南東Garudaの4方位を列挙している。",
    ["Whichever coin you pick, correct or not, you receive a Shelling Piece."] = "正誤にかかわらずタルタル古銭を得る。",
    ["Trade the Shelling Piece to Ropunono to complete the quest and receive 4,800 gil."] = "Ropunonoにタルタル古銭を渡し4,800ギル。",
    ["This quest cannot be started if you have started Say It with Flowers or the mission The Price of Peace."] = "花と修羅やThe Price of Peace進行中は開始不可。",
    ["Before starting, check whether Kerutoto keeps asking about challenging Diabolos. If so, you must accept that quest (Waking Dreams) first; once it is in your quest log, you can start Food for Thought."] = "KerutotoがDiabolosへの挑戦を繰り返し勧めるなら、先に笑み曲ぐ夢魔とを受領してログへ載せてから買出し部隊を受ける。",
    ["Go to the northern Rhinostery building and speak with Kerutoto in Windurst Waters South (J-8); the quest is added to your quest log."] = "ウィンダス水の区南(J-8)、鼻の院北側建物のKerutotoから正式受領。",
    ["Speak with Ohbiru-Dohbiru and Kenapa-Keppa again to get their food orders."] = "Ohbiru-DohbiruとKenapa-Keppaに再び話し料理の注文を聞く。",
    ["Trade the food orders: a Grilled Hare to Kerutoto, plus the orders you got from Ohbiru-Dohbiru and Kenapa-Keppa."] = "Kerutotoに野兎のグリルを渡し、ほか2人にも指定料理を渡す。原文は2人の料理名を省略している。",
    ["The quest completes automatically once the final order is traded, so you do not need to speak with Kerutoto again."] = "最後の料理を渡すと自動完了。Kerutotoへの再報告は不要。",
    ["Speak with Honoi-Gomoi in Windurst Waters South (E-7) to start the quest. He is upstairs in his house, reached by a back stairway."] = "ウィンダス水の区南(E-7)、家の裏階段を上がりHonoi-Gomoiから受領。",
    ["Speak with Kohlo-Lakolo in Port Windurst (G-5)."] = "ウィンダス港(G-5)のKohlo-Lakoloに話す。",
    ["Go to Windurst Walls (G-3) and check the door of the House of the Hero."] = "ウィンダス石の区(G-3)のHouse of the Heroの扉を調べる。",
    ["Go to Toraimarai Canal and open a Coffer there to obtain the Joker card. Various enemies in the zone drop the Toraimarai Coffer Key, or you can buy one from the Curio Vendor Moogle for 5,000 gil."] = "トライマライ水路のCofferからJoker cardを得る。Toraimarai Coffer Keyは現地の敵かCurio Vendor Moogle（5,000ギル）で用意。",
    ["If you spoke to Joker during the previous cutscene, return to the House of the Hero for your reward."] = "前のイベントでJokerに話した分岐なら、House of the Heroへ戻って報酬。",
    ["Return to Honoi-Gomoi to complete the quest."] = "Honoi-Gomoiに報告して完了。",
    ["Speak with Khoto Rokkorah in Windurst Waters North (H-10) for a cutscene that starts the quest."] = "ウィンダス水の区北(H-10)のKhoto Rokkorahから受領。",
    ["Touch the Peculiar Rootprints in Rolanberry Fields (S) at (H-14). The Rolanberry Fields (S) Survival Guide is the fastest way; second best is to teleport to the stronghold in Pashhow Marshlands (S) and zone into Rolanberry Fields (S)."] = "ロランベリー耕地 (S)(H-14)のPeculiar Rootprintsを調べる。Survival Guide、またはパシュハウ沼 (S)の拠点経由が便利。",
    ["Touch another Peculiar Rootprints in North Gustaberg (S) at (E-11), close to where Campaign Arbiters teleport you."] = "北グスタベルグ (S)(E-11)、カンパニエ転送先付近のPeculiar Rootprintsを調べる。",
    ["Touch the third and final Peculiar Rootprints in Meriphataud Mountains (S) at (L-4), near the zone line to The Sanctuary of Zi'Tah. The Meriphataud Mountains (S) Survival Guide and Recall-Meriph are both good ways to get there."] = "メリファト山地 (S)(L-4)、聖地ジ・タ入口付近のPeculiar Rootprintsを調べる。Survival GuideやRecall-Meriphを利用可。",
    ["Return to Khoto Rokkorah for the final cutscene and your reward."] = "Khoto Rokkorahに報告して報酬。",
    ["Speak with Kopuro-Popuro in Windurst Woods (H-10) to start the quest."] = "ウィンダス森の区(H-10)のKopuro-Popuroから受領。",
    ["Obtain a Rabbit Hide, a Two-Leaf Mandragora Bud and an Insect Wing."] = "野兎の毛皮、マンドラゴラの双葉、虫の翅を用意。",
    ["The Two-Leaf Mandragora Bud is exclusive and can be found by defeating most Mandragora-type enemies, including Tiny Mandragora in East Sarutabaruta and West Sarutabaruta."] = "マンドラゴラの双葉はEX品。東サルタバルタ／西サルタバルタのTiny Mandragoraなどから入手。",
    ["Trade the Two-Leaf Mandragora Bud, the Insect Wing and the Rabbit Hide to Kopuro-Popuro to complete the quest and receive 200 gil."] = "Kopuro-Popuroに3品を渡し200ギル。",
    ["Speak with Illu Bohjaa in Windurst Woods (I-6) to start the quest. When asked, you must answer \"Yup!\" for the quest to begin the first time."] = "ウィンダス森の区(I-6)のIllu Bohjaaから受領。初回は「Yup!」を選ぶ。",
    ["Obtain Silk Thread x3 or Crawler Calculus x3. Both drop from Crawler enemies in East Sarutabaruta and West Sarutabaruta."] = "Silk Thread3個かCrawler Calculus3個を用意。両方とも東サルタバルタ／西サルタバルタのCrawlerが落とす。",
    ["Silk Thread can also be bought from Meriri (only for Clothcraft Apprentices or higher) or from Kuzah Hpirohpon at the nearby Clothcrafting Guild (Home Point #5)."] = "絹糸はHome Point #5近くの裁縫ギルドのKuzah Hpirohpon、または徒弟以上ならMeririから購入可。",
    ["Trade either Silk Thread x3 or Crawler Calculus x3 to Illu Bohjaa to complete the quest and receive 600 gil."] = "Illu Bohjaaにどちらか3個を渡し600ギル。",
    ["Speak with Perih Vashai in Windurst Woods (K-7) as a Ranger, level 40 or higher, to receive the temporary key item Chieftainness's twinstone earring."] = "狩人40以上でウィンダス森の区(K-7)のPerih Vashaiに話しChieftainness's 双子石のピアスを得る。",
    ["She sends you to Ranguemont Pass to look for Semih Lafihna. Semih Lafihna is not there, so speak with Perchond at (F-10); Semih Lafihna was searching for Glittersand around the pond at (E-5)."] = "ラングモント峠へSemih Lafihnaを探しに行く。本人は不在なので(F-10)のPerchondから、(E-5)の池の輝ける砂を探していたと聞く。",
    ["Go to the pond at (E-5) and defeat Evil Weapon enemies until you get a Glittersand."] = "(E-5)の池付近のEvil Weaponから輝ける砂を得る。",
    ["Trade the Glittersand to Perchond, who gives you the temporary key item Perchond's envelope and explains that a merchant in Jugner Forest has also seen the creature, and that Semih Lafihna is probably there."] = "Perchondに渡してPerchond's envelopeを受け取り、ジャグナー森林の商人に向かう手掛かりを聞く。",
    ["After the cutscene, return to Perih Vashai to receive your Sniping Bow."] = "イベント後Perih Vashaiへ戻りスナイプボウ。原文は商人との中間イベントを省略している。",
    ["You must zone after completing Sin Hunting before you start this quest."] = "罪狩り完了後はエリアチェンジして受領。",
    ["Speak with Perih Vashai in Windurst Woods (K-7); she sends you to the Blacksmiths' Guild in Mhaura."] = "ウィンダス森の区(K-7)のPerih Vashaiからマウラ鍛冶ギルド行きを指示される。",
    ["Speak with Koh Lenbalalako inside the Blacksmiths' Guild in Mhaura (F-9)."] = "マウラ(F-9)鍛冶ギルドのKoh Lenbalalakoに話す。",
    ["After the cutscene, go back to Windurst Woods and speak with Perih Vashai again. A cutscene with the Mithran Tracker sends you to Castle Oztroja to search a pool for an Old Earring."] = "Perih Vashaiに報告すると罪狩りのミスラのイベント。オズトロヤ城の池で古びたピアスを探す。",
    ["Use the job ability Scavenge in the pool until you get the Old Earring. You can come as a high-level job with Ranger as your subjob to use Scavenge."] = "池で「スカベンジ」を使い古びたピアスを得る。高レベルの別ジョブにサポ狩人でも可。",
    ["Trade the Old Earring to Perih Vashai for a cutscene and the Hunter's Beret."] = "Perih Vashaiに古びたピアスを渡しハンターベレー。",
    ["This quest cannot be started while you have the quests The Tenshodo Showdown, As Thick as Thieves, Hitting the Marquisate or Rock Racketeer, or Windurst Mission 2-1, active."] = "天晶堂へ集え／アタルフォーネ盗賊団の宝／侯国の栄光／手ごたえは宝石やウィンダス2-1進行中は開始不可。",
    ["Speak with Nanaa Mihgo in Windurst Woods (J-3) several times until the quest is flagged."] = "ウィンダス森の区(J-3)のNanaa Mihgoに受領できるまで何度か話す。",
    ["Obtain Yagudo Necklace x4."] = "Yagudo Necklace4個を用意。",
    ["Trade the Yagudo Necklace x4 to Nanaa Mihgo to complete the quest and receive 200 gil."] = "Nanaa Mihgoに4個を渡し200ギル。",
    ["Completing it raises your fame in Norg, not in Windurst: 53 completions bring your Norg fame to level 4, enough to start The Sahagin's Stash (Utsusemi: Ichi) and Trial by Water."] = "上がるのはウィンダスでなくノーグ名声。原文では53回でノーグ名声4となりThe Sahagin's Stash（空蝉の術:壱）やTrial by Waterを開始可能と記載。",
    ["Completing this quest is also one of the requirements to obtain Nanaa Mihgo's Trust."] = "Nanaa Mihgoのフェイス取得条件の1つでもある。",
    ["You must zone after completing Fire and Brimstone before you start this quest."] = "火の部族完了後はエリアチェンジして受領。",
    ["Speak with Perih Vashai in Windurst Woods (K-7) for a cutscene in which she sends you to Mhaura."] = "ウィンダス森の区(K-7)のPerih Vashaiからマウラへ向かうよう頼まれる。",
    ["In Mhaura, speak twice with Koh Lenbalalako (F-9) for a cutscene. She asks you for a Gold Earring."] = "マウラ(F-9)のKoh Lenbalalakoに2回話しゴールドピアスを頼まれる。",
    ["Obtain a Gold Earring. It can be obtained for free by completing the Records of Eminence objective Conflict: Xarcabard for the first time."] = "ゴールドピアスを用意。原文ではエミネンスConflict: ザルカバードの初回報酬でも入手可能と記載。",
    ["Trade the Gold Earring to Koh Lenbalalako for a second cutscene and the key item Koh's letter."] = "Koh Lenbalalakoに渡してKoh's letterを得る。",
    ["Zone into Xarcabard for a cutscene that hints you to look near Castle Zvahl Baileys."] = "ザルカバードへ入るとイベント。ズヴァール城外郭周辺を探す手掛かりを得る。",
    ["Find the cave at (E-7) in Xarcabard and examine the ???: after a cutscene a Koenigstiger appears."] = "ザルカバード(E-7)の洞窟の???を調べるとKoenigstigerが現れる。原文は戦闘後の処理を省略している。",
    ["Return to Windurst Woods and speak with Perih Vashai for the final cutscene and your reward: Hunter's Socks and Ice Arrow x99."] = "ウィンダス森の区のPerih Vashaiへ報告しハンターソックスとIce Arrow99本。",
    ["Speak with Tapoh Lihzeh in Windurst Woods (I-8). The quest will not start while Chocobilious is active."] = "ウィンダス森の区(I-8)のTapoh Lihzehから受領。病気のチョコボ進行中は開始不可。",
    ["Obtain Beehive Chip x3 or Remi Shell x2. Beehive Chip can be bought for 40 gil from Odoba at the Alchemy Guild in Bastok Mines (K-6)."] = "Beehive Chip3個かRemi Shell2個を用意。蜂の巣のかけらはバストゥーク鉱山区(K-6)錬金術ギルドのOdobaで40ギル。",
    ["Trade Beehive Chip x3 for 150 gil or Remi Shell x2 for 200 gil to Tapoh Lihzeh to complete the quest."] = "Tapoh LihzehにBeehive Chip3個なら150ギル、Remi Shell2個なら200ギル。",
    ["If you are doing this quest for a Vana'Bout objective and have already completed it once, you do not need to speak with Tapoh Lihzeh again: just trade her the items."] = "ヴァナ・バウト目的で初回完了済みなら、改めて会話せず品を渡して反復可。",
    ["Speak with Kuoh Rhel inside the corral at the Chocobo Stables in Windurst Woods (K-12) to start the quest."] = "ウィンダス森の区(K-12)、チョコボ厩舎の柵内のKuoh Rhelから受領。",
    ["Obtain a Papaka Grass."] = "パパカ草を用意。",
    ["Speak with Tapoh Lihzeh at the medicine shop at (I-8), past the Dhalmel farm, and trade her one Papaka Grass."] = "ダルメル牧場の先(I-8)の薬屋Tapoh Lihzehに話し、パパカ草を1個渡す。",
    ["Speak with Kuoh Rhel again to complete the quest and receive 1,500 gil."] = "Kuoh Rhelに報告し1,500ギル。",
    ["Speak with Gioh Ajihri in Windurst Woods (K-5) to start the quest; she asks for a Twinstone Earring."] = "ウィンダス森の区(K-5)のGioh Ajihriから双子石のピアスを頼まれる。",
    ["Obtain a Twinstone Earring. It can be found at the Auction House, or farmed from Hill Lizard enemies in Meriphataud Mountains."] = "双子石のピアスは競売かメリファト山地のHill Lizardから用意。",
    ["Bring the Twinstone Earring back to Gioh Ajihri to receive your reward."] = "Gioh Ajihriに届けて報酬。",
    ["Zone first if you have just completed Chocobilious."] = "病気のチョコボ直後ならエリアチェンジ。",
    ["Speak with Kuoh Rhel in Windurst Woods (K-12) to start the quest."] = "ウィンダス森の区(K-12)のKuoh Rhelから受領。",
    ["Speak with Matata (K-12)."] = "Matata(K-12)に話す。",
    ["Go to Ranpi-Monpi in the northern part of Windurst Waters (D-9) and trade him Woozyshroom x3 to receive the key item Ranpi-Monpi's special stew."] = "ウィンダス水の区北(D-9)のRanpi-MonpiにWoozyshroom3個を渡しRanpi-Monpi's special stewを得る。",
    ["Speak with Kuoh Rhel to complete the quest and receive 900 gil."] = "Kuoh Rhelに話し900ギル。",
    ["To repeat the quest you must wait until the next Conquest update."] = "反復は次のコンクェスト集計以降。",
    ["You must zone after completing the previous quest. This quest cannot be started while Windurst Mission 9-2 or the quest The Kind Cardian is open."] = "前提クエスト完了後はエリアチェンジ。ウィンダス9-2やThe Kind Cardian進行中は開始不可。",
    ["Speak with Kororo in the Manustery in Windurst Woods (H-9)."] = "ウィンダス森の区(H-9)、手の院のKororoに話す。",
    ["Speak with the Cardian that Kororo mentions and choose any greeting; the choice does not matter."] = "Kororoが指定するカーディアンに挨拶を教える。どれを選んでもよい。",
    ["Leave Windurst Woods, then return after one Earth minute and speak with Kororo again."] = "ウィンダス森の区から出て地球時間1分後に戻りKororoに話す。",
    ["The Cardian you are looking for is the Five of Spades, at the outpost in Buburimu Peninsula. Go there and speak with Five of Spades."] = "ブブリム半島のアウトポストのFive of Spadesに話す。",
    ["Return to Kororo to complete the quest and receive a Tourmaline Earring."] = "Kororoに報告しトルマリンピアス。",
    ["You must zone after completing A Greeting Cardian before you start this quest."] = "正しいあいさつ完了後はエリアチェンジして受領。",
    ["Obtain a Luminicloth, a Revival Tree Root and a Wolf Hide. All three can be found at the Auction House."] = "夜光布、反魂樹の根、狼の毛皮を用意。競売でも購入可。",
    ["Trade the Luminicloth, the Revival Tree Root and the Wolf Hide to Kopuro-Popuro to complete the quest and receive 700 gil and Scentless Armlets."] = "Kopuro-Popuroに3品を渡し700ギルと無臭の腕輪。",
    ["Zone first if you have just completed the previous quest."] = "前提クエスト直後ならエリアチェンジ。",
    ["Obtain a Beetle Shell and a Hecteyes Eye."] = "甲虫の甲殻とヘクトアイズの眼を用意。",
    ["Trade the Beetle Shell and the Hecteyes Eye to Kopuro-Popuro to complete the quest and receive 600 gil."] = "Kopuro-Popuroに2品を渡し600ギル。",
    ["Speak with Apururu in Windurst Woods (H-9)."] = "ウィンダス森の区(H-9)のApururuに話す。",
    ["Obtain a Bruised Starfruit, which drops from Cursed Weapon enemies (levels 43-45) in Xarcabard."] = "ザルカバードのCursed Weapon（43〜45）から傷んだ星の木の実を得る。",
    ["Take the Bruised Starfruit to Apururu."] = "Apururuに傷んだ星の木の実を渡す。",
    ["Speak with Perih Vashai in Windurst Woods (K-7). She may say something about Trusts the first time you talk to her after zoning in; keep talking to her until her dialogue is about this quest."] = "ウィンダス森の区(K-7)のPerih Vashaiに話す。入場直後にフェイスの話をする場合は当クエストの台詞まで話す。",
    ["Travel to Sauromugue Champaign and find the cave at (L-10); to get there, go up the cliff at (L-8). The Survival Guide at (J-9/J-10) is the easiest way to reach it."] = "ソロムグ原野(L-10)の洞窟へ。(L-8)から崖上に進む。Survival Guide(J-9/J-10)が便利。",
    ["Examine the Tiger Bones in the cave to spawn the Old Sabertooth, and watch it die naturally, which takes about three Earth minutes."] = "洞窟のTiger Bonesを調べOld Sabertoothを出し、攻撃せず自然死を待つ。約地球時間3分。",
    ["Once the Old Sabertooth has died on its own, examine the Tiger Bones to get the key item Old tiger's fang."] = "自然死後Tiger Bonesを調べOld tiger's fangを得る。",
    ["If you do not examine the Tiger Bones soon enough after its death, you must examine them again and watch it die naturally once more."] = "調べるのが遅いと再度出現させ自然死を待ち直す。",
    ["Return to Perih Vashai to complete the quest and receive the Ranger's Necklace."] = "Perih Vashaiに報告して狩人の首飾り、狩人取得。",
    ["Speak with Nanaa Mihgo in Windurst Woods (J-3) to receive the key item Sharp gray stone."] = "ウィンダス森の区(J-3)のNanaa MihgoからSharp gray stoneを受け取る。",
    ["Speak with Ardea in Bastok Markets (H-8), near Home Point #4, and sell her the stone for 10 gil."] = "バストゥーク商業区(H-8)、Home Point #4付近のArdeaに10ギルで売る。",
    ["Return to Nanaa Mihgo."] = "Nanaa Mihgoへ戻る。",
    ["Speak with Varun in Windurst Woods (H-9)."] = "ウィンダス森の区(H-9)のVarunに話す。",
    ["Optional: speak with Ardea again to try to get the stone back."] = "任意：Ardeaに石を返してもらえないか聞く。",
    ["Obtain some pickaxes, then go to the third floor of Palborough Mines."] = "つるはしを用意しパルブロ鉱山の3階へ。",
    ["At (I-9) you find two Mythril Seams. Mine the western seam to get a Sharp Stone."] = "(I-9)の2つのMythril Seamsのうち西側を掘りとんがり石を得る。",
    ["Trade the Sharp Stone to Varun to complete the quest and receive 2,100 gil."] = "Varunにとんがり石を渡し2,100ギル。",
    ["Speak with Soni-Muni in Windurst Woods (H-10) to start the quest."] = "ウィンダス森の区(H-10)のSoni-Muniから受領。",
    ["Obtain a Scorpion Stinger. It drops from Labyrinth Scorpion and Maze Scorpion enemies in the Maze of Shakhrami, and from Diplopod enemies in Kuftal Tunnel."] = "シャクラミの地下迷宮のLabyrinth Scorpion／Maze Scorpion、またはクフタルの洞門のDiplopodから大サソリの針を得る。",
    ["Trade the Scorpion Stinger to Soni-Muni to complete the quest and receive 1,500 gil."] = "Soni-Muniに渡し1,500ギル。",
    ["Speak with Ibwam in Windurst Woods (G-11) to receive a Green Sentinel badge and start the quest."] = "ウィンダス森の区(G-11)のIbwamから緑色の山猫バッジを受け取る。",
    ["In Windurst Waters North, speak with Npopo (G-4), Amagusa-Chigurusa (G-9), Funpo-Shipo (F-9), Kyume-Romeh (F-10) and Lago-Charago (F-8)."] = "ウィンダス水の区北でNpopo(G-4)、Amagusa-Chigurusa(G-9)、Funpo-Shipo(F-9)、Kyume-Romeh(F-10)、Lago-Charago(F-8)に話す。",
    ["In Windurst Walls, speak with Yoriri (J-11), Moan-Maon (J-6), Shantotto (K-7), Chomomo (H-3) and Naih Arihmepp (F-5)."] = "ウィンダス石の区でYoriri(J-11)、Moan-Maon(J-6)、Shantotto(K-7)、Chomomo(H-3)、Naih Arihmepp(F-5)に話す。",
    ["In Port Windurst, speak with Yujuju (M-6), Choyi Totlihpa (F-6), Yaman-Hachuman (E-7), Kunchichi (E-7) and Three of Clubs (G-7)."] = "ウィンダス港でYujuju(M-6)、Choyi Totlihpa(F-6)、Yaman-Hachuman(E-7)、Kunchichi(E-7)、Three of Clubs(G-7)に話す。",
    ["In Windurst Woods, speak with Umumu (I-5), Cayu Pensharhumi (I-10), Nanaa Mihgo (J-3), Etsa Rhuyuli (J-13) and Soni-Muni (H-10)."] = "ウィンダス森の区でUmumu(I-5)、Cayu Pensharhumi(I-10)、Nanaa Mihgo(J-3)、Etsa Rhuyuli(J-13)、Soni-Muni(H-10)に話す。",
    ["Once you have spoken to all 20 people, return to Ibwam, who takes your Green Sentinel badge and gives you a Green invitation card."] = "20人に話したらIbwamに報告。緑色の山猫バッジと引換えに緑色の招待券を得る。",
    ["After joining Salaheem's Sentinels, speak with Naja Salaheem and show her the invitation card to receive Imperial currency; the more Lure of the Wildcat quests you have completed, the greater the reward."] = "サラヒム・センチネル入社後、Naja Salaheemに招待状を見せると皇国貨幣。各地のLure of the Wildcat完了数で報酬が増える。",
    ["After joining Salaheem's Sentinels, Alib-Mufalib offers to teleport you to Aht Urhgan Whitegate for 300 gil."] = "入社後Alib-Mufalibから300ギルでアトルガン白門へ転送してもらえる、と原文に記載。",
    ["You cannot start this quest while another Weapon Skill quest is active; return to the person who gave it and quit it first. You need Archery skill 250 or higher, level 71, and the Rise of the Zilart pack."] = "他のWSクエスト進行中は先に取消。弓術250以上、71以上、ジラート導入が必要。",
    ["Speak with Perih Vashai in Windurst Woods (K-7) to receive the key item Weapons Training Guide and the Bow of Trials."] = "ウィンダス森の区(K-7)のPerih VashaiからWeapons Training GuideとBow of Trialsを得る。",
    ["Break the latent on the Bow of Trials before completing the rest of the quest. The latent is active while you have fewer than 300 Skillchain points accumulated; you know you have enough when it breaks and the weapon's elemental resistances disappear from your active resistances."] = "Bow of Trialsの潜在を消す。300ポイント未満では潜在が有効で、属性耐性の補正が消えたら達成。",
    ["Trade the Bow of Trials back to Perih Vashai."] = "Bow of TrialsをPerih Vashaiに返す。",
    ["Go back and speak with Perih Vashai to receive your reward, the Empyreal Arrow weapon skill."] = "Perih Vashaiに報告しEmpyreal Arrowを習得。原文はNM戦・証拠回収を省略している。",
    ["Speak with the starting NPC at the Chocobo stables in Windurst Woods (K-12); you are asked to deliver a Chocobo to a distant stable."] = "ウィンダス森の区(K-12)チョコボ厩舎の依頼者から、別の厩舎へのチョコボ配達を受ける。",
    ["To Bastok: Miratete's Memoirs at 31:00 to 32:29, a Chocobo Ticket at 32:30 to 34:43, Gysahl Greens at 34:44 or more."] = "原文のバストゥーク行き報酬：31:00〜32:29はMiratete's Memoirs、32:30〜34:43はChocobo Ticket、34:44以上はGysahl Greens。",
    ["To Jeuno: a Windurst Woods Glyph at 14:00 to 15:29, Gysahl Greens at 15:30 or more."] = "原文のジュノ行き報酬：14:00〜15:29はウィンダス森の区 Glyph、15:30以上はGysahl Greens。記載より速い到着の扱いは原文で明示されていない。",
    ["Having Windurst Mission 2-1 active prevents you from starting this quest. Nanaa Mihgo is involved in several quests and missions, so you may have to speak with her several times to trigger the cutscene that starts it."] = "ウィンダス2-1進行中は開始不可。Nanaa Mihgoは関連イベントが多いので数回話して受領する。",
    ["Speak with Nanaa Mihgo in Windurst Woods (J-3) as a Thief, level 40 or higher; she gives you the key item Letter from the Tenshodo. You must have the Tenshodo Membership to continue."] = "シーフ40以上でウィンダス森の区(J-3)のNanaa MihgoからLetter from the Tenshodoを得る。先に進むにはTenshodo Membershipが必要。",
    ["Go to Lower Jeuno and speak with Harnek inside the Tenshodo at (J-7) for a cutscene. You receive the key item Tenshodo envelope."] = "ジュノ下層(J-7)天晶堂内のHarnekからTenshodo envelopeを得る。",
    ["A cutscene with Sneaking Tiger asks you for a Quadav Stew. It can only be stolen from certain Quadavs in Beadeaux, and you can steal it before going to Selbina to save time."] = "Sneaking Tigerからクゥダフ風シチューを頼まれる。ベドーの特定クゥダフから「ぬすむ」で入手する品で、セルビナへ行く前に調達してもよい。",
    ["Go to Beadeaux and steal from Garnet Quadav, Silver Quadav, Zircon Quadav and Bronze Quadav until you obtain the Quadav Stew."] = "ベドーのGarnet Quadav／Silver Quadav／Zircon Quadav／Bronze Quadavからクゥダフ風シチューを盗む。",
    ["Go to Selbina and trade the Quadav Stew to Elfriede (J-9)."] = "セルビナ(J-9)のElfriedeにクゥダフ風シチューを渡す。原文はその後の終了報告を省略している。",
    ["Speak with Nanaa Mihgo in Windurst Woods (J-3) to start the quest. She asks what the last signature on the key item Signed envelope was: the correct answer is V, although it likely does not matter what you answer."] = "ウィンダス森の区(J-3)のNanaa Mihgoから受領。Signed envelopeの最後の署名はV。原文では他の回答でも進む可能性があると説明。",
    ["Optional: speak with Cha Lebagta and Bopa Greso, just south of Nanaa Mihgo at (J-4), for a couple of clues."] = "任意：南の(J-4)のCha Lebagta、Bopa Gresoから手掛かりを聞く。",
    ["Obtain Rock Salt, Gausebit Grass and Lizard Egg. You may need several of each."] = "岩塩、ゴゼビの野草、トカゲの卵を用意。複数必要になる場合もある。原文は調達後の工程を省略している。",
    ["You must be level 5 or higher on any job."] = "任意のジョブが5以上必要。",
    ["Speak with Wetata in Windurst Woods (G-10); you receive the key item Green institute card."] = "ウィンダス森の区(G-10)のWetataからGreen institute cardを得る。",
    ["Go to Heavens Tower and speak with Kupipi. If this is not your first Trust quest, you are finished here and receive the key item Windurst Trust permit."] = "天の塔のKupipiに話す。他国のフェイス入門を終えていればここでWindurst Trust permitを得て完了。",
    ["If this is your first Trust quest, you must use the Trust spell Kupipi in West Sarutabaruta or East Sarutabaruta, then return to Kupipi to receive the Windurst Trust permit."] = "初めてのフェイス入門なら西サルタバルタか東サルタバルタでKupipiを呼び、Kupipi本人に報告してWindurst Trust permitを得る。",
    ["You must zone after completing As Thick as Thieves before you start this quest."] = "アタルフォーネ盗賊団の宝完了後はエリアチェンジして受領。",
    ["Speak with Nanaa Mihgo in Windurst Woods (J-3) to receive the key item Cat Burglar's note."] = "ウィンダス森の区(J-3)のNanaa MihgoからCat Burglar's noteを得る。",
    ["Trade Quake Grenade x4 to the NPC who asks for them, to get a clue. You can skip this part and get the key item Bomb incense to fight the Chandelier, but you must turn in the Quake Grenades to clear the key item from Nanaa Mihgo so that she lets you complete the quest."] = "指定NPCにQuake Grenade4個を渡して手掛かり。先にBomb incenseを得てChandelier戦へ進むこともできるが、終了には震天雷納品でNanaa Mihgoのメモを片付ける必要がある、と原文に記載。",
    ["Go back to Windurst Woods and speak with Nanaa Mihgo. The correct answer is \"Blank\", but any answer progresses the quest."] = "ウィンダス森の区のNanaa Mihgoに報告。答えは「Blank」だがどれでも進む。",
    ["Get a Pickaxe. Zone into Ordelle's Caves and back out again before continuing, or you will not be able to trade the pickaxe."] = "つるはしを用意。先にオルデール鍾乳洞へ入り外へ出ておかないと渡せない、と原文に記載。",
    ["Trade your Pickaxe to the ??? for a cutscene and your reward."] = "???につるはしを渡して報酬。原文は対象エリアやNM戦の詳細を省略している。",
    ["Speak with Naiko-Paneiko at The Tarutaru Times Company in Southern Windurst Waters (C-11) to start the quest."] = "ウィンダス水の区南(C-11)、タルタル新聞社のNaiko-Paneikoから受領。",
    ["Speak with Kyume-Romeh in the Timbre Timbers Tavern in Northern Windurst Waters (F-10) to get the key item Windurst Waters scoop."] = "ウィンダス水の区北(F-10)の酒場のKyume-Romehからウィンダス水の区 scoopを得る。",
    ["Speak with Hiwon-Biwon by Shantotto's house in Windurst Walls (K-8) to get the key item Windurst Walls scoop."] = "ウィンダス石の区(K-8)、Shantotto宅近くのHiwon-Biwonからウィンダス石の区 scoopを得る。",
    ["Speak with Umumu near the Dhalmel Farm in Windurst Woods (I-6) to get the key item Windurst Woods scoop."] = "ウィンダス森の区(I-6)、ダルメル牧場近くのUmumuからウィンダス森の区 scoopを得る。",
    ["Speak with Yujuju by the Air Travel Agency in Port Windurst (M-6) to get the key item Port Windurst scoop."] = "ウィンダス港(M-6)、飛空艇乗り場近くのYujujuからウィンダス港 scoopを得る。",
    ["Return to Naiko-Paneiko, who asks you to check out a lead in Inner Horutoto Ruins. Enter it from East Sarutabaruta (J-7)."] = "Naiko-Paneikoに報告し内ホルトト遺跡の取材へ。東サルタバルタ(J-7)から入る。",
    ["Examine the Mahogany Door at (G-8) to confirm the Windurst Woods scoop."] = "(G-8)のMahogany Doorを調べウィンダス森の区 scoopの裏を取る。",
    ["Return to Naiko-Paneiko to complete the quest and receive your reward."] = "Naiko-Paneikoに報告して報酬。",
    ["You must zone after completing Making Headlines before you start this quest."] = "特ダネ・ウィンダス完了後はエリアチェンジして受領。",
    ["Speak with Naiko-Paneiko in Windurst Waters South (C-11) to start the quest."] = "ウィンダス水の区南(C-11)のNaiko-Paneikoから受領。",
    ["Take the ferry between Mhaura and Selbina and fish up Ocean Crab; they drop the Bronze Box you need."] = "マウラ〜セルビナ間の機船でOcean Crabを釣り、青銅の箱を得る。",
    ["Trade the Bronze Box to Naiko-Paneiko to complete the quest and receive 1,500 gil."] = "Naiko-Paneikoに青銅の箱を渡し1,500ギル。",
    ["Speak with Churano-Shurano on the roof of the Optistery in Windurst Waters (F-8), in front of the telescope."] = "ウィンダス水の区(F-8)、目の院屋上の望遠鏡前のChurano-Shuranoに話す。",
    ["Accept his offer to give him 10,000 gil towards his cause. You can then purchase the permanent key item Magicked astrolabe."] = "10,000ギルの寄付に同意し、永続だいじなもの魔法の天文盤を購入。",
    ["The Magicked astrolabe lets you open the doors in The Eldieme Necropolis by yourself."] = "魔法の天文盤があればエルディーム古墳の扉を1人で開けられる。",
