    -- Jeuno quests: original JP summaries; ID-scoped fame requirements.
    ["You need to be level 30 or higher. Speak with Bki Tbujhja in Lower Jeuno (H-8), inside the Merry Minstrel."] = "30以上でジュノ下層(H-8)、吟遊詩人の酒場のBki Tbujhjaに話す。",
    ["Travel through the tunnel in Valkurm Dunes (C-6) to the Secret Beach and examine the Song Runes (B-7) for a last cutscene."] = "バルクルム砂丘(C-6)の洞窟を抜け隠し海岸へ行き、(B-7)のSong Runesを調べる。原文では途中の関連依頼を省略。",
    ["A quick way to reach the destination is to take the Survival Guide to Gustav Tunnel, then exit to Valkurm Dunes."] = "グスタフの洞門のSurvival Guideからバルクルム砂丘へ出ると近い。",
    ["This quest does not appear in your quest list until it is completed."] = "完了するまでクエスト一覧には載らない。",
    ["You need to be level 30 or higher. Examine the Door: Merchant's House on the second floor in Lower Jeuno (G-11), above the chocobo stables."] = "30以上でジュノ下層(G-11)、チョコボ厩舎上の2階のDoor: Merchant's Houseを調べる。",
    ["Speak with Shalott in Upper Jeuno (G-7), outside the Chocobo Stables, for a cutscene."] = "ジュノ上層(G-7)、チョコボ厩舎外のShalottに話す。",
    ["Examine the Door: Merchant's House in Lower Jeuno (G-11) again for another cutscene."] = "ジュノ下層(G-11)のDoor: Merchant's Houseを再調査。",
    ["Examine the Night Flowers down the ramp in Qufim Island (F-8) between 21:30 and 4:00 for a cutscene."] = "クフィム島(F-8)、坂を下りた先のNight Flowersを21:30〜04:00に調べる。",
    ["A Kraken (level 37-38) may spawn above the Night Flowers."] = "Night Flowersの上にはKraken（37〜38）が出現することがある。",
    ["Examine the Door: Merchant's House in Lower Jeuno for a cutscene and your rewards."] = "ジュノ下層のDoor: Merchant's Houseを調べて報酬。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need Axe skill 240 or higher and level 71."] = "他のWSクエスト受領中は先に取消。片手斧240以上、71以上が必要。",
    ["Speak with Brutus in Upper Jeuno (G-7) to receive the key item Weapons Training Guide and the Pick of Trials. You need to break the latent on the Pick of Trials before completing the rest of the quest."] = "ジュノ上層(G-7)のBrutusからWeapons Training Guideとトライアルピックを得て潜在を消す。",
    ["Trade the Pick of Trials back to Brutus."] = "Brutusにトライアルピックを返す。",
    ["The page gives these directions for the next part: follow the path to the T-intersection and head north, follow the path and exit the Temple, and once inside follow the path south to the ???."] = "原文の道順は「T字路を北、道なりに寺院を出て、再び中へ入ったら南の???へ」。エリア名・NM戦・証拠回収が省略されている。",
    ["Go back and speak with Brutus to receive your reward, the Decimation weapon skill."] = "Brutusに報告してデシメーションを習得。",
    ["Head to Upper Jeuno and speak with Brutus at (G-7). This quest starts the first time you speak to him, together with Chocobo's Wounds."] = "ジュノ上層(G-7)のBrutusに初めて話すと、傷ついたチョコボとともに進行する。",
    ["Help the chocobo leave when prompted."] = "促されたらチョコボが出て行くのを手伝う。",
    ["Head to La Theine Plateau and check the Chocobo Tracks at the far northwest corner of (E-5), just south of the sliver of map in (E-4)."] = "ラテーヌ高原(E-5)北西端、(E-4)から張り出した部分の南のChocobo Tracksを調べる。",
    ["Return to Upper Jeuno and speak to Brutus (G-7) again."] = "ジュノ上層(G-7)のBrutusに戻る。",
    ["Return to Brutus (G-7) in Upper Jeuno one last time to complete the quest."] = "ジュノ上層(G-7)のBrutusに最後の報告をして完了。原文は途中の工程を省略。",
    ["Speak to Brutus (G-7) after one game day to receive a chocobo egg. You must change zones and return to Upper Jeuno after the day change."] = "ヴァナ日付変更後、エリアチェンジしてジュノ上層(G-7)のBrutusからチョコボの卵を受け取る。",
    ["Trade the egg to one of the VCS Trainers located in Bastok Mines, Southern San d'Oria or Windurst Woods to begin raising a chocobo."] = "バストゥーク鉱山区／南サンドリア／ウィンダス森の区のVCS Trainerに卵を渡して育成開始。",
    ["To begin, speak with Brutus in Upper Jeuno (G-7) on any job at level 20 or higher. This starts the quest Chocobo on the Loose! first, and this quest follows it."] = "20以上でジュノ上層(G-7)のBrutusに話す。逃げだしたチョコボが先に発生し、その後に当依頼。",
    ["Speak to him two more times to start the correct quest, and choose \"Nope, never!\"."] = "さらに2回話して対象の依頼を受け、「Nope, never!」を選ぶ。",
    ["Obtain Gausebit Grass x4. It drops from Wadi Hare enemies in Dangruf Wadi and Crane Fly enemies in Meriphataud Mountains."] = "Gausebit Grass4個を用意。ダングルフの涸れ谷のWadi Hareやメリファト山地のCrane Flyが落とす。",
    ["Feed the chocobo standing next to Osker by trading it one Gausebit Grass. You can feed it once every real life minute."] = "Oskerの隣のチョコボにゴゼビの野草を1個ずつ渡す。地球時間1分ごとに1回。",
    ["It takes 6 feeding attempts to complete the quest. The first 2 attempts automatically fail and do not consume a grass."] = "給餌は計6回。最初の2回は必ず断られ、草は消費しない。",
    ["Once the chocobo has eaten the Gausebit Grass x4, you are presented with a Chocobo license."] = "4個食べさせるとチョコボ乗り免許証を得る。",
    ["Complete the prior quests Chocobo's Wounds and Save My Son. You need to be level 30 or higher."] = "30以上で傷ついたチョコボと息子に罪はないを完了しておく。",
    ["Speak with Brutus in Upper Jeuno (G-7) for a cutscene. You may have to talk to him multiple times to get the cutscene."] = "ジュノ上層(G-7)のBrutusにイベントが起きるまで何度か話す。",
    ["This quest does not show up in your quest log until it is completed."] = "完了するまでクエストログに載らない。",
    ["Speak with Brutus in Upper Jeuno (G-7) as a Beastmaster of level 40 or higher. From this point on you can complete the quest on any job."] = "獣使い40以上でジュノ上層(G-7)のBrutusから受領。以後は他ジョブでも進行可。",
    ["Kill monsters on the 7th to 10th floors of Upper Delkfutt's Tower until you get a Delkfutt Chest Key. Alternatively, you can buy one from the Curio Vendor Moogle."] = "デルクフの塔上層の7〜10階の敵からDelkfutt Chest Keyを得る。Curio Vendor Moogleでも購入可。",
    ["Use the key to open a chest in the zone to receive a Guiding bell."] = "現地のChestを開け迷わずの鈴を得る。",
    ["Return to Brutus to receive your reward, the Barbaroi Axe."] = "Brutusに報告しバルバロイアクス。",
    ["Speak with Brutus in Upper Jeuno (G-7) as a Beastmaster of level 50 or higher; he gives you three Aquaflora key items. From here on you can be on any job."] = "獣使い50以上でジュノ上層(G-7)のBrutusから3つの水中花を受け取る。以後は他ジョブ可。",
    ["Examine the pools on map 2 of Fei'Yin, located at (H-8), (H-5) and lastly (F-5). They are the little green marks on the map. Home Point #2, just outside the Cloister of Frost, is the closest warp."] = "フェ・インのマップ2、(H-8)→(H-5)→(F-5)の池を調べる。地図の小さな緑の印が目印。凍結の回廊外のHome Point #2が近い。",
    ["When the pool at (F-5) is examined, the NM Dabotz's Ghost spawns. It uses Curse often."] = "(F-5)の池でDabotz's Ghostが出現。呪いを多用する。",
    ["Return to Brutus for a cutscene."] = "Brutusに報告してイベント。",
    ["Next, head to Castle Oztroja and kill the monsters to find an Oztroja Chest Key."] = "オズトロヤ城の敵からOztroja Chest Keyを得る。",
    ["Use the key to open a chest inside the castle to receive a Beast Collar."] = "城のChestを開け獣の首輪を得る。",
    ["Return to Brutus for your reward."] = "Brutusに報告して報酬。",
    ["If you have any other Borghertz's Hands quest active, you must complete that one before you can start this quest."] = "他ジョブのボルグヘルツの魔手クエスト受領中は、先にそちらを完了する。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Summoner of level 50 or higher to begin the quest. You need the Rise of the Zilart pack."] = "召喚士50以上でジュノ上層(H-8)防具店のGuslamから受領。ジラート導入が必要。",
    ["You do not need to be on Summoner when opening the coffer, only when accepting the quest. A Grotto Coffer Key and a Mythril Beastcoin (if you do not have access to the Proto-Waypoints) are required for this quest."] = "受領時のみ召喚士必須で、宝箱は他ジョブでも可。Grotto Coffer Key、Proto-Waypoint未開通なら獣人ミスリル貨も用意。原文は宝箱から手を得て修復する途中の工程を省略。",
    ["Return to Upper Jeuno and speak with Guslam. After the cutscene, the quest is complete."] = "ジュノ上層のGuslamに報告して完了。原文にはジョブにより修復・闇の炎回収などの中間工程の省略がある。",
    ["Guslam mentions that there is still armor scattered about Vana'diel. These coffers are not required to complete the quest: once you receive your hands the quest is completed, but it must be either active or completed for you to receive those attire pieces."] = "他の部位も各地の宝箱から得られるが、魔手クエスト完了には不要。手の取得で当依頼は完了。他部位は当依頼の進行中または完了後に取得可。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Ranger of level 50 or higher to begin the quest. This quest follows Fire and Brimstone."] = "Fire and Brimstone後、狩人50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Go to Garlaige Citadel. Either obtain a Garlaige Coffer Key or pick the lock as a Thief."] = "ガルレージュ要塞へ。Garlaige Coffer Keyを用意するかシーフで解錠。",
    ["Travel to the Durable Shields shop in Upper Jeuno and speak with Guslam at (H-8) as a Dragoon of level 50 or higher to begin the quest. This quest requires the Rise of the Zilart pack and follows Chasing Quotas."] = "Chasing Quotas後、竜騎士50以上でジュノ上層(H-8)防具店のGuslamから受領。ジラート導入が必要。",
    ["Go to The Boyahda Tree. Either obtain a Boyahda Coffer Key or pick the lock as a Thief."] = "ボヤーダ樹へ。Boyahda Coffer Keyを用意するかシーフで解錠。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Bard of level 50 or higher to begin the quest."] = "吟遊詩人50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Obtain a Zvahl Coffer Key. The Curio Vendor Moogle sells it; alternatively you can farm the key or pick the lock as a Thief."] = "Zvahl Coffer KeyをCurio Vendor Moogleか現地の敵から用意。シーフでの解錠も可。",
    ["You do not need to be on Bard when opening the coffer. You receive the key item Old gauntlets from the coffer."] = "宝箱を開ける際は吟遊詩人以外でも可。古びた小手を得る。",
    ["Return to Upper Jeuno and speak with Guslam."] = "ジュノ上層のGuslamに報告。",
    ["You must be on Bard for the next step."] = "次の工程は吟遊詩人が必要、と原文に記載。原文はその具体的な工程を省略している。",
    ["Guslam mentions that there is still armor scattered about Vana'diel. You can find two more pieces of armor by opening coffers in other zones with the corresponding coffer key. These coffers are not required to complete the quest: once you receive your hands the quest is completed."] = "他の宝箱に残る2部位は当依頼完了に不要。対応するカギで取得でき、手を得た時点で当依頼は完了。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a White Mage to begin the quest. Once you have started it as a White Mage you may complete the other steps on a different job, even finishing the quest and receiving the Healer's Mitts."] = "白魔道士でジュノ上層(H-8)防具店のGuslamから受領。以後、ヒーラーミトンを受け取る完了時を含め他ジョブでも可。",
    ["Go to Beadeaux and find a Treasure Coffer. Either obtain a Beadeaux Coffer Key or pick the lock as a Thief. The key is sold for 5,000 gil by the Curio Vendor Moogle."] = "ベドーのTreasure Cofferをベドー Coffer Keyかシーフで解錠。カギはCurio Vendor Moogleで5,000ギル。",
    ["You receive the key item Old gauntlets from the coffer."] = "宝箱から古びた小手を得る。",
    ["Once Dark Spark is defeated, examine one of the torches to receive the key item Shadow flames."] = "Dark Spark討伐後、松明を調べ闇の炎を得る。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Samurai of level 50 or higher to begin the quest. This quest requires the Rise of the Zilart pack."] = "侍50以上でジュノ上層(H-8)防具店のGuslamから受領。ジラート導入が必要。",
    ["Either obtain a Kuftal Coffer Key or pick the lock as a Thief. You do not need to be on Samurai when opening the coffer."] = "Kuftal Coffer Keyかシーフで解錠。宝箱を開ける時は侍以外でも可。",
    ["Travel to Durable Shields in Upper Jeuno and speak with Guslam at (H-8) as a Ninja of level 50 or higher to begin the quest. This quest requires the Rise of the Zilart pack and follows 20 in Pirate Years."] = "忍者50以上でジュノ上層(H-8)防具店のGuslamから受領。ジラート導入、手順上の前提は20 in Pirate Years。原文の前提欄はI'll Take the Big Boxで、表記が異なる。",
    ["Go to Ifrit's Cauldron. A quick route is the Unity Warp (level 122) to Yhoator Jungle, then hug the right wall; it is a short ride."] = "イフリートの釜へ。ユニティCL122のヨアトル大森林転送から右壁沿いが近い。",
    ["Return to Upper Jeuno and speak with Guslam. If you have completed the AF hands quest on another job, you do not need to view this cutscene or pay gil."] = "ジュノ上層のGuslamに報告。他ジョブの魔手を完了済みなら、このイベントやギル支払いは不要と原文に記載。",
    ["Guslam mentions that there is still armor scattered about Vana'diel. These coffers are not required to complete the quest: once you receive your hands the quest is completed."] = "各地の他部位は当依頼完了に不要。手を受け取れば当依頼は完了。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Dark Knight of level 50 or higher to begin the quest. This quest follows Dark Puppet."] = "Dark Puppet後、暗黒騎士50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Go to The Eldieme Necropolis. You can buy the permanent key item Magicked astrolabe for 10,000 gil from Churano-Shurano in Windurst Waters (F-8)."] = "エルディーム古墳へ。ウィンダス水の区(F-8)のChurano-Shuranoから魔法の天文盤を10,000ギルで買える。",
    ["Return to Upper Jeuno and speak with Guslam. If this is your first time completing a Borghertz's Hands quest for any job, there are additional steps first."] = "ジュノ上層のGuslamに報告。全ジョブを通じて魔手初回なら、先に追加工程が必要。",
    ["Travel to the Durable Shields shop in Upper Jeuno and speak with Guslam at (H-8) as a Thief of level 50 or higher to begin the quest. This quest follows As Thick as Thieves."] = "As Thick as Thieves後、シーフ50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Go to Davoi, then travel to Monastic Cavern and locate a Treasure Coffer. Either obtain a Davoi Coffer Key to open it, or pick the lock. You do not need to be on Thief when opening the coffer."] = "ダボイ経由で修道窟のTreasure Cofferへ。ダボイ Coffer Keyかシーフで解錠。カギならシーフ以外でも可。",
    ["Return to Upper Jeuno and speak with Guslam inside the Durable Shields shop."] = "ジュノ上層の防具店のGuslamに報告。",
    ["Travel to the Durable Shields shop in Upper Jeuno and speak with Guslam at (H-8) as a Black Mage of level 50 or higher to begin the quest. This quest follows The Three Magi."] = "黒魔道士50以上でジュノ上層(H-8)防具店のGuslamから受領。手順はThe Three Magiを前提とするが、原文の前提欄はRecollections。",
    ["Go to Garlaige Citadel and find a Treasure Coffer. Either obtain a Garlaige Coffer Key or pick the lock as a Thief. The Curio Vendor Moogle sells the key for 5,000 gil."] = "ガルレージュ要塞のTreasure CofferをGarlaige Coffer Keyかシーフで解錠。カギはCurio Vendor Moogleで5,000ギル。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Paladin of level 50 or higher to begin the quest. This quest requires the Rise of the Zilart pack and follows A Boy's Dream."] = "A Boy's Dream後、ナイト50以上でジュノ上層(H-8)防具店のGuslamから受領。原文ではジラート導入も条件。",
    ["Go to The Eldieme Necropolis. You can buy the permanent key item Magicked astrolabe for 10,000 gil from Churano-Shurano in Windurst Waters (F-8); it lets you open the doors in The Eldieme Necropolis by yourself."] = "エルディーム古墳へ。ウィンダス水の区(F-8)のChurano-Shuranoから魔法の天文盤を10,000ギルで購入すると扉を1人で開けられる。",
    ["Return to Upper Jeuno and speak with Guslam. Then head to Lower Jeuno, inside the Tenshodo area."] = "ジュノ上層のGuslamに報告し、ジュノ下層の天晶堂へ。原文はその後の工程を省略。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Monk of level 50 or higher to begin the quest."] = "モンク50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["You do not need to be on Monk when opening the coffer. You receive the key item Old gauntlets from the coffer."] = "宝箱はモンク以外でも可。古びた小手を得る。原文は対象宝箱の場所を省略。",
    ["Return to Upper Jeuno and speak with Guslam. He informs you that he is unable to repair the gauntlets."] = "ジュノ上層のGuslamに、手を修理できないと言われる。",
    ["If this is your first AF, do the following steps; otherwise skip them. Go to Port Jeuno and head to the crates near the Auction House and the Jeuno Duty-Free Shop at (H-8), and click on the ??? for a cutscene."] = "初AFのみ：ジュノ港(H-8)、競売と免税店近くの木箱の???を調べる。初回以外は原文の指示どおりこの工程を省略。",
    ["Travel to Castle Zvahl Baileys and go to (F-8) on the first map. Click on one of the torches to spawn Dark Spark."] = "ズヴァール城外郭の最初のマップ(F-8)、松明を調べDark Sparkを出す。",
    ["Return to Port Jeuno and examine the ???."] = "ジュノ港の???を調べる。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Red Mage of level 50 or higher to begin the quest. This quest follows The Crimson Trial."] = "赤魔道士50以上でジュノ上層(H-8)防具店のGuslamから受領。手順の前提はThe Crimson Trialだが、原文の前提欄はEnveloped in Darkness。",
    ["Go to The Eldieme Necropolis and find a Treasure Coffer."] = "エルディーム古墳のTreasure Cofferを探す。",
    ["Return to Upper Jeuno and speak with Guslam. Then click on the ???."] = "ジュノ上層のGuslamに報告し???を調べる。原文は対象や途中の修復工程を省略。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Warrior of level 50 or higher to begin the quest. This quest follows The Talekeeper's Truth."] = "The Talekeeper's Truth後、戦士50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Guslam mentions that there is still armor scattered about Vana'diel. These coffers are not required to complete the quest: once you receive your hands the quest is completed. Borghertz's Warring Hands must either be active or completed for you to receive those attire pieces."] = "他の宝箱の部位は当依頼完了に不要。手を受け取れば完了。他部位にはボルグヘルツの失われた魔手＜戦士＞の進行中または完了が必要。",
    ["Travel to the Durable Shields shop and speak with Guslam in Upper Jeuno (H-8) as a Beastmaster of level 50 or higher to begin the quest. This quest follows Scattered Into Shadow."] = "闇に散りしものたち後、獣使い50以上でジュノ上層(H-8)防具店のGuslamから受領。",
    ["Go to Crawlers' Nest. Either obtain a Nest Coffer Key or pick the lock as a Thief. You do not need to be on Beastmaster when opening the coffer."] = "クロウラーの巣へ。Nest Coffer Keyかシーフで解錠。カギなら獣使い以外でも可。",
    ["Return to Upper Jeuno and speak with Guslam. If this is your first AF, there are additional steps first."] = "ジュノ上層のGuslamに報告。初AFなら先に追加工程が必要。",
    ["Speak with Mertaire in Lower Jeuno, who tells you to take the Star ring (tarnished) to an antique collector. You must be a Bard of level 50 or higher, and the quest does not appear in your log yet. This quest requires the Rise of the Zilart pack and follows The Requiem."] = "吟遊詩人50以上、ジラート導入とThe Requiem完了が必要。ジュノ下層のMertaireからStar ring (tarnished)を骨董屋へ持参するよう頼まれる。まだログには載らない。",
    ["Speak with Imasuke in Port Jeuno (E-6). You must have your current job set to Bard to receive the cutscene; after speaking with him you may change to any job."] = "吟遊詩人でジュノ港(E-6)のImasukeに話す。以後は他ジョブ可。",
    ["Travel to (I-10) in Xarcabard and examine the Perennial Snow at the end of the short tunnel. You must now wait one Earth minute before you can retrieve the ring."] = "ザルカバード(I-10)、短い洞窟奥のPerennial Snowを調べ、地球時間1分待つ。",
    ["Retrieve the Star ring (indecipherable) by examining the Perennial Snow."] = "Perennial Snowを再調査してStar ring (indecipherable)を回収。",
    ["Go back to Imasuke, who tells you to find someone who can translate the ring."] = "Imasukeから指輪の文字を読める人を探すよう言われる。",
    ["Head to Chateau d'Oraguille and speak with Chalvatot at (F-7) to receive the Moon ring."] = "ドラギーユ城(F-7)のChalvatotからMoon ringを受け取る。",
    ["Listen to his instructions and travel to Monastic Cavern via Davoi (H-11)."] = "指示を聞きダボイ(H-11)経由で修道窟へ。",
    ["Walk to the small circular room at (I-8) with the altar in it. After clearing the Orcs, examine the altar to spawn Bugaboo."] = "(I-8)の小円形の祭壇の部屋でオークを片付け、祭壇からBugabooを出す。",
    ["Defeat Bugaboo, then examine the altar again for a cutscene."] = "Bugabooを倒して祭壇を再調査。",
    ["Return and speak with Chalvatot for your reward, the Choral Justaucorps, and to complete the quest."] = "Chalvatotに報告してコラルジュストコル。",
    ["Speak with Imasuke in Port Jeuno (E-6) to begin the quest. You need Jeuno fame level 2."] = "ジュノ名声2が必要。ジュノ港(E-6)のImasukeから受領。",
    ["Head to Qufim Island and kill Dancing Weapon enemies until you obtain a Kaiser Sword. Kaiser Swords can also sometimes be found at the Auction House."] = "クフィム島のDancing Weaponからカイザーソードを得る。競売に出ることもある。",
    ["Trade the Kaiser Sword to Imasuke to complete the quest and receive the Map of Delkfutt's Tower."] = "Imasukeにカイザーソードを渡しMap of Delkfutt's Tower。",
    ["Speak with Radeivepart in Ru'Lude Gardens (H-9). He requests that you bring him a Flame Degen. You need Jeuno fame level 4."] = "ジュノ名声4が必要。ル・ルデの庭(H-9)のRadeivepartからフレイムデーゲンを頼まれる。",
    ["Obtain a Flame Degen. It can be purchased at the Auction House, purchased with Sparks of Eminence, crafted, or it rarely drops from Napalm enemies."] = "フレイムデーゲンを競売・エミネンス・合成、またはNapalmの低確率ドロップで用意。",
    ["Trade the Flame Degen to Radeivepart to complete the quest and receive the Map of Castle Zvahl."] = "Radeivepartに渡しMap of Castle Zvahl。",
    ["Speak with Maat in Ru'Lude Gardens (H-5) on a level 50 job. You need Jeuno fame level 1."] = "50のジョブでル・ルデの庭(H-5)のMaatに話す。原文ではジュノ名声1も条件。",
    ["Maat asks for three items. Three key items combine into each required item. Be wary of Explosure's Self-Destruct and Exoray's conal Breath damage attacks."] = "3品を頼まれる。各品は対応するだいじなもの3つの収集でも得られる。Explosureの自爆とExorayの前方ブレスに注意。",
    ["Bomb Coal drops from Explosure enemies, or you can receive it after obtaining three Bomb coal fragments from ??? spots."] = "ボムの炭はExplosureのドロップ、または???のボムの炭 fragments3つを集める方法で得る。",
    ["Exoray Mold drops from Exoray enemies (uncommon), or you can receive it after obtaining three Exoray mold crumbs from ??? spots."] = "エクソレイの粘菌はExorayの低確率ドロップ、または???のエクソレイの粘菌 crumbs3つを集める方法で得る。",
    ["Ancient Papyrus drops from Lich enemies (common), or you can receive it after obtaining three Ancient papyrus shreds from ??? spots. Do not walk over the graves throughout the zone, as you may fall through them to a lower level."] = "古代魔法のパピルスはLichのドロップ、または???の古代魔法のパピルス shreds3つを集める方法で得る。墓の上を歩くと下層へ落ちる場所がある。",
    ["Take care while triggering the lever, as the single bomb that wanders nearby is aggressive by sight and by magic."] = "レバー近くのボムは視覚・魔法感知なので操作時は注意。",
    ["Trade the items to Maat to complete the quest, which raises your level cap to 55."] = "Maatに3品を渡してレベル上限55。",
    ["Speak with Maat in Ru'Lude Gardens (H-5) on a level 51 job. You need Jeuno fame level 1. He asks you for three key items guarded by monsters in Xarcabard."] = "51のジョブでル・ルデの庭(H-5)のMaatからザルカバードの魔物が守る3つのだいじなものを頼まれる。原文ではジュノ名声1も条件。",
    ["If this is your first time heading to Xarcabard, you may use the Unity level 125 warp to Xarcabard."] = "ザルカバード初訪問ならユニティCL125転送も利用可。",
    ["The key items are: Round frigicite from Boreal Tiger at (I-5), Square frigicite from Boreal Coeurl at (J-6) and Triangular frigicite from Boreal Hound at (G-10)."] = "Boreal Tigerの(I-5)でRound frigicite、Boreal Coeurlの(J-6)でSquare frigicite、Boreal Houndの(G-10)でTriangular frigiciteを得る。",
    ["The Notorious Monsters stand guard in caves, have a fairly large aggro range, and respawn within about 5 minutes after being defeated."] = "洞窟を守るNMは感知範囲が広く、討伐後約5分で再出現。",
    ["The ??? spot is always present at the far end of the cave, and you receive the key item once you touch it, so you do not need to defeat the Notorious Monsters: you can simply hold them while examining the spots. They no longer use draw-in according to the page, although a note says the Coeurl did use it several times when tested in 2024."] = "奥の???は常設で、調べれば入手できる。NMを倒さず引きつけてもらう方法も可。原文は引き寄せを使わなくなったとする一方、2024年のCoeurlの使用報告も併記。",
    ["Speak with Maat once you have all three key items to complete the quest, which raises your level cap to 60."] = "3つを集めMaatに報告してレベル上限60。",
    ["Speak with Maat in Ru'Lude Gardens on a level 56 or higher job. You need Jeuno fame level 1. He asks for three crests, each found in a different place."] = "56以上でル・ルデの庭のMaatから3つの紋章を頼まれる。原文ではジュノ名声1も条件。",
    ["The key items are: Orcish crest in Monastic Cavern (J-6), Quadav crest in Qulun Dome (J-7) and Yagudo crest in Castle Oztroja (H-6). A ??? spot appears in each of these areas, close to True-Sight or True-Sound Notorious Monsters."] = "修道窟(J-6)のOrcish crest、クゥルンの大伽藍(J-7)のQuadav crest、オズトロヤ城(H-6)のYagudo crestを集める。各???は見破りNM付近。",
    ["For the Orcish crest, either you or a player assisting you must possess the Crimson orb key item from the mini-quest. Exit Monastic Cavern at (I-8) and proceed to the (J-9) entrance of Monastic Cavern; you or a partner need a Crimson orb from Sedal-Godjal to enter. Once inside, click the ???."] = "Orcish crestへは本人か手伝いがCrimson orbを用意。修道窟(I-8)から出て(J-9)入口へ行き、Sedal-GodjalのCrimson orbで中へ入り???を調べる。",
    ["Lower level players may want to bring and use a Reraise item. You will need to run to the Brass Door before it closes, and after that door monsters become more challenging for low level players and dangerous by the fourth floor."] = "低レベルならリレイズ用品を準備。Brass Doorは閉まる前に通る。扉以降、特に4階の敵は危険。原文は各紋章までの詳細ルートを省略。",
    ["Speak with Maat once you have all three key items to complete the quest, which raises your level cap to 65."] = "3つを集めMaatに報告してレベル上限65。",
    ["Speak with Maat in Ru'Lude Gardens (H-5) on a level 61 or higher job. You need Jeuno fame level 1. He gives you four clues and wants you to trade a Kindred's Seal to each of the people described in the clues."] = "61以上でル・ルデの庭(H-5)のMaatから4人の手掛かりを聞き、各人に獣神印章を渡す。原文ではジュノ名声1も条件。",
    ["You are not provided with the Kindred's Seals and need to get them yourself. Check your inventory and the Port Jeuno NPCs Shemo and Shami (Status, Currencies, Kindred's Seals Stored), as you may already have enough seals."] = "印章は自分で4個用意。鞄やジュノ港のShemo／Shamiへの預け数を「ステータス→通貨」で確認。",
    ["Kindred's Seals can be acquired from any normal monster of level 50-69 that checks as Easy Prey or higher, or exchanged 3 for 1 (or 2 for 1 during certain campaigns) for other seal types from Shemo."] = "獣神印章は経験値の入る50〜69の通常敵、またはShemoの他印章3:1交換（特定キャンペーン時2:1）で用意。",
    ["In return for a seal you receive either a Smiling stone, Scowling stone, Somber stone or Spirited stone."] = "各人からSmiling stone／Scowling stone／Somber stone／Spirited stoneを得る。",
    ["Speak with Maat once you have all four stones to complete the quest, which raises your level cap to 70."] = "4つを集めMaatに報告してレベル上限70。",
    ["Speak with Maat in Ru'Lude Gardens (H-5) on any level 66-70 job. You need Jeuno fame level 1. This limit break applies to the jobs that existed before the Treasures of Aht Urhgan expansion, and it needs the Testimony item for the job you want to fight Maat with."] = "66〜70のジョブでル・ルデの庭(H-5)のMaatに話す。アトルガン以前のジョブが対象で、戦うジョブのTestimonyが必要。原文ではジュノ名声1も条件。",
    ["Once you trade the Testimony to Maat, he asks if you are ready."] = "TestimonyをMaatに渡し準備確認に答える。",
    ["Trade the Testimony to the Burning Circle to enter a one-on-one battle against Maat. The time limit is 10 minutes, and after about 5 minutes from engaging Maat, he begins to use Asuran Fists. Maat has all the relevant abilities and spells of your main job."] = "Burning CircleにTestimonyを渡しMaatとの1対1のBFへ。10分制限。原文では交戦約5分後から夢想阿修羅拳を使い、対応ジョブの魔法・アビリティを使うと記載。",
    ["A White Mage may instead pull Maat and stay alive for 5 minutes, causing Maat to give up. A Thief may try to steal a Scroll of Instant Warp from Maat; once you steal it, Maat gives up."] = "原文の代替勝利条件：白魔道士は交戦して5分生存、シーフはMaatから呪符デジョンを盗む。小売版との差異や条件変更に注意。",
    ["When Maat gives up, you receive the title Maat Masher and a Scroll of Instant Warp."] = "Maat降参で称号Maat Masherと呪符デジョン。",
    ["Return to Ru'Lude Gardens and speak with Maat to complete the quest, which raises your level cap to 75."] = "ル・ルデの庭のMaatに報告してレベル上限75。",
    ["If you have not yet gained access to Aht Urhgan Whitegate through the quest The Road to Aht Urhgan, you may trade your Testimony afterwards under the advanced path option and complete the quest."] = "The Road to Aht Urhgan未完了なら、後で上級者向けの選択肢でTestimonyを渡して渡航依頼を終える方法もある。",
    ["This quest requires the Rise of the Zilart pack. Talk to Maat at (H-5) in Ru'Lude Gardens on each of the 15 jobs that existed before Treasures of Aht Urhgan, and defeat him with each one."] = "ジラート導入が必要。ル・ルデの庭(H-5)のMaatをアトルガン以前の15ジョブでそれぞれ倒す。",
    ["The level required to fight Maat is at least level 66."] = "Maat戦への挑戦は66以上が必要。",
    ["To check which jobs you have beaten Maat with, enter the Feretory and speak with Teyrnon. Instincts associated with the jobs on which you have defeated Maat cost 5,000 Infamy instead of 10,000."] = "魂の聖櫃のTeyrnonで確認可能。勝利済みジョブに対応するInstinctはInfamy10,000でなく5,000で交換できる。",
    ["Upon defeating Maat for the last time, speak with him to receive the cutscene and your new Maat's Cap."] = "最後のジョブで勝ったらMaatに話しマートキャップ。",
    ["After finishing all of the cutscenes after Dawn, including Blueblade Fell, walk towards the Palace in Ru'Lude Gardens to begin the cutscene with Esha'ntarl."] = "Dawn後のBlueblade Fellを含む全イベントを終え、ル・ルデの庭の宮殿へ進みEsha'ntarlのイベント。",
    ["Examine the Dilapidated Gate in Misareaux Coast (F-7) for a cutscene. The Unity warp puts you right in front of this gate."] = "ミザレオ海岸(F-7)のDilapidated Gateを調べる。ユニティ転送先の正面。",
    ["Examine the green Unstable Displacement in the northwest section of Riverne - Site #B01 (E-7) for a cutscene. You can warp and use the Home Point to get there, or farm one Giant Scale to get to (E-7) the long way."] = "リヴェーヌ岩塊群サイトB01北西(E-7)の緑のUnstable Displacementを調べる。Home Point、またはGiant Scale1枚を用意して進む。",
    ["Click the green Unstable Displacement again to enter the battlefield Storms of Fate against Bahamut."] = "緑の転送口を再調査し、BF「日輪を担いて」でBahamutと戦う。",
    ["Kill Bahamut for a cutscene."] = "Bahamutを倒してイベント。",
    ["Return to the Palace in Ru'Lude Gardens for a cutscene that completes the quest and gives you the key item Whisper of the Wyrmking."] = "ル・ルデの庭の宮殿へ戻り龍王の息吹を得て完了。",
    ["You must complete Storms of Fate to trigger this quest, and you need the key item Whisper of the Wyrmking."] = "日輪を担いて完了と龍王の息吹所持が必要。",
    ["Wait until the next in-game day after completing Storms of Fate to activate this quest. If you reset your memories, this wait does not apply."] = "日輪を担いて完了後、次のヴァナ日付まで待つ。記憶を消しての再挑戦時はこの待機不要。",
    ["Walk into the Palace in Ru'Lude Gardens for the cutscene in which you receive the key item Note written by Esha'ntarl. It is a different cutscene from the one that ended Storms of Fate, which does not give a key item."] = "ル・ルデの庭の宮殿に進みエシャンタールメモを得る。前依頼の終了イベントとは別。",
    ["Travel to the crags of Holla, Dem and Mea and investigate the coordinates where the strange readings from the Emptiness are occurring, to obtain the key items Promyvion - Holla sliver, Promyvion - Dem sliver and Promyvion - Mea sliver."] = "Holla／Dem／Meaの岩で虚ろの反応を調べ、プロミヴォン-ホラ sliver／Dem sliver／Mea sliverを得る。原文は調査地点への詳細ルートを省略。",
    ["You need to have completed Rise of the Zilart Mission 17 and Chains of Promathia Mission 8-4. You must zone and wait until the next game day after completing the previous quest."] = "ジラート17とプロマシア8-4完了が必要。前依頼完了後、エリアチェンジして次のヴァナ日付を待つ。",
    ["Zone and wait until the next Vana'diel day after completing the battlefield, then talk to Gilgamesh in Norg for a cutscene to complete the quest and receive an earring of your choice."] = "BF後エリアチェンジし、次のヴァナ日付以降ノーグのGilgameshに話して耳装備を1つ選ぶ。原文は前工程からBFまでの移動・戦闘説明を省略。",
    ["If you chose the wrong earring or want a different one, drop your earring and proceed to the Empyreal Paradox (it must be dropped before you zone into the Empyreal Paradox). The fastest way is the Home Point warp: Lumoria, The Garden of Ru'Hmet, #1, and descend."] = "取り直すなら耳装備を捨ててから天象の鎖へ入る。Home Point「ルモリア→ル・メトの園 #1」から下りると近い。",
    ["Select the ??? near the entrance and erase your memories (\"I've already forgotten them\" and \"Yes, erase my memories\"), then complete Shadows of the Departed and Apocalypse Nigh again to obtain an earring of your choice."] = "入口近くの???で「I've already forgotten them」→「Yes, erase my memories」を選び、亡者の影と世界に在りて君は何を想うのか？をやり直して報酬を再選択。",
    ["You need to have completed Chains of Promathia Mission 3-2. Speak with Taillegeas in Ru'Lude Gardens (I-7) to begin the quest."] = "プロマシア3-2完了後、ル・ルデの庭(I-7)のTaillegeasから受領。",
    ["He asks you to bring him a few items from a list of possible requests."] = "候補一覧の中から指定される品を用意する。原文は一覧を省略。",
    ["Trade Taillegeas the items he requests to receive your reward, 4,000 gil. You can repeat the quest."] = "Taillegeasに指定品を渡し4,000ギル。反復可。",
    ["First enter any Promyvion area, and return to Harith in the Grand Duke's house in Ru'Lude Gardens (H-5) without erasing your memory at the Large Apparatus."] = "いずれかのPromyvionへ入り、Large Apparatusで記憶を消さずル・ルデの庭(H-5)大公私邸のHarithに戻る。",
    ["Some monsters inside Promyvion drop items called Recollections. Trade Harith one of these Recollections plus 2,000 gil to receive an Anima: Recollection of Pain gives Hysteroanima (negates special attacks), Recollection of Fear gives Psychoanima (negates normal attacks) and Recollection of Guilt gives Terroanima (causes the monster to flee)."] = "Recollections1個と2,000ギルをHarithに渡してアニマ化。悩ましき記憶の一塊→迷のアニマ（特殊技封じ）、Fear→驚のアニマ（通常攻撃封じ）、Guilt→脅のアニマ（敵を逃走させる）。",
    ["Alternatively, trade Harith one of these Recollections, without gil, to receive an item: Recollection of Suffering gives a Hamayumi, Recollection of Anxiety gives a Stone Gorget and Recollection of Animosity gives a Dia Wand. The Recollections of Suffering and Animosity come from Notorious Monsters in Promyvion - Vahzl."] = "ギルなしなら別の品に交換。苦苦しき記憶の一塊→破魔弓、Anxiety→ストーンゴルゲット、Animosity→ディアワンド。SufferingとAnimosityはプロミヴォン-ヴァズのNMが落とす。",
    ["The quest can be repeated."] = "反復可能。",
