    -- Whitegate quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Ahkk Jharcham in Aht Urhgan Whitegate (I-10). You need Aht Urhgan fame level 1. She wants a Parchment and a Black Ink so she can write down her secret."] = "アトルガン白門(I-10)のAhkk Jharchamから受領。原文条件はアトルガン名声1。羊皮紙と黒インクを頼まれる。",
    ["Obtain a Parchment, which Pikini-Mikini sells in Mhaura (G-9) for 2,019 gil, and a Black Ink, which Maymunah sells in Bastok Mines (K-7) for 570 gil."] = "羊皮紙はマウラ(G-9)のPikini-Mikiniで2,019ギル、黒インクはバストゥーク鉱山区(K-7)のMaymunahで570ギル。",
    ["Trade the Parchment and the Black Ink to Ahkk Jharcham. The reward is the ability to exit your Mog House to any zone within the city of Aht Urhgan."] = "Ahkk Jharchamに2品を渡すと、モグハウスからアトルガン各区へ退出可能になる。",
    ["Speak with Hadahda in Aht Urhgan Whitegate (F-10), above the Mog House. He wants paper pieces with letters written on them: one each of M, U and T, and two each of A and D."] = "アトルガン白門(F-10)、モグハウス上のHadahdaから受領。M・U・T各1枚、A・D各2枚を集める。",
    ["Collect the letters from NPCs in Aht Urhgan Whitegate: Qutiba (K-12) gives an A, Zabahf (F-8) gives the T, Mathlouq (F-5) gives the U, Mhasbaf (J-8) gives the M, Balakaf (I-5) gives a D, and Ekhu Pesshyadha (H-6) gives the second A. You may need to speak to Ekhu Pesshyadha twice if you have logged The Die Is Cast."] = "白門内でQutiba(K-12)からA、Zabahf(F-8)からT、Mathlouq(F-5)からU、Mhasbaf(J-8)からM、Balakaf(I-5)からD、Ekhu Pesshyadha(H-6)からA。その女、性悪につき受領中はEkhuに2回会話が必要な場合あり。",
    ["Collect the 7 letters in total. The source I found does not say who gives the first D."] = "計7枚を集める。原文はもう1枚のDの提供者を明記していない。",
    ["Return to Hadahda for another cutscene and your reward, a Sutlac."] = "Hadahdaに戻りシュトラッチを得る。",
    ["You can trade the Sutlac back to Hadahda if you prefer an Imperial Bronze Piece."] = "シュトラッチをHadahdaに渡しアトルガン青銅貨と交換することも可能。",
    ["Make sure you pick up a few Pickaxes before leaving, since they can break. This quest requires the Treasures of Aht Urhgan pack."] = "壊れる場合に備えつるはしを数本用意。アトルガン導入が必要。",
    ["Speak with Dkhaaya in Aht Urhgan Whitegate (G-9) for a cutscene and to obtain Dkhaaya's research journal."] = "アトルガン白門(G-9)のDkhaayaからDkhaaya's research journalを受け取る。",
    ["Enter Aydeewa Subterrane through the cave at (I-7) in Bhaflau Thickets."] = "バフラウ段丘(I-7)の洞窟からエジワ蘿洞へ。",
    ["Head to the room at (H-9) and mine in it until you find one of three key items: Electrocell, Electropot or Electrolocomotive. This is the same room where you finish the Blue Mage flag quest."] = "(H-9)の部屋で採掘し雷池／雷動掃磁器／雷動車のいずれかを得る。青魔道士取得の池と同じ部屋。",
    ["Return to Dkhaaya, who rewards you with a Lightning Band."] = "Dkhaayaに報告して雷輪。",
    ["At this point the quest is completed. If you trade the Lightning Band to the Leypoint in Wajaom Woodlands (G-8), it transforms into an Olduum Ring."] = "ここで依頼は完了。ワジャーム樹林(G-8)のLeypointに雷輪を渡すとオルドゥームリングになる。",
    ["If you drop your Olduum Ring, speak to Dkhaaya to repeat the quest."] = "オルドゥームリングを捨てた場合はDkhaayaから依頼を再受領可。",
    ["Speak with Tehf Kimasnahya in Aht Urhgan Whitegate (F-8). You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. He wants you to get a vial of luminous water from Ekhu Pesshyadha."] = "アトルガン白門(F-8)のTehf Kimasnahyaから受領。アトルガン導入と原文名声1が必要。Ekhu Pesshyadhaから煌きの水をもらう。",
    ["Speak with Ekhu Pesshyadha in Aht Urhgan Whitegate (H-6)."] = "アトルガン白門(H-6)のEkhu Pesshyadhaに話す。",
    ["Speak with Zabahf in Aht Urhgan Whitegate (F-8)."] = "アトルガン白門(F-8)のZabahfに話す。",
    ["Speak with Ekhu Pesshyadha to receive the Vial of luminous water."] = "Ekhu PesshyadhaからVial of luminous waterを得る。",
    ["Speak with Tehf Kimasnahya."] = "Tehf Kimasnahyaに話す。",
    ["Go to the lower level of Aht Urhgan Whitegate (J-10) to trigger a cutscene, near the NPC Hajaom."] = "アトルガン白門(J-10)下段、Hajaom近くへ進んでイベント。",
    ["Speak with Tehf Kimasnahya again."] = "Tehf Kimasnahyaに再び話す。",
    ["Zone and then speak with Tehf Kimasnahya once more to receive your reward, the Bibiki Seashell."] = "エリアチェンジ後Tehf Kimasnahyaに話しビビキーの潮騒。原文は待ち時間の記載がない。",
    ["Speak with Waoud in Aht Urhgan Whitegate (J-10), on the top floor. You need to be level 30 or higher."] = "30以上でアトルガン白門(J-10)上段のWaoudに話す。",
    ["He offers a divination for 1,000 gil and asks a series of questions. Upon success, Waoud mentions seeing all five serpent symbols. It is possible not to be able to progress further, as he may mention only one serpent."] = "1,000ギルの占いで質問に答える。進行できる回答では五蛇の紋章の話になるが、1つしか示されず進まない場合もある。",
    ["If you progress through the questions, Waoud will not progress the quest until at least one game day later, and you must zone at least once."] = "質問を通過したらヴァナ1日以上待ち、1回以上エリアチェンジしてWaoudに話す。",
    ["Waoud then asks for one item, giving clues. The possible items include Sunsand, Dangruf Stone and Siren's Tear; read the item entries themselves for how to get each one. Sunsand is the only requested item that can be bought at the Auction House."] = "指定品を手掛かりから選ぶ。バルクルムの太陽砂／ダングルフの奇岩石／セイレーンの涙のいずれか。競売で買えるのはバルクルムの太陽砂のみ。",
    ["Unequip your weapons in order to pick up the item if needed, and keep it in your inventory."] = "採取に必要なら武器を外す。指定品は鞄に保持。",
    ["Trade him the item and he tells you to go to Aydeewa Subterrane."] = "Waoudに指定品を渡す操作でエジワ蘿洞へ向かうよう指示される。原文では品は消費しない。",
    ["In Aydeewa Subterrane, go to the pond room at (H-9) for a cutscene. You do not get the cutscene if you do not have the requested item on you."] = "エジワ蘿洞(H-9)の池でイベント。指定品を持っていないと発生しない。",
    ["If you refuse him every time instead, the entire quest resets and you have to start over from the beginning."] = "拒否し続けると進行がリセットされ最初からになる。",
    ["When the cutscene is over, you are returned to Aht Urhgan Whitegate and able to change to Blue Mage. You receive the key item Mark of Zahak, and the item you brought is still in your inventory."] = "イベント後白門へ戻され、青魔道士取得とザッハークの呪印。持参品は残る。",
    ["You can return to Waoud and ask him to \"gaze away\" at your fate to get a cutscene. This is necessary for the next quest."] = "Waoudに戻り「gaze away」で後日談を見る。次の依頼に必要。",
    ["As a job at level 30 or higher, speak with Ratihb in Aht Urhgan Whitegate (J-12), at the Shararat Teahouse, for a cutscene that begins the quest. This quest requires the Treasures of Aht Urhgan pack."] = "30以上でアトルガン白門(J-12)茶屋のRatihbから受領。アトルガン導入が必要。",
    ["Speak with Mafwahb at the Palace Door in Aht Urhgan Whitegate (L-9) for a cutscene."] = "アトルガン白門(L-9)、宮殿扉前のMafwahbに話す。",
    ["Go to Arrapago Reef and click on the ??? (not the shining spot labeled \"-\") at the northeast corner of (H-10) for a cutscene. It is located on a ship, and you need a Lamian Fang Key to get there. There are only a few possible opponents (5) between the zone line and the gate before the quest marker."] = "アラパゴ暗礁域(H-10)北東、船上の???を調べる。「-」の光点ではない。途中の扉にラミアの牙のカギが必要。原文では入口から扉まで敵候補5体。",
    ["Lamian Fang Keys drop from Lamia and Drauger enemies in the area. You can also receive one from a ??? spot in Caedarva Mire (I-7), Map 1, once every game day: use the Lamian Fang Key on the Iron Gate at (J-10), then go west on the small map to another Iron Gate, which is unlocked. The Survival Guide in Arrapago Reef is very near to the Iron Gate."] = "カギは現地のLamia／Drauger、またはカダーバの浮沼マップ1(I-7)の???からヴァナ1日1個。アラパゴ暗礁域(J-10)のIron Gateを開け、西の小マップの無施錠扉へ。Survival Guideが近い。",
    ["Travel west into the tunnel entrance, then north to find the Rock Slab. Examine it for a cutscene that ends the quest and gives you your reward, the Corsair Die."] = "西の洞窟入口から北のRock Slabを調べ、コルセアのダイスを得て完了。原文は中間の船上イベントやエリア移動を省略。",
    ["Speak with Mishhar in Aht Urhgan Whitegate (H-8) to begin the quest. He wants you to find out what Isween is doing in Wajaom Woodlands at night."] = "アトルガン白門(H-8)のMishharから、夜のIsweenの行動調査を受ける。",
    ["Head to Wajaom Woodlands (K-7) and check the ??? at night (after 20:00 game time) for a cutscene."] = "ワジャーム樹林(K-7)の???を夜（原文20:00以降）に調べる。",
    ["Return to Mishhar for a cutscene."] = "Mishharに報告。",
    ["Head to Mamook using the (E-12) entrance in Wajaom Woodlands."] = "ワジャーム樹林(E-12)からマムークへ。",
    ["At the end of the tunnel (L-9) there is a ??? you need to examine for another cutscene."] = "通路奥(L-9)の???を調べる。",
    ["Return to Mishhar for your reward."] = "Mishharに報告して報酬。",
    ["After completing Vanishing Act, zone and wait one Earth minute."] = "消えたカボチャ頭完了後、エリアチェンジして地球時間1分待つ。",
    ["Speak with Qutiba in Aht Urhgan Whitegate (K-12) for a cutscene. You may have to talk to her several times and agree to listen to a recipe before the cutscene plays."] = "アトルガン白門(K-12)のQutibaにイベントまで数回話す。レシピを聞く選択が必要な場合あり。",
    ["Trade Qutiba three pots of White Honey for another cutscene and your reward, the Irmik Helvasi and additional recipes."] = "QutibaにWhite Honey3個を渡しイルミクヘルバスとレシピ。",
    ["Speak with Dabhuh in Aht Urhgan Whitegate (K-11), near The Pit, to begin the quest. He wants you to bring him a Merrow Scale. This quest requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(K-11)、The Pit付近のDabhuhからメローの鱗を頼まれる。アトルガン導入が必要。",
    ["Trade him a Merrow Scale to complete the quest and receive Merrow No.17's Locket."] = "メローの鱗を渡しメロー17号ロケット。",
    ["Speak with Ratihb in Aht Urhgan Whitegate (J-12) to start this quest. The correct cutscene is the one about Balajaha, Yadhiwa and a game of dice, not the one for Luck of the Draw. This quest requires the Treasures of Aht Urhgan pack."] = "アトルガン白門(J-12)のRatihbから受領。海鳥は賽を振るでなくBalajaha／Yadhiwaとサイコロの話。アトルガン導入が必要。",
    ["Speak with Ekhu Pesshyadha (H-6) for a cutscene with Yadhiwa. You can pick any option to proceed; you may choose to gamble with her, but she always wins."] = "Ekhu Pesshyadha(H-6)に話す。選択肢はどれでも進むが、賭けを選ぶとYadhiwaに必ず負ける。",
    ["Travel to Nashmau and speak with Jijiroon (H-8). You can pick any option again to proceed with this cutscene. Before you leave Nashmau, bring a good supply of Echo Drops for the NM fight."] = "ナシュモ(H-8)のJijiroonに話す。選択肢不問。出発前にNM戦用のやまびこ薬を十分用意。",
    ["Obtain a Lamian Fang Key. You can get one from a ??? in Caedarva Mire at (I-7), in a small crevice behind a Jnun, or it can drop from a Reserve Draugar in Caedarva Mire. Otherwise, obtain it from Merrow enemies inside Arrapago Reef."] = "ラミアの牙のカギを用意。カダーバの浮沼(I-7)のJnun裏の裂け目の???、Reserve Draugar、またはアラパゴ暗礁域のMerrow等が対象と原文に記載。",
    ["Travel to Arrapago Reef by way of the (I-6) entrance from Caedarva Mire and open the first Iron Gate at (J-10) with the Lamian Fang Key."] = "カダーバの浮沼(I-6)からアラパゴ暗礁域へ入り、(J-10)の最初のIron Gateをカギで開ける。",
    ["Cross over the Corsair quest ship and down onto land, cross two bridges to the west shore (G-10), then head west to (F-10) and cross two more bridges. The first bridge is the start of Arrapago Reef map 2 (K-11)."] = "コルセア取得の船を越えて陸へ。橋2本で西岸(G-10)、さらに西(F-10)から橋2本へ。最初の橋から原文マップ2(K-11)になる。",
    ["The quest's ??? is at (K-10), at the water's edge on map 2. Cast your buffs before you click it, as the NM Bukki that spawns uses Deafening Tantara (area Silence) immediately and often."] = "原文マップ2(K-10)水辺の???を調べBukkiを出す。即座に範囲沈黙Deafening Tantaraを使うので先に強化。",
    ["Defeat Bukki, then click the ??? again to get the Bag of gold pieces and complete this part of the quest."] = "Bukkiを倒し???を再調査してBag of gold pieces。",
    ["Return to Aht Urhgan Whitegate and speak with Ratihb for the final cutscene with Balajaha to complete the quest and receive your reward, the Random Ring."] = "白門のRatihbに報告しランダムリング。",
    ["Speak with Milazahn in Aht Urhgan Whitegate (G-8) for a cutscene."] = "アトルガン白門(G-8)のMilazahnに話す。",
    ["Speak with Cacaroon (G-11) for a cutscene."] = "Cacaroon(G-11)に話す。",
    ["Trade Cacaroon 1,000 gil for another cutscene."] = "Cacaroonに1,000ギルを渡す。",
    ["Zone into Mamook from the Mamool Ja Staging Point exit."] = "Mamool Ja Staging Pointからマムークへ。",
    ["Head northwest to (E-8) and check the Viscous Liquid for a cutscene."] = "北西(E-8)のViscous Liquidを調べる。",
    ["Examine the Viscous Liquid again to spawn the NM Mamool Ja."] = "再調査してMamool Jaを出す。",
    ["After the NM is defeated, examine the Viscous Liquid for a cutscene."] = "討伐後Viscous Liquidを再調査。",
    ["Return to Milazahn for your reward, an Imperial Mythril Piece."] = "Milazahnに報告しアトルガン霊銀貨。",
    ["Begin this quest by speaking to Waoud in Aht Urhgan Whitegate (J-10) once your Blue Mage is level 40 and you have completed Aht Urhgan Mission 2. This quest follows An Empty Vessel."] = "青魔道士40以上、アトルガン2と渇望完了後、白門(J-10)のWaoudから受領。",
    ["If you did not originally watch the extra scene for completing An Empty Vessel, you need to speak to him again after zoning. Tell Waoud that you want him to \"Gaze Away\" at your fate and the quest cutscene begins. Wait three in-game days, zone, and speak to Waoud again, choosing the same option. The quest log says you have the quest from Raubahn, even though Waoud acts as your contact."] = "渇望後日談がまだならエリアチェンジ後「Gaze Away」。原文ではさらにヴァナ3日後、エリアチェンジして同じ選択。ログ上の依頼者はRaubahn。",
    ["Once the quest has started, go to each of the five staging points with Blue Mage as your main job and talk to the Immortal there for a quick cutscene and a key item: Azouph Isle Staging Point, Dvucca Isle Staging Point, Mamool Ja Staging Point, Halvung Staging Point and Ilrusi Atoll Staging Point. You do not need to speak to the guard at Nyzul Isle for this quest."] = "青魔道士で5監視哨の不滅隊士に話す。Azouph Isle／Dvucca Isle／Mamool Ja／ハルブーン／イルルシ環礁。ナイズル島は不要。",
    ["The key items are the Brand of the Springserpent, the Brand of the Galeserpent, the Brand of the Flameserpent, the Brand of the Skyserpent and the Brand of the Stoneserpent. They are permanent."] = "Springserpent／Galeserpent／Flameserpent／Skyserpent／Stoneserpentの5つのBrandを得る。永続だいじなもの。",
    ["After you have all five Brand key items, speak to Waoud again for the final cutscene to finish the quest and receive the Immortal's Scimitar. You also receive the title Branded by the Five Serpents."] = "Waoudに報告してイモータルシミターと称号Branded by the Five Serpents。",
    ["Wait one in-game day since completing Beginnings and re-zone into Aht Urhgan Whitegate if you have not already. You need to be a Blue Mage of level 50 or higher."] = "開門完了後、原文ではヴァナ1日待って白門へ入り直す。青魔道士50以上が必要。",
    ["Speak with Waoud in Aht Urhgan Whitegate (J-10) to begin the quest. Raubahn directs you to find and kill a Flan in the Navukgo Execution Chamber."] = "白門(J-10)のWaoudから受領。ナバゴ処刑場のフラン討伐を指示される。",
    ["The quickest way is the Home Point in the part of Mount Zhayolm just outside the chamber, or the Mount Zhayolm Unity warps (level 128 or 135)."] = "処刑場外のゼオルム火山のHome Point、またはユニティCL128／135転送が便利。",
    ["In the Navukgo Execution Chamber, examine the Decorative Bronze Gate to start a battlefield fight. Up to 18 people can enter, but more people cause more Immortal Flans to spawn. Trust Magic is allowed."] = "処刑場のDecorative Bronze Gateを調べBFへ。最大18人、人数でImmortal Flan数が増える。原文ではフェイス可。",
    ["Return to Aht Urhgan Whitegate and speak with Waoud. You are given a Sealed Immortal envelope."] = "白門のWaoudからSealed Immortal envelopeを受け取る。",
    ["Deliver the envelope to Lathuya in Aht Urhgan Whitegate (F-8), on the second floor inside the stall."] = "白門(F-8)、露店内2階のLathuyaへ封書を届ける。",
    ["Return to Aht Urhgan Whitegate and speak with Lathuya again to receive your reward, the Magus Charuqs."] = "Lathuyaに再び話してメガスチャルク。原文は途中の待ち時間の記載がない。",
    ["You must zone after completing Omens to start this quest; if you do not zone and get a divination from Waoud, you will have to wait for the next game day. You need the Treasures of Aht Urhgan pack."] = "兆候後はエリアチェンジが必要。移動せず占ってもらうと翌ヴァナ日まで待つ。アトルガン導入が必要。",
    ["Speak with Waoud in Aht Urhgan Whitegate (J-10) as a Blue Mage of level 50 or higher."] = "青魔道士50以上で白門(J-10)のWaoudに話す。",
    ["Ask for a divination by selecting \"Gaze away.\" and pay the 1,000 gil. He tells you that your fate lies beyond the gate of nobility. There are other cutscenes possible here, so make sure you have the quest flagged before leaving Aht Urhgan Whitegate."] = "「Gaze away.」で占い料1,000ギル。別イベントもあるので依頼フラグを確認して出発。",
    ["Examine the Imperial Whitegate in Aht Urhgan Whitegate (L-8) for a cutscene. The quest is formally added to your quest log after this cutscene, and you no longer need to be on Blue Mage."] = "白門(L-8)のImperial Whitegateを調べ正式受領。以後は他ジョブ可。",
    ["After this cutscene you may commission Blue Mage Artifact Armor (Magus Shalwar, Magus Bazubands and Magus Jubbah) from Lathuya, who gives you a Magus order slip and tells you to come back later. You do not have to defeat the Nepionic Soulflayer first."] = "このイベント後LathuyaにMagus Shalwar／Magus Bazubands／Magus Jubbahを発注可能。Magus order slipを受け取り後で戻る。Nepionic Soulflayer討伐前でも可。",
    ["To fight the Nepionic Soulflayer, gather your party and make sure everyone has an Imperial Silver Piece. Go to Nashmau, take the western exit to Caedarva Mire, head west to (E-11) and enter the Alzadaal Undersea Ruins by trading your Imperial Silver Piece to the guard."] = "各自アトルガン白銀貨を用意。ナシュモ西口からカダーバの浮沼(E-11)へ進み、門番に銀貨を渡してアルザダール海底遺跡群へ。",
    ["Go down to the main room for a cutscene and take the right teleporter."] = "広間でイベント後、右の転送装置へ。",
    ["Examine the blank spot at (G-7) to spawn the NM Nepionic Soulflayer. When you have defeated it, examine the blank spot again to receive your Magus Keffiyeh and the title Paragon of Blue Mage Excellence."] = "(G-7)の名前のない対象でNepionic Soulflayerを出し、倒して再調査。メガスケフィエと称号を得る。",
    ["Speak with Ratihb in Aht Urhgan Whitegate (J-12), at the Shararat Teahouse. If his response is to welcome you and revitalize you with tea, you probably already did the optional last step of the previous quest. You need to be a Corsair of level 40 or higher."] = "コルセア40以上で白門(J-12)茶屋のRatihbに話す。茶を勧められるだけなら前依頼の任意後日談は済んでいる可能性あり。",
    ["Go to Arrapago Reef. Use the Arrapago Reef Survival Guide to get there quickly; if you do not have it, you can get it by walking from Nashmau or take the long way using the Azouph Isle Staging Point from Aht Urhgan Whitegate. You need a Lamian Fang Key to get to the ???."] = "アラパゴ暗礁域へ。Survival Guide、ナシュモ徒歩、またはAzouph Isle Staging Point経由。???までにラミアの牙のカギが必要。",
    ["Lamian Fang Keys drop from Lamia and Drauger enemies in the area, and you can also receive one from a ??? spot in Caedarva Mire (I-7), map 1, once every game day. Use the key on the Iron Gate at (J-10), then go west on the small map to another Iron Gate, which is unlocked."] = "Lamia／Drauger、またはカダーバの浮沼マップ1(I-7)の???からカギを得る（ヴァナ1日1個）。(J-10)のIron Gateを開け、西の小マップの無施錠扉へ。",
    ["Examine the ??? in Arrapago Reef (H-10) for a cutscene, as a Corsair of level 40 or higher."] = "コルセア40以上でアラパゴ暗礁域(H-10)の???を調べる。",
    ["Speak with Ratihb in Aht Urhgan Whitegate (J-12) for your reward, the Trump Gun. You may have to speak to him twice."] = "白門(J-12)のRatihbに報告しトランプガン。2回会話が必要な場合あり。原文は間の調査を省略。",
    ["While on Corsair at level 50 or higher, head to the Shararat Teahouse in Aht Urhgan Whitegate (K-12) for a cutscene and the key item Life float. This quest requires the Treasures of Aht Urhgan pack."] = "コルセア50以上で白門(K-12)茶屋へ進みLife floatを得る。アトルガン導入が必要。",
    ["After the cutscene you may commission Corsair Artifact Armor from Leleroon. You may choose the order in which you receive the armor, and you may commission a new piece one Vana'diel day (one Earth hour) after the last piece was completed."] = "LeleroonにAF装束を任意順で発注可能。原文では前の完成からヴァナ1日（地球時間1時間）後に次を発注可。",
    ["The rest of this quest may be completed on any job. If you lose the battle, you may return to get another key item after one real life day (midnight JST)."] = "以後は他ジョブ可。敗北時は次の日本時間午前0時以降にだいじなものを再取得、と原文に記載。",
    ["Head to the Ashu Talif in Arrapago Reef through the Dvucca Isle Staging Point or Alzadaal Undersea Ruins. To access the Cutter, first travel to the Dvucca Isle Staging Point and leave it, which puts you in Caedarva Mire (Map 2)."] = "Dvucca Isle Staging Pointかアルザダール海底遺跡群経由でAshu Talifへ。監視哨を出るとカダーバの浮沼マップ2。",
    ["Head west to (F-9) and zone into Arrapago Reef through entrance 3. Head north to (H-8) to find the Cutter."] = "西(F-9)の入口3からアラパゴ暗礁域へ入り、北(H-8)のCutterへ。",
    ["Approach the Cutter for a cutscene. Examine the Cutter to enter a battlefield against Yazquhl and Gowam."] = "Cutterに近づきイベント後、調べてYazquhl／GowamとのBFへ。原文は討伐後の報告を省略。",
    ["Speak with Iruki-Waraki in Aht Urhgan Whitegate (K-9). You need to be a Puppetmaster of level 40 or higher, and this quest follows No Strings Attached. He wants to recover his stolen automaton, which you can tell is his because of its very unique personality."] = "からくり士40以上、オートマトン後、白門(K-9)のIruki-Warakiから盗難オートマトン捜索を受ける。",
    ["He asks you to go to Nashmau and search for the culprit. Once in Nashmau, proceed to (H-6) (second floor) and speak with Dnegan."] = "ナシュモ(H-6)、2階のDneganに話す。",
    ["Go back to Iruki-Waraki in Aht Urhgan Whitegate to receive your Turbo Animator."] = "白門のIruki-Warakiに報告しターボストリンガー。原文は途中の調査を省略。",
    ["You must zone after the previous quest, The Wayward Automaton, in order to start this quest. Speak with Iruki-Waraki in Aht Urhgan Whitegate (K-9) as a Puppetmaster of level 50 or higher. You discover that he is trying to get his automaton back and has formed a plan, and he gives you a shopping list of items. From here on you can be on any job."] = "投げ込んだのは貴方じゃないですか後エリアチェンジ。からくり士50以上で白門(K-9)のIruki-Warakiから買物リストを受け取る。以後は他ジョブ可。",
    ["Trade Iruki-Waraki 1 Sleeping Potion and 1 Chai."] = "Sleeping Potion1個とChai1個を渡す。",
    ["He asks you to arrange a meeting with the thief in Nashmau. Head to Nashmau and seek out Dnegan at (H-6), on the second floor. Do not choose \"Ask about the automaton.\"; choose either of the other first dialogue options to continue."] = "ナシュモ(H-6)2階のDneganに話す。「Ask about the automaton.」以外の選択肢で進む。",
    ["When asked what to drink, choose either Chai or coffee. Do not choose \"I'll pass, thanks.\". When choosing a cup, select the cup with the suspicious vapor."] = "飲物はチャイかcoffeeを選ぶ。「I'll pass, thanks.」は不可。怪しい湯気のカップを選ぶ。",
    ["The next part of the cutscene takes you to Nashmau Port, where you see Iruki's plan in action. You are then presented with 3 options."] = "港のイベントで作戦を見て、3つの選択肢へ。",
    ["The next part of this quest is long and leaves you stuck in a remote area, so bring either a Warp Ring or a Scroll of Instant Warp."] = "次は遠隔地で長くなるためWarp Ringか呪符デジョンを準備。",
    ["Obtain a Lamian Fang Key. Enter Arrapago Reef from Caedarva Mire at (I-6), use the Lamian Fang Key to pass through the Iron Gate in Arrapago Reef, and continue through Arrapago Reef to exit back into Caedarva Mire."] = "ラミアの牙のカギを用意しカダーバの浮沼(I-6)からアラパゴ暗礁域へ。施錠扉を抜け、再びカダーバの浮沼へ出る。",
    ["A location for this quest is in Caedarva Mire at (K-5), which is actually part of the Azouph Isle map."] = "原文の目的地はカダーバの浮沼(K-5)、アズーフ島側マップ。具体的な調査・報告工程は省略。",
    ["Speak with Iruki-Waraki in Aht Urhgan Whitegate (K-9). You need to be a Puppetmaster of level 50 or higher and have the Treasures of Aht Urhgan pack; this quest follows Operation Teatime. In a cutscene he wonders why Shamarhaan picked him to be a Puppetmaster and asks you to inquire with his mentor about the situation."] = "からくり士50以上、アトルガン導入、キモいから名前で呼ぶな後、白門(K-9)のIruki-Warakiから師匠への相談を受ける。",
    ["At this point you can commission Dhima Polevhia to craft three Artifact pieces."] = "ここからDhima PolevhiaにAF3部位を発注可能。",
    ["Go to Bastok Markets and speak with Shamarhaan. He compliments you on becoming a fine Puppetmaster and, after contemplating, tells you that Iruki-Waraki has always had what a Puppetmaster should ideally have. You receive the key items Valkeng's memory chip and Toggle switch."] = "バストゥーク商業区のShamarhaanからValkeng's memory chipとToggle switchを得る。",
    ["Head to Nashmau and zone into Caedarva Mire at (G-7), on the second floor (west exit). The battlefield Puppetmaster Blues has a maximum of 6 people and a time limit of 30 minutes."] = "Nashmau2階の西口(G-7)からカダーバの浮沼へ。原文のBFは最大6人、30分制限で、BF入口への移動説明は省略。",
    ["After the cutscene you face an automaton named Valkeng. Upon defeating Valkeng, a cutscene occurs; your choice of answer does not affect any outcome."] = "Valkengを倒す。イベントの回答は結果に影響しない。",
    ["Return to Bastok Markets and speak with Shamarhaan for a cutscene. Again, the answer to the question does not matter. He tells you to come to the port in Nashmau."] = "バストゥーク商業区のShamarhaanへ戻る。回答は不問で、ナシュモ港へ行くよう頼まれる。",
    ["As soon as you enter Nashmau, a cutscene should start. If it does not, trigger it by talking to Sajhra at (H-9), in the docks. Travel back to Aht Urhgan Whitegate to speak with Iruki-Waraki once again for a cutscene if the quest asks for it."] = "ナシュモ入場でイベント。発生しなければ港(H-9)のSajhraに話す。進行に応じ白門のIruki-Warakiにも報告。",
    ["Return to Iruki-Waraki in Aht Urhgan Whitegate and speak with him for one last cutscene and to receive your reward, the Puppetry Taj."] = "Iruki-Warakiに最後の報告をしてパペトリタージ。",
    ["Speak with Mishhar in Aht Urhgan Whitegate (H-8), near Home Point #1. This requires waiting until after Japanese midnight following Give Peace a Chance."] = "始まりの夜完了後、日本時間午前0時をまたいで白門(H-8)、Home Point #1近くのMishharに話す。",
    ["Go to the Shararat Teahouse (J-12) for another cutscene."] = "(J-12)の茶屋でイベント。",
    ["Return to Mishhar (H-8)."] = "Mishhar(H-8)に話す。",
    ["Enter Mamook from (D-12) in Wajaom Woodlands and click on a nearby ???, which is right next to the Survival Guide. Using the Mamook Survival Guide puts you at the correct entrance."] = "ワジャーム樹林(D-12)からマムークへ入り、Survival Guide脇の???を調べる。Guide転送も利用可。",
    ["Head to Jade Sepulcher and click the battlefield entrance (Ornamental Door) for a cutscene. The Home Point #1 warp from Aht Urhgan Whitegate to Bhaflau Thickets makes this fast."] = "翡翠廟のOrnamental Doorを調べる。バフラウ段丘のHome Point #1が便利。",
    ["Click again to enter the battlefield Moment of Truth. Protect Blacktattoo Vedool Ja (BLM), Shadowhand Kajeel Ja (NIN) and Whitetattoo Rahool Ja (WHM), who must not die."] = "再調査してBF「再会の暁」へ。Blacktattoo Vedool Ja（黒）、Shadowhand Kajeel Ja（忍）、Whitetattoo Rahool Ja（白）を死なせない。原文は終了報告を省略。",
    ["Speak with Kubhe Ijyuhla in Serpentking Square, Aht Urhgan Whitegate (I-8), to begin the quest. This quest requires the Treasures of Aht Urhgan pack and follows Got It All. The rest of the quest involves running around Aht Urhgan Whitegate and watching cutscenes."] = "恋のレシピ後、白門(I-8)蛇王広場のKubhe Ijyuhlaから受領。アトルガン導入が必要。",
    ["Head to the (G/H-10) boundary and exit into Wajaom Woodlands through the Ironbound Gate. As you zone, you watch a cutscene."] = "(G/H-10)境界のIronbound Gateからワジャーム樹林へ出るとイベント。",
    ["Head back to Kubhe Ijyuhla, who started the quest, for another cutscene."] = "Kubhe Ijyuhlaに戻る。",
    ["Speak with Ratihb inside the Shararat Teahouse (J-12). If the cutscene does not involve Foudeel and Wahboud, speak to him again for the correct cutscene."] = "(J-12)茶屋のRatihbに話す。Foudeel／Wahboudの話でなければ再会話。",
    ["Next, speak with Tehf Kimasnahya at (F-8) on Balrahn Way, who explains the whole thing."] = "(F-8)バルラーン大通りのTehf Kimasnahyaに話す。",
    ["Finally, return to Kubhe Ijyuhla to complete the quest. She rewards you with an Imperial Bronze Piece."] = "Kubhe Ijyuhlaに報告しアトルガン青銅貨。",
    ["Speak with Waoud in Aht Urhgan Whitegate (J-10) to flag the quest. You need to be a Blue Mage of level 66 or higher and have the Treasures of Aht Urhgan pack. Remember to set the Records of Eminence objective Level Cap Increase: 75 (BLU) under Objective, Tutorial, Level Cap Increase. Waoud may offer an optional 1,000-gil divination afterwards, which is not required."] = "青魔道士66以上、アトルガン導入で白門(J-10)のWaoudから受領。エミネンス「チュートリアル→限界突破→75（BLU）」も設定。追加の1,000ギル占いは不要。",
    ["Obtain a Blue Mage's Testimony from Mamool Ja Mimicker enemies."] = "Mamool Ja Mimickerから偉大な青魔道士の証を得る。",
    ["Trade the testimony to the Imperial Whitegate (L-8) and you are teleported to Jade Sepulcher."] = "Imperial Whitegate(L-8)に証を渡し翡翠廟へ転送。",
    ["Trade the same testimony to the Ornamental Door to initiate a battle against Raubahn. If you have the key item Rhapsody in Umber, you can summon Trust Magic to aid you. If the attempt fails, return to the Imperial Whitegate with a usable testimony and trade it again."] = "Ornamental Doorに同じ証を渡しRaubahn戦。Rhapsody in Umber所持ならフェイス可。失敗時は使用可能な証を宮門へ再び渡す。",
    ["Defeat Raubahn to complete the quest and raise your level cap to 75. You receive the title Master of Ambition. This quest does not need to be completed for the level limit increase if you have already completed New Worlds Await."] = "Raubahnを倒して上限75、称号Master of Ambition。New Worlds Awaitで上限突破済みなら限界開放のために当依頼を終える必要はない。",
    ["Speak with Fari-Wari at the Shararat Teahouse in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest. General Rughadjeen must be present in Al Zahbi, or you will not get the cutscenes in Aht Urhgan Whitegate."] = "白門(K-12)茶屋のFari-Wariから受領。Rughadjeenがアルザビに不在だとイベントが進まない。",
    ["Go to Wajaom Woodlands (C-8) to enter Halvung. Go to (H-11) and examine the ??? to acquire a Lilac ribbon. The fastest way is the Wajaom Woodlands Survival Guide."] = "ワジャーム樹林(C-8)からハルブーンへ入り、(H-11)の???からライラック ribbonを得る。樹林のSurvival Guideが便利。",
    ["Speak with Fari-Wari."] = "Fari-Wariに話す。",
    ["Wait a game day and speak with Fari-Wari to complete the quest and receive 1,000 Imperial Standing and an Imperial Gold Piece."] = "ヴァナ1日後Fari-Wariに話して皇国軍戦績1,000とアトルガン黄金貨。",
    ["Speak with Fari-Wari in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest. You need to have completed When the Bow Breaks and Fist of the People, or complete them during this quest."] = "白門(K-12)のFari-Wariから受領。風纏う弓と土噛みし拳は完了済み、または当依頼中に完了する。",
    ["With the key item Biyaada's letter, go to Al Zahbi and speak with Gaweesh (G-8) and Talhaal (H-6)."] = "Biyaada's letterを持ちアルザビのGaweesh(G-8)とTalhaal(H-6)に話す。",
    ["Complete the quests When the Bow Breaks and Fist of the People."] = "風纏う弓と土噛みし拳を完了する。",
    ["Speak with Fari-Wari to complete the quest and receive an Imperial Gold Piece."] = "Fari-Wariに報告しアトルガン黄金貨。",
    ["You need to have completed Aht Urhgan Mission 11, and Mihli Aliapoh must be present in Al Zahbi. Go to (G-9) in Aht Urhgan Whitegate and talk to Eunheem."] = "アトルガン11完了とMihli Aliapohのアルザビ在留が必要。白門(G-9)のEunheemに話す。",
    ["Talk to Nadeey at (K-7) inside the Walahra Temple. You may get a cutscene upon entry for The Rider Cometh."] = "(K-7)ワラーラ寺院のNadeeyに話す。入場時The Rider Comethの別イベントが起こる場合あり。",
    ["Talk to Mihli Aliapoh in Al Zahbi (H-7), who tells you to obtain a Colorful Hair."] = "アルザビ(H-7)のMihli Aliapohから色とりどりの髪を頼まれる。",
    ["Kill Aydeewa Diremite enemies until you get a Colorful Hair. You can find them around (I-9) after you take the (I-7) entrance from Bhaflau Thickets and slide down at (H-8). Circle back up to farm the item, then slide back down. The Voidwatch warp, if you have it, is a quick shortcut."] = "バフラウ段丘(I-7)からエジワ蘿洞へ入り、(H-8)の坂を下りて(I-9)付近のAydeewa Diremiteから色とりどりの髪を得る。VW転送も利用可。",
    ["Use the (I-7) Bhaflau Thickets entrance to Aydeewa Subterrane (not the Survival Guide entrance) and find the ??? at (H-8) after sliding down the ramp. Trade the Colorful Hair for a cutscene."] = "同じバフラウ段丘(I-7)入口から入り、坂下(H-8)の???へ色とりどりの髪を渡す。Survival Guide側の入口ではない。",
    ["Return to Fari-Wari to complete the quest and receive 1,000 Imperial Standing and an Imperial Gold Piece."] = "Fari-Wariに報告し皇国軍戦績1,000とアトルガン黄金貨。",
    ["Talk to Fari-Wari at the Shararat Teahouse in Aht Urhgan Whitegate (K-12) for a cutscene that begins the quest. This quest requires the Treasures of Aht Urhgan pack, and Gadalar must be present in Al Zahbi."] = "Gadalarがアルザビ在留中、白門(K-12)茶屋のFari-Wariから受領。アトルガン導入が必要。",
    ["Head to Mount Zhayolm and click on the Sprightly Footsteps at (L-7) between 18:00 and 06:00. The Voidwatch teleport takes you to the exact location; casting Escape from inside Halvung puts you at (L-7), just north of the location."] = "18:00〜06:00、ゼオルム火山(L-7)のSprightly Footstepsを調べる。VW転送かハルブーン内からのエスケプが便利。",
    ["Click on the Withered Petals at (L-6), in the southeast portion near the coastal cliffs, between 18:00 and 06:00."] = "18:00〜06:00、南東海岸崖付近(L-6)のWithered Petalsを調べる。",
    ["Trade a Hydrangea to Fari-Wari."] = "Fari-Wariにハイドランジアを渡す。",
    ["Return to Fari-Wari for a cutscene and an Imperial Gold Piece. Speak to Fari-Wari after this to learn Trust: Gadalar."] = "Fari-Wariに話しアトルガン黄金貨。さらに会話でフェイス：Gadalarを習得。",
    ["Speak to Fari-Wari after the day changes to receive a Mercenary Camp Entry Slip."] = "日付変更後Fari-WariからMercenary Camp Entry Slip。",
    ["Speak with Ahaadah in Aht Urhgan Whitegate (G-6), in Philosopher's Alley near the Alchemists' Guild, to begin the quest. Alcander and Ahaadah want you to help Tinga-Matonga become a respectable citizen."] = "白門(G-6)、錬金術ギルド近くのAhaadahからTinga-Matongaの更生を頼まれる。",
    ["Walk beneath the roofed stall at (I-11) to trigger a cutscene."] = "(I-11)の屋根付き露店の下へ進みイベント。",
    ["Continue to the end of the upper walkway at (I-12) to trigger another cutscene."] = "上段通路の先(I-12)へ進みイベント。",
    ["Travel to Bhaflau Thickets through the northern exit from Aht Urhgan Whitegate at (H-7)."] = "白門北口(H-7)からバフラウ段丘へ。",
    ["Check the ??? among the grass at (I-8) for a cutscene. Plague Chigoe appears when the cutscene ends."] = "(I-8)草むらの???を調べ、イベント後Plague Chigoe出現。",
    ["Defeat Plague Chigoe, which has a 75% Triple Attack rate."] = "Plague Chigoeを倒す。原文ではトリプルアタック率75%。",
    ["Check the ??? again after defeating Plague Chigoe to complete the quest and receive the Map of Caedarva Mire."] = "???を再調査しMap of カダーバの浮沼を得て完了。",
    ["Speak with Fochacha in Aht Urhgan Whitegate (I-9), in Serpentking Square, for a cutscene that starts the quest. Her cooking supplies have been stolen and her son has gone to retrieve them. This quest requires the Treasures of Aht Urhgan pack."] = "白門(I-9)蛇王広場のFochachaから、盗まれた食材の話を聞く。アトルガン導入が必要。",
    ["Go to the Shararat Teahouse (K-12), on the upper level, and talk to either Ulamaal or Qutiba for another cutscene."] = "上段(K-12)茶屋のUlamaalかQutibaに話す。",
    ["Return to Fochacha for a cutscene that completes the quest and gives you 3 Imperial Bronze Pieces."] = "Fochachaに報告しImperial Bronze Piece3枚。",
    ["You must zone after completing Delivering the Goods before Ulamaal gives you this quest. Speak with Ulamaal in Aht Urhgan Whitegate (K-12) to begin the quest. This quest requires the Treasures of Aht Urhgan pack. The leader of the Epicureans has been missing since saying he was going to the port."] = "グルメな人々後エリアチェンジ。白門(K-12)のUlamaalから、港へ行ったまま戻らない団長の捜索を受ける。アトルガン導入が必要。",
    ["Speak with Fochacha at (I-9)."] = "Fochacha(I-9)に話す。",
    ["Head to the Alchemy Guild at (G-5) for a cutscene."] = "(G-5)錬金術ギルドへ進みイベント。",
    ["Begin harvesting in Wajaom Woodlands with a Sickle (you may need several) to obtain the Rainbow berry."] = "ワジャーム樹林で草刈鎌を使い虹苺を得る。鎌は予備も用意。",
    ["Speak with Ulamaal for your reward, an Imperial Silver Piece."] = "Ulamaalに報告しアトルガン白銀貨。原文は実を渡す工程を省略。",
    ["Speak with Wazyih in Aht Urhgan Whitegate (F-11) to begin the quest. This quest requires the Treasures of Aht Urhgan pack. His failure to deliver a package has caused a rift between him and Saliyahf, and the self-proclaimed Defenders of Aht Urhgan need your help."] = "白門(F-11)のWazyihから受領。荷物紛失でSaliyahfと仲違いしている。アトルガン導入が必要。",
    ["Talk to Saliyahf at (G-7)."] = "Saliyahf(G-7)に話す。",
    ["Return to Wazyih."] = "Wazyihに戻る。",
    ["Walk towards the crates at (F-9)."] = "(F-9)の木箱付近へ進む。",
    ["Return to Saliyahf."] = "Saliyahfに戻る。",
    ["Speak with Wazyih again."] = "Wazyihに再び話す。",
    ["You must now find a targetable location in Al Zahbi to find Munahda's package."] = "アルザビで名前のない対象を探しMunahda's packageを得る。",
    ["Zone back into Aht Urhgan Whitegate from Al Zahbi for a cutscene."] = "アルザビから白門へ入りイベント。",
    ["Return to Wazyih at (F-11) in Aht Urhgan Whitegate."] = "白門(F-11)のWazyihに戻る。",
    ["Finally, speak with Saliyahf at (G-7) for your reward, 3 Imperial Bronze Pieces, and to finish the quest."] = "Saliyahf(G-7)に話してImperial Bronze Piece3枚、完了。",
    ["Speak with Mhasbaf in Aht Urhgan Whitegate (J-8) to begin the quest. This quest requires the Treasures of Aht Urhgan pack. Galiwao and his colleagues need help locating their employer."] = "白門(J-8)のMhasbafから主人捜索を受ける。アトルガン導入が必要。",
    ["Walk downstairs to the pillar at (J-8) for a cutscene."] = "(J-8)の下段の柱付近へ進む。",
    ["Speak with Tohka Telposkha at (I-8) for a cutscene. You must tell the Galka to go to Port Ephramad; if you choose any other option, you must select again until you pick Port Ephramad."] = "Tohka Telposkha(I-8)に話しPort Ephramadを指定。他の回答では選び直す。",
    ["Talk to Rubahah at (F-9) and repeat this process, and then do the same with Cacaroon at (G-11)."] = "Rubahah(F-9)、Cacaroon(G-11)にも同様に話す。",
    ["Walk to (I-11), down the ramp beside the ferry, for a cutscene to obtain the key item Letter from Bernahn."] = "機船脇の坂下(I-11)へ進みLetter from Bernahnを得る。",
    ["Speak with Tataroon in Nashmau (G-8) to complete the quest and receive an Imperial Silver Piece."] = "ナシュモ(G-8)のTataroonに話しアトルガン白銀貨。",
    ["Talk to Maudaal in Aht Urhgan Whitegate (E-9) to start the quest. You receive a lengthy cutscene. You have been hired by Professor Clavauert B Chanoix to accompany him and his guinea toad, Salwa-Molwa, to Mamook to research the elusive Poroggo."] = "白門(E-9)のMaudaalから、男爵とSalwa-Molwaのマムーク調査護衛を受ける。",
    ["You are directed to head to the secret entrance to Wajaom Woodlands, at (G-10)/(H-10) of Aht Urhgan Whitegate. Upon zoning, you receive another cutscene."] = "白門(G-10)/(H-10)の通用口からワジャーム樹林へ出る。",
    ["Reach Mamook by entering the cave at (D-12) on the Wajaom Woodlands map, or by using the Mamook Survival Guide warp."] = "ワジャーム樹林(D-12)からマムークへ。Survival Guideも利用可。",
    ["Once inside, find a Toad's Footprint at (J-7) and click it for another cutscene."] = "(J-7)のToad's Footprintを調べる。",
    ["Enter the hallway in the southern part of (G-7)/(H-7) that contains the Toad's Footprints and click one for another cutscene. Check them a second time for a fight."] = "(G-7)/(H-7)南側通路のToad's Footprintsを調べ、再調査で戦闘。",
    ["A Poroggo Casanova spawns, assisted by Mikiruru, Mikiluru, Mikirulu, Nikilulu and Mikilulu. They cannot be put to sleep, even with Elemental Seal."] = "Poroggo CasanovaとMikiruru／Mikiluru／Mikirulu／Nikilulu／Mikiluluが出現、と原文に記載。印スリプルでも寝ない。",
    ["Killing the Casanova makes all the other frogs disappear and ends the battle. Mikilulu cannot be killed but can be brought down to 1% HP. You only have to fight it once for it to count for the rest of your party if they are at that stage of the quest."] = "Casanovaを倒せば他の蛙も消え終了。Mikiluluは1%まで削れるが倒せない。同行者が同段階なら戦闘は1回でよい。",
    ["Return to Aht Urhgan Whitegate and talk to Maudaal again for the final cutscene and your reward, the Chanoix's Gorget."] = "白門のMaudaalに報告しシャノアゴルジェ。",
    ["Complete 25 points worth of Assaults as a Private Second Class. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. President Naja wants you to bring her an Imp Wing."] = "二等傭兵でアサルト勤務評価25ポイントを得る。アトルガン導入と原文名声1が必要。Najaにインプの翼を頼まれる。",
    ["Trade an Imp Wing to Naja Salaheem in Aht Urhgan Whitegate (I-10) to complete the quest and receive the key item PFC Wildcat badge, which gives access to PFC Assaults."] = "白門(I-10)のNaja Salaheemにインプの翼を渡すと山猫一等傭兵バッジ、一等傭兵アサルト解禁。",
    ["You can skip this quest by purchasing the key item PFC Wildcat badge from a Curio Vendor Moogle once you meet the 25 Mercenary Rank points requirement and have the key item Rhapsody in Azure from Rhapsodies of Vana'diel."] = "原文では勤務評価25とRhapsody in Azure所持ならCurio Vendor Moogleからバッジ購入で省略可能。必要な煌めきはWiki記載と異なる。",
    ["Complete 25 points worth of Assaults as a Private First Class. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. Your task is to find hard evidence that the Dark Rider has truly appeared out of legend and is terrorizing the Empire."] = "一等傭兵で勤務評価25。アトルガン導入と原文名声1が必要。冥路の騎士の実在する証拠を探す。",
    ["Return to Naja Salaheem in Aht Urhgan Whitegate (I-10) to complete the quest and receive the SP Wildcat badge, which gives access to SP Assaults."] = "白門(I-10)のNajaに報告し山猫上等傭兵バッジ、上等傭兵アサルト解禁。原文は足跡調査の工程を省略。",
    ["Complete 25 points worth of Assaults as a Superior Private (5 points for a previously unbeaten Assault, 1 point for one already beaten). You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. Falzum, your fellow mercenary, has been given the task of creating a batch of mythralline liquid, and as his superior it is your job to teach him how a mercenary carries out his duty. Speak with Abquhbah in Aht Urhgan Whitegate (I-10) for a cutscene that starts the quest."] = "上等傭兵で勤務評価25（初クリア5、既クリア1）。アトルガン導入と原文名声1が必要。白門(I-10)のAbquhbahからFalzumの霊晶水調整の補助を受ける。",
    ["After accepting the quest, talk to Nafiwaa at the Alchemist's Guild in Aht Urhgan Whitegate (G-5). She gives you 5 empty test tube key items."] = "白門(G-5)錬金術ギルドのNafiwaaから空の試験管5本を得る。",
    ["Fill each test tube at its Mythralline Wellspring (the ??? at each pond), in any order. Enter Wajaom Woodlands through the Ironbound Gate at (H-10) and Bhaflau Thickets through the Ironbound Gate at (H-7)."] = "池のMythralline Wellspringで各管に採水、順不同。ワジャーム樹林へは(H-10)、バフラウ段丘へは(H-7)のIronbound Gate。",
    ["Test tube #1 goes to Wajaom Woodlands (H-11), #2 to Wajaom Woodlands (G-11), #3 to Wajaom Woodlands (I-7), #4 to Wajaom Woodlands (J-8) and #5 to Bhaflau Thickets (G-7), on map 1."] = "管1はワジャーム樹林(H-11)、2は(G-11)、3は(I-7)、4は(J-8)、5はバフラウ段丘マップ1(G-7)。",
    ["Return to Nafiwaa for a cutscene and begin the mixing process. All five tubes must be filled first, and the quality of the mixture decides your Imperial currency reward. The best quality is Luminium: choose Test Tube #3 three times, Test Tube #2 once, Test Tube #4 once and Test Tube #5 once."] = "5本そろえNafiwaaの調合へ。原文の最高品質Luminium配合は管3を3回、管2・4・5を各1回。品質で報酬貨幣が変わる。",
    ["Wait a game day and zone at least once, then return to Abquhbah for a cutscene. Choose \"Helping his fellow mercenaries\" to complete the quest. You receive the LC Wildcat badge, access to LC Assaults, and a varying amount of Imperial currency, up to 2 Imperial Gold Pieces."] = "ヴァナ1日待ち1回以上エリアチェンジしAbquhbahへ。「Helping his fellow mercenaries」で山猫傭兵長バッジ、傭兵長アサルト解禁。追加報酬は品質で最大黄金貨2枚。",
    ["Complete 25 points worth of Assaults as a Lance Corporal. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. To track the movements of the Dark Rider, you are given a quartz transmitter to place in his warhorse's hoofprint."] = "傭兵長で勤務評価25。アトルガン導入と原文名声1が必要。冥路の騎士の蹄跡へ発信機を設置する。",
    ["Talk to Naja Salaheem in Aht Urhgan Whitegate (I-10) to receive the Quartz transmitter."] = "白門(I-10)のNajaからQuartz transmitterを得る。",
    ["Find the Warhorse Hoofprint and click on it to place the Quartz transmitter. The Warhorse Hoofprint is visible on Widescan and is found in four different zones: Bhaflau Thickets, Caedarva Mire, Mount Zhayolm and Wajaom Woodlands."] = "バフラウ段丘／カダーバの浮沼／ゼオルム火山／ワジャーム樹林のWarhorse Hoofprintを調べ設置。広域スキャンで確認可。",
    ["Return to Naja Salaheem to complete the quest and receive the C Wildcat badge, which gives access to C Assaults."] = "Najaに報告し山猫伍長バッジ、伍長アサルト解禁。",
    ["Complete 25 points worth of Assaults as a Corporal. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. The perfumier Liliroon has come to Salaheem's Sentinels in search of help, believing it to be a famous detective agency, and President Naja wants you to help collect her reward."] = "伍長で勤務評価25。アトルガン導入と原文名声1が必要。探偵社と勘違いした調香師Liliroonの依頼を手伝う。",
    ["Talk to Naja Salaheem in Aht Urhgan Whitegate (I-10). When presented an option, choose \"Balrahn Way\"."] = "白門(I-10)のNajaに話し「Balrahn Way」を選ぶ。",
    ["Go to Balrahn Way for another cutscene. When presented an option, choose \"Where have you been\"."] = "バルラーン大通りのイベントで「Where have you been」を選ぶ。",
    ["Obtain a Sutlac and head off to Nashmau."] = "シュトラッチを用意しナシュモへ。",
    ["At (H-9) in Nashmau, another cutscene takes place. Choose \"No, let's keep trying!\". If you choose the wrong answer during the cutscene, you need to wait for a new game day before repeating it."] = "ナシュモ(H-9)のイベントで「No, let's keep trying!」。誤答時は翌ヴァナ日まで待つ。",
    ["Trade a Sutlac to Totoroon."] = "Totoroonにシュトラッチを渡す。",
    ["Exit east to Caedarva Mire and go to (I-10). Check the ??? on the east side of the pond for a cutscene."] = "東口からカダーバの浮沼(I-10)へ進み、池東側の???を調べる。",
    ["Return to Naja Salaheem to complete the quest and receive the S Wildcat badge, which gives access to S Assaults."] = "Najaに報告し山猫軍曹バッジ、軍曹アサルト解禁。",
    ["Complete 25 points worth of Assaults as a Sergeant. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. You must fulfill your duty as a sergeant by training your subordinates into proper mercenaries. Head to Salaheem's Sentinels in Aht Urhgan Whitegate (I-10) for a cutscene with Naja Salaheem."] = "軍曹で勤務評価25。アトルガン導入と原文名声1が必要。白門(I-10)でNajaのイベントを見て部下の訓練へ。",
    ["Naja requires you to successfully complete three mini-games. If you fail any portion, wait one real-life minute and speak to Naja again. After each one you may need to wait a game day to find out whether you passed; if you failed, you repeat that mini-game."] = "3つの試験に合格する。失敗時は地球時間1分待ちNajaに再会話。各試験の結果判定は翌ヴァナ日を待つ場合あり。",
    ["Trial 1, push-ups: count three NPCs doing push-ups and determine who did the least; it is either one of the three, or none. A reliable way is to use a piece of paper and make a mark in three different sections each time an NPC does a push-up."] = "腕立て：3人の回数を数え最も少ない者を選ぶ。「該当なし」もある。紙を3区画に分け回数を記録するとよい。",
    ["Trial 2, sit-ups: you must give a message advancement prompt with proper timing as the three NPCs do sit-ups. The Windower addon Enternity must be unloaded for this trial, as it repeatedly queues the advancement prompt. You can practice indefinitely with Abquhbah. In the real challenge, three NPCs have slightly different timings."] = "腹筋：3人の動作に合わせ文章送りを入力。自動送りのWindowerアドオンEnternityは外すよう原文に記載。Abquhbahで無制限に練習可能。本番は3人の周期が少し異なる。",
    ["Trial 3, running: you must give prompts to the three NPCs so that they finish running at the same time. If you select an NPC who is not behind, you are penalized and can fail the trial."] = "走り込み：3人を同時にゴールさせる。遅れていない者を叱ると減点され失敗し得る。",
    ["After the final trial is complete, speak to Naja Salaheem to finish the quest and receive the SM Wildcat badge, which gives access to SM Assaults."] = "全試験後Najaに話し山猫曹長バッジ、曹長アサルト解禁。",
    ["Complete 25 points worth of Assaults as a Sergeant Major (5 points for a previously unbeaten Assault, 1 point for one already beaten). You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. Abquhbah asks you to visit the weapon shop in his stead; his heavy sighs have you slightly worried."] = "曹長で勤務評価25（初回5、既クリア1）。アトルガン導入と原文名声1が必要。Abquhbahの代わりに武器屋へ行く。",
    ["Head to Salaheem's Sentinels in Aht Urhgan Whitegate (I-10) for a cutscene with Abquhbah, who redirects you to Hagakoff at (K-10)."] = "白門(I-10)のAbquhbahから(K-10)のHagakoffへ。",
    ["Talk to Hagakoff, then go back to Abquhbah, then Hagakoff once more. Through these cutscenes you learn that Naja Salaheem's mace is rusty and needs to be cleaned, and that the best way is with Scourshrooms, found in Aydeewa Subterrane."] = "Hagakoff→Abquhbah→Hagakoff。Najaの錆びたメイスをエジワ蘿洞のScourshroomで磨く話を聞く。",
    ["Enter Aydeewa Subterrane from Wajaom Woodlands (I-10). This is the same entrance next to the Aydeewa Subterrane Survival Guide."] = "ワジャーム樹林(I-10)からエジワ蘿洞へ。Survival Guide近くの入口。",
    ["Once inside, go to the point where (I-9) and (J-8) meet and check the mushroom patch to find a mature Scourshroom (a key item). Then check the mushroom patch at (I-9)/(J-9) to plant it. Repeat the process at (E-7)."] = "(I-9)と(J-8)の境の成熟Scourshroomを採り、(I-9)/(J-9)の菌床へ植える。(E-7)でも同様に行う。",
    ["Zone out and back in and wait for the game day to change. Return to both patches of mushrooms between 04:00 and 06:00 game time to harvest young Scourshrooms. You need at least 2 young Scourshrooms to complete the quest."] = "出入りしてヴァナ日付変更を待ち、04:00〜06:00に両菌床で若いScourshroomを採る。最低2つ必要。",
    ["After cleaning the weapon twice you may choose to complete the quest or continue cleaning. Whether you stop at two cleanings or five, the quest is complete and you receive the CS Wildcat badge, access to CS Assaults, 1 Imperial Mythril Piece and possibly 1 Imperial Gold Piece as well."] = "2回磨けば完了可能、5回まで続行も可。山猫特務曹長バッジ、特務曹長アサルト解禁と霊銀貨1枚、場合により黄金貨1枚も得る。",
    ["Complete 25 points worth of Assaults as a Chief Sergeant. You need Aht Urhgan fame level 1 and the Treasures of Aht Urhgan pack. You also need 3 Imperial Gold Pieces and 6 Imperial Mythril Pieces. You have enrolled in the Salaheem Officer Academy to earn your position in the upper ranks of Salaheem's Sentinels."] = "特務曹長で勤務評価25、アトルガン導入と原文名声1。黄金貨3枚と霊銀貨6枚を用意し士官学校へ。",
    ["Enter Naja's office in Aht Urhgan Whitegate (I-10) to start the quest."] = "白門(I-10)のNajaの事務所へ入る。",
    ["Trade 3 Imperial Gold Pieces to Abquhbah, who gives you the Officer Academy manual."] = "Abquhbahに黄金貨3枚を渡しOfficer Academy manualを得る。",
    ["Trade 2 Imperial Mythril Pieces to Abquhbah to start the first trial. Trial 1, Memory: you are shown a scene for a short period of time and then asked questions about it. Get them all right to pass. In scene 1 you are asked what kind of critters were shown to you."] = "霊銀貨2枚を渡し記憶力試験。短時間の場面を見て全問正答する。最初の場面は生物の種類を問われる。",
    ["Trade 2 Imperial Mythril Pieces to Abquhbah to start the second trial. Trial 2, Proof of competence: any unwearable Aht Urhgan beastmen weapon or armor will work."] = "霊銀貨2枚を渡し実力証明。原文では装備できないアトルガン獣人製の武器・防具なら対象。",
    ["Trade 2 Imperial Mythril Pieces to Abquhbah to start the third trial. Trial 3, Trivia."] = "霊銀貨2枚を渡し知識試験。",
    ["After all 3 trials are complete, you are awarded your promotion and the SL Wildcat badge, which gives access to SL Assaults. If you fail any trial, you need to pay the initiation fee of 2 Imperial Mythril Pieces again in order to repeat it."] = "3試験後山猫少尉バッジ、少尉アサルト解禁。失敗した試験の再挑戦は霊銀貨2枚が再度必要。",
    ["Complete 25 points worth of Assaults as a Second Lieutenant. You need Aht Urhgan fame level 1, the Treasures of Aht Urhgan pack and 5 Imperial Gold Pieces. Your final term at the Salaheem Officer Academy has begun."] = "少尉で勤務評価25。アトルガン導入、原文名声1、黄金貨5枚が必要。士官学校後期へ。",
    ["The quest is started by entering the Salaheem's Sentinels office in Aht Urhgan Whitegate (I-10). Trade Abquhbah 5 Imperial Gold Pieces."] = "白門(I-10)事務所へ入りAbquhbahに黄金貨5枚を渡す。",
    ["Talk to Abquhbah to start the first trial. The quest is split into three parts, and you must wait until the next in-game day between each part."] = "Abquhbahに話し第1試験へ。3部構成で各部の間は翌ヴァナ日まで待つ。",
    ["Part 1, Counterespionage: a three-part mini-game in which you must find the qiqirn hiding in a crowd of twelve humes. In the first group there are three qiqirn to find."] = "防諜訓練：ヒューム12人に紛れたキキルンを探す3段階の試験。最初は3人。",
    ["Part 2, Cipher: talk to Abquhbah to start it, and answer his questions."] = "暗号訓練：Abquhbahに話し質問へ回答。",
    ["Part 3, BCG Training: a rock-paper-scissors type game against the cadets. An opponent always repeats whatever his first three calls were, and they switch plans after every two or three hit points they lose. The final round is against Drill Sergeant Rongelouts: get him down to four, tie him three times in a row, then win the next round by dealing four points of damage."] = "BCG演習：じゃんけん型の戦い。原文では敵は最初の3手を繰り返し、HPを2〜3失うと変更。最後のRongeloutsは残り4にし、3連続あいこ後、4ダメージで勝つ。",
    ["Once you have beaten everyone, wait until the next in-game day and talk to Abquhbah to be promoted and receive the FL Wildcat badge, which gives access to FL Assaults."] = "全員に勝ち翌ヴァナ日以降Abquhbahに話し山猫中尉バッジ、中尉アサルト解禁。",
    ["If Suldiran is taken prisoner during Besieged, this quest is unavailable until he is rescued. This quest requires the Treasures of Aht Urhgan pack."] = "Suldiranがビシージで捕虜の場合は救出まで進行不可。アトルガン導入が必要。",
    ["Speak with Suldiran in Al Zahbi (J-10), on the upper level, to begin the quest. He asks for 2 Imp Wings."] = "アルザビ(J-10)上段のSuldiranからImp Wing2個を頼まれる。Wikiの座標は(J-9)だが原文を保持。",
    ["Trade Suldiran 2 Imp Wings to complete the quest and receive 200 gil. You can repeat the quest."] = "2個を渡し200ギル。反復可。",
    ["While the quest Ode to the Serpents is active, speak with Gaweesh in Al Zahbi (G-8). You may only get the cutscenes when General Najelith is in Al Zahbi."] = "詠うは誰そ彼の受領中、Najelithが在留中にアルザビ(G-8)のGaweeshに話す。",
    ["In Wajaom Woodlands, kill Aht Urhgan Attercop enemies (spiders) until you get a Frayed Arrow. Three Aht Urhgan Attercops are located at the Giwahb Watchtower."] = "ワジャーム樹林のAht Urhgan Attercopから薄汚れた矢を得る。ギワブ監視塔付近に3体。",
    ["Go to the Giwahb Watchtower in Wajaom Woodlands (F-5) and trade the Frayed Arrow to the door for a cutscene that completes the quest and gives you 500 Imperial Standing."] = "ワジャーム樹林(F-5)ギワブ監視塔の扉に渡し、皇国軍戦績500で完了。",
    ["While the quest Ode to the Serpents is active, speak with Talhaal in Al Zahbi (H-6). You may only get the cutscenes when General Zazarg is in Al Zahbi."] = "詠うは誰そ彼の受領中、Zazarg在留中にアルザビ(H-6)のTalhaalに話す。",
    ["Speak with Fari-Wari in Aht Urhgan Whitegate (K-12)."] = "白門(K-12)のFari-Wariに話す。",
    ["In Wajaom Woodlands, kill Wajaom Tiger enemies until you get a Rusty Medal."] = "ワジャーム樹林のWajaom Tigerから錆びたアイアン章を得る。",
    ["Go to the Leypoint in Wajaom Woodlands (G-8) and trade the Rusty Medal for a cutscene that completes the quest and gives you 500 Imperial Standing."] = "ワジャーム樹林(G-8)のLeypointに渡し皇国軍戦績500。",
    ["Return to the teahouse and speak with Fari-Wari again to learn Trust: Zazarg."] = "茶屋のFari-Wariに戻ってフェイス：Zazargを習得。",
    ["Speak with Ququroon in Nashmau (H-6) for a cutscene that starts the quest. He wants to practice cooking so he can open a restaurant one day. This quest requires the Treasures of Aht Urhgan pack."] = "ナシュモ(H-6)のQuquroonから料理修行の材料を頼まれる。アトルガン導入が必要。Wiki依頼者座標は(G-6)で原文と異なる。",
    ["Obtain the five fish he asks for: Ahtapot, Istakoz, Istavrit, Istiridye and Mercanbaligi. You can buy them at the Auction House or fish them up in the Treasures of Aht Urhgan zones."] = "アフポット／イスタコズ／イスタヴリット／イスティルディエ／メルジャンバルウを競売かアトルガンの釣りで用意。",
    ["Fishing tip: with a Lu Shang's Fishing Rod you can do this at fishing skill 32. Fishing in Nashmau with Minnow, Sinking Minnow and Crayfish Balls eventually gives 4 of the 5 fish, and the Istavrit can be fished in Talacca Cove with a Sinking Minnow. You can also catch 4 of the 5 in Talacca Cove and the Istiridye in Nashmau."] = "原文釣り例：スキル32、太公望の釣竿。ナシュモでミノー／シンキングミノー／ザリガニ団子を使い4種、タラッカ入江でシンキングミノーを使いイスタヴリット。逆に入江で4種、ナシュモでイスティルディエでも可。",
    ["Trade all five fish to Ququroon to complete the quest and receive a Nashmau Stew. There is a small chance that he fails to make the stew: the quest still counts as completed, but you do not receive the reward. You can repeat the quest."] = "5種をQuquroonに渡しナシュモ風シチュー。低確率で料理失敗し報酬なしでも完了扱い。反復可。",
    ["Speak with Tsetseroon in Nashmau (G-6) to begin the quest. There is no cutscene to start it. He needs a cobalt jellyfish and a chunk of tin ore to make his special stew. This quest requires the Treasures of Aht Urhgan pack."] = "ナシュモ(G-6)のTsetseroonに話す。開始イベントはなく、コバルトジェリーとスズ石を頼まれる。アトルガン導入が必要。",
    ["Head to Wajaom Woodlands (D-9) and zone into Aydeewa Subterrane. Reach (G-10) on map 3 for a cutscene."] = "ワジャーム樹林(D-9)からエジワ蘿洞マップ3(G-10)へ進みイベント。",
    ["Return to Tsetseroon to officially begin the quest."] = "Tsetseroonに戻って正式受領。",
    ["Trade Tsetseroon a Tin Ore and a Cobalt Jellyfish. He gives you a Pot of Tsetseroon's stew."] = "スズ石とコバルトジェリーを渡しPot of Tsetseroon's stewを得る。",
    ["Return to Aydeewa Subterrane (G-10, map 3) and check the ??? at the top of the damaged stairwell for a cutscene. Choose to look into Wawaroon's bag to receive a Map of Aydeewa Subterrane."] = "エジワ蘿洞マップ3(G-10)、壊れた階段上の???を調べ、Wawaroonの鞄をのぞくとMap of エジワ蘿洞。",
    ["Return to Tsetseroon for an Imperial Bronze Piece and to complete the quest. If you chose not to look into Wawaroon's bag, you receive the Map of Aydeewa Subterrane from Tsetseroon instead, and you do not get the Imperial Bronze Piece."] = "Tsetseroonに報告しアトルガン青銅貨。鞄をのぞかなかった場合はこちらで地図を得るが青銅貨は得られない。",
    ["Speak with Fhe Maksojha in Nashmau (H-6). Wadayra wants you to look for her son Ahgdeen, who ran away from home and was last sighted in the northern part of Caedarva Mire."] = "ナシュモ(H-6)のFhe Maksojhaから家出したAhgdeenの捜索を受ける。",
    ["Head to Caedarva Mire and click the ??? at (K-8)."] = "カダーバの浮沼(K-8)の???を調べる。",
    ["Speak with Fhe Maksojha again."] = "Fhe Maksojhaに話す。",
    ["Return to the ??? in Caedarva Mire."] = "カダーバの浮沼の???へ戻る。",
    ["Click the ??? to spawn the NMs Lamia No. 27 and Moshdahn."] = "調べてLamia No. 27とMoshdahnを出す。",
    ["Defeat the NMs, then check the ??? again."] = "討伐後???を再調査。",
    ["Return to Fhe Maksojha for your reward, 3 Imperial Gold Pieces."] = "Fhe Maksojhaに報告しImperial Gold Piece3枚。",
    ["Speak with Kakkaroon in Nashmau (H-8). He is afraid of children, and young Rapipi adores the Qiqirn and wants to make friends with the beastmen in Nashmau."] = "ナシュモ(H-8)のKakkaroonに話す。子供が苦手な本人とRapipiの仲を取り持つ。",
    ["Speak with Nadee Periyaha in Aht Urhgan Whitegate (H-9)."] = "白門(H-9)のNadee Periyahaに話す。",
    ["Speak with Cacaroon in Aht Urhgan Whitegate (G-11) and trade him one Imperial Bronze Piece."] = "白門(G-11)のCacaroonに話しImperial Bronze Piece1枚を渡す。",
    ["Now you must complete Cook-a-roon? to get a Nashmau Stew. Buying one from the Auction House will not work, and keeping one from a previous repeat of Cook-a-roon? will not work either."] = "新たにCook☆ルンを終えてナシュモ風シチューを作る。競売品や以前の反復時の作り置きは不可。",
    ["Trade the Nashmau Stew to Kyokyoroon back in Nashmau (H-7)."] = "ナシュモ(H-7)のKyokyoroonにStewを渡す。",
    ["Speak with Kakkaroon to complete the quest and receive 2 Imperial Gold Pieces, 2 Imperial Mythril Pieces and 3 Imperial Silver Pieces."] = "Kakkaroonに報告し黄金貨2・霊銀貨2・白銀貨3枚。",
    ["Examine the unnamed target on a manhole cover at (L-7) in Mount Zhayolm for a cutscene that begins the quest. This quest requires the Treasures of Aht Urhgan pack. Zurtermor has dropped his precious pickaxe into a crevasse."] = "ゼオルム火山(L-7)、マンホールの名前のない対象を調べる。Zurtermorのつるはし捜索。アトルガン導入が必要。",
    ["During this quest the Plasma rock key item is mentioned, but it is actually not obtainable."] = "話に出るPlasma rockは実際には取得不可。",
    ["Trade a Pickaxe to the same unnamed target for another cutscene."] = "同じ対象につるはしを渡す。",
    ["Head south to zone out of Mount Zhayolm, then zone back in."] = "南へ進み火山から出て入り直す。",
    ["Trade a Mythril Pick to the same unnamed target for the final cutscene and your reward: the Map of Mount Zhayolm (if you do not already own it), 2,000 experience points and 2,000 gil."] = "同じ対象にミスリルピックを渡し、未所持ならゼオルム火山地図と経験値2,000、2,000ギル。",
    ["Examine the ??? in Arrapago Reef (H-10), map 1, for a cutscene. You need to be a Corsair of level 50 or higher, and a Lamian Fang Key is required to reach this point."] = "コルセア50以上でアラパゴ暗礁域マップ1(H-10)の???を調べる。途中にラミアの牙のカギが必要。",
    ["Lamian Fang Keys drop from Lamia and Drauger enemies in the area. You can also receive one from a ??? spot in Caedarva Mire (I-7), map 1 (southern part of the block); you can obtain a new key from there once every game day."] = "カギはLamia／Drauger、またはカダーバの浮沼マップ1(I-7)南側の???からヴァナ1日1個。",
    ["You no longer have to be on Corsair for the rest of this quest. You are asked to fish up a Hydrogauge."] = "以後は他ジョブ可。測深儀を釣り上げるよう頼まれる。原文は釣り場所を省略。",
    ["Once you have fished up a Hydrogauge, trade it to Leleroon in Nashmau (G-7)."] = "ナシュモ(G-7)のLeleroonに測深儀を渡す。",
    ["Head to (G-8) in Wajaom Woodlands and trade the Hydrogauge to the Leypoint."] = "ワジャーム樹林(G-8)のLeypointに測深儀を渡す。",
    ["Return to the ??? in Arrapago Reef (H-10), map 1, for your reward, the Corsair's Culotte."] = "アラパゴ暗礁域マップ1(H-10)の???へ戻りコルセアトルーズ。",
    ["You need to be a Corsair of level 66 or higher and have a Corsair's Testimony. Obtain a Corsair's Testimony from Merrow Icedancer, Merrow Kabukidancer, Merrow Chantress or Lamia Fatedealer enemies."] = "コルセア66以上で偉大なコルセアの証を用意。Merrow Icedancer／Kabukidancer／Chantress、Lamia Fatedealerが落とす。",
    ["Go to the Rock Slab in Arrapago Reef (H-10), on map 1. You end up in the correct area to continue after the conclusion of Against All Odds."] = "アラパゴ暗礁域マップ1(H-10)のRock Slabへ。原文はやがて海霧の夜に翔ぶ終了後に正しい場所へ着くと説明。",
    ["Trade the Corsair's Testimony to the Rock Slab to enter the battlefield. This quest does not need to be completed for the level limit increase if you have already completed New Worlds Await or better."] = "Rock Slabに証を渡しBFへ。New Worlds Await以降で上限突破済みなら限界開放目的で当依頼は不要。",
    ["Completing the battle raises your level limit to 75 and gives you the title Master of Chance."] = "勝利して上限75、称号Master of Chance。",
    ["Talk to Shamarhaan in Bastok Markets (F-9). You need to be level 30 or higher and have the Treasures of Aht Urhgan pack."] = "30以上でバストゥーク商業区(F-9)のShamarhaanに話す。アトルガン導入が必要。",
    ["Head to Aht Urhgan Whitegate and talk to Iruki-Waraki (K-9, top floor)."] = "白門(K-9)上段のIruki-Warakiに話す。",
    ["Speak with Ghatsad in Aht Urhgan Whitegate (I-7), inside the Automaton Workshop."] = "白門(I-7)工房内のGhatsadに話す。",
    ["Take the northern Port Ephramad ferry to Nashmau and go through the North Gate to Caedarva Mire. Head northeast or northwest to the (I-6) zone line to Arrapago Reef."] = "北港のイフラマド航路でナシュモへ。北門からカダーバの浮沼、北東または北西へ進み(I-6)からアラパゴ暗礁域へ。原文はオートマトン回収・修理を省略。",
    ["Speak with Iruki-Waraki (K-9, top floor) in Aht Urhgan Whitegate to complete the quest and receive your Animator."] = "白門(K-9)上段のIruki-Warakiに報告しストリンガー。",
    ["Approach Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest. Imperial researchers are uneasy about curious readings from the chamber where the iron colossus sleeps."] = "白門(I-10)のNajaに近づき、機関巨人内部の異常調査を受ける。",
    ["Examine the Imperial Whitegate in Aht Urhgan Whitegate (L-8/9) to receive the key item Imperial missive. The quest now appears under Aht Urhgan: Current Quests."] = "白門(L-8/9)のImperial WhitegateからImperial missiveを得て正式受領。",
    ["Examine the Imperial Whitegate in Aht Urhgan Whitegate (L-8/9) to receive the key item Present for Megomak."] = "白門(L-8/9)のImperial WhitegateからPresent for Megomakを得る。原文は国々の協力・修復・BFへの中間工程を省略。",
    ["In the battle you face Alexander, who can spawn up to three Alexander Images. At low HP, Alexander uses Divine Judgment, dealing high damage to everyone in range."] = "Alexanderは分身を最大3体出し、HP低下で広範囲高威力のDivine Judgmentを使う。",
    ["Upon defeating the battlefield you receive the Whisper of radiance. Examine the Imperial Whitegate in Aht Urhgan Whitegate (L-8/9) for a cutscene."] = "勝利後Whisper of radianceを得て、白門(L-8/9)のImperial Whitegateを調べる。",
    ["Speak with Naja Salaheem to choose your reward: an Imperial Gold Piece and one of Pact with Alexander, Colossus's Torque, Colossus's Mantle, Colossus's Earring or 10,000 gil."] = "Najaに報告し黄金貨1枚と、Alexander召喚契約／コロッサストルク／Mantle／Earring／10,000ギルから1つを選ぶ。",
    ["Approach Naja Salaheem in Aht Urhgan Whitegate (I-10) for a cutscene that begins the quest. If you are repeating this quest, skip this step and go straight to the Imperial Whitegate in the next step. This quest follows Waking the Colossus."] = "アトルガンの守護者後、白門(I-10)のNajaに近づく。反復時は省略して宮門へ。",
    ["Examine the Imperial Whitegate in Aht Urhgan Whitegate (L-8/9)."] = "白門(L-8/9)のImperial Whitegateを調べる。原文は修復とBF戦の工程を省略。",
    ["Speak with Naja Salaheem to choose your reward. You can repeat the quest."] = "Najaに報告して報酬を選ぶ。反復可。",
