    -- Outlands quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Hari Pakhroib in Kazham (I-11), who wants Wild Pamamas. You need Kazham fame level 7 and the Rise of the Zilart pack."] = "カザム(I-11)のHari Pakhroibに話しワイルドパママの供物を頼まれる。原文条件はカザム名声7とジラート導入。",
    ["Obtain a Wild Pamamas, which drops from Young Opo-opo enemies in Yuhtunga Jungle and can sometimes be found at the Auction House. On later repeats a Wild Melon also works. Despite what the NPC says, you do not need to bring Ice Clusters, as there are no Flame Spouts on the path."] = "ユタンガ大森林のYoung Opo-opoからワイルドパママを得るか競売で探す。再依頼ではワイルドメロンも対象。原文ルートには炎の壁がないため氷の塊は不要。",
    ["Head to Ifrit's Cauldron using the entrance from (G-6) in Yhoator Jungle. The Survival Guide can also bring you there."] = "ヨアトル大森林(G-6)入口からイフリートの釜へ。Survival Guideも利用可。Wiki掲載入口とは異なる原文経路。",
    ["Once inside Ifrit's Cauldron, take the left path at the fork and continue until you find the Altar of Ashes at (I-9) on map 2, a black pillar near the edge of the path. Alternatively, use the Unity 125 teleport to map 3 and take exit G, then A, then B to reach (I-9) of map 2."] = "釜内の分岐を左へ進みマップ2(I-9)の黒い柱Altar of Ashesへ。別案はユニティ125転送でマップ3へ入り、出口G→A→Bからマップ2(I-9)。",
    ["Trade the Wild Pamamas to the Altar. The NPC mentions needing to shout your name, but that is not necessary."] = "祭壇にワイルドパママを渡す。名前を叫ぶ必要はない。",
    ["Return to Hari Pakhroib for your reward, 5,000 gil. You can repeat the quest."] = "Hari Pakhroibに報告し5,000ギル。反復可。",
    ["Talk to Etteh Sulaej in Kazham (J-9). You need Kazham fame level 6 and the Rise of the Zilart pack, and this quest follows A Pose by Any Other Name. You receive the key item Letter to Angelica."] = "カザム(J-9)のEtteh Sulaejからアンジェリカあての手紙。原文条件はカザム名声6、ジラート導入、A Pose by Any Other Name後。",
    ["Take the letter to Windurst Waters and talk to Angelica at the Rarab Tail Hostelry. You receive the key items Angelica's letter and the painting \"Final Fantasy\", which she wants you to hang in the Temple of Uggalepih."] = "ウィンダス水の区のララブのしっぽ亭でAngelicaに渡し、アンジェリカからの手紙と絵「最後の幻想」を預かる。",
    ["Go back to Kazham and talk to Etteh Sulaej."] = "カザムのEtteh Sulaejに戻る。",
    ["Go to (G-8) on the first map of the Temple of Uggalepih and hang the picture at the Stone Picture Frame, on the south wall of the Paintbrush Room, to spawn the Golem NM Trompe L'Oeil. The Temple of Uggalepih Survival Guide warp puts you a short distance from the Stone Frame."] = "ウガレピ寺院マップ1(G-8)、絵筆の部屋南壁のStone Picture Frameに絵を掛けTrompe L'Oeilを出す。寺院Survival Guideから近い。原文は討伐後の絵の回収を省略。",
    ["Return to Etteh Sulaej to receive your reward, 3,000 gil. You can repeat the quest."] = "Etteh Sulaejに報告し3,000ギル。反復可。",
    ["To begin this quest you must have traded an Unlit Lantern to the Altar of Rancor and received a Rancor Flame at some point before; it helps to have a Rancor Flame on you. This quest follows A Question of Taste and requires the Rise of the Zilart pack."] = "事前に消えたランタンをAltar of Rancorへ渡し怨みの炎を得たことが必要。所持しておくとよい。画廊の迷宮後、ジラート導入。",
    ["Once you have used a Rancor Flame, talk to Jakoh Wahcondalo in Kazham (J-9), who tells you to leave her village. The other NPCs in the room tell you to go to the Den of Rancor and Temple of Uggalepih complex to be cleansed and then come back. You get the title Excommunicate of Kazham as soon as the quest becomes active."] = "怨みの炎使用後、カザム(J-9)のJakoh Wahcondaloに話すと追放を告げられる。室内の者から怨念洞・ウガレピ寺院での浄化を聞く。受領時にカザム追放者の称号。",
    ["Once in the temple, head to (I-10) and defeat the Temple Guardian to open the door."] = "寺院(I-10)でTemple Guardianを倒し扉を開く。",
    ["Past the guardian's door, head north to (I-7) inside the paintings room."] = "扉の先を北へ進み絵画の部屋(I-7)へ。原文は怨念洞でランタン4つに点火する中間工程を省略。",
    ["Kill the Rancor Torch, then head back to Kazham and talk to the Chieftainess for your reward, 11,000 gil."] = "Rancor Torchを倒し、カザムの族長に報告して11,000ギル。",
    ["Trade Mhebi Juhbily in Kazham (I-10) a Sandfish. You need Kazham fame level 6 and the Rise of the Zilart pack. When asked, tell her you give it to her. Then check the shed behind her for a cutscene."] = "カザム(I-10)のMhebi Juhbilyにサンドフィッシュを渡し、贈り物だと答えて背後のShedを調べる。原文条件は名声6とジラート導入。",
    ["Speak with Vah Keshura at (H-9)."] = "(H-9)のVah Keshuraに話す。",
    ["Obtain a Tonberry Board. It drops from Tonberry Pursuer enemies in the Temple of Uggalepih, Tonberry Shadower enemies in Yhoator Jungle and Tonberry Trailer enemies in the Den of Rancor."] = "ウガレピ寺院のTonberry Pursuer、ヨアトル大森林のTonberry Shadower、怨念洞のTonberry Trailerからトンベリのまな板を得る。",
    ["Use a Unity Concord NPC warp to the Temple of Uggalepih (level 125), or walk in. Part of the route leads you back outside to Yhoator Jungle; head left and re-enter the Temple at (H-11)."] = "ユニティ125転送か徒歩でウガレピ寺院へ。一度ヨアトル大森林へ出たら左へ進み(H-11)から再入場。",
    ["Back inside, head west, then south until you reach (H-10). There you receive the key item Nonberry's knife."] = "西へ進み南の(H-10)へ行きノンベリ包丁を得る。原文はChef Nonberryへの素材トレードを省略。",
    ["Return to Mhebi Juhbily for your reward, 7,200 gil."] = "Mhebi Juhbilyに報告し7,200ギル。",
    ["Speak with Rauteinot in Kazham (G-9), who asks for a slab of Elshimo Marble. You need Kazham fame level 3 and the Rise of the Zilart pack."] = "カザム(G-9)のRauteinotからエルシモの名石を頼まれる。原文条件はカザム名声3とジラート導入。",
    ["Obtain an Elshimo Marble, which drops from Ivory Lizard enemies in Yuhtunga Jungle."] = "ユタンガ大森林のIvory Lizardからエルシモの名石を得る。",
    ["Trade the Elshimo Marble to Rauteinot. You receive Rauteinot's parcel."] = "Rauteinotに渡しロテノーの小包を預かる。",
    ["Head to Northern San d'Oria and speak with Mulaujeant at (E-5), on the second floor near the Blacksmithing Guild."] = "北サンドリア(E-5)、鍛冶ギルド付近2階のMulaujeantに話す。",
    ["Wait until one Earth minute has passed and speak with Mulaujeant again to be given the Sublime statue of the Goddess."] = "地球時間1分後、Mulaujeantから荘厳なる女神像。",
    ["Return to Rauteinot for your reward, the Scroll of Teleport-Yhoat."] = "Rauteinotに報告しテレポヨトの巻物。",
    ["Speak with Magriffon in Kazham (I-7), inside Celodekhi's B&B. You need Kazham fame level 6 and the Rise of the Zilart pack. He has given all his worldly possessions to save a pack of Opo-opos from starvation, and needs someone to save him from getting kicked out before he completes his top-secret mission."] = "カザム(I-7)民宿セロデッキのMagriffonに話す。原文条件は名声6とジラート導入。オポオポ救済のため財産を使い、宿代の援助が必要だという。",
    ["Trade him the gil he asks for, between 10,000 and 30,000 gil. This earns you the title Gullible's Travels."] = "要求額10,000〜30,000ギルを渡す。原文の称号表記はああ！奇跡の出会い！（Wikiでは「いい人カモ」）。",
    ["You must zone after completing Gullible's Travels before you can flag this quest. You need Kazham fame level 7 and the Rise of the Zilart pack. Magriffon has spent all of his (your?) money to save a maiden in distress."] = "ああ！奇跡の出会い！完了後エリアチェンジ。原文条件は名声7とジラート導入。Magriffonは女性救出のためまた金を使ったという。",
    ["Speak with Magriffon in Kazham (I-7) and trade him the gil he asks for."] = "カザム(I-7)のMagriffonに要求額を渡す。",
    ["Zone, then return to Magriffon, who gives you a Treasure map key item."] = "エリアチェンジ後MagriffonからTreasure map。原文はラフレシア3か所を調べる工程を省略。",
    ["Return to Magriffon to finish the quest and receive 3 Rafflesia Nectar."] = "Magriffonに戻りRafflesia Nectar3個で完了、と原文に記載。Wikiでは蜜は花から採取する。",
    ["After completing this quest, all Mithra in Kazham are repulsed by you, but Opo-opos are attracted to you. The only way to fix this is by completing Personal Hygiene, though it is recommended that you finish The Opo-opo and I first so you can get an Opo-opo Crown."] = "以後カザムのミスラは臭いを嫌い、オポオポは好む。温泉へ行こうで落とせるが、先にオポオポ王への道を始めオポオポ王の王冠を狙うとよい。",
    ["You need the scent from Even More Gullible's Travels. This scent repulses all Mithra in Kazham, but it is required to start The Opo-opo and I, so if you plan to do that quest, do not wash it off before you start it. You need the Rise of the Zilart pack."] = "おお！勇気ある決断！の臭いが必要。オポオポ王への道の受領前に洗い落とさない。ジラート導入が必要。",
    ["Speak with Gatih Mijurabi in Kazham (I-8) to begin the quest to remove the scent. The Mithra of Kazham are having a hard time holding in their lunches, and the only way to get clean is a long dip in a hot spring deep beneath the sea."] = "カザム(I-8)のGatih Mijurabiから臭い落としの依頼。海底温泉で長く温まる必要がある。",
    ["The hot spring is in Korroloka Tunnel (G-9) on map 4."] = "コロロカの洞門マップ4(G-9)の温泉へ。原文は5分間浸かり、離れて成功ログを確認する工程を省略。",
    ["Return to Gatih Mijurabi to complete the quest and receive the Mithran Stone."] = "Gatih Mijurabiに報告しミスラストーン。",
    ["If you need to re-apply the scent for The Opo-opo and I, you can check the three Rafflesia flowers in Yuhtunga Jungle once per game day until you get the scent back."] = "オポオポ王への道用に臭いを付け直すなら、ユタンガ大森林のラフレシア3か所をヴァナ1日ごとに調べ、臭いが付くまで繰り返す。",
    ["Once you have finished Even More Gullible's Travels and received the scent, speak with Lulupp in Kazham (G-7) for a cutscene. The Opo-opo in Kazham love your new fragrance: bring them what they want, in the correct order, and they make you their king."] = "おお！勇気ある決断！後、臭い付きでカザム(G-7)のLuluppに話す。欲しい物を正しい順で渡せばオポオポの王になれる。",
    ["You must trade items in order to a list of Opo-opos. The first is Lulupp (G-7), who wants a Broken Mithran Rod, which can be bought at the Auction House."] = "指定順に品物を渡す。最初は(G-7)のLuluppへ折れたミスラ式釣竿（競売可）。原文は残る9匹の品物・順序を省略。",
    ["If you forget how far you are into the quest, simply chat with the Opo-opos on the list. One that has already received the correct item responds and you can bow to it."] = "進度を忘れたら各オポオポに話す。正しい品物を渡し済みの者はお辞儀する。",
    ["When every Opo-opo has received its item, you receive the Opo-opo Crown and the title King of the Opo-opos."] = "全員への納品後オポオポ王の王冠とオポオポの王の称号。",
    ["Speak with Ronta-Onta in Kazham (J-9) to obtain the quest. You need Kazham fame level 6 and the Rise of the Zilart pack. Once you have the key item Tuning fork of fire, you can safely undertake the quest. Each party member must have their own Tuning fork of fire."] = "カザム(J-9)のRonta-Ontaから火の音叉。原文条件は名声6とジラート導入。参加者全員に各自の音叉が必要。",
    ["Travel to Yhoator Jungle and look for the entrance to Ifrit's Cauldron at (I-6). On the first map of Ifrit's Cauldron head to the Flame Spout at (H-6). When you land (Map C) go to the drop at (H-7), then proceed to (G-6) to find the entrance to the Cloister of Flames. Preferably, use the Home Point warp to Ifrit's Cauldron #1."] = "ヨアトル大森林(I-6)からイフリートの釜へ。マップ1(H-6)の炎の壁、落下後マップC(H-7)、(G-6)から灼熱の回廊へ。釜Home Point #1を使うと便利。",
    ["Defeat Ifrit Prime to receive the key item Whisper of flames."] = "Ifrit Primeを倒し火の息吹。",
    ["Return to Ronta-Onta with the whisper and he offers several reward options, including the ability to summon Ifrit. You can only select one of the rewards at any time, and you may repeat this quest once per Earth day. You may also keep the whisper to meet the requirements of The Moonlit Path."] = "Ronta-Ontaに戻り、イフリート召喚契約などから1つ選ぶ。地球1日ごとに反復可。The Moonlit Path用に息吹を保持することもできる。",
    ["To save travel time to the Cloister, use the Mini Fork of Fire from Trial-Size Trial by Fire: be on Summoner as your main job, get the Mini Tuning Fork from Dodmos, trade it back to Dodmos, and enter the Protocrystal normally. As long as you do not clear the level 20 version of the battlefield, you may warp to the Cloister as many times as you wish."] = "火の試練・改の火の音叉・改で移動短縮可。メイン召喚士でDodmosから音叉を受け、渡し直して転送後、通常の巨大クリスタルに入る。20制限戦を完了しなければ繰り返し転送可。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. Speak with Jakoh Wahcondalo in Kazham (J-9) to receive the Dagger of Trials."] = "他のWS依頼が進行中なら依頼者に中止を申し出る。カザム(J-9)のJakoh Wahcondaloからトライアルダガー。",
    ["You need to break the latent on the Dagger of Trials before completing the rest of the quest. You know you have enough points when the latent breaks and the weapon's elemental resistances disappear from your active resistances (the colored dots below the gear grid)."] = "トライアルダガーの潜在を消す。装備欄下の属性耐性ボーナスが消えれば必要ポイント達成。",
    ["You are instructed to travel to Gustav Tunnel. Take Silent Oils and Prism Powders with you. You will also find a Grounds Tome close to your spawn point, where you can get Sneak and Invisible."] = "グスタフの洞門へ。サイレントオイル・プリズムパウダーを用意。入口近くのGrounds Tomeでスニーク・インビジも利用可。原文は???の所在と前段の返却工程を省略。",
    ["Defeat the NM that appears and, once you kill it, re-examine the ???. Return to Jakoh Wahcondalo to receive your reward, the Evisceration weapon skill."] = "出現NMを倒し???を再調査。Jakoh Wahcondaloに報告してエヴィサレーション。",
    ["You need to be a Summoner of level 20 or higher, Kazham fame level 2 and the Rise of the Zilart pack. Speak with Dodmos in Kazham (J-9) to begin the quest and obtain a Mini Tuning Fork of Fire."] = "召喚士20以上、原文カザム名声2、ジラート導入で(J-9)のDodmosから火の音叉・改。Wiki受領条件15以上と差あり。",
    ["You may prepare for the upcoming battle and, whenever you are ready, trade Dodmos the tuning fork to be transported to the arena."] = "準備後Dodmosに音叉を渡し回廊へ転送。",
    ["Trade the fork to the Fire Protocrystal to enter the fighting arena."] = "Fire Protocrystalに音叉を渡しBFへ。",
    ["Defeat Ifrit Prime to complete the quest."] = "Ifrit Primeを倒して完了。",
    ["You may re-obtain the Mini Tuning Fork from Dodmos at any point if you want to repeat the fight, but he will no longer teleport you to the Cloister. Try to fight Ifrit on Watersday and do not fight him on Firesday."] = "再戦用音叉はDodmosから再入手できるが、完了後は転送不可。水曜日が有利、火曜日は避ける。",
    ["Speak with Jaucribaix in Norg (K-8), near the Captain's Chamber, to begin the quest. You need to be level 30 or higher on any job and have the Rise of the Zilart pack. A lump of bomb steel and a sacred branch are required to make a new katana, and Jaucribaix's pupils can tell you where to get them."] = "ノーグ(K-8)船長室付近のJaucribaixに30以上で話す。ジラート導入が必要。刀の材料ボムの卸し鉄と聖地の木の枝の集め方は弟子に聞く。",
    ["Speak with Aeka at (I-8) to receive the first material."] = "(I-8)のAekaから素材を得る。原文はもう一方の弟子・素材入手と2か所のNM戦を省略。",
    ["If you are doing the quest for multiple people, you must wait 4 minutes for the Forger to respawn for another Bomb Steel, and you only need to kill the Treant once."] = "複数人分ならForger再出現まで4分待つ。Treantは1回倒せばよい、と原文に記載。",
    ["Trade the Bomb Steel and the Sacred Branch to Jaucribaix."] = "ボムの卸し鉄と聖地の木の枝をJaucribaixへ渡す。",
    ["Return in 72 in-game hours (3 real-life hours) to receive your reward: the Mumeito and the ability to become a Samurai, with the title Bushido Blade."] = "ヴァナ72時間後（原文の地球時間表記は3時間）、無銘刀と侍取得、ブシドー・ザ・ブレードの称号。",
    ["The Mumeito is required for the Samurai artifact quest The Sacred Katana, so hold on to it. If you lose it, you have to pay Ranemaud 30,000 gil for a replacement."] = "無銘刀は侍AFの神刀で必要なので保管。失った場合Ranemaudから30,000ギルで再取得。",
    ["Speak with Muzaffar in Norg (I-8) to begin the quest. You need Outlands fame level 1 (the page is unsure) and the Rise of the Zilart pack."] = "ノーグ(I-8)のMuzaffarに話す。原文は辺境名声1を未確証とし、ジラート導入が必要。",
    ["Bring him either 4 Eastern Pottery, 4 Northern Fur or 4 Southern Mummy to complete the quest. Eastern Pottery x4 pays 2,000 gil and drops from Clockwork Pods in Garlaige Citadel or Fei'Yin."] = "東方の磁器／北方の毛皮／南方の木乃伊のいずれか4個を渡す。東方の磁器はガルレージュ要塞・フェ・インのClockwork Podから、報酬2,000ギル。",
    ["Northern Fur x4 pays 1,500 gil and drops from Giant Hunter enemies in Qufim Island, and from Giant Lobber enemies in Lower Delkfutt's Tower or Middle Delkfutt's Tower. Southern Mummy x4 pays 3,000 gil and drops from Lich enemies in Western Altepa Desert."] = "北方の毛皮はクフィム島のGiant Hunter、デルクフの塔下層・中層のGiant Lobberから、4個で1,500ギル。南方の木乃伊は西アルテパ砂漠のLichから、4個で3,000ギル。",
    ["All the required items can also be found at the Auction House, under Others, Misc. 1. The quest gives you the title Black Marketeer and can be repeated."] = "必要品は競売のその他・雑貨1でも購入可。闇ブローカーの称号、反復可。",
    ["Speak with Mamaulabion in Norg (G-6) to activate the quest. You need Norg fame level 4 and the Rise of the Zilart pack. This does not need to be done before obtaining the seven items. He would like any \"thuper-dee-duper\" special power items you come across, but cannot tell you where to find them."] = "ノーグ(G-6)のMamaulabionに話す。原文ノーグ名声4、ジラート導入。7品を先に集めてもよい。特別な力を持つ品を欲しがる。",
    ["Obtain the seven items by selecting them as your reward after defeating the seven Prime Avatars in the Trial battles: Bubbly Water, Egil's Torch, Eye of Nept, Desert Light, Elder Branch, Rust 'B' Gone and Ancients' Key."] = "7召喚獣の試練報酬から空気の水／エギルの松明／ネプトの目／砂漠の光／長老の枝／サビトレール／古代種のカギを集める。",
    ["Return all seven items to Mamaulabion. They must be traded one at a time, and it is not necessary to turn in all seven at once."] = "7品をMamaulabionへ1個ずつ渡す。全部を一度にそろえなくてもよい。",
    ["Wait until midnight (JST), then speak with Mamaulabion once more to receive the Evoker's Ring."] = "日本時間の午前0時をまたぎMamaulabionに話してエボカーリング。",
    ["The quest is only repeatable if the Evoker's Ring is dropped."] = "エボカーリングを捨てた場合のみ再依頼可。",
    ["Travel to Norg and enter the Buccaneer's Quarters at (J-8). You need to be level 10 or higher with Norg fame level 4 and have the Rise of the Zilart pack."] = "ノーグ(J-8)の海賊の部屋へ。10以上、原文ノーグ名声4、ジラート導入が必要。",
    ["Talk to Washu. He gives you an Empty Barrel, which you need to fill with Opo-opo brew found in a Yhoator Jungle tree."] = "Washuから空っぽの酒樽を預かり、ヨアトル大森林の木からOpo-opo brewを汲む。",
    ["Examine a ??? that spawns randomly in Yhoator Jungle. Once you find it, the Empty Barrel turns into a Barrel of Opo-opo brew."] = "ヨアトル大森林の???を調べヨアトル産天然ワインを得る。原文はランダム配置、現行Wikiは固定位置。",
    ["Return to Washu to receive your reward, the Scroll of Hojo: Ichi, and the title Apprentice Sommelier."] = "Washuに報告し捕縄の術:壱の巻物とソムリエ見習いの称号。",
    ["Speak with Edal-Tahdal in Norg (H-9) to obtain the quest. You need Norg fame level 4 and the Rise of the Zilart pack. Once you have the key item Tuning fork of water, you can safely undertake the quest. Each party member must have their own Tuning fork of water."] = "ノーグ(H-9)のEdal-Tahdalから水の音叉。原文名声4、ジラート導入。全員に各自の音叉が必要。",
    ["Use the Paintbrush of souls on the empty Picture frame to open the door to the Den of Rancor. Use the Home Point warp to Den of Rancor #2 if you can."] = "魂の絵筆を空の額縁で使い怨念洞への扉を開く。怨念洞Home Point #2も利用可。",
    ["On the first map of the Den of Rancor (Map C), drop down the hole at (J-7) to the sixth map (Map D) and enter the Cloister of Tides at (I-7)."] = "怨念洞マップ1（C）の(J-7)から穴を落ち、マップ6（D）の(I-7)から海流の回廊へ。",
    ["Defeat Leviathan Prime to receive the key item Whisper of tides."] = "Leviathan Primeを倒し水の息吹。",
    ["Return to Edal-Tahdal with the whisper and he offers several reward options, including the ability to summon Leviathan. You can only select one of the rewards at any time, and you may repeat this quest once per Earth day. You receive the title Heir of the Great Water."] = "Edal-Tahdalに戻りリヴァイアサン召喚契約などから1つ選ぶ。地球1日ごとに反復可、大いなる水の継承者の称号。",
    ["To save travel time to the Cloister, use the Mini Tuning Fork given by the quest Trial-Size Trial by Water. As long as you do not clear the level 20 version of the battlefield, you may warp to the Cloister as many times as you wish."] = "水の試練・改の音叉で移動短縮可。20制限戦を完了しなければ繰り返し転送できる。",
    ["Speak with Magephaud in Norg (I-8) to begin the quest. You need Outlands fame level 2 and the Rise of the Zilart pack, and you must have defeated a Tonberry before you can start it. He asks for three gold beastcoins if you want to learn how to rid yourself of the Tonberries' rancor."] = "ノーグ(I-8)のMagephaudからトンベリの怨みの浄化方法を聞く。原文辺境名声2、ジラート導入、トンベリ討伐歴が必要。獣人金貨3枚を頼まれる。",
    ["Bring Magephaud the 3 gold beastcoins. You receive the permanent key item Tonberry key (Zilart)."] = "獣人金貨3枚を渡し恒久だいじなものウガレピ寺院小部屋のカギ。",
    ["With the Tonberry key (Zilart) you can reset your Tonberry Hate at any time: use it on the secret door at (F-11) on map 1 of the Temple of Uggalepih, where the Tonberry Priest resets your Tonberry Hate in exchange for a gil penance."] = "ウガレピ寺院マップ1(F-11)の隠し扉をそのカギで開けると、Tonberry Priestへギルを払って怨みを消せる。",
    ["The Tonberry key (Shantotto) from the A Shantotto Ascension missions is a temporary key item and does not do this. If you are having trouble resetting Tonberry Hate, you may have the wrong key item; check with Magephaud to see if he still requests the 3 beastcoins."] = "シャントット帝国のTonberry key (Shantotto)は一時だいじなもので用途が違う。浄化できなければMagephaudが金貨3枚を求めるか確認。",
    ["To begin this quest you first need a Damp Scroll. It can be fished up in Sea Serpent Grotto or bought at the Auction House. You need level 10 or higher, Outlands fame level 3 and the Rise of the Zilart pack."] = "濡れた巻物を海蛇の岩窟で釣るか競売で入手。10以上、原文辺境名声3、ジラート導入が必要。",
    ["You must have the Damp Scroll in your inventory when you speak with Shivivi in Norg (J-8) to begin the quest."] = "巻物を所持してノーグ(J-8)のShiviviに話し受領。",
    ["Take the scroll to Horlais Peak (hot springs side) and trade it to the hot springs there. This transforms the scroll into a Scroll of Jubaku: Ichi and gives you the title Cracker of the Secret Code."] = "ホルレーの岩峰の温泉側でHot Springsに巻物を渡すと呪縛の術:壱と暗号？解読者の称号。",
    ["Speak with Laisrean in Norg (H-7) to begin the quest. You need Norg fame level 4 and the Rise of the Zilart pack. He wants something from the Sahagins' storage area in the Sea Serpent Grotto; anything will do."] = "ノーグ(H-7)のLaisreanから海蛇の岩窟のサハギン宝物庫調査。原文名声4、ジラート導入が必要。",
    ["Exit Norg into Sea Serpent Grotto. Head south until you reach the fork at (H-6) and go east. Turn south at (J-5), head east at (J-10), and turn east at (K-12)."] = "海蛇の岩窟で南の分岐(H-6)から東、(J-5)から南、(J-10)から東、(K-12)から東へ。",
    ["Go past the Silver Door at (N-14): examine the door three times and trade it a Silver Beastcoin to get through. You keep the Silver Beastcoin."] = "(N-14)のSilver Doorを3回調べ獣人銀貨を渡す。銀貨は失わない。",
    ["Fall off the path to the one below at (H-8) and continue north. Follow the path until you find the ??? at (H-3). Interacting with it gives you a Sea serpent statue."] = "(H-8)で下段へ降り北の(H-3)へ。???を調べ海龍の像。",
    ["Return to Laisrean for your reward, the Scroll of Utsusemi: Ichi, and the title Treasure-House Ransacker."] = "Laisreanに報告し空蝉の術:壱の巻物と宝物庫あらしの称号。",
    ["Speak with Keal in Norg (H-8) to begin the quest. He walks around by the Survival Guide. You need to be level 5 or higher, Outlands fame level 3 and have the Rise of the Zilart pack. He wants you to bring back a sealed iron box from the Sahagin-infested Norg vault."] = "ノーグ(H-8)、Survival Guide付近のKealから倉庫の封のされた箱回収。原文条件5以上・辺境名声3・ジラート導入。",
    ["Exit Norg into Sea Serpent Grotto. Once there, head south until you reach (H-7) and go west from there."] = "海蛇の岩窟へ出て南へ、(H-7)から西へ。",
    ["Turn south at (F-7) and continue west, following the path as it turns north at (B-7)."] = "(F-7)で南へ曲がり西へ、(B-7)で北へ続く道を進む。",
    ["The ??? you are looking for is in the room at (C-5). Examine it to get the key item Sealed iron box."] = "(C-5)の部屋の???から封のされた箱。",
    ["Return to Keal to complete the quest and receive the Scroll of Tonko: Ichi."] = "Kealに報告し遁甲の術:壱の巻物。",
    ["Speak with Heiji in Norg (I-7) to begin the quest. You need Norg fame level 3 and the Rise of the Zilart pack. Ten rusty subligaria are needed for the training of young ninjas, and Heiji accepts them one at a time."] = "ノーグ(I-7)のHeijiから錆びたサブリガ10個の依頼。原文名声3、ジラート導入。1個ずつでも受領される。",
    ["Obtain 10 Rusty Subligar (they are fished up) and trade them to Heiji. You do not have to trade all 10 at the same time, as he remembers how many you have traded."] = "釣り等でRusty Subligar10個を集めHeijiへ。分納数は記録される。",
    ["Once all 10 are traded you receive your reward, the Scroll of Kurayami: Ichi, and the title Looks Sublime in a Subligar."] = "10個納品で暗闇の術:壱の巻物とサブリガを輝かせる者の称号。",
    ["Speak with Heizo in Norg (H-7) to begin the quest. You need Norg fame level 3 and the Rise of the Zilart pack. Ten pairs of rusty leggings are needed for the training of young ninjas, and Heizo accepts them one at a time."] = "ノーグ(H-7)のHeizoから錆びたレギンス10個の依頼。原文名声3、ジラート導入。1個ずつでも可。Wikiの依頼者座標とは差あり。",
    ["Obtain 10 Rusty Leggings (they are fished up or come from a Goblin Box) and trade them to Heizo. You do not have to trade all 10 at the same time, as he remembers how many you have traded."] = "釣りやゴブリンの不思議箱からRusty Leggings10個を得てHeizoへ。分納可。",
    ["Once all 10 are traded you receive your reward, the Scroll of Dokumori: Ichi, and the title Looks Good in Leggings."] = "10個納品で毒盛の術:壱の巻物とレギンスを輝かせる者の称号。",
    ["Talk to Jaucribaix in Norg (K-8), near the Captain's Chamber, while on Samurai to initiate the quest. You need to be a Samurai of level 40 or higher and have the Rise of the Zilart pack; this quest follows Forge Your Destiny. You may change to a different job to complete the rest of the quest."] = "侍40以上でノーグ(K-8)船長室付近のJaucribaixに話す。ある刀鍛冶の依頼後、ジラート導入。受領後は他ジョブ可。",
    ["Travel to The Sanctuary of Zi'Tah."] = "聖地ジ・タへ。",
    ["Kill Goblin Robber enemies to get a Sack of Fish Bait, a common drop."] = "Goblin Robberから撒き餌の袋を得る。",
    ["Trade the Fish Bait to the ??? at (E-8) to pop Isonade, a fish NM with approximately 6,100 HP."] = "(E-8)の???に撒き餌を渡し、原文HP約6,100のIsonadeを出す。",
    ["Re-examine the ??? to obtain the Handful of crystal scales."] = "討伐後???を再調査して水晶の鱗。",
    ["Return to Norg and trade your Mumeito to Jaucribaix to complete the quest and receive the Magoroku. If you do not have your Mumeito, Ranemaud at (I-7) can give you a new one for 30,000 gil."] = "ノーグでJaucribaixに無銘刀を渡し孫六兼元。無銘刀紛失時は(I-7)のRanemaudから30,000ギルで再購入。",
    ["You must zone after completing The Sacred Katana to begin this quest. Speak with Jaucribaix in Norg (K-8). You need to be a Samurai of level 50 or higher and have the Rise of the Zilart pack. A ritual is needed to send the souls of those who died in a long-ago war to their proper resting place."] = "神刀後エリアチェンジし、侍50以上でノーグ(K-8)のJaucribaixに話す。ジラート導入。戦没者の魂を送る儀式を手伝う。",
    ["Speak with Washu at (J-8)."] = "(J-8)のWashuに話す。",
    ["Trade Washu a Bastore Sardine, a Frost Turnip, a piece of Giant Sheep Meat and a Hecteyes Eye to receive the key item Washu's tasty wurst."] = "バストアサーディン／シモカブ／大羊の肉／ヘクトアイズの眼をWashuへ渡しワシュウ特製詰め物。",
    ["Examine the ??? in Labyrinth of Onzozo (F-8) to spawn the NM Ubume. An alternate route to Labyrinth of Onzozo is through Buburimu Peninsula."] = "オンゾゾの迷路(F-8)の???からUbumeを出す。ブブリム半島経由でも到達可。原文は討伐後の羽根回収を省略。",
    ["Return to Norg and speak with Jaucribaix."] = "ノーグのJaucribaixに報告。",
    ["Exit Norg, re-enter, and speak with Jaucribaix to receive the key item Yomotsu Hirasaka."] = "ノーグを出入りしJaucribaixから神刀黄泉平坂。原文は待機とバルクルム砂丘でのNM戦を省略。",
    ["Speak with Jaucribaix again to receive your reward, the Myochin Sune-Ate."] = "Jaucribaixに再会話し明珍筒脛当。",
    ["You must zone after completing Yomi Okuri to begin this quest. Speak with Jaucribaix in Norg (K-8). You need to be a Samurai of level 50 or higher and have the Rise of the Zilart pack. At the close of the Great War, Gilgamesh's father trapped a terrible spirit within a helm, and that helm has been stolen."] = "黄泉送り後エリアチェンジし、ノーグ(K-8)のJaucribaixに侍50以上で話す。ジラート導入。大戦末期に封印した兜が盗まれたという。",
    ["Speak with Sanosuke in Port Jeuno (H-8), inside the Duty Free Shop."] = "ジュノ港(H-8)免税店のSanosukeに話す。",
    ["Speak with Phoochuchu in Mhaura (H-8), on the ground level under the bridge."] = "マウラ(H-8)、橋の下のPhoochuchuに話す。Wikiの会話順と原文は異なる。",
    ["Speak with Jaucribaix in Norg to receive a Banishing Charm."] = "ノーグのJaucribaixから破魔の御守。原文はバストゥークでのイベントとBF戦を省略。",
    ["Speak with Jaucribaix again; he requests a Gold Thread. Trade a Gold Thread to Jaucribaix."] = "Jaucribaixに話し金糸を渡す。",
    ["Zone out of Norg, then return to Jaucribaix for your reward, the Myochin Kabuto, and the title Paragon of Samurai Excellence. You can toss the Banishing Charm after completing the quest, as it serves no further purpose."] = "ノーグを出入りしJaucribaixから明珍桃形兜、無双なる大武士の称号。完了後破魔の御守は処分可。",
    ["Talk to Ryoma in Norg (H-8), at Home Point #1, to begin the quest, then head to Port Bastok. You need to be a Ninja of level 40 or higher, Outlands fame level 1 and the Rise of the Zilart pack; this quest follows Ayame and Kaede. Norg has begun investigating an ancient scroll that was rediscovered recently."] = "ノーグ(H-8)、Home Point #1のRyomaに忍者40以上で話しバストゥーク港へ。原文辺境名声1、ジラート導入、Ayame and Kaede後。古い文書を調査する。",
    ["Speak with Kagetora inside Warehouse #2 at (F-6) in Port Bastok (near Port Bastok Home Point #3)."] = "バストゥーク港(F-6)、Home Point #3近くの第2倉庫でKagetoraに話す。",
    ["Go to (I-5) in Port Bastok and speak with Ensetsu."] = "バストゥーク港(I-5)のEnsetsuに話す。",
    ["After speaking with Ensetsu, make your way to (H-5)/(H-6) of Eastern Altepa Desert. From this point you can continue on any job. The shortest route to the ??? is to take the Survival Guide to Western Altepa Desert and then zone to Eastern Altepa Desert."] = "東アルテパ砂漠(H-5)/(H-6)へ。以後は他ジョブ可。Survival Guideで西アルテパ砂漠へ飛び東へ抜けると近い。",
    ["Clear the area and examine the ??? once ready. Two Tsuchigumo NMs spawn. Both NM corpses must disappear before you can obtain the Trick box."] = "周囲を片づけ???を調べTsuchigumo2体を出す。両方倒し死体が消えてから組木細工の箱を得る。",
    ["Head back to Norg and speak with Ryoma to complete the quest and receive your reward, Anju and Zushio."] = "ノーグのRyomaに報告し安寿と厨子王。",
    ["Travel to Norg and speak with Ryoma (H-8) to receive the quest. You need to be a Ninja of level 50 or higher, Outlands fame level 1 and the Rise of the Zilart pack; this quest follows 20 in Pirate Years. If you just completed 20 in Pirate Years, you need to zone and re-enter Norg for Ryoma to begin it. The trick box you brought back has been identified as a fake, and he needs help finding the real box."] = "ノーグ(H-8)のRyomaに忍者50以上で話す。原文辺境名声1とジラート導入、海賊たちの20年後の出入りが必要。箱は偽物で本物を探す。",
    ["Once in Mhaura, take the ferry to Selbina so that you are traveling at nighttime. Suitable ferry departure times for this quest leave Mhaura at 16:00 and 0:00. On the ferry that departs at 16:00, you must wait until night time at 20:00 for the event to appear."] = "マウラ16:00か0:00発のセルビナ行き機船へ。16:00発では20:00の夜間イベントまで待つ。原文はエンセツ・Leodarionへの訪問、杖入手、船上NM戦を省略。",
    ["You receive a cutscene and the Ninja Hakama, and the quest is complete. You can repeat the quest."] = "イベント後乱波袴で完了。原文では反復可と記載。",
    ["Speak with Ryoma in Norg (H-8) to begin the quest. You need to be a Ninja of level 50 or higher and have the Rise of the Zilart pack; this quest follows I'll Take the Big Box. The Sahagin have stolen Mitsunari's treasure and hidden it somewhere in the jungle on Elshimo Island."] = "ノーグ(H-8)のRyomaに忍者50以上で話す。想いを遺すために後、ジラート導入。ミツナリの宝がエルシモの森に隠されたという。",
    ["Travel to (I-7) in Yhoator Jungle. The quickest way is Survival Guide teleportation from Elshimo Uplands to Yhoator Jungle, with one east of Home Point #1 in Norg. The Unity warp (level 122) teleports you to (J-7)."] = "ヨアトル大森林(I-7)へ。ノーグHome Point #1東のSurvival Guideから高地エルシモを選ぶと便利。ユニティ122転送先は(J-7)。",
    ["Once prepared, examine the ??? at (I-7), northwest of Bloodlet Spring, to spawn 3 Sahagin NMs: Kappa Akuso (Monk), Kappa Biwa (Bard) and Kappa Bonze (White Mage)."] = "準備後Bloodlet Spring北西(I-7)の???を調べ、Kappa Akuso（モ）／Kappa Biwa（吟）／Kappa Bonze（白）を出す。",
    ["Only one of them needs to be killed, so a recommended strategy is to zone to Den of Rancor and fight one while the others despawn."] = "原文案は怨念洞へ逃げて2体を消し、残る1体を倒す方法。実行時の敵の消失順に注意。",
    ["Return to Ryoma for another cutscene."] = "Ryomaに報告しイベント。原文は討伐後の箱回収とクフタルのコッファー工程を省略。",
    ["Return to Leodarion to complete the quest and receive the Ninja Chainmail and the title Paragon of Ninja Excellence. You can repeat the quest."] = "Leodarionに戻り乱波鎖帷子、沈勇なる大忍者の称号。原文では反復可。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need to be level 71 with a base Great Katana skill of 250 or higher."] = "他のWS依頼は中止しておく。71以上、素の両手刀スキル250以上が必要。",
    ["Speak with Jaucribaix in Norg (K-8). He grants you the key item Weapons Training Guide as well as the Tachi of Trials. Wield the katana to find your true potential; when the blade has lost its power, you will know you have been accepted."] = "ノーグ(K-8)のJaucribaixからWeapons Training Guideと試練の太刀。刀を使い潜在能力を消す。",
    ["You need to break the latent on the Tachi of Trials. With it equipped in your main hand, fight experience-yielding monsters (Incredibly Easy Prey or higher) and perform Weapon Skills or close skillchains to accumulate 300 Trial Points."] = "経験値対象（とてもとても楽以上）へWSや連携の締めを行い、試練の太刀の試練ポイント300をためる。",
    ["You will know the latent is broken when the elemental resistances listed in the description of the Tachi of Trials have disappeared from the elemental resistances in the equipment window."] = "装備画面で試練の太刀の属性耐性ボーナスが消えれば潜在解除。",
    ["Trade the Tachi of Trials back to Jaucribaix. Then go back and speak with him to receive your reward, the weapon skill Tachi: Kasha."] = "Jaucribaixへ刀を返し、再会話で九之太刀・花車、と原文に記載。原文はクフタルのNM戦と???再調査を省略。",
    ["You cannot start this quest if you have another Weapon Skill quest active; return to the person who gave it and quit it first. You need a Ninja of level 71 and Katana skill 250 or higher, and the Rise of the Zilart pack."] = "他のWS依頼を中止し、忍者71以上・片手刀250以上で受領。ジラート導入が必要。",
    ["Speak with Ryoma in Norg (H-8). He grants you the key item Weapons Training Guide as well as the Kodachi of Trials."] = "ノーグ(H-8)のRyomaからWeapons Training Guideと試練の小太刀。",
    ["You need to break the latent on the Kodachi of Trials. With it equipped in your main hand, fight experience-yielding monsters (Incredibly Easy Prey or higher) and perform Weapon Skills or close skillchains to accumulate 300 Trial Points. A weapon skill with no skillchain gives 5 points and a level 1 skillchain gives 7."] = "経験値対象（とてもとても楽以上）へWSや連携の締めを行い試練ポイント300。原文配点は単発5・レベル1連携7で小売版の配点とは異なる。",
    ["You will know the latent is broken when its bonus stats disappear on un-equipping and re-equipping the Kodachi of Trials; the elemental resistances also disappear from your stats."] = "試練の小太刀を着脱し、能力値と属性耐性のボーナスが消えていれば潜在解除。",
    ["Take Silent Oil and Prism Powder to the Labyrinth of Onzozo. Inside, follow the path to (H-9) and take the eastern tunnel, continue northeast through the large room and take the tunnel at (J-8). In the next large room, curve around the eastern wall to the tunnel at (H-7), head north at the next intersection, and continue north to the border of (I-5)/(I-6), where the ??? spawns the NM."] = "サイレントオイルとプリズムパウダーを用意しオンゾゾの迷路へ。(H-9)の東トンネル、広間北東の(J-8)、次の広間東壁沿いから(H-7)、次の分岐を北へ進み(I-5)/(I-6)境の???へ。原文はNM戦後の再調査を省略。",
    ["Trade the Kodachi of Trials back to Ryoma, then go back and speak with him to receive your reward, the weapon skill Blade: Ku."] = "試練の小太刀をRyomaへ返し、再会話で空。",
    ["You need to be a Summoner of level 20 or higher, Outlands fame level 2 and the Rise of the Zilart pack. Speak with Verctissa in Norg (H-9) to begin the quest and obtain a Mini Tuning Fork of Water."] = "召喚士20以上、原文辺境名声2、ジラート導入でノーグ(H-9)のVerctissaから水の音叉・改。Wikiの受領条件15以上と差あり。",
    ["Trade the fork to the Water Protocrystal to enter the fighting arena."] = "Water Protocrystalへ音叉を渡しBFへ。",
    ["Defeat Leviathan Prime to complete the quest. Only Carbuncle may be used for this battle; Siren can also be used, but that seems unintended."] = "Leviathan Primeを倒して完了。原文ではカーバンクル限定だが、セイレーンも使えるとの未確証注記あり。",
    ["You may re-obtain the Mini Tuning Fork from Verctissa at any point if you want to repeat the fight, but she will no longer teleport you to the Cloister."] = "完了後もVerctissaから音叉は再入手できるが転送不可。",
    ["Speak with Stray Cloud in Norg (H-9) for a cutscene. You need Outlands fame level 4 and the Rise of the Zilart pack. Find Stray Cloud's friend Gubokka in the Sea Serpent Grotto."] = "ノーグ(H-9)のStray Cloudに話す。原文辺境名声4、ジラート導入。海蛇の岩窟へ向かったGubokkaを探す。",
    ["Head towards Sea Serpent Grotto; you get another cutscene shortly before you reach the zone line."] = "海蛇の岩窟への出口手前でイベント。",
    ["Once inside Sea Serpent Grotto, head to (K-6), where you find a ???. Check the ??? to spawn Glyryvilu."] = "海蛇の岩窟(K-6)の???を調べGlyryviluを出す。",
    ["Defeat Glyryvilu, then check the ??? again to receive the key item Caliginous Blade."] = "Glyryviluを倒し???を再調査して鈍色の剣。",
    ["Return to Stray Cloud for your reward, the Light Buckler."] = "Stray Cloudに報告しライトバックラー。",
    ["First head to Rabao and talk to Rudolfo (J-7). You need to have completed Promathia Mission 2-1 and have the Chains of Promathia pack. A young cargo hauler named Sanctia has suddenly left Rabao, and Zoriboh wants you to find her; she has probably headed for Norg to board a ship bound for the Tavnazian Marquisate."] = "ラバオ(J-7)のRudolfoに話す。原文条件プロマシア2-1完了と導入。Zoribohからタブナジアへ向かったSanctia捜索。",
    ["Talk to Zoriboh in Rabao (F-6)."] = "ラバオ(F-6)のZoribohに話す。",
    ["Head to Norg and talk to Sohyon (J-8). Then talk to Washu to receive the key item Washu's flask."] = "ノーグ(J-8)のSohyon、続いてWashuに話しワシュウの水筒。",
    ["Head to Korroloka Tunnel. You need to fill the flask by interacting with four different Giant Clams. The first Giant Clam is at (F-10) on map 1, as you zone into Korroloka Tunnel from Zeruhn Mines."] = "コロロカの洞門のGiant Clam4か所で水筒を満たす。最初はツェールン鉱山側マップ1(F-10)。原文は残る貝の場所と、その後のバストゥーク・セルビナ・ルフェーゼの工程を省略。",
    ["Head to Rabao and talk to Zoriboh (F-6) to complete the quest and receive your reward, the Venerer Ring and 4,000 gil."] = "ラバオ(F-6)のZoribohに報告しベネラーリングと4,000ギル。",
    ["Speak with Edigey in Rabao (F-9) to begin the quest. You need Rabao fame level 4 and the Rise of the Zilart pack. He wants sand scorpion poison so he can make an antidote, an essential item for the desert caravans."] = "ラバオ(F-9)のEdigeyから隊商用解毒薬の材料を頼まれる。原文ラバオ名声4、ジラート導入。",
    ["Obtain a Desert Venom, which drops from Doom Scorpion enemies in Eastern Altepa Desert and Tulwar Scorpion enemies in Western Altepa Desert, or buy one at the Auction House."] = "東アルテパ砂漠のDoom Scorpion、西アルテパ砂漠のTulwar Scorpionから砂サソリの毒を得るか競売で購入。",
    ["Trade the Desert Venom to Edigey for your reward. The first time you complete the quest you receive a Dotanuki and the title Desert Hunter; each time after that you only receive gil. You can repeat the quest."] = "Edigeyに渡し初回は同田貫とデザートハンターの称号。2回目以後はギルのみ、反復可。",
    ["To begin this quest in your log, you need the key item Serpent Rumors. It can be bought from Fennella in Port Windurst (C-8) for 95,000 Guild Points with Fishing rank Adept or higher. You can still obtain the other items needed for this quest before initiating it. You need the Rise of the Zilart pack."] = "サーペントの伝説所持が必要。ウィンダス港(C-8)のFennellaから釣り皆伝以上でギルドポイント95,000と交換。他素材は受領前から集められる。ジラート導入。",
    ["Speak with Irmilant in Rabao (G-7). He asks you to bring the two base materials required to craft a legendary fishing rod, which seem to have found their way into the bellies of sea creatures that still elude the finest fishermen."] = "ラバオ(G-7)のIrmilantから伝説の釣竿の材料2種を頼まれる。",
    ["Trade the Opal Silk and the Saber Shoot to Irmilant."] = "五色の糸と剣の枝をIrmilantへ渡す。",
    ["Return to Irmilant after the Conquest tally to receive your reward, the Ebisu Fishing Rod. It can be re-obtained if dropped by mistake."] = "コンクェスト集計後Irmilantから恵比寿釣竿。誤って捨てた場合は再取得可。",
    ["You need a Broken Lu Shang's Rod, which you can get by breaking your own Lu Shang's Fishing Rod or buying a broken one. You need the Rise of the Zilart pack."] = "太公望の釣竿を折るか競売で折れた太公望の釣竿を用意。ジラート導入。",
    ["Trade Irmilant in Rabao (G-7) the Broken Lu Shang's Rod, a Piece of Ancient Lumber and 2 Light Crystals."] = "ラバオ(G-7)のIrmilantへ折れた太公望の釣竿、Ancient Lumber1個、Light Crystal2個を渡す。",
    ["Irmilant repairs the rod and you receive the Lu Shang's Fishing Rod and the title The Immortal Fisher, Lu Shang. You do not need to have completed The Competition or The Rivalry to have your rod fixed. You can repeat the quest."] = "修復された太公望の釣竿と不死身の太公望の称号。The Competition／The Rivalry完了は不要。反復可。",
    ["Speak with Datta in Rabao (F-7) to begin the quest. You need to be level 40 or lower and have the Rise of the Zilart pack. You have been asked to join a tour planned by Datta: travel to the cliff inside the entrance to Kuftal Tunnel with a party of two or more people of level forty or lower, and meet Datta's partner, Hawk Nose."] = "ラバオ(F-7)のDattaに40以下で話す。ジラート導入。40以下2人以上のPTでクフタル入口崖上のHawk Noseを訪ねる。",
    ["Form a party with at least two people who are level 40 or lower. Level sync does work. If you buy a chocobo in Rabao, you can cross the desert without having to worry about aggro."] = "40以下2人以上のPTを組む。レベルシンク可。ラバオのチョコボなら砂漠を安全に横断できる。",
    ["Head to Kuftal Tunnel and examine the ??? just inside the entrance for a cutscene, with your party members close by. You and your party overlook the Kuftal Tunnel."] = "PTを近くに集め、クフタルの洞門入口すぐの???を調べイベント。",
    ["Once you get the cutscene in Kuftal Tunnel, return to Datta for your reward, 8,000 gil, and the title Kuftal Tourist. You can watch the cutscene again with the Goblin Footprint after returning to Datta."] = "Dattaに報告し8,000ギルとクフタルツーリストの称号。報告後Goblin Footprintで再視聴可。",
    ["Speak with Alfesar in Rabao (H-7), who asks you to help him find an Ancient tablet fragment. You need Rabao fame level 4 and the Rise of the Zilart pack."] = "ラバオ(H-7)のAlfesarから古代石版の欠片捜索。原文名声4、ジラート導入。Wiki依頼者座標は(H-8)。",
    ["The Ancient tablet fragment is found by checking one of 5 ???s in the Quicksand Caves: (H-6), (H-10) and (E-9) on map 1, and (D-9) and (L-11) on map 2. As soon as the ??? is found, it instantly respawns in one of those 5 locations."] = "流砂洞マップ1(H-6)／(H-10)／(E-9)、マップ2(D-9)／(L-11)の5か所の???を探す原文案。調べると別地点へ移ると記載。現行Wikiは固定位置であり差異を留保。",
    ["Return to Alfesar, who gives you the Tablet of ancient magic and the Letter from Alfesar."] = "Alfesarに戻り古代魔法の石版とアルフェザールの紹介状。",
    ["Speak with Charlaimagnat in Northern San d'Oria (M-7)."] = "北サンドリア(M-7)のCharlaimagnatに話す。",
    ["Zone and return to Charlaimagnat after one Earth minute for your reward, the Scroll of Teleport-Altep."] = "出入りして地球時間1分後Charlaimagnatからテレポルテの巻物。",
    ["Speak with Agado-Pugado in Rabao (G-9) to obtain the quest. You need Rabao fame level 6 and the Rise of the Zilart pack. Once you have the key item Tuning fork of wind, you can safely undertake the quest. Each party member must have their own Tuning fork of wind."] = "ラバオ(G-9)のAgado-Pugadoから風の音叉。原文名声6、ジラート導入。全員に音叉が必要。",
    ["Travel to Cape Teriggan (F-5) to enter the Cloister of Gales and ring the tuning fork upon the protocrystal."] = "テリガン岬(F-5)から突風の回廊へ入り巨大クリスタルに音叉をかざす。",
    ["Defeat Garuda Prime to receive the key item Whisper of gales."] = "Garuda Primeを倒し風の息吹。",
    ["Return to Agado-Pugado with the whisper and she offers several reward options, including the ability to summon Garuda. You can only select one of the rewards at any time, and you may repeat this quest once per Earth day. You receive the title Heir of the Great Wind. You may also keep the whisper to meet the requirements of The Moonlit Path."] = "Agado-Pugadoに戻りガルーダ召喚契約などから1つ選ぶ。地球1日ごとに反復可、大いなる風の継承者の称号。The Moonlit Path用に息吹を保持してもよい。",
    ["To save travel time to the Cloister, use the Mini Fork of Wind from Trial-Size Trial by Wind: be on Summoner as your main job, get the Mini Tuning Fork from Rahi Fohlatti, trade it back to her, and enter the Protocrystal normally. As long as you do not clear the level 20 version of the battlefield, you may warp to the Cloister as many times as you wish."] = "風の試練・改の風の音叉・改で短縮可。メイン召喚士でRahi Fohlattiから受け、渡して転送後通常のクリスタルへ。20制限戦未完了なら繰り返し転送可。",
    ["You need to be a Summoner, Rabao fame level 2 and have the Rise of the Zilart pack. Speak with Rahi Fohlatti in Rabao (G-9) to begin the quest and obtain a Mini Tuning Fork of Wind."] = "召喚士、原文ラバオ名声2、ジラート導入でラバオ(G-9)のRahi Fohlattiから風の音叉・改。",
    ["You may prepare for the upcoming battle and, whenever you are ready, trade Rahi Fohlatti the tuning fork to be transported to the arena."] = "準備後Rahi Fohlattiへ音叉を渡し転送。",
    ["Trade the fork to the Wind Protocrystal to enter the fighting arena."] = "Wind Protocrystalに音叉を渡しBFへ。",
    ["Defeat Garuda Prime to complete the quest. Clarsach Call is wind-elemental and gets absorbed, so do not use it."] = "Garuda Primeを倒して完了。Clarsach Callは風属性で吸収されるため使用しない。",
    ["You may re-obtain the Mini Tuning Fork from Rahi Fohlatti at any point if you want to repeat the fight, but she will no longer teleport you to the Cloister."] = "音叉はRahi Fohlattiから再入手できるが完了後の転送不可。",
    ["Speak with Lokpix in Eastern Altepa Desert (G-7). You need the Rise of the Zilart pack. He requests a Tremorstone in addition to one of the following: 1 Meteorite, 1 Soil Gem or 12 Soil Geode."] = "東アルテパ砂漠(G-7)のLokpixに話す。ジラート導入。震動石に加えMeteorite1個／Soil Gem1個／Soil Geode12個のどれかを用意。",
    ["A Meteorite is dropped by Crawler enemies in West Sarutabaruta, on Starfall Hillock (R)."] = "隕石は西サルタバルタの星降る丘(R)のCrawlerが落とす。",
    ["Trade Lokpix the Tremorstone and one of the options to receive the key item Loadstone. The Loadstone lets you open the weighted doors in Quicksand Caves solo, without needing multiple players."] = "Lokpixへ必要品を渡し重量石。流砂洞の重量扉を1人で開けられる。",
    ["You must first have Zilart Mission 5, Headstone Pilgrimage, active or complete, and have the Rise of the Zilart pack. The Opo-opos are not happy that you stole their \"red treasure\"."] = "ジラート5「古代石碑巡礼」受領または完了とジラート導入が必要。オポオポの赤い宝に触れて怒らせてしまった。",
    ["Obtain a Garnet."] = "ガーネットを用意。",
    ["Trade the Garnet to the Cermet Headstone in Yuhtunga Jungle (L-7) at any time during or after Zilart Mission 5 to receive an Opo-opo Necklace and the title Friend of the Opo-opos."] = "ジラート5進行中または終了後、ユタンガ大森林(L-7)のCermet Headstoneへガーネットを渡しオポオポネックレスとオポオポの友の称号。Wikiの石碑座標は(L-6)。",
    ["You must have Zilart Mission 5, Headstone Pilgrimage, activated (or already completed), and have the Rise of the Zilart pack. Is there any way to soothe the spirits that wander about Cape Teriggan? Perhaps a Rain Lily."] = "ジラート5「古代石碑巡礼」受領または完了、ジラート導入が必要。テリガン岬の霊へレインリリーを供える。",
    ["Obtain a Rain Lily."] = "レインリリーを用意。",
    ["Trade the Rain Lily to the Cermet Headstone in Cape Teriggan (H-5) to receive a Flagellant's Rope and the title Bearer of Bonds Beyond Time."] = "テリガン岬(H-5)のCermet Headstoneへ渡しフラジラントロープと時を越えた絆持つ者の称号。",
    ["You must first have completed Zilart Mission 7 and have the Rise of the Zilart pack."] = "ジラート7完了とジラート導入が必要。",
    ["Touch the Cermet Headstone in The Sanctuary of Zi'Tah (I-7) with the key item from that mission in your possession."] = "そのミッションのだいじなものを持ち、聖地ジ・タ(I-7)のCermet Headstoneに触れる。",
    ["You receive the Bat Earring and the title Guider of Souls to the Sanctuary."] = "バットピアスと聖地に魂導く者の称号。",
    ["Enter The Shrine of Ru'Avitau from the (H-9) entrance in Ru'Aun Gardens. You need to have completed Zilart Mission 13, and you need an Illuminink, a Parchment and an Ark Pentasphere; the Illuminink and the Parchment are also needed to do the quest a second time."] = "ル・オンの庭(H-9)からル・アビタウ神殿へ。原文はジラート13完了、光るインク・羊皮紙・五戦士魔法陣所持を要求。再挑戦にもインクと羊皮紙が必要。",
    ["Examine the Blank Target at (G/H-11) in the main entrance of The Shrine of Ru'Avitau to flag the quest. You must flag it there, or you will not receive credit and will have to acquire another Ark Pentasphere. Divine Might now appears in your Outlands quests log."] = "神殿正面入口(G/H-11)の名前のない対象を調べ受領。未受領だとクリア判定されず五戦士魔法陣を再入手する必要がある。辺境クエスト欄に神威が載る。",
    ["Enter and complete the Divine Might battlefield at La'Loff Amphitheater."] = "ラ・ロフの劇場の神威BFをクリア。",
    ["Once you have finished the battle, return to the Blank Target in The Shrine of Ru'Avitau to choose your reward: the key items Shard of Apathy, Shard of Arrogance, Shard of Cowardice, Shard of Envy and Shard of Rage, and one of the following earrings: Abyssal Earring, Beastly Earring, Bushinomimi, Knight's Earring or Suppanomimi."] = "神殿の名前のない対象に戻り、5つのかけら（無知・驕慢・怯懦・嫉妬・憎悪）と暗黒の耳／獣使の耳／武士の耳／騎士の耳／素破の耳から1つを選ぶ。",
    ["To repeat the quest, drop your current earring and receive the quest again at the unmarked target (G/H-11) in the main entrance of The Shrine of Ru'Avitau. It appears as a second Divine Might quest in your quest log with a different description."] = "再取得は現在の耳を捨て、神殿入口(G/H-11)の名前のない対象で別説明の神威を受け直す。原文は月光の鉱石と魔法陣の準備を省略。",
