    -- Crystal War quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Thorben (J-10). in Batallia Downs (S)."] = "バタリア丘陵〔Ｓ〕(J-10)のThorbenに話す。Wiki掲載座標とは差あり。",
    ["Enter The Eldieme Necropolis (S) through the Crypt Door beside Thorben (J-10).."] = "Thorben(J-10)脇のCrypt Doorからエルディーム古墳〔Ｓ〕へ。",
    ["Examine the Sarcophagus at (I-9) to obtain the right map piece."] = "(I-9)のSarcophagusから地図の右片。",
    ["Examine the Gravestone at (H-8) to obtain the middle map piece."] = "(H-8)のGravestoneから地図の中央片。",
    ["During Campaign, speak with Erik (H-7). to obtain the left map piece."] = "原文ではカンパニエ中に(H-7)のErikから左片。現行Wikiでは常時出現への修正を記載。",
    ["Examine Blank Target beside Erik. beside Erik (H-7). and choose \"Into the fire\" to return to Batallia Downs (S)."] = "Erik(H-7)脇の名前のない対象を調べ「Into the fire」でバタリア丘陵〔Ｓ〕へ戻る。",
    ["Speak with Thorben (J-10). again to complete the quest and receive the reward."] = "Thorben(J-10)に報告して報酬。",
    ["Speak with Romualdo (I-7). in Batallia Downs (S)."] = "バタリア丘陵〔Ｓ〕(I-7)のRomualdoに話す。原文は現代の大工房での事前会話を省略。",
    ["Follow Romualdo (I-7).'s instructions and investigate the requested location in the Shadowreign area."] = "Romualdo(I-7)の指示で過去世界の指定地点を調査。原文に個別地点の記載なし。",
    ["Complete the examination sequence and return to Romualdo (I-7).."] = "調査を終えRomualdo(I-7)に報告。",
    ["Enter Jugner Forest from Batallia Downs for the required event."] = "現代のバタリア丘陵からジャグナー森林へ入りイベント。",
    ["Examine Metallic Hodgepodge (F-9). in Jugner Forest."] = "ジャグナー森林(F-9)のMetallic Hodgepodgeを調べる。Wikiは(G-9)で、原文座標を保持。",
    ["Enter Ghelsba Outpost to obtain the Orcish Infiltration Kit key item."] = "ゲルスバ野営陣へ入りオークの着ぐるみを得る。",
    ["Travel to Yughott Grotto Map 1 and examine Scrape Mark (G-9).."] = "ユグホトの岩屋マップ1(G-9)のScrape Markへ。",
    ["Examine Scrape Mark (G-9). again to enter the Face of the Future battlefield."] = "(G-9)を再調査してそれぞれの未来へのBFへ。",
    ["Defeat Fangmonger Colossus. Killing the Tombstones weakens its damage resistance, and NPC allies assist during the battle."] = "Fangmonger Colossusを倒す。Tombstoneを倒すとボスの被ダメージ耐性が下がり、味方NPCも参戦。",
    ["Examine Cavernous Maw (H-5). in Batallia Downs to complete the quest and receive the Griffon Ring."] = "現代のバタリア丘陵(H-5)のCavernous Mawを調べ、グリフィンリングで完了。",
    ["Speak with Rholont (E-7). in Southern San d'Oria (S) and bring the Bundle of half-inscribed scrolls to obtain Trust: Excenmille (S)."] = "南サンドリア〔Ｓ〕(E-7)のRholontへ未完成のスクロール束を持参しフェイス：Excenmille〔Ｓ〕。原文の追加報酬工程。",
    ["Speak with Halver (I-9). in Chateau d'Oraguille."] = "ドラギーユ城(I-9)のHalverに話す。",
    ["Obtain a Lilac."] = "ライラックを用意。",
    ["Travel to the Weathered Gravestone (I-10). in Batallia Downs."] = "現代のバタリア丘陵(I-10)のWeathered Gravestoneへ。",
    ["Trade the Lilac to the Weathered Gravestone to complete the quest and obtain the Tiny Memory Fragment."] = "墓にライラックを渡し小さな想ひ出のかけらで完了。",
    ["Speak with Naiko-Paneiko (L-8). in Crawlers' Nest (S) and receive the Scoop-Dedicated Linkpearl."] = "クロウラーの巣〔Ｓ〕(L-8)のNaiko-Paneikoからナイコパニィコ特製リンクパール。",
    ["Travel to Rolanberry Fields (S) at (G-9) and speak with Rakula-Motakula (G-9). on the turret."] = "ロランベリー耕地〔Ｓ〕(G-9)砲台のRakula-Motakulaに話す。",
    ["Answer the mandragora questions: Leafed = 4, Black = 4, and Flowered = 5."] = "質問に葉付き4、黒4、花付き5と答える。",
    ["Return to Naiko-Paneiko (L-8). to complete the quest and receive the Map of Fort Karugo-Narugo."] = "Naiko-Paneiko(L-8)に報告しカルゴナルゴ城砦地図。",
    ["Speak with Rodeupansat (J-7). in Crawlers' Nest (S) and receive the Evil Warding Seal."] = "クロウラーの巣〔Ｓ〕(J-7)のRodeupansatから辟邪の印。",
    ["Travel to Vunkerl Inlet (S) at (D-11)."] = "ブンカール浦〔Ｓ〕(D-11)へ。",
    ["Examine the ??? on the back side of the boarded-up tower window. on the back side of the boarded-up tower window."] = "板で塞がれた塔の窓の裏側の???を調べる。",
    ["Return to Rodeupansat (J-7). in Crawlers' Nest (S) to complete the quest."] = "巣〔Ｓ〕(J-7)のRodeupansatに報告。",
    ["Speak with Ranpi-Monpi (E-9). in Windurst Waters (S)."] = "ウィンダス水の区〔Ｓ〕(E-9)のRanpi-Monpiに話す。",
    ["Travel to present-day Windurst Waters and speak with Ranpi-Monpi there."] = "現代の水の区のRanpi-Monpiへ。",
    ["Obtain Bastore Sweeper, Walnut, Dragon Fruit, and Pepperoni."] = "バストアスイーパー／胡桃／ドラゴンフルーツ／ペパローニを用意。",
    ["Trade all four ingredients to Ranpi-Monpi and wait one Vana'diel day."] = "現代のRanpi-Monpiへ4素材を渡しヴァナ1日待つ。原文は出来上がった料理の受領を省略。",
    ["Return to Ranpi-Monpi in Windurst Waters (S), receive the Culinary Knife, and bring it to the present-day Ranpi-Monpi."] = "水の区〔Ｓ〕のRanpi-Monpiからクッキングナイフを得て現代の本人へ。",
    ["Receive the Trainee Knife reward."] = "トレイニーナイフを受領。",
    ["Speak with Kocco Ehllek (H-8). in Windurst Waters (S)."] = "水の区〔Ｓ〕(H-8)のKocco Ehllekに話す。",
    ["Speak with Rohn Ehlbalna (G-9).."] = "(G-9)のRohn Ehlbalnaに話す。Wiki座標は(F-9)。",
    ["Return to Kocco Ehllek (H-8)., who asks for a piece of kionite."] = "Kocco Ehllek(H-8)に戻り碧い石を頼まれる。",
    ["Examine ??? (F-9). in Vunkerl Inlet (S) to obtain the Piece of Kionite."] = "ブンカール浦〔Ｓ〕(F-9)の???から紺碧石。",
    ["Return the blue stone to Kocco Ehllek (H-8).."] = "Kocco Ehllek(H-8)へ石を渡す。",
    ["Wait until the next Vana'diel day and speak with Kocco Ehllek (H-8). again to receive the reward."] = "翌ヴァナ日、Kocco Ehllek(H-8)から報酬。",
    ["Speak with Miah Riyuh (H-9). in Windurst Waters (S) and exchange the Green Recommendation Letter for putty."] = "水の区〔Ｓ〕(H-9)のMiah Riyuhに翠の紹介状を渡し、原文表記puttyを得る。Wikiではなんでも魔符。",
    ["Travel to West Sarutabaruta (S) and apply the putty to the sealed entrances at (F-4), (F-11), and (J-8)."] = "西サルタバルタ〔Ｓ〕(F-4)／(F-11)／(J-8)のSealed Entranceへ取り付ける。",
    ["Return to Miah Riyuh (H-9). in Windurst Waters (S)."] = "水の区〔Ｓ〕(H-9)のMiah Riyuhに報告。",
    ["Enter Windurst Waters (S) and obtain the Inky Black Yagudo Feather."] = "水の区〔Ｓ〕に入りヤグードの漆黒羽根を得る。",
    ["Speak with Dhea Prandoleh (H-10). in Windurst Waters (S)."] = "水の区〔Ｓ〕(H-10)のDhea Prandolehに話す。",
    ["Travel to West Sarutabaruta (S) and examine ??? at Starfall Hillock (I-6). at Starfall Hillock to obtain the Small Starfruit key item."] = "西サルタバルタ〔Ｓ〕(I-6)星降る丘の???から小さな星の木の実。",
    ["Check the Door: Acolyte Hostel (K-5).."] = "(K-5)のDoor: Acolyte Hostelを調べる。",
    ["Travel to Fort Karugo-Narugo (S) and speak with Rotih Moalghett on the Fivespires map."] = "カルゴナルゴ城砦〔Ｓ〕、Fivespires側マップのRotih Moalghettに話す。",
    ["Exit the fortress and examine ??? (I-9)., then examine it again to face War Lynx."] = "城砦外(I-9)の???を調べ、再調査でWar Lynx。",
    ["Defeat War Lynx."] = "War Lynxを倒す。",
    ["Examine ??? (I-9). again after the battle."] = "戦闘後(I-9)の???を再調査。",
    ["Return to Dhea Prandoleh (H-10). to receive the reward."] = "Dhea Prandoleh(H-10)に報告し報酬。",
    ["Examine the southern Rhinostery door in Windurst Waters (S)."] = "水の区〔Ｓ〕の鼻の院南側の扉を調べる。",
    ["Take a Mythril Beastcoin to Quu Bokye in Giddeus and trade it for the Leather-bound Book."] = "現代ギデアスのQuu Bokyeへ獣人ミスリル貨を渡し革張りの希覯書。",
    ["Return to the Rhinostery door in Windurst Waters (S)."] = "水の区〔Ｓ〕の鼻の院扉へ戻る。",
    ["Examine the Optistery door and obtain the Vellum and Lynx Pelt requirements."] = "目の院の扉を調べベラムと古びたリンクスの皮を頼まれる。",
    ["Trade the Vellum at the Optistery door, then obtain the Lynx Pelt from the ??? in Castle Oztroja (S) at (G-8)."] = "原文は目の院扉へベラムを渡した後、オズトロヤ城〔Ｓ〕(G-8)の???で古びたリンクスの皮を得る順。Wikiの手順順序とは差あり。",
    ["Wait one Vana'diel day and return to the Optistery to receive the Scroll of Retrace."] = "ヴァナ1日待ち目の院でリトレースの巻物。",
    ["Defeat Yagudo near the fortification in Sauromugue Champaign (S) around (K-9) until you obtain a 108-Knot Quipu."] = "ソロムグ原野〔Ｓ〕(K-9)付近の砦周辺のヤグードから百八結節のキープス。",
    ["Check Door: Acolyte Hostel (K-5). in Windurst Waters (S)."] = "水の区〔Ｓ〕(K-5)のDoor: Acolyte Hostelを調べる。",
    ["Travel to Sauromugue Champaign (S) at (F-6) and check Bulwark Gate (F-6). to meet Rachemace."] = "ソロムグ原野〔Ｓ〕(F-6)のBulwark GateでRachemaceに会う。",
    ["Trade the 108-Knot Quipu to Bulwark Gate (F-6).."] = "(F-6)のBulwark Gateへ百八結節のキープスを渡す。",
    ["Check the Bulwark Gate repeatedly until the \"door is firmly sealed\" message appears at least three times."] = "「door is firmly sealed」の表示が3回以上出るまで門を繰り返し調べる、との原文指示。",
    ["Enter Southern San d'Oria (S) from East Ronfaure (S) on foot to meet Pattna-Ottna."] = "東ロンフォール〔Ｓ〕から徒歩で南サンドリア〔Ｓ〕へ入りPattna-Ottnaに会う。",
    ["Go through the Portcullis and check Door: House (M-8). at (M-8) to complete the quest and receive the reward."] = "格子門を抜け(M-8)のDoor: Houseを調べ完了、報酬。",
    ["Speak with Hampu-Kampu in Windurst Waters (S) at (G-8)."] = "水の区〔Ｓ〕(G-8)のHampu-Kampuに話す。",
    ["Examine Door: Acolyte Hostel (K-5). at (K-4) on the upper floor."] = "上階(K-4)のDoor: Acolyte Hostelを調べる。原文の対象ラベルには(K-5)も併記。",
    ["Return to Hampu-Kampu and receive the Torn Patches of Leather key item."] = "Hampu-Kampuからバラバラの革きれ。",
    ["Travel to the Tanners' Guild in present-day Southern San d'Oria and speak with Kipopo."] = "現代の南サンドリア革工ギルドのKipopoへ。",
    ["Obtain Laminated Ram Leather, Sheep Leather, and Silk Thread and trade them to Kipopo."] = "雄羊の撓革／大羊のなめし革／絹糸をKipopoへ渡す。",
    ["Change zones and return to Kipopo to receive the Repaired Handbag."] = "出入りしKipopoから修理された手作りバッグ。",
    ["Return to Hampu-Kampu in Windurst Waters (S) and trade the handbag for the Trainee's Needle reward."] = "水の区〔Ｓ〕のHampu-Kampuに渡しトレイニーニードル。",
    ["Speak with Erlene (J-8). in The Eldieme Necropolis (S) while on a level 30+ job."] = "30以上のジョブでエルディーム古墳〔Ｓ〕(J-8)のErleneに話す。",
    ["Obtain 12 sheets of Vellum."] = "Vellum12枚を用意。",
    ["Trade all 12 Vellum to Erlene (J-8).."] = "Erlene(J-8)へ12枚すべて渡す。",
    ["Change to BLM, RDM, SMN, or BLU and activate Astral Flow, Chainspell, Azure Lore, or Manafont."] = "黒・赤・召・青のいずれかへ変更し、魔力の泉／連続魔／アストラルフロウ／アジュールローの対応SPアビリティを発動。",
    ["While the two-hour ability is active, speak with Erlene (J-8). again."] = "効果中にErlene(J-8)に話す。原文の2時間アビ表記を現行呼称ではSPアビとして表示。",
    ["Receive the Grimoire and Scholar job access."] = "戦術魔道書グリモアを得て学者取得。",
    ["Speak with Heptachiond (H-8). in The Eldieme Necropolis (S)."] = "エルディーム古墳〔Ｓ〕(H-8)のHeptachiondに話す。",
    ["Travel to Fort Karugo-Narugo (S) and reach the Phosphorous Ward at (I-9) on Map 1."] = "カルゴナルゴ城砦〔Ｓ〕マップ1(I-9)のPhosphorous Wardへ。",
    ["Proceed to Map 2 and speak with Pecca-Pocca at (G-12) to receive the Sheaf of Handmade Incense."] = "マップ2(G-12)のPecca-Poccaから慰霊香。",
    ["Return to Heptachiond (H-8). to receive the Scroll of Recall-Meriph."] = "Heptachiond(H-8)に報告しリコールメリファの巻物。",
    ["Speak with Erlene (J-8). and Ulbrecht (J-8). in The Eldieme Necropolis (S)."] = "エルディーム古墳〔Ｓ〕(J-8)のErleneとUlbrechtに話す。",
    ["Complete the required Scholar artifact objectives and combat sequence."] = "学者AFの指定目的と戦闘工程を進める、との原文要約。個別の移動先等は記載なし。Wikiでは手紙を届ける依頼で必須戦闘の記載なし。",
    ["Return to Erlene (J-8). to receive Klimaform."] = "Erlene(J-8)に報告し虚誘掩殺の策。",
    ["Speak with Erlene (J-8). in The Eldieme Necropolis (S)."] = "エルディーム古墳〔Ｓ〕(J-8)のErleneに話す。",
    ["Complete the required Scholar artifact objectives and battlefield."] = "学者AFの指定目的とBFを進める、との原文要約。Wikiの暗転は調査・帽子回収で、必須BFの記載なし。",
    ["Return to Erlene (J-8). to receive the Scholar's Bracers."] = "Erlene(J-8)からスカラーブレーサー。",
    ["Speak with Adelbrecht (E-9). in Bastok Markets (S) and turn in the Blue Recommendation Letter to receive Battle Rations."] = "バストゥーク商業区〔Ｓ〕(E-9)のAdelbrechtへ蒼の紹介状を渡しBattle Rations。Wikiの座標は(E-8)。",
    ["Travel to North Gustaberg (S), ascend Zegham Hill, and speak with Gebhardt (I-6).."] = "北グスタベルグ〔Ｓ〕ゼーガムの丘のGebhardt(I-6)に話す。",
    ["Go to (E-11) and speak with Roderich (E-11).."] = "(E-11)のRoderichに話す。",
    ["Go to (E-7) and interact with Barricade (E-7).."] = "(E-7)のBarricadeを調べる。",
    ["Return to Adelbrecht (E-9).."] = "Adelbrecht(E-9)へ戻る。",
    ["Speak with Gentle Tiger (H-6). in Bastok Markets (S)."] = "商業区〔Ｓ〕(H-6)のGentle Tigerに話す。",
    ["Speak with Engelhart (K-10). in Bastok Markets (S)."] = "商業区〔Ｓ〕(K-10)のEngelhartに話す。",
    ["Travel to Batallia Downs (S) and enter The Eldieme Necropolis (S) via (J-10)."] = "バタリア丘陵〔Ｓ〕(J-10)からエルディーム古墳〔Ｓ〕へ。",
    ["Reach the southern chamber at (G-9), fall through the center hole, and enter the northern room at (I-7)."] = "南の大部屋(G-9)の中央穴から落ち、北の(I-7)の部屋へ。",
    ["Defeat or evade the Orcs and examine the Sarcophagus."] = "オークを倒すか回避しSarcophagusを調べる。",
    ["Return to Gentle Tiger (H-6). in Bastok Markets (S)."] = "商業区〔Ｓ〕のGentle Tiger(H-6)へ報告。",
    ["Speak with Blatherix (F-8). to receive the reward."] = "Blatherix(F-8)から報酬を受け取る。",
    ["Enter Bastok Markets (S) from North Gustaberg (S)."] = "北グスタベルグ〔Ｓ〕から商業区〔Ｓ〕へ入る。",
    ["Speak with Gentle Tiger (H-6).."] = "Gentle Tiger(H-6)に話す。",
    ["Examine Monument on Zegham Hill (J-7). on Zegham Hill in North Gustaberg (S)."] = "北グスタベルグ〔Ｓ〕ゼーガムの丘(J-7)のMonumentを調べる。",
    ["Examine ??? near Witchfire Glen (F-5/H-6 area). inside the cave at (I-6) to complete the quest."] = "(I-6)の洞窟の???を調べ完了。原文はWitchfire Glen付近(F-5/H-6 area)も併記し所在地が不整合。",
    ["Speak with Adelbrecht (E-9).."] = "Adelbrecht(E-9)に話す。",
    ["Travel to the Eduard Watchtower on Zegham Hill in North Gustaberg (S) and speak with Gebhardt (I-6).."] = "北グスタベルグ〔Ｓ〕ゼーガムの丘のエドゥアルト塔でGebhardt(I-6)に話す。",
    ["Speak with Roderich (E-11). at the Benedikt Watchtower."] = "ベネディクト塔のRoderich(E-11)に話す。",
    ["Examine Barricade (E-7). in North Gustaberg (S)."] = "北グスタベルグ〔Ｓ〕(E-7)のBarricadeを調べる。",
    ["Return to Adelbrecht (E-9). to receive the Large Memory Fragment."] = "Adelbrecht(E-9)に戻り想ひ出のかけら。",
    ["Leave Bastok Markets (S) for North Gustaberg (S) at (G-4) and obtain the Clump of Animal Hair."] = "商業区〔Ｓ〕(G-4)から北グスタベルグ〔Ｓ〕へ出て獣毛の束。",
    ["Deliver the Clump of Animal Hair to Engelhart (K-10). in Bastok Markets (S)."] = "商業区〔Ｓ〕(K-10)のEngelhartへ届ける。",
    ["Travel to the waterfall in North Gustaberg (S) at (F-8) and examine the ???."] = "北グスタベルグ〔Ｓ〕(F-8)の滝近くの???へ。",
    ["Obtain a Gnole Claw."] = "ノールの爪を用意。",
    ["Travel to Vunkerl Inlet (S) and trade the Gnole Claw to Leadavox (J-6). for the Xhifhut key item."] = "ブンカール浦〔Ｓ〕(J-6)のLeadavoxにノールの爪を渡しシフート。",
    ["Return to Engelhart (K-10). in Bastok Markets (S)."] = "商業区〔Ｓ〕(K-10)のEngelhartに戻る。",
    ["Speak with Pagdako (H-9).."] = "Pagdako(H-9)に話す。",
    ["Travel to present-day Metalworks and speak with Iron Eater in the President's Office at (J-8)."] = "現代の大工房(J-8)、大統領執務室のIron Eaterに話す。",
    ["Return to the past and speak with Engelhart (K-10). again."] = "過去へ戻りEngelhart(K-10)に話す。",
    ["Travel to Grauberg (S) and examine ??? near Witchfire Glen (F-5/H-6 area). inside the cave at (I-6)."] = "グロウベルグ〔Ｓ〕(I-6)の洞窟の???を調べる。原文のWitchfire Glen付近(F-5/H-6 area)表記とは不整合。",
    ["Return to Bastok Markets (S) and speak with Engelhart (K-10).."] = "商業区〔Ｓ〕のEngelhart(K-10)に戻る。",
    ["Travel to the Metalworks gate area and speak with Gentle Tiger (H-6).."] = "大工房入口のGentle Tiger(H-6)に話す。",
    ["Return to Engelhart (K-10). to complete the quest."] = "Engelhart(K-10)に報告し完了。",
    ["Speak with Scarred Shark (G-5). in Bastok Markets (S)."] = "商業区〔Ｓ〕(G-5)のScarred Sharkに話す。",
    ["Obtain a Heavy Quadav Chestplate and Heavy Quadav Backplate."] = "クゥダフの超重胸甲とクゥダフの超重背甲を用意。",
    ["Trade both armor pieces to Scarred Shark (G-5).."] = "Scarred Shark(G-5)へ両方渡す。",
    ["Change zones and speak with Scarred Shark (G-5). again to receive the Trainee Hammer."] = "出入りしScarred Shark(G-5)からトレイニーハンマー。",
    ["Trade with Blatherix (F-8).: either 30 Goblin Chocolate or 5,000 gil for the Mine Shaft Key."] = "Blatherix(F-8)へGoblin Chocolate30個か5,000ギルを渡し鉱山の坑道のカギ。",
    ["Enter Pashhow Marshlands (S) from Grauberg (S)."] = "グロウベルグ〔Ｓ〕からパシュハウ沼〔Ｓ〕へ入る。",
