    ["Receive the Republican Silver Medal reward."] = "共和シルバー章を受領。原文はGentle Tigerへの完了会話を省略。",
    ["Wait one Vana'diel day after Fire in the Hole, then enter Bastok Markets (S) from North Gustaberg (S)."] = "隠滅の炎後ヴァナ1日待ち、北グスタベルグ〔Ｓ〕から商業区〔Ｓ〕へ入る。",
    ["Speak with Gentle Tiger (H-6). at the Metalworks entrance in Bastok Markets (S)."] = "大工房入口のGentle Tiger(H-6)に話す。原文は住民3人への聞き込みを省略。",
    ["Obtain Goblin Mess Tin, Goblin Mushpot, and Twinkle Powder."] = "ゴブリンメスティン／ゴブリン風キノコ鍋／ツインクルパウダーを用意。",
    ["Return to Blatherix (F-8). and trade all three items."] = "Blatherix(F-8)へ3品すべて渡す。",
    ["Return to Gentle Tiger (H-6).."] = "Gentle Tiger(H-6)に戻る。",
    ["Travel to Vunkerl Inlet (S) at (F-6) and examine ??? at Vunkerl Inlet (S) (F-6).."] = "ブンカール浦〔Ｓ〕(F-6)の???を調べる。",
    ["Speak with Blatherix (F-8). in Bastok Markets (S) to receive the Goblin Belt."] = "商業区〔Ｓ〕のBlatherix(F-8)からゴブリンベルト。",
    ["Travel to Vunkerl Inlet (S) and examine ??? at Vunkerl Inlet (S) (F-6)., just east of the bridge."] = "ブンカール浦〔Ｓ〕、橋のすぐ東(F-6)の???を調べる。",
    ["Examine Beastman Ensign (J-7).."] = "(J-7)のBeastman Ensignを調べる。",
    ["Return to Gentle Tiger (H-6). and receive a Flare Grenade."] = "Gentle Tiger(H-6)から試製閃光手榴弾。",
