    ["Speak with Red Axe (I-8). in The Eldieme Necropolis (S)."] = "エルディーム古墳〔Ｓ〕(I-8)のRed Axeに話す。原文は途中のGentle Tiger会話を省略。",
    ["Travel to Vunkerl Inlet (S) and trade Beeswax and Red Textile Dye to Leadavox (J-6). for the Wax Seal."] = "ブンカール浦〔Ｓ〕(J-6)のLeadavoxへ蜜蝋とテキスタイルダイＲを渡し封蝋。",
    ["Return to Red Axe (I-8). in The Eldieme Necropolis (S)."] = "古墳〔Ｓ〕(I-8)のRed Axeに戻る。",
