    ["Speak with Gentle Tiger (H-6). in Bastok Markets (S) and receive the Sack of Victuals key item."] = "商業区〔Ｓ〕のGentle Tiger(H-6)から食糧の入った布袋。",
    ["Travel to Benedikt Watchtower in North Gustaberg (S) and speak with Roderich (E-11).."] = "北グスタベルグ〔Ｓ〕ベネディクト塔のRoderich(E-11)に話す。",
    ["Travel to Xarcabard (S) and obtain the Commander's Endorsement key item."] = "ザルカバード〔Ｓ〕へ入り青の奉書。",
    ["Examine Forbidding Portal (I-7)., then examine it again to enter battle."] = "(I-7)のForbidding Portalを調べ、再調査で戦闘。",
    ["Defeat the humanoid opponent."] = "人型の相手を倒す。",
    ["Return to Gentle Tiger (H-6). to receive the Fourth Staff."] = "Gentle Tiger(H-6)に報告しフォーススタッフ。",
    ["Obtain an Elixir."] = "エリクサーを用意。",
    ["Enter Castle Zvahl Baileys (S)."] = "ズヴァール城外郭〔Ｓ〕へ入る。",
