    ["Examine ??? in the southwest room (G-9). in the southwest room on Map 3."] = "マップ3南西の部屋(G-9)の???を調べる。",
    ["Drop down, use the center teleporter, and examine Displaced Block. to complete the quest and receive the reward."] = "下へ降り中央転送装置を使いDisplaced Blockを調べ完了。",
    ["Speak with Mainchelite (I-9). in Southern San d'Oria (S) and turn in the Red Recommendation Letter."] = "南サンドリア〔Ｓ〕(I-9)のMaincheliteへ紅の紹介状を渡す。",
    ["Travel to East Ronfaure (S) and collect the Charred Propeller at (H-8), Oxidized Plate at (I-8), and Piece of Shattered Lumber at (J-7)."] = "東ロンフォール〔Ｓ〕(H-8)のCharred Propeller、(I-8)のOxidized Plate、(J-7)のPiece of Shattered Lumberを集める。",
    ["Return to Mainchelite (I-9).."] = "Mainchelite(I-9)に戻る。",
    ["Speak with Wyatt (L-6). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕(L-6)のWyattに話す。",
    ["Obtain 4 Ladybug Wings."] = "Ladybug Wing4枚を用意。",
    ["Trade the 4 Ladybug Wings to Wyatt (L-6). to receive the reward."] = "Wyatt(L-6)へ4枚渡し報酬。",
    ["Speak with Louxiard (G-7). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕(G-7)のLouxiardに話す。",
    ["Leave the area and return to Louxiard (G-7).."] = "出入りしてLouxiard(G-7)へ戻る。",
    ["Speak with Rholont (E-7).."] = "Rholont(E-7)に話す。",
    ["Trade Plumes d'Or to Machionage (C-6), Louxiard (G-7), Illeuse (H-9), Rongelouts N Distaud (I-9), Sabiliont (I-11), Elnonde (K-9), and Loillie (K-9 via the stairs at L-8)."] = "金の羽根をMachionage(C-6)、Louxiard(G-7)、Illeuse(H-9)、Rongelouts N Distaud(I-9)、Sabiliont(I-11)、Elnonde(K-9)、Loillie(K-9 via the stairs at L-8)へ。最後はL-8の階段経由。",
    ["Return to Rholont (E-7).."] = "Rholont(E-7)へ戻る。",
    ["Wait one Vana'diel day after Gifts of the Griffon."] = "少年たちの贈り物後ヴァナ1日待つ。",
    ["Speak with Rholont (E-7). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕のRholont(E-7)に話す。",
