    ["Defeat Fingerfilcher Dradzad."] = "Fingerfilcher Dradzadを倒す。",
    ["Examine ??? tree stump (I-6). again to complete the quest."] = "(I-6)の???を再調査して完了。",
    ["Speak with Raustigne (I-7). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕(I-7)のRaustigneに話す。",
    ["Travel to Vunkerl Inlet (S) at (H-6) and examine ??? near the bridge (H-6). near the bridge to obtain the Vunkerl Herb Memo."] = "ブンカール浦〔Ｓ〕(H-6)橋付近の???からブンカール浦薬草メモ。",
    ["Determine the correct herb color from the current time: Red/Sandy 00:00-07:59, Blue/Bastok 08:00-15:59, Green/Windurst 16:00-23:59."] = "原文の時刻判定：00:00-07:59は赤／サンドリア、08:00-15:59は青／バストゥーク、16:00-23:59は緑／ウィンダス。",
    ["Travel to Vunkerl Inlet (S) at (F-5), find Leafy Patch (F-5)., and select the correct color."] = "ブンカール浦〔Ｓ〕(F-5)のLeafy Patchで正しい色を選ぶ。",
    ["Obtain the Vunkerl Herb from the Leafy Patch."] = "Leafy Patchからブンカール浦の野草。",
