    ["Speak with Thierride (F-8). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕(F-8)のThierrideに話す。",
    ["Obtain 2 Lufet Salts from River Crabs in West Ronfaure."] = "西ロンフォールのRiver CrabからLufet Salt2個。",
    ["Return to Thierride (F-8). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕のThierride(F-8)に戻る。",
    ["Trade one Lufet Salt, then another, to complete the required sequence."] = "塩を1個ずつ2回渡す。",
    ["Change zones and return to Thierride (F-8). to receive the Angler's Cassoulet reward."] = "出入りしThierride(F-8)から漁師風カスレー。",
    ["Wait one Vana'diel day after Wrath of the Griffon, then change zones and speak with Rholont (E-7). in Southern San d'Oria (S)."] = "ちいさな勝利、ひとつの決意後ヴァナ1日待ち、出入りして南サンドリア〔Ｓ〕のRholont(E-7)に話す。",
