    ["Speak with Daigraffeaux (I-11). in Southern San d'Oria (S)."] = "南サンドリア〔Ｓ〕(I-11)のDaigraffeauxに話す。",
    ["Travel to Jugner Forest (S) at (I-6) and examine ??? tree stump (I-6). to obtain the Orcish Warmachine Body key item."] = "ジャグナー森林〔Ｓ〕(I-6)の切り株の???からオーク戦車の装甲。原文は途中のRholont会話と納品を省略。",
    ["Enter Beaucedine Glacier (S) and examine Colossal Footprint (I-7). behind the tower."] = "ボスディン氷河〔Ｓ〕へ入り、塔裏(I-7)のColossal Footprintを調べる。",
    ["Examine Rocky Perch (G-10). at the lake at least three times to obtain the Goliath Worm items."] = "湖(G-10)のRocky Perchを3回以上調べゴライアスワーム。",
    ["Fish for Paladin Lobster at (G-10), Scutum Crab at (J-7), and Lance Fish at (H-9)."] = "(G-10)でアーマードロブスター、(J-7)でシールドクラブ、(H-9)でハープーンフィッシュを釣る。",
    ["Return to Colossal Footprint (I-7). and submit the required key items."] = "Colossal Footprint(I-7)に戻り必要品を渡す。",
    ["Trade a Flint Stone to Charred Firewood. two levels above and north of the (I-7) tower."] = "(I-7)の塔から北へ2段上がりCharred Firewoodへ火打石を渡す。",
    ["Examine Compressed Snow (H-10). near the tower, then examine it again to face Orcish Bloodletter."] = "塔付近(H-10)のCompressed Snowを調べ、再調査でOrcish Bloodletter。",
    ["Defeat Orcish Bloodletter and examine Compressed Snow (H-10). a third time to complete the quest."] = "倒して(H-10)を3回目に調べ完了。",
    ["Speak with Rongelouts N Distaud in Southern San d'Oria (S) at (I-9)."] = "南サンドリア〔Ｓ〕(I-9)のRongelouts N Distaudに話す。",
    ["Enter Xarcabard (S) from Beaucedine Glacier (S)."] = "ボスディン氷河〔Ｓ〕からザルカバード〔Ｓ〕へ。",
    ["Examine Backfilled Pit (F-8).."] = "(F-8)のBackfilled Pitを調べる。",
    ["Examine Compact Footprint (H-8).."] = "(H-8)のCompact Footprintを調べる。",
    ["Examine Sunken Footprint (H-6/H-7). up the northwest ramp."] = "北西の坂上(H-6/H-7)のSunken Footprintを調べる。",
    ["Examine Compact Footprint (H-8). again."] = "(H-8)のCompact Footprintを再調査。",
    ["Enter Batallia Downs (S) from Beaucedine Glacier (S)."] = "ボスディン氷河〔Ｓ〕からバタリア丘陵〔Ｓ〕へ。",
    ["Examine Fresh Snowmelt (H-5).."] = "(H-5)のFresh Snowmeltを調べる。",
    ["Examine Fresh Snowmelt (H-5). again to face NM Menechme and defeat it with Excenmille within 30 minutes."] = "(H-5)を再調査しExcenmilleと共に30分以内にMenechmeを倒す。",
    ["Examine Fresh Snowmelt (H-5). one final time to complete the quest and receive the reward."] = "(H-5)を最後に調べ完了、報酬。",
    ["Enter Southern San d'Oria from East Ronfaure."] = "現代の東ロンフォールから南サンドリアへ。",
    ["Complete Her Memories: Old Bean, Her Memories: The Faux Pas, and Her Memories: Grave Resolve."] = "彼女の想ひ出～涙の豆料理／彼女の想ひ出～彼と少女の事情／彼女の想ひ出～墓前の決意を完了する。",
    ["The three Tiny Memory Fragments combine into the Large Memory Fragment and complete the quest."] = "小さな想ひ出のかけら3つが想ひ出のかけらになり完了。",
    ["Enter Southern San d'Oria (S) from East Ronfaure (S)."] = "東ロンフォール〔Ｓ〕から南サンドリア〔Ｓ〕へ。",
    ["Speak with Mainchelite (I-9). to begin the quest."] = "Mainchelite(I-9)に話し受領。",
    ["Enter East Ronfaure (S) on foot."] = "徒歩で東ロンフォール〔Ｓ〕へ出る。",
    ["Examine the designated ??? at (J-7), (I-8), and (H-8) to complete the three required steps."] = "(J-7)／(I-8)／(H-8)の指定???を調べ3工程を終える。",
    ["Return to Mainchelite (I-9). to receive the Large Memory Fragment."] = "Mainchelite(I-9)に報告し想ひ出のかけら。",
    ["Speak with Amaura (G-6). in Southern San d'Oria (S)."] = "原文では南サンドリア〔Ｓ〕(G-6)のAmaura。Wikiは現代の南サンドリア。",
    ["Speak with Monberaux (G-10). in Upper Jeuno."] = "ジュノ上層(G-10)のMonberauxに話す。",
    ["Examine the Library Book in the Optistery in Windurst Waters at (G-7)."] = "現代の水の区(G-7)、目の院のLibrary Bookを調べる。Wiki掲載座標は(G-8)。",
    ["Obtain a Philosopher's Stone."] = "賢者の石を用意。",
    ["Trade the Philosopher's Stone to Fey Blossoms (F-5). in Grauberg (S)."] = "グロウベルグ〔Ｓ〕(F-5)のFey Blossomsへ渡す。",
    ["Wait one Vana'diel day and change zones."] = "ヴァナ1日待ち、エリアチェンジする。",
    ["Examine Fey Blossoms (F-5). again to receive the key item."] = "Fey Blossoms(F-5)を再調査しだいじなもの。",
    ["Speak with Raustigne (I-7). in Southern San d'Oria (S) to receive the Large Memory Fragment."] = "南サンドリア〔Ｓ〕(I-7)のRaustigneに話し想ひ出のかけら。",
    ["Speak with Rarcasmeult in Garlaige Citadel (S) at (J-6)."] = "ガルレージュ要塞〔Ｓ〕(J-6)のRarcasmeultに話す。",
    ["Proceed to the Storeroom Door at (G-7) on the second map."] = "マップ2(G-7)のStoreroom Doorへ。",
