    ["Speak with Fondactiont in Garlaige Citadel (S) at (I-6)."] = "ガルレージュ要塞〔Ｓ〕(I-6)のFondactiontに話す。",
    ["Travel to Grauberg (S)."] = "グロウベルグ〔Ｓ〕へ。",
    ["Examine the ??? in the waterfall area at (G-6) to obtain the Ornate Package."] = "(G-6)の滝付近の???から装飾された小包。",
    ["Return to Fondactiont to receive the Scroll of Recall-Pashh."] = "Fondactiontに報告しリコールパシュの巻物。",
    ["Speak with Diordinne at (I-6) in Garlaige Citadel (S) Map 1 and receive the Number Eight Shelter Key."] = "ガルレージュ要塞〔Ｓ〕マップ1(I-6)のDiordinneから8番壕のカギ。",
    ["Travel east to Map 2 and examine Wooden Crates (H-9). to enter Ghoyu's Reverie; the party leader must perform this examination."] = "東のマップ2(H-9)のWooden Cratesをリーダーが調べ、ゴユの空洞へ。",
    ["Locate and defeat Orcish Turret at approximately (H-10) on Map 15 within 30 minutes."] = "原文ではマップ15(H-10)付近のOrcish Turretを30分以内に倒す。",
    ["Manage the Goblin Effluvial Grenade attacks and poison effects during the battle."] = "ゴブリンのEffluvial Grenadeと毒に対処。",
    ["Return to Southern San d'Oria (S) between 18:00 and 00:00."] = "18:00〜00:00に南サンドリア〔Ｓ〕へ戻る。",
    ["Speak with Rholont (E-7). to complete the quest and receive the Fullmetal Bullet."] = "Rholont(E-7)に報告してフルメタルブレット。",
    ["Wait one Vana'diel day after In a Haze of Glory, then change zones."] = "それぞれの死地へ後ヴァナ1日待ち出入りする。",
    ["Obtain Ronfaure Maple Syrup by logging in East Ronfaure (S), Long-life Biscuits from the Tree Hollow behind Rholont (E-7)., and a Flask of Kingdom Water from the Well east of Rholont (E-7).."] = "東ロンフォール〔Ｓ〕の伐採でメープルの樹液、Rholont(E-7)背後のTree Hollowから特製ビスケット、東側のWellから王都の地下水。",
    ["Speak with Rholont (E-7). again to receive Biscuit a la Rholont."] = "Rholont(E-7)に話しビスケットサンド。",
    ["Examine Felled Trees (G-7).."] = "(G-7)のFelled Treesを調べる。",
    ["Examine the first Toppled Cresset at (I-8), then the second at (F-9)/(F-8) in Vunkerl Inlet (S)."] = "ブンカール浦〔Ｓ〕(I-8)のToppled Cresset、続いて(F-9)/(F-8)の同名対象を調べる。",
    ["Examine Underbrush (F-13)., then examine it again to face Madthrasher Zradbodd."] = "(F-13)のUnderbrushを調べ、再調査でMadthrasher Zradbodd。",
    ["Defeat Madthrasher Zradbodd and examine the Underbrush again for the instructions leading to Pashhow Marshlands (S)."] = "倒してUnderbrushを再調査、パシュハウ沼〔Ｓ〕へ向かう。",
    ["Examine Shimmering Pondweed (G-6). in Pashhow Marshlands (S) to complete the quest and receive the reward."] = "パシュハウ沼〔Ｓ〕(G-6)のShimmering Pondweedで完了、報酬。",
    ["Speak with Rholont (E-7). in Southern San d'Oria (S) and receive the Letter to Count Aurchiat."] = "南サンドリア〔Ｓ〕のRholont(E-7)からオルシャー卿宛ての書状。",
    ["Travel to Pashhow Marshlands (S) and examine Shimmering Pondweed (G-6).."] = "パシュハウ沼〔Ｓ〕(G-6)のShimmering Pondweedへ。",
    ["Follow the quest route into Jugner Forest (S) and gather the required logging key items."] = "依頼経路に従いジャグナー森林〔Ｓ〕へ進み、伐採で指定だいじなものを集める。原文に個別地点・手順の記載なし。",
    ["Proceed to the designated battlefield and defeat the Young Behemoth encounter."] = "指定BFへ進みYoung Behemothとの戦いに勝つ。原文に突入口の記載なし。",
    ["Complete the follow-up event after the battlefield victory."] = "勝利後のイベントを終える。",
    ["Report to Rongelouts N Distaud in Southern San d'Oria (S) to receive the Behemoth Horn reward."] = "南サンドリア〔Ｓ〕のRongelouts N Distaudへ報告しベヒーモスの角。",
    ["Examine Animal Spoor (J-9). in Xarcabard (S) and register the Home Point at (H-9)."] = "ザルカバード〔Ｓ〕(J-9)のAnimal Spoorを調べ、(H-9)のHome Pointを登録。",
    ["Examine Wheel Rut (I-9). in the dead-end tunnel to the south."] = "南の行き止まり(I-9)のWheel Rutを調べる。",
    ["Examine Animal Spoor (J-9). again to obtain the Vial of Military Prism Powder key item."] = "Animal Spoor(J-9)を再調査し軍用プリズムパウダー。",
    ["Examine Forbidding Portal (I-7). to enter the battlefield."] = "(I-7)のForbidding PortalからBFへ。",
    ["Defeat 2 Bloodwing Deathrainers, 4 Bloodwing Maimers, Gherrmoga, and Kingslayer Doggvdegg. Excenmille assists, and defeating Doggvdegg ends the battle."] = "Bloodwing Deathrainer2体、Bloodwing Maimer4体、Gherrmoga、Kingslayer Doggvdeggと戦う。Excenmilleが加勢し、Doggvdeggを倒せば終了。",
    ["Examine Wheel Rut (I-9). again to complete the quest and receive the Ram Staff."] = "Wheel Rut(I-9)を再調査してラムスタッフで完了。",
    ["Enter Castle Zvahl Baileys (S) from Castle Zvahl Keep (S)."] = "ズヴァール城内郭〔Ｓ〕から外郭〔Ｓ〕へ出る。",
    ["Defeat all four imps in the central room on Map 3."] = "内郭マップ3中央のインプ4体を倒す。原文は事前の???イベントを省略。先に倒すと進まない点に注意。",
    ["Examine ??? in the southwest room (G-9). again to face Gargouille Warden; defeat it and examine the ??? again to obtain the Zvahl Passkey."] = "南西(G-9)の???からGargouille Wardenを出し、倒して再調査し王の間のカギ。",
    ["Enter Throne Room (S) and examine the Throne Room door."] = "王の間〔Ｓ〕へ入り王の間の扉を調べる。",
    ["Examine the Throne Room door again to enter battle and defeat the humanoid opponent with Zeid assisting."] = "再調査でBFへ。Zeidと共に人型の相手を倒す。",
    ["Defeat Marquis Amon."] = "Marquis Amonを倒す。",
    ["Speak with Gentle Tiger (H-6). in Bastok Markets (S) to complete the quest and receive the Excelsis Ring."] = "商業区〔Ｓ〕のGentle Tiger(H-6)に報告しエクセルシスリングで完了。",
    ["Bring the Bundle of half-inscribed scrolls to Gentle Tiger (H-6). to obtain Trust: Klara."] = "Gentle Tiger(H-6)へ未完成のスクロール束を持参しフェイス：Klara。原文の追加報酬工程。",
    ["Enter Southern San d'Oria from East Ronfaure to begin the Her Memories sequence."] = "現代の東ロンフォールから南サンドリアへ入り彼女の想ひ出連続依頼を開始。",
    ["Speak with Thierride (F-8). in the Rusty Anchor Pub in Port San d'Oria."] = "サンドリア港の錆びた錨亭(F-8)のThierrideに話す。Wikiは(G-7)。原文は料理をAmauraへ届けて戻る工程を省略。",
    ["Receive the Tiny Memory Fragment and continue the Her Memories chain."] = "小さな想ひ出のかけらを得て連続依頼を進める。",
    ["Speak with Abioleget in the Cathedral in Northern San d'Oria at (M-7)."] = "北サンドリア(M-7)大聖堂のAbiolegetに話す。",
    ["Speak with Bertenont (E-4). in Northern San d'Oria."] = "北サンドリア(E-4)のBertenontに話す。",
    ["Receive the Tiny Memory Fragment."] = "小さな想ひ出のかけらを得る。",
    ["Enter Batallia Downs (S) from Jugner Forest (S)."] = "ジャグナー森林〔Ｓ〕からバタリア丘陵〔Ｓ〕へ。",
    ["Examine the Bulwark Gate in Sauromugue Champaign (S) at (E-6)."] = "ソロムグ原野〔Ｓ〕(E-6)のBulwark Gateを調べる。Wikiは(F-6)。",
    ["Obtain Rice Vinegar, Ground Wasabi, and Holy Basil."] = "ライスビネガー／ねりわさび／ホーリーバジルを用意。",
    ["Travel to Vunkerl Inlet (S) and trade all three ingredients to Leadavox (J-6). to receive the Pot of Martial Relish."] = "ブンカール浦〔Ｓ〕(J-6)のLeadavoxへ3品を渡し特製スパイス。",
    ["Examine the Bulwark Gate in Sauromugue Champaign (S) at (E-6) again."] = "ソロムグ原野〔Ｓ〕(E-6)のBulwark Gateへ戻る。",
    ["Enter Batallia Downs (S) from Rolanberry Fields (S) to receive the Large Memory Fragment."] = "ロランベリー耕地〔Ｓ〕からバタリア丘陵〔Ｓ〕へ入り想ひ出のかけら。",
