    -- Other quests: original JP summaries; ID-scoped fame requirements.
    ["Speak with Nereus in Mhaura (I-8), near the Proto-Waypoint, to begin the quest. You need Windurst fame level 5. Nereus seeks a dish of Gusgen clay from the depths of the Gusgen Mines."] = "マウラ(I-8)、Proto-Waypoint付近のNereusに話す。ウィンダス名声5が必要。グスゲン鉱山の奥で採れる土を頼まれる。",
    ["Obtain a Gusgen Clay from the Gusgen Mines."] = "グスゲン鉱山でグスゲン鉱山の土を入手する。",
    ["Bring the Gusgen Clay to Nereus for your reward, 2,160 gil. You can repeat the quest."] = "Nereusへ土を届けて2,160ギルを受け取る。繰り返し可能。",
    ["Wait 8 Vana'diel days after completing His Name Is Valgeir to begin this quest. Speak with Take in Mhaura (I-8), inside the Sailor's Stay. She wants you to bring back one of Valgeir's dishes from Selbina."] = "「その名はヴァルゲール」後、ヴァナ時間8日待つ。マウラ(I-8)の船乗りの宿でTakeに話し、セルビナのValgeirの料理を頼まれる。",
    ["Speak with Valgeir in Selbina (I-9), inside the Shepherd's Muster."] = "セルビナ(I-9)、羊飼いの溜まり場のValgeirに話す。",
    ["Obtain 1 Scream Fungus and 1 Land Crab Meat and trade them to Valgeir."] = "サケビタケと陸ガニの肉を各1個用意し、Valgeirに渡す。",
    ["Bring the dish back to Take for your reward, the Tableware Set, and the title Three-Star Purveyor."] = "Takeに料理を届けて食器一式と称号Three-Star Purveyorを得る。",
    ["You need to wait two, possibly three game days after completing Unending Chase before this quest is offered. Speak with Rycharde in Mhaura (I-8). He gives you an Aragoneu pizza to deliver to his father, Valgeir, in Selbina."] = "「飽くなき追求」後、ヴァナ時間2～3日待つ。マウラ(I-8)のRychardeから、セルビナの父Valgeirに届けるアラゴーニュピザを預かる。",
    ["Rycharde pays your fare for the next Ferry between Mhaura and Selbina if you choose to take it."] = "次のマウラ～セルビナ航路に乗る場合、Rychardeが船賃を負担する。",
    ["Deliver the pizza to Valgeir in Selbina (I-9)."] = "セルビナ(I-9)のValgeirにピザを届ける。",
    ["Return to Rycharde for your reward, the Map of the Toraimarai Canal."] = "Rychardeに報告し、トライマライ水路地図を受け取る。",
    ["Speak with Fyi Chalmwoh in the Goldsmithing shop in Mhaura (G-8) to begin the quest, then speak to her again. You need Windurst fame level 4. She wants to build a mannequin that rivals those of times past, and it is your job to gather information on how to make one."] = "ウィンダス名声4が必要。マウラ(G-8)の彫金ギルドでFyi Chalmwohに話し、もう一度話す。昔のものに負けないマネキン作りの情報集めを頼まれる。",
    ["Speak with Ramona in Selbina (H-9) to receive the Mannequin joint diagrams."] = "セルビナ(H-9)のRamonaに話し、Mannequin joint diagramsを入手する。",
    ["Gather all 5 Mannequin pieces and trade them to Fyi Chalmwoh. They can also be bought from player bazaars."] = "マネキンの部品5種をそろえてFyi Chalmwohに渡す。プレイヤーのバザーでも購入できる。",
    ["Zone and speak with Fyi Chalmwoh again to receive your reward, a mannequin matching your race and gender."] = "エリアを切り替えてFyi Chalmwohに話し、自分の種族・性別に合うマネキンを受け取る。",
    ["Speak with Orlando in Mhaura (G-9) to begin the quest. Find where the Goblins bury their junk: he is interested in the items that Goblin Diggers tend to bury if left undisturbed."] = "マウラ(G-9)のOrlandoに話す。放置したGoblin Diggerが埋めるガラクタに関心があるため、埋められた場所を探す。",
    ["Trade Orlando eight of any one of the items to complete the quest and receive 100 to 900 gil, depending on the item. You can repeat the quest."] = "対象品のうち同じもの8個をOrlandoに渡す。品に応じて100～900ギルを得る。繰り返し可能。",
    ["Speak with Keshab-Menjab at the lower level of Mhaura (H-9) to begin the quest. You need Other fame level 1. You have been asked to help bring in cleanly snapped rods for recycling; the recycled rods are supposedly sold somewhere around Bibiki Bay."] = "マウラ下層(H-9)のKeshab-Menjabに話す。その他名声1が必要。リサイクル用のきれいに折れた竿を頼まれる。再生品はビビキー湾付近で売られるらしい。",
    ["Obtain a Clean Snap Rod. You can speak to Keshab-Menjab again for some additional dialogue."] = "綺麗な折れ口の釣竿を入手する。Keshab-Menjabに再度話すと追加の会話を聞ける。",
    ["Return the rod to Keshab-Menjab to complete the quest and receive 1,500 gil."] = "竿をKeshab-Menjabに届けて1,500ギルを得る。",
    ["Speak with Rycharde in Mhaura (I-8) to begin the quest. He needs your help to find some dhalmel meat."] = "マウラ(I-8)のRychardeに話し、ダルメルの肉の調達を頼まれる。",
    ["Obtain 2 Dhalmel Meat and trade them to Rycharde to complete the quest. You receive 1,500 gil and the title Purveyor in Training."] = "ダルメルの肉を2個Rychardeに渡す。1,500ギルと称号「食材調達人見習い」を得る。",
    ["Speak with Ripapa in Mhaura (I-9) to obtain the quest. You need Mhaura fame level 6. Warning: Trust Magic cannot be used in this battlefield. Once you have the key item Tuning fork of lightning, you can safely undertake the quest, and every party member needs their own."] = "マウラ名声6が必要。マウラ(I-9)のRipapaから雷の音叉を受け取る。BFではフェイス不可。参加者全員が自分の音叉を用意する。",
    ["Ring the tuning fork upon the Lightning Protocrystal in the Boyahda Tree. Up to 6 party members can enter the arena, and the time limit is 30 minutes."] = "ボヤーダ樹のLightning Protocrystalで音叉を使う。最大6人、制限時間30分。",
    ["Defeat Ramuh Prime to receive the key item Whisper of storms."] = "Ramuh Primeを倒し、だいじなもの「雷の息吹」を得る。",
    ["Return to Ripapa with the whisper and she offers several reward options, including the ability to summon Ramuh. You can only select one of the rewards at any time, and you may repeat this quest once per Earth day."] = "Ripapaに息吹を届ける。ラムウ召喚などの報酬から1つ選べる。地球時間1日ごとに再挑戦可能。",
    ["To save travel time to the Cloister, use the Mini Fork of Ltn. given by Trial-Size Trial by Lightning: be on Summoner as your main job, get the Mini Tuning Fork from Lacia, trade it back to her, and enter the Protocrystal normally."] = "回廊への移動短縮には「雷の試練・改」の雷の音叉・改を使う。メインを召喚士にし、Laciaから音叉・改を受け取って渡し直し、通常どおりプロトクリスタルへ入る。",
    ["You need to be a Summoner of level 20 or higher and have Other fame level 2. Speak with Lacia in Mhaura (I-9) to begin the quest and obtain a Mini Tuning Fork of Lightning."] = "召喚士20以上、その他名声2が必要。マウラ(I-9)のLaciaから雷の音叉・改を受け取る。",
    ["You may prepare for the upcoming battle and, whenever you are ready, trade Lacia the tuning fork to be transported to the arena."] = "準備ができたらLaciaに音叉を渡して闘技場へ転送してもらう。",
    ["Trade the fork to the Lightning Protocrystal to enter the fighting arena."] = "Lightning Protocrystalに音叉を渡し、BFへ入る。",
    ["Defeat Ramuh Prime to complete the quest. Only Carbuncle may be used for this battle; Siren can also be used, but that seems unintended."] = "Ramuh Primeを倒す。この戦闘で使えるのはカーバンクルのみ。原文にはセイレーンも使えるが意図した仕様ではなさそうとの注意がある。",
    ["You may re-obtain the Mini Tuning Fork from Lacia at any point if you want to repeat the fight, but she will no longer teleport you to the Cloister."] = "再戦する場合、Laciaから音叉・改を再取得できる。ただし以後は回廊へ転送してもらえない。",
    ["You need to wait 8 real-life hours after completing The Clue before this quest is offered. Speak with Rycharde in Mhaura (I-8), who asks you to take Mhauran couscous to Valgeir in Selbina."] = "「手がかり」後、地球時間8時間待つ。マウラ(I-8)のRychardeから、セルビナのValgeirへマウラ風クスクスを届けるよう頼まれる。",
    ["Rycharde offers to buy you a ticket for the next Ferry between Mhaura and Selbina, but you can travel to Selbina any way you choose."] = "Rychardeが次のセルビナ行きの船賃を出してくれるが、ほかの移動手段でもよい。",
    ["Deliver the dish to Valgeir in Selbina (I-9) and report back to Rycharde on how he liked it."] = "セルビナ(I-9)のValgeirへ料理を届け、Rychardeに感想を報告する。",
    ["Speak with Rycharde in Mhaura (H-8). This quest follows Expertise. He seeks an ingredient known as Crawler's Eggs."] = "「その腕前」後、マウラ(H-8)のRychardeに話す。蟲の卵の調達を頼まれる。",
    ["Obtain Crawler's Eggs and bring them to Rycharde to complete the quest. You receive 3,000 gil and the title Four-Star Purveyor."] = "蟲の卵をRychardeに届け、3,000ギルと称号Four-Star Purveyorを得る。",
    ["Speak with Vera in Mhaura (G-10). You need to be level 18 or higher. Fulfill her request if you want the promised rewards."] = "レベル18以上でマウラ(G-10)のVeraに話し、依頼を引き受ける。",
    ["Obtain a Bloody Robe, a Dhalmel Saliva and a Wild Rabbit Tail and bring them to Vera."] = "血染めの衣、ダルメルの唾液、野兎の尻尾を入手し、Veraに渡す。",
    ["Completing the quest unlocks your Support Job."] = "クリアするとサポートジョブを設定できる。",
    ["Speak with Blandine in Mhaura (I-9) to begin the quest. You need Windurst fame level 4."] = "ウィンダス名声4が必要。マウラ(I-9)のBlandineに話す。",
    ["Speak with Zexu."] = "Zexuに話す。",
    ["Exit the dock, then talk to Blandine again."] = "船着場から出てBlandineにもう一度話す。",
    ["Speak with Celestina in the nearby Goldsmithing Guild. The quest now shows in your log."] = "近くの彫金ギルドにいるCelestinaに話す。ここでクエストがリストに載る。",
    ["Obtain a Sand Charm, which drops from Crossbones on the Ferry between Mhaura and Selbina. Crossbones appear on the ferry only when pirates attack, which is a rare occurrence."] = "マウラ～セルビナの機船に、まれに海賊が襲来する。そのとき出現するCrossbonesから砂の護符を入手する。",
    ["Trade the Sand Charm to Celestina to complete the quest and receive the Map of Bostaunieux Oubliette."] = "Celestinaに砂の護符を渡し、ボストーニュ監獄地図を得る。",
    ["You need to wait 8 real-life hours (8 game days) after completing Way of the Cook before this quest is offered. Speak with Rycharde in Mhaura (I-8). He wants you to get him an ingredient called a puffball."] = "「料理の道」後、地球時間8時間（ヴァナ時間8日）待つ。マウラ(I-8)のRychardeからパフボールを頼まれる。",
    ["Obtain a Puffball and trade it to Rycharde to complete the quest. You receive 2,100 gil and the title Two-Star Purveyor."] = "パフボールをRychardeに渡し、2,100ギルと称号Two-Star Purveyorを得る。",
    ["You need to wait 8 real-life hours after completing Rycharde the Chef before this quest is offered. Speak with Rycharde in Mhaura to begin it. He needs your help finding some ingredients: a beehive chip and some dhalmel meat."] = "「料理人ライチャード」後、地球時間8時間待つ。マウラのRychardeに話し、蜂の巣のかけらとダルメルの肉を頼まれる。",
    ["Obtain a Beehive Chip and a Dhalmel Meat and trade them to Rycharde to complete the quest. You receive between 1,000 and 1,500 gil and the title One-Star Purveyor."] = "蜂の巣のかけらとダルメルの肉を各1個Rychardeに渡す。1,000～1,500ギルと称号「食材調達人」を得る。",
    ["Talk to Abelard in Selbina (G-9) to receive some Selbina Clay. You need to be level 15 or higher. The mayor wants you to find the stone monuments left by a certain adventurer and copy their writings to clay."] = "レベル15以上でセルビナ(G-9)のAbelardに話し、セルビナの粘土を受け取る。冒険者が各地に残した石碑を粘土に写すよう頼まれる。",
    ["Take the Selbina Clay to the Stone Monuments around the world and copy their writings. Repeat for the remaining Stone Monuments; the quest does not complete until you finish all the tablets."] = "世界各地の石碑にセルビナの粘土を使い、碑文を写す。残りの石碑も回り、すべて写すまで続ける。",
    ["Return the tablets to Abelard. When you finish them all you receive the Map of the Crawlers' Nest. You can repeat the quest."] = "写した粘土をAbelardへ届ける。すべて終えるとクロウラーの巣地図を得る。繰り返し可能。",
    ["Three more monuments exist in the Shadowreign: Vunkerl Inlet (S) at (E-12), Grauberg (S) at (F-5) and Fort Karugo-Narugo (S) at (E-7), outside the map. You can copy them with the Selbina Clay, but when you trade them there is no response from Abelard."] = "過去にはブンカール浦〔Ｓ〕(E-12)、グロウベルグ〔Ｓ〕(F-5)、カルゴナルゴ城砦〔Ｓ〕(E-7)（地図外）にも石碑がある。粘土に写せるが、Abelardに渡しても反応しない。",
    ["Talk to Vuntar in Selbina (H-9). He will pay a premium price for rolanberries, but only for those that are thoroughly aged and can serve as food for long voyages."] = "セルビナ(H-9)のVuntarに話す。長い航海の食料用に、長期間熟成したロランベリーを高く買い取ってくれる。",
    ["Purchase some Rolanberries."] = "ロランベリーを購入する。",
    ["Proceed to the Crawlers' Nest to turn your Rolanberries into higher quality Rolanberries."] = "クロウラーの巣でロランベリーを上質な熟成品にする。",
    ["Trade the aged Rolanberries to Vuntar to complete the quest. The payment depends on the Rolanberry you hand in. You can repeat the quest."] = "熟成したロランベリーをVuntarに渡す。種類に応じた代金を受け取れる。繰り返し可能。",
    ["Speak with Romeo in Selbina (H-9). You need Other fame level 1. Donate five pieces of onion equipment to help new recruits everywhere; donors may receive an award."] = "その他名声1が必要。セルビナ(H-9)のRomeoに話す。新兵の支援にオニオン装備5個を寄付すると、お礼をもらえるらしい。",
    ["Trade him five pieces of the same type of onion equipment to complete the quest. You receive a Wastebasket and the title Ecologist."] = "同じ種類のオニオン装備5個をRomeoに渡す。くずかごと称号「エコロジスト」を得る。",
    ["Speak with Isacio in Selbina (G-10). You need to be level 18 or higher. You must prove yourself worthy before you can learn his fighting techniques."] = "レベル18以上でセルビナ(G-10)のIsacioに話し、戦う技術を教わるために腕を示す。",
    ["Obtain a Damselfly Worm, a Magicked Skull and a Crab Apron and bring them to Isacio."] = "ガガンボの腹虫、呪われたサレコウベ、陸ガニのふんどしを入手し、Isacioに渡す。",
    ["Speak with Zaldon in Selbina (H-9). This quest follows The Real Gift. You need a Fishing skill of 30 or higher; you can use gear and Advanced Synthesis Image Support to reach it. Some fish in Vana'diel like to eat shiny objects, and Zaldon will cut open any you catch."] = "「本当のプレゼント」後、セルビナ(H-9)のZaldonに話す。装備・上級サポートを含め釣りスキル30以上が必要。光るものを飲み込んだ魚の腹を調べてもらえる。",
    ["Trade Zaldon certain fish and he will gut them for you. What you receive depends on the fish, and some of them earn a title. You can repeat the quest."] = "対象の魚をZaldonに渡して腹を調べてもらう。魚によって報酬が異なり、称号を得られるものもある。繰り返し可能。",
    ["Speak with Melyon in Selbina (I-9). You need Other fame level 1. He will pay premium prices for any of the following: five heads of La Theine Cabbage, three ears of Millioncorn, or one clump of Boyahda Moss."] = "その他名声1が必要。セルビナ(I-9)のMelyonに話す。ラテーヌキャベツ5個、ミリオンコーン3個、ボヤーダ苔1個のいずれかを高く買い取ってくれる。",
    ["Trade Melyon any one of those sets to complete the quest and receive between 100 and 600 gil. If you have already completed the quest at least once, you do not need to speak to him again to start it; you can simply trade the items again."] = "いずれか1組をMelyonに渡し、100～600ギルを得る。初回クリア後は話しかけ直さず、直接トレードして繰り返せる。",
    ["Repeating this quest several times is the easiest way to improve your reputation in Bastok, San d'Oria, Jeuno, Selbina and Rabao. You can repeat the quest."] = "繰り返すとバストゥーク、サンドリア、ジュノ、セルビナ、ラバオの名声を上げやすい。再挑戦可能。",
    ["You need to have finished Under the Sea to get this quest. Speak with Oswald in Selbina (I-9). He wants to order something nutritious to cheer his girlfriend up a bit, and asks you for the special ingredient, a Danceshroom."] = "「港の落とし物」後、セルビナ(I-9)のOswaldに話す。元気のない恋人のための料理に使うオドリタケを頼まれる。",
    ["Trade Oswald a Danceshroom to complete the quest and receive the Sleep Dagger. Danceshrooms can be bought at the Auction House under Food, Ingredients."] = "Oswaldにオドリタケを渡し、スリプルダガーを得る。オドリタケは競売の食品→食材でも買える。",
    ["The Sand Charm must be completed before you are offered this quest. Speak with Oswald in Selbina (I-9) to begin it."] = "「安否」クリア後、セルビナ(I-9)のOswaldに話す。",
    ["Trade Oswald a Shall Shell to complete the quest. You receive the Glass Fiber Fishing Rod and the title The Love Doctor."] = "シャル貝をOswaldに渡し、グラスロッドと称号「キング・オブ・ラブ」を得る。",
    ["Speak with Thunder Hawk in Selbina (G-9) to begin the quest. He wants you to rescue two merchants from captivity; they should be somewhere in the Quadav camp in Beadeaux."] = "セルビナ(G-9)のThunder Hawkに話す。ベドーのクゥダフの拠点に捕らわれた商人2人の救出を頼まれる。",
    ["Head to Beadeaux and kill a De'Vyu Headhunter to obtain a Quadav Charm."] = "ベドーでDe'Vyu Headhunterを倒し、クゥダフの呪符を入手する。",
    ["Head to (I-8) and trade the Quadav Charm to the Jail Door, on the ground floor, for a cutscene and a Trader's sack."] = "(I-8)の地上階でJail Doorにクゥダフの呪符を渡し、イベントで商人のずだ袋を得る。",
    ["Return to Thunder Hawk for a storytelling scene and your reward, the Map of the Ranguemont Pass and 3,000 gil, and the title Honorary Citizen of Selbina."] = "Thunder Hawkへ戻って話を聞き、ラングモント峠地図と3,000ギル、称号Honorary Citizen of セルビナを得る。",
    ["Speak with Devean in Selbina (I-8). He asks you to bet on how long it takes you to get a pair of Power Sandals from Davoi. Find the pair of Power Sandals hidden in a jar somewhere in Davoi and bring them back before time runs out for a cash prize."] = "セルビナ(I-8)のDeveanに話し、ダボイからど根性サンダルを持ち帰るまでの時間に賭ける。制限時間内に壺に隠されたサンダルを探して持ち帰れば賞金を得る。",
    ["The quicker you return, the more money you get back. The time is measured in game hours, not Earth hours."] = "早く戻るほど賞金が高い。計測は地球時間ではなくヴァナ時間。",
    ["Once in Davoi you need to locate a Jar that contains the Power Sandals. The jar can spawn at (I-8), (K-9), (J-8), (H-8), (F-6), (J-9), (F-9), (G-9), (H-9) and (F-7)."] = "ダボイのJarからど根性サンダルを探す。候補は(I-8)、(K-9)、(J-8)、(H-8)、(F-6)、(J-9)、(F-9)、(G-9)、(H-9)、(F-7)。",
    ["Return the Power Sandals to Devean before time runs out. You can also choose to keep the Power Sandals for yourself, but that means you fail the quest."] = "制限時間内にDeveanへど根性サンダルを届ける。自分のものにすることもできるが、その場合は失敗となる。",
    ["Speak with Oswald in Selbina (I-9). This quest involves a Fat Greedie, a fish that can be caught in the sea at Selbina, and an Etched ring."] = "セルビナ(I-9)のOswaldに話す。セルビナの海で釣れる太ったグリーディと名前の刻まれた指輪に関わる依頼。",
    ["Bring the ring back to Oswald for your reward, the Amber Earring."] = "Oswaldに指輪を届け、アンバーピアスを得る。",
    ["Talk to Frescheque in Tavnazian Safehold (H-8, 3rd floor) to start the quest."] = "タブナジア地下壕(H-8、3階)のFreschequeに話す。",
    ["Talk to Raminey (J-7, 3rd floor)."] = "Raminey(J-7、3階)に話す。",
    ["Talk to Equette (I-9, 2nd floor)."] = "Equette(I-9、2階)に話す。",
    ["Defeat the NMs and select the ??? again to obtain the Tiny wristlet."] = "NMを倒して???を再度調べ、小さな腕輪を得る。",
    ["Return to the Tavnazian Safehold and talk to Frescheque for your reward, the Yinyang Lorgnette. Talk to Equette again for an additional cutscene."] = "タブナジア地下壕のFreschequeへ報告し、陰陽のローネットを受け取る。Equetteに再度話すと後日談を見られる。",
    ["Talk to Quelveuiat in Tavnazian Safehold (I-10, middle floor)."] = "タブナジア地下壕(I-10、中層)のQuelveuiatに話す。",
    ["Zone into Lufaise Meadows by taking the south exit at (I-6), then head to (H-10). Clear any nearby Orcs, as they will link."] = "(I-6)の南出口からルフェーゼ野へ出て(H-10)へ向かう。周囲のオークはリンクするので先に倒す。",
    ["Click the ??? at the top of the platform to spawn Splinterspine Grukjuk, a Ranger Orc NM, and defeat it."] = "物見台の上の???を調べ、狩人タイプのオークNM、Splinterspine Grukjukを出現させて倒す。",
    ["Return to Tavnazian Safehold and speak with Quelveuiat to complete the quest and receive 2,100 gil."] = "タブナジア地下壕のQuelveuiatへ報告し、2,100ギルを得る。",
    ["Optional: after completing the quest you may trade Quelveuiat a Sealion Crest Key and a Coral Crest Key to obtain a Temple Knight key, which lets you open the large door to the inner part of Sacrarium at (H-7) solo."] = "任意：クリア後に海獅子の紋章のカギと珊瑚の紋章のカギをQuelveuiatに渡すと侯国騎士団長のカギを得る。礼拝堂(H-7)の奥への大扉を1人で開けられる。",
    ["Talk to Enaremand in Tavnazian Safehold (J-7, Home Point #3), on the upper level. This quest follows It's Raining Mannequins and requires the Chains of Promathia pack. One last material is required to complete his final masterpiece, and the mannequin craftswoman in Mhaura may have clues."] = "「呪われた人形」後、タブナジア地下壕(J-7、ホームポイント#3)上層のEnaremandに話す。「プロマシアの呪縛」が必要。傑作の仕上げの素材を探すため、マウラのマネキン職人に手がかりを聞く。",
    ["Go to Mhaura and talk with Fyi Chalmwoh at (G-8)."] = "マウラ(G-8)のFyi Chalmwohに話す。",
    ["Go to Carpenters' Landing, entering from Jugner Forest at (J-8), where you will fight an Orc NM. When you touch the ???, Bullheaded Grosvez spawns."] = "ジャグナー森林(J-8)からギルド桟橋へ入り、???を調べてオークNM、Bullheaded Grosvezを出現させる。",
    ["After you have defeated Bullheaded Grosvez, touch the ??? again to receive the Red oil."] = "Bullheaded Grosvezを倒し、???を再度調べてレッドオイルを得る。",
    ["Go back to the Tavnazian Safehold and talk to Enaremand again for your reward, the Mannequin Pumps."] = "タブナジア地下壕のEnaremandへ報告し、マヌカンパンプスを得る。",
    ["This quest follows Secrets of Ovens Lost and requires the Chains of Promathia pack. Speak with Despachiaire in Tavnazian Safehold (K-10). He has asked you to investigate the origin of his late wife's amulet."] = "「失われた料理」後、タブナジア地下壕(K-10)のDespachiaireに話す。「プロマシアの呪縛」が必要。亡き妻のアミュレットの由来を調べるよう頼まれる。",
    ["Investigate the amulet's origin and return to Despachiaire for your reward, the Elegant Ribbon."] = "アミュレットの由来を調べてDespachiaireに報告し、エレガントリボンを得る。",
    ["Speak with Ferchinne in Tavnazian Safehold (G-9) to begin the quest. You need to be on or past Promathia Mission 4-2 and have the Chains of Promathia pack."] = "プロマシアミッション4-2以降、「プロマシアの呪縛」が必要。タブナジア地下壕(G-9)のFerchinneに話す。",
    ["Obtain 2 Hippogryph Tailfeathers and trade them to Ferchinne for your reward, the Mistmelt. You can repeat the quest."] = "ヒポグリフの尾羽根を2本Ferchinneに渡し、雲消霧散石を得る。繰り返し可能。",
    ["To activate this quest you must be on or past Promathia Mission 4-2 and have zoned into Riverne - Site B01. You need the Chains of Promathia pack."] = "プロマシアミッション4-2以降、リヴェーヌ岩塊群サイトB01へ入ったことが必要。「プロマシアの呪縛」が必要。",
    ["Speak with Epinolle in Tavnazian Safehold (F-8) to begin the quest."] = "タブナジア地下壕(F-8)のEpinolleに話す。",
    ["Enter Riverne - Site B01 and defeat the goblin NMs Book Browser Bokabraq, Chemical Cook Chemachiq and Spell Spitter Spilospok."] = "リヴェーヌ岩塊群サイトB01でBook Browser Bokabraq、Chemical Cook Chemachiq、Spell Spitter Spilospokを倒す。",
    ["Return to Epinolle for your reward, the Map of Cape Riverne."] = "Epinolleに報告し、リヴェーヌ岩塊群地図を得る。",
    ["Speak with Tressia in Tavnazian Safehold (J-6). You need to have completed Darkness Named and have the Chains of Promathia pack. Search for information regarding what happened on the day Wazozo's treasure was stolen."] = "「神を名乗りて」クリアと「プロマシアの呪縛」が必要。タブナジア地下壕(J-6)のTressiaから、Wazozoの宝が盗まれた日の出来事を調べるよう頼まれる。",
    ["Return to Tressia with what you found for your reward, the Gramary Cape."] = "集めた情報をTressiaへ報告し、グラマリーケープを得る。",
    ["Start the quest by talking to Yurim in Tavnazian Safehold (J-8), on the top floor. This quest requires the Chains of Promathia pack."] = "タブナジア地下壕(J-8)最上階のYurimに話す。「プロマシアの呪縛」が必要。",
    ["Choose a reward, then trade the appropriate base item and chip to Yurim. Be careful: you cannot cancel the quest after making your decision. You can repeat the quest."] = "報酬を決めて、対応する元の装備とチップをYurimに渡す。選択後は取り消せないので注意。繰り返し可能。",
    ["Wait up to 1 minute after completing Behind the Smile. Talk with Enaremand in Tavnazian Safehold (J-7)."] = "「微笑みの模像」後、最大1分待ち、タブナジア地下壕(J-7)のEnaremandに話す。",
    ["Talk to Chemioue (J-6). If you have not done Petals for Parelbriaux and you are at Promathia Mission 3-5 or later, you may get that cutscene first."] = "Chemioue(J-6)に話す。プロマシアミッション3-5以降で「ふたりはいつか」が未完了なら、先にそのイベントが発生することがある。",
    ["Go to Phomiuna Aqueducts, find a Wooden Ladder at (C-9) on the second map, and climb the ladder for a cutscene."] = "フォミュナ水道2枚目の地図(C-9)でWooden Ladderを登り、イベントを見る。",
    ["Complete the rest of the quest to be able to pose your mannequin."] = "残りの手順を進めてクリアすると、マネキンのポーズを変えられる。",
    ["Speak with Nivorajean in Tavnazian Safehold (I-9), on the surface level. You need to be level 50 or higher, have the Chains of Promathia pack, and have Promathia Mission 4-3 flagged for Sacrarium access. To complete a map of the Sacrarium, she needs you to find a piece of the old floorplans."] = "レベル50以上、「プロマシアの呪縛」とミッション4-3受領による礼拝堂への立ち入りが必要。タブナジア地下壕(I-9)の地上階でNivorajeanに話し、古い設計図の切れ端を探すよう頼まれる。",
    ["Find the piece of the old floorplans in the Sacrarium and bring it back to Nivorajean for your reward, the Map of the Sacrarium."] = "礼拝堂で設計図の切れ端を入手し、Nivorajeanへ届けて礼拝堂地図を得る。",
    ["Speak with Chemioue on the top floor of Tavnazian Safehold (J-6), slightly north of Home Point #3, for a cutscene. You need to have completed Promathia Mission 3-5 and have the Chains of Promathia pack."] = "プロマシアミッション3-5クリアと「プロマシアの呪縛」が必要。タブナジア地下壕最上階(J-6)、ホームポイント#3の少し北でChemioueに話し、イベントを見る。",
    ["If you get a cutscene about a Shikaree tracker, that is for Tango with a Tracker: go talk to Despachiaire at (K-10), behind a Walnut Door, then return to Parelbriaux and talk to him twice more for a cutscene with Chemioue."] = "罪狩りの話なら「罪狩りたちの舞踏曲」のイベント。(K-10)、胡桃 Doorの奥のDespachiaireに話してからParelbriauxへ戻り、さらに2回話してChemioueとのイベントを見る。",
    ["Speak with Ondieulix at (I-7) to receive your reward, the Powerful Rope."] = "Ondieulix(I-7)に話し、パワフルロープを得る。",
    ["Talk to Despachiaire in Tavnazian Safehold (K-10), on the top floor. This quest follows Spice Gals and requires the Chains of Promathia pack."] = "「Spice Gals」後、タブナジア地下壕(K-10)最上階のDespachiaireに話す。「プロマシアの呪縛」が必要。",
    ["Talk to Jonette on the middle floor, near the stream at (G-9)."] = "中層(G-9)、水路付近のJonetteに話す。",
    ["Complete the rest of the quest to receive a page from Miratete's Memoirs."] = "残りの手順を終え、ミラテテ様言行録を受け取る。",
    ["This quest follows Tango with a Tracker and requires the Chains of Promathia pack. Speak with Despachiaire in Tavnazian Safehold (K-10)."] = "「罪狩りたちの舞踏曲」後、タブナジア地下壕(K-10)のDespachiaireに話す。「プロマシアの呪縛」が必要。",
    ["Complete the quest to receive your reward, which varies, and the title Disciple of Justice. You can repeat the quest."] = "クリアすると各種報酬と称号Disciple of Justiceを得る。繰り返し可能。",
    ["Speak with Leporaitceau in Tavnazian Safehold (J-8, 3rd floor)."] = "タブナジア地下壕(J-8、3階)のLeporaitceauに話す。",
    ["Speak with Equette (I-9, 2nd floor)."] = "Equette(I-9、2階)に話す。",
    ["Speak with Anteurephiaux (J-8, 3rd floor) to officially begin the quest."] = "Anteurephiaux(J-8、3階)に話すと正式に受領する。",
    ["Travel to Misareaux Coast and look for a ??? at (K-12). Checking the ??? spawns the NM Bloody Coffin."] = "ミザレオ海岸(K-12)の???を調べ、NMのBloody Coffinを出現させる。",
    ["Once the NM is defeated, check the ??? again to receive the key item Whispering conch."] = "NMを倒して???を再度調べ、だいじなもの追憶の巻き貝を得る。",
    ["Return to Anteurephiaux. Finally, speak with Equette to complete the quest and receive the Memento Muffler."] = "Anteurephiauxに報告後、Equetteに話してメメントマフラーを得る。",
    ["Speak with Elysia on the first floor of Tavnazian Safehold (G-10) to begin the quest. She dropped her hairpin while doing her shopping."] = "タブナジア地下壕(G-10)1階のElysiaに話す。買い物中に落とした髪飾りを探す。",
    ["Head up to the second floor of the safehold and examine the ??? behind the pillar at (K-9), near the Walnut Door. You obtain the Alabaster hairpin."] = "2階へ上がり、(K-9)の胡桃 Door付近の柱の裏にある???を調べ、純白の髪飾りを得る。",
    ["Return to Elysia for your reward, the Map of Tavnazia."] = "Elysiaに報告し、タブナジア群島地図を得る。",
    ["Speak with Justinius on the second floor of Tavnazian Safehold (J-6) to activate the quest and receive a Monarch Linn Patrol Permit. You need Other fame level 1, and the Chains of Promathia mission The Savage must be complete."] = "「猛き者たちよ」クリア、その他名声1が必要。タブナジア地下壕(J-6)2階のJustiniusから帝龍の飛泉調査委任状を受け取る。",
    ["Take the permit to Monarch Linn and complete the task there."] = "許可証を持って帝龍の飛泉へ行き、現地で依頼を遂行する。",
    ["Return to Justinius for your reward."] = "Justiniusに報告して報酬を得る。",
    ["Talk to Despachiaire in Tavnazian Safehold (K-10, upper level), behind the Walnut Door at (K-9), to start the quest."] = "タブナジア地下壕(K-10)上層、(K-9)の胡桃 Doorの奥のDespachiaireに話す。",
    ["Obtain a Tavnazian Liver and bring it to Despachiaire for your reward, 4,000 gil."] = "タブナジア羊レバーを入手し、Despachiaireに渡して4,000ギルを得る。",
    ["Speak with Despachiaire in Tavnazian Safehold (K-10) to obtain the Letter from Shikaree X. The letter has arrived in the safehold, and she wants to gauge your battle prowess in Boneyard Gully."] = "タブナジア地下壕(K-10)のDespachiaireからスカリーXからの挑戦状を受け取る。千骸谷で実力を試したいという便り。",
    ["Head to Boneyard Gully and select \"Tango with a Tracker\" at the Dark Miasma to enter a battlefield."] = "千骸谷のDark Miasmaで「罪狩りたちの舞踏曲」を選び、BFへ入る。",
    ["Win the battle to complete the quest and receive 10,000 gil."] = "戦闘に勝利して10,000ギルを得る。",
    ["Travel to Riverne - Site #A01 and check the Stone Monument at (C-7). You receive a cutscene and the Ornamented scroll."] = "リヴェーヌ岩塊群サイトA01(C-7)の石碑を調べ、イベントでOrnamented scrollを得る。",
    ["Speak with Reinberta in Bastok Markets (I-8)."] = "バストゥーク商業区(I-8)のReinbertaに話す。",
    ["Speak with Mevreauche in Northern San d'Oria (E-6)."] = "北サンドリア(E-6)のMevreaucheに話す。",
    ["Head back to the Stone Monument in Riverne - Site #A01 and check it for a cutscene. Examine it again to spawn the NM Arcane Phantasm."] = "リヴェーヌ岩塊群サイトA01の石碑へ戻り、イベントを見る。もう一度調べてArcane Phantasmを出現させる。",
    ["After defeating the NM, click the Stone Monument once more to complete the quest and receive the Minstrel's Dagger."] = "NMを倒して石碑を再度調べ、ミンストレルダガーを得る。",
    ["You need to be on or past the Chains of Promathia mission Flames for the Dead. Speak with Buffalostalker Dodzbraz in Uleguerand Range (F-9), just southeast of the Unity warp level 128. He is an Orc who despises snolls."] = "「迎え火」以降、ウルガラン山脈(F-9)、ユニティのレベル128転送先の南東でBuffalostalker Dodzbrazに話す。スノールを嫌うオークの依頼。",
    ["Obtain 2 Cluster Cores, a fairly common drop from Cluster-type monsters."] = "クラスター族からクラスターの魂を2個入手する。",
    ["Trade him the two Cluster Cores to receive your reward, the Shu'Meyo Salt. You can repeat the quest."] = "クラスターの魂を2個渡してシュ・メーヨ海の塩を得る。繰り返し可能。",
    ["Speak with Carbuncle at the ??? in La Theine Plateau (G-6). You must first have obtained spirit pacts with the 6 summonable Celestial avatars before you are presented with the Rainbow resonator."] = "6属性の召喚獣との契約後、ラテーヌ高原(G-6)の???でCarbuncleに話し、虹の呼び玉を得る。",
    ["Use the Rainbow resonator to enter the battlefield."] = "虹の呼び玉を使ってBFへ入る。",
    ["Once the three avatars are defeated, five Carbuncle Primes spawn at once. Defeat all five Carbuncle Primes to win the battle."] = "召喚獣3体を倒すとCarbuncle Primeが5体同時に出現する。5体とも倒して勝利する。",
    ["Every player who participates in the final fight receives a Carbuncle's Pole. All other quest rewards are dropped at random at the end of the Carbuncle Prime battle."] = "最終戦の参加者全員がカーバンクルポールを得る。ほかの報酬はCarbuncle Prime戦の終了時にランダムでドロップする。",
    ["Speak with Koblakiq in Oldton Movalpolos (H-11) to begin the quest. This quest requires the Chains of Promathia pack."] = "「プロマシアの呪縛」が必要。ムバルポロス旧市街(H-11)のKoblakiqに話す。",
    ["Obtain a Soiled Letter and trade it to Koblakiq to complete the quest and receive 4,000 gil."] = "汚れた封筒をKoblakiqに渡し、4,000ギルを得る。",
    ["After completing Missionary Moblin you need to zone out and back in to initiate this quest. Talk to Koblakiq in Oldton Movalpolos (H-11) to begin it. A letter has arrived from Zeelozok asking for an arnica root to be brought to Castle Oztroja, and Koblakiq entrusts the task to you. It is suggested that you have the three beastmen stronghold Survival Guides, as the quest requires traveling between the three strongholds, and that you bring Echo Drops, Holy Water or someone who can cast Cursna."] = "「ズィーロゾックの冒険」後、エリアを切り替えてムバルポロス旧市街(H-11)のKoblakiqに話す。Zeelozokからオズトロヤ城へアルニカの根を届けるよう便りが来ている。獣人拠点3か所のSurvival Guideを開通し、やまびこ薬・聖水かカーズナを使える仲間を用意するとよい。",
    ["Obtain an Arnica Root if you have not already."] = "アルニカの根を用意する。",
    ["Head to Castle Oztroja and go to the Brass Door at (I-8)."] = "オズトロヤ城(I-8)のBrass Doorへ向かう。",
    ["After the fight, talk to Ge'Fhu Yagudoeye again for a short cutscene."] = "戦闘後にGe'Fhu Yagudoeyeに再度話し、短いイベントを見る。",
    ["Head back to Oldton Movalpolos and speak with Koblakiq to complete the quest and receive your Jaguar Mantle."] = "ムバルポロス旧市街のKoblakiqに報告し、ジャガーマントを得る。",
    ["Speak with Koblakiq in Oldton Movalpolos (H-11) to begin the quest. Make sure you have zoned after completing For the Birds. To save time, you can bring a Demon Pen with you when you travel to start this quest."] = "「ズィーロゾックの思い出」後にエリアを切り替え、ムバルポロス旧市街(H-11)のKoblakiqに話す。あらかじめデーモンの指ペンを持っていくと移動を減らせる。",
    ["Head to Castle Zvahl Baileys and fight Blood Demons and Demon Generals until you obtain a Demon Pen."] = "ズヴァール城外郭のBlood DemonやDemon Generalからデーモンの指ペンを入手する。",
    ["Trade the Demon Pen to Koblakiq to complete the quest and receive the Goblin Grenade."] = "Koblakiqにデーモンの指ペンを渡し、ゴブリングレネードを得る。",
    ["Place a Bronze Bed in your Mog House using the furniture Layout menu. You need Other fame level 3 (home nation fame). Wait one Earth minute, exit your Mog House, re-enter and speak to the Moogle. If you have enough fame, you receive a cutscene."] = "自国名声3が必要。モグハウスのレイアウトでブロンズベッドを置き、地球時間1分待って出入りし、モーグリに話す。名声が足りていればイベントが発生する。",
    ["Trade the Moogle the items he asks for: a Power Bow and a Beetle Ring. The Power Bow can be bought from a Records of Eminence NPC using Sparks (equip level 10 to 19). The Beetle Ring +1 does not count."] = "モーグリにパワーボウとビートルリングを渡す。パワーボウはエミネンス交換（装備レベル10～19）でも入手できる。ビートルリング+1では代用できない。",
    ["When your Moogle returns from his trip after one Earth minute (without ever leaving your Mog House), he gives you a Mog Safe that holds 60 items and you receive the title Mog's Kind Master."] = "モグハウスを出ずに地球時間1分待つ。モーグリが帰るとモグ金庫が60枠になり、称号「やさしいご主人様」を得る。",
    ["Place a bed in your Mog House using the furniture Layout menu, exit your Mog House, re-enter it and speak to your Moogle. You need to have completed The Moogle's Picnic! and have Other fame level 7 (home nation fame)."] = "「ピクニックに行きたいクポの巻」クリアと自国名声7が必要。モグハウスにベッドを置いて出入りし、モーグリに話す。",
    ["Your moogle wants to take a raptor mantle and a wool hat to his friends in the Outlands. Trade him the items he requests."] = "辺境の友人への土産にラプトルマントとウールハットを頼まれるので渡す。",
    ["When he returns from his trip, your Mog Safe capacity is increased to 80 items."] = "モーグリが戻るとモグ金庫が80枠になる。",
    ["Place a Mahogany Bed in your Mog House, then speak to the Moogle. You need to have completed Give a Moogle a Break. Zone out of your Mog House and then come back."] = "「モグ祭りが近いクポの巻」後、モグハウスにマホガニーベッドを置いてモーグリに話し、外へ出て入り直す。",
    ["Your moogle wants to take a shrimp lure and some Selbina butter back home. He would be very happy if you found them for him; trade him the items."] = "故郷への土産にシュリンプルアーとセルビナバターを頼まれるので渡す。",
    ["When he returns from his trip, your Mog Safe capacity is increased to 70 items."] = "モーグリが戻るとモグ金庫が70枠になる。",
    ["Enter the Altar Room, in Castle Oztroja, for a cutscene with Hooknox that starts the quest. You need to be level 60 or higher. You are given a choice to start the quest or not."] = "レベル60以上でオズトロヤ城の祭壇の間に入るとHooknoxとのイベント。依頼を引き受けるか選ぶ。",
    ["Obtain a Yagudo Headgear. It is crafted with Clothcraft (skill 80)."] = "裁縫スキル80の合成品ヤグードヘッドギアを用意する。",
    ["Return to the Altar Room while wearing your Yagudo Headgear for a cutscene. You receive the key item Vault quipus."] = "ヤグードヘッドギアをかぶって祭壇の間へ戻り、イベントで宝物庫のキープを得る。",
    ["Defeat the Yagudo Avatar. The other Yagudo NMs in the room are Duu Masa the Onecut, Fee Jugu the Ramfist, Goo Pake the Bloodhound, Kee Taw the Nightingale, Laa Yaku the Austere and Poo Yozo the Babbler."] = "Yagudo Avatarを倒す。同じ部屋にはDuu Masa the Onecut、Fee Jugu the Ramfist、Goo Pake the Bloodhound、Kee Taw the Nightingale、Laa Yaku the Austere、Poo Yozo the Babblerもいる。",
    ["Trade your Yagudo Headgear to the Stone Lid for a cutscene; it is replaced by Tsoo's Headgear."] = "Stone Lidにヤグードヘッドギアを渡すとイベントが発生し、ハジャヘッドギアに交換される。",
    ["Zone out to the south of the Altar Room and then back into the zone for a cutscene and a Gold Beastcoin. You receive the title Yagudo Initiate."] = "祭壇の間の南へ出て入り直すとイベント。獣人金貨と称号Yagudo Initiateを得る。",
    ["A Potter's Preference"] = "ある陶芸家のこだわり",
