    ["Under the Sea"] = "港の落とし物",
    ["A Bitter Past"] = "愛する君達へ",
    ["A Hard Day's Knight"] = "タブナジア侯国騎士団",
    ["Behind the Smile"] = "微笑みの模像",
    ["Elderly Pursuits"] = "信仰と信頼と",
    ["Fly High"] = "その翼、空高く",
    ["Go! Go! Gobmuffin!"] = "空に浮かぶ岩塊",
    ["In Search of the Truth"] = "誠実なる予告を",
    ["In the Name of Science"] = "古の秘術",
    ["Knocking on Forbidden Doors"] = "しとやかな傀儡",
    ["Paradise, Salvation, and Maps"] = "神の御許に",
    ["Petals for Parelbriaux"] = "ふたりはいつか",
    ["Secrets of Ovens Lost"] = "失われた料理",
    ["Requiem of Sin"] = "罪狩りたちの鎮魂歌",
    ["The Big One"] = "巨大な影の正体",
    ["The Call of the Sea"] = "海からの贈り物",
    ["Unforgiven"] = "秘めたる想い",
    ["Uninvited Guests"] = "招かざる影たち",
    ["X Marks the Spot"] = "スカリーX",
    ["Tango with a Tracker"] = "罪狩りたちの舞踏曲",
    ["VW Op. 026: Tavnazian Terrors"] = "VW作戦第026計画タブナジア群島",
    ["Mithran Delicacies"] = "ミスラの大好物",
    ["Confessions of a Bellmaker"] = "鐘楼の名残",
    ["VW Op. 004: Bibiki Bombardment"] = "VW作戦第004計画ビビキー湾",
