    ["Bastok Markets (E-11) / Southern San d'Oria (G-10) / Windurst Woods (J-10) / Western Adoulin (H-11)"] = "バストゥーク商業区 (E-11) / 南サンドリア (G-10) / ウィンダス森の区 (J-10) / 西アドゥリン (H-11)",
    ["Southern San d'Oria (G-10) / Bastok Markets (E-11) / Windurst Woods (J-10) / Western Adoulin (H-11)"] = "南サンドリア (G-10) / バストゥーク商業区 (E-11) / ウィンダス森の区 (J-10) / 西アドゥリン (H-11)",

    -- Original Phoenix guide and camp display labels; CatsEye applicability not verified.
    ["Welcome"] = "ようこそ",
    ["Welcome to Phoenix! This guide covers your first hours in Vana'diel: what to do in town, where to level, how to make your first gil, and the milestones along the way to level 75."] = "これはPhoenix向けの原ガイドの翻訳です。CatsEyeでの仕様・有効性は未検証です。街での準備、レベル上げ、最初の金策、レベル75までの節目を案内します。",
    ["See Game Terms for common abbreviations such as AF and RSE. Fame explains quest reputation and where to check it, and Inventory lists Phoenix's Mog Wardrobe unlocks."] = "AFやRSEなどの略語は原WikiのGame Terms、クエストの名声と確認方法はFame、Phoenixのモグワードローブ解放はInventoryを参照してください。",
    ["Phoenix is a level-75 server. Rise of the Zilart, Chains of Promathia, and Treasures of Aht Urhgan are available. Wings of the Goddess and later expansions are not. See How Phoenix differs from retail for systems that aren't here yet."] = "原ガイドのPhoenixはレベル75上限です。「ジラートの幻影」「プロマシアの呪縛」「アトルガンの秘宝」があり、「アルタナの神兵」以降はありません。未導入の仕組みは「Phoenixと小売版の違い」を参照してください。CatsEyeの説明ではありません。",
    ["Choosing a nation"] = "所属国を選ぶ",
    ["You begin in one of the three starting nations: San d'Oria, Bastok, or Windurst. Your nation decides which city you start in, which storyline missions you follow, and which gate guards give you Signet. The fields around each city are similar in difficulty, so pick the city and story you like best."] = "最初の所属国はサンドリア、バストゥーク、ウィンダスのいずれかです。開始する街、国のミッション、シグネットを受けるガードが国によって変わります。近隣の敵の強さは似ているので、好みの街や物語を選びましょう。",
    ["Your race has a home nation: Humes and Galka come from Bastok, Elvaan from San d'Oria, and Tarutaru and Mithra from Windurst. If you start in your race's home nation you also receive its nation ring. You start with extra fame in your chosen nation and some in your race's home nation."] = "原ガイドではヒューム・ガルカの故郷はバストゥーク、エルヴァーンはサンドリア、タルタル・ミスラはウィンダスです。種族の故郷を開始国にすると国の指輪も得られます。選んだ国と種族の故郷で開始時の名声に加算があります。",
    ["Each nation page lists its city areas, guilds, and a table of nearby areas by monster level."] = "原Wikiの各国ページには街の区域、ギルド、近隣エリアの敵レベル一覧があります。",
    ["Your first steps in town"] = "街で最初にすること",
    ["You start with your race's starting clothes, a weapon for your job, a map of your nation, and 10 gil. Before you head out:"] = "種族の初期服、ジョブ用の武器、所属国の地図、10ギルを持って始まります。出発前に次を確認しましょう。",
    ["Trade in your Adventurer Coupon"] = "冒険者優待券を交換する",
    ["The opening cutscene gives you an Adventurer Coupon. Trade it to one of these NPCs for 50 gil. It can't be replaced if you lose it, so don't drop or sell it."] = "冒頭のイベントで冒険者優待券を得ます。以下のNPCに渡すと50ギルを受け取れます。失くすと再発行できないので捨てたり売ったりしないでください。",
    ["San d'Oria"] = "サンドリア",
    ["Teilsa (Port San d'Oria), Matildie (Northern San d'Oria), Ailevia (Southern San d'Oria)"] = "Teilsa（サンドリア港）、Matildie（北サンドリア）、Ailevia（南サンドリア）",
    ["Bastok"] = "バストゥーク",
    ["Arva (Bastok Mines), Reet (Bastok Markets), Dulsie (Port Bastok)"] = "Arva（バストゥーク鉱山区）、Reet（バストゥーク商業区）、Dulsie（バストゥーク港）",
    ["Windurst"] = "ウィンダス",
    ["Jack of Hearts (Windurst Waters), Jack of Clubs (Port Windurst), Jack of Spades (Windurst Woods), Jack of Diamonds (Windurst Walls)"] = "Jack of Hearts（ウィンダス水の区）、Jack of Clubs（ウィンダス港）、Jack of Spades（ウィンダス森の区）、Jack of Diamonds（ウィンダス石の区）",
    ["Get Signet from a gate guard"] = "ガードからシグネットを受ける",
    ["Talk to one of your nation's gate guards at the city exits. Their names end in T.K. in San d'Oria, I.M. in Bastok, and W.W. in Windurst. Signet lets monsters drop crystals and earns you conquest points while you fight in the regions around the nations and Jeuno. It lasts a few hours at low rank, so renew it whenever you pass a guard."] = "街の出口にいる自国のガードに話します。名前の末尾はサンドリアがT.K.、バストゥークがI.M.、ウィンダスがW.W.。シグネット中は三国やジュノ周辺で敵からクリスタルを得られ、コンクェストの個人戦績もたまります。低ランクでは数時間で切れるので、ガードを通る際に更新しましょう。",
    ["Set your home point"] = "ホームポイントを設定する",
    ["Your first home point is your starting city. If you're knocked out, you can return to the last home point you set. Home points can't teleport you between cities."] = "最初のホームポイントは開始した街です。戦闘不能時は最後に設定した地点へ戻れます。原ガイドのPhoenixでは、ホームポイントによる街間の転送はできません。",
    ["Levels 1-10: the fields outside town"] = "レベル1～10：街の周辺",
    ["Solo in the areas right outside your city. The table on your nation page lists nearby areas from easiest to hardest, with the typical level of the monsters in each:"] = "街のすぐ外でソロを始めます。原Wikiの各国ページには、近隣エリアが易しい順に並び、敵の代表的なレベルが載っています。",
    ["Leveling near San d'Oria: West Ronfaure and East Ronfaure"] = "サンドリア周辺：西ロンフォール、東ロンフォール",
    ["Leveling near Bastok: North Gustaberg and South Gustaberg"] = "バストゥーク周辺：北グスタベルグ、南グスタベルグ",
    ["Leveling near Windurst: West Sarutabaruta and East Sarutabaruta"] = "ウィンダス周辺：西サルタバルタ、東サルタバルタ",
    ["Use the /check command before you fight. Monsters that check as \"easy prey\" or \"decent challenge\" are good targets at low levels. Watch for aggressive monsters (marked on each zone page) and beastmen camps."] = "戦う前に/checkで強さを調べましょう。低レベルでは「楽な相手」「丁度いい相手」が目安です。各エリアページで示されるアクティブな敵や獣人の拠点に注意してください。",
    ["Death costs experience from level 5. Be careful once you pass level 4."] = "原ガイドではレベル5から戦闘不能時に経験値を失います。レベル4を越えたら注意してください。",
    ["Levels 10-20: your first parties"] = "レベル10～20：初めてのパーティ",
    ["From around level 10, most players leave their home region and group up. Common places to go:"] = "レベル10前後から、故郷を離れてパーティを組む人が増えます。代表的な行き先は次のとおりです。",
    ["Valkurm Dunes, near the port of Selbina, reached through La Theine Plateau or Konschtat Highlands."] = "セルビナの近くのバルクルム砂丘。ラテーヌ高原かコンシュタット高地を経由します。",
    ["Buburimu Peninsula, near the port of Mhaura, reached through Tahrongi Canyon."] = "マウラの近くのブブリム半島。タロンギ大峡谷を経由します。",
    ["Jugner Forest, Pashhow Marshlands, and Meriphataud Mountains in the mid-teens."] = "レベル10台半ばにはジャグナー森林、パシュハウ沼、メリファト山地。",
    ["Qufim Island, off the coast of Jeuno, around level 20."] = "レベル20前後にはジュノ沖のクフィム島。",
    ["Each zone page lists its monsters, their levels, and whether they're aggressive."] = "原Wikiのエリアページには敵の種類、レベル、アクティブかどうかが載っています。",
    ["Party tips"] = "パーティの心得",
    ["Look for a group with /sea all or put up your seeking-party flag."] = "/sea allで仲間を探すか、パーティ参加希望を出しましょう。",
    ["A typical experience party has a tank, a healer, damage dealers, and someone to pull monsters back to camp."] = "一般的な経験値パーティは盾役、回復役、攻撃役、敵をキャンプへ釣る役で構成します。",
    ["Check monsters, stay at camp, and ask before pulling extra monsters."] = "敵の強さを調べ、キャンプで待ち、追加で釣る前に仲間へ確認しましょう。",
    ["Level Sync is available, so a higher-level player can sync down to join your party. Syncing down more than 10 levels can cost some experience when the server is busy."] = "原ガイドではレベルシンクがあり、高レベルの仲間もレベルを下げて参加できます。10レベルを超えて下げると、混雑時には経験値が減る場合があるとされています。",
    ["Power-leveling is limited. If a monster keeps attacking a character five or more levels above it, that character counts toward the fight, which cuts the experience the monster gives."] = "原ガイドのPhoenixではPLに制限があります。敵より5レベル以上高いキャラクターが攻撃を受け続けると、その人も戦闘参加者に数えられ、得られる経験値が減ります。",
    ["Milestones"] = "冒険の節目",
    ["Level 10"] = "レベル10",
    ["Outpost warps to the regions around your nation can be used, once you've unlocked them with a supply run."] = "補給クエストで開通した、自国周辺リージョンへのアウトポスト転送を利用できます。",
    ["Level 15"] = "レベル15",
    ["You can rent a chocobo in Southern San d'Oria, Bastok Mines, and Windurst Woods, once you have a license."] = "チョコボ乗り免許証があれば、南サンドリア、バストゥーク鉱山区、ウィンダス森の区でチョコボを借りられます。",
    ["Level 18"] = "レベル18",
    ["Unlock your support job with The Old Lady (Vera in Mhaura) or Elder Memories (Isacio in Selbina). You can only do one of the two."] = "マウラのVeraから「ごうつくばあさん」、またはセルビナのIsacioから「ある老人の回想」を受け、サポートジョブを取得します。両方はクリアできません。",
    ["Level 20"] = "レベル20",
    ["Get your chocobo license with Chocobo's Wounds (Brutus in Upper Jeuno). You feed a wounded chocobo Gausebit Grass. Each feeding has to wait one Vana'diel day. Chocobos can then be rented at level 20 anywhere."] = "ジュノ上層のBrutusから「傷ついたチョコボ」を受け、免許証を取ります。傷ついたチョコボにゴゼビの野草を与え、給餌ごとにヴァナ時間1日待ちます。レベル20になると各地で借りられます。",
    ["Level 30"] = "レベル30",
    ["Advanced jobs unlock. See Jobs for each job's unlock quest."] = "追加ジョブを取得できます。各取得クエストは原WikiのJobsを参照してください。",
    ["Level 50"] = "レベル50",
    ["Your level is capped at 50 until you complete Limit Break quests, starting with In Defiant Challenge. Each one raises the cap on the way to 75."] = "最初の上限は50です。「限界への挑戦」から始まる限界突破クエストで、75までの上限を段階的に引き上げます。",
    ["Support job quest items"] = "サポートジョブ取得用の品",
    ["The Old Lady: Wild Rabbit Tail, Dhalmel Saliva, and Bloody Robe."] = "ごうつくばあさん：野兎の尻尾、ダルメルの唾液、血染めの衣。",
    ["Elder Memories: Magicked Skull, Damselfly Worm, and Crab Apron."] = "ある老人の回想：呪われたサレコウベ、ガガンボの腹虫、陸ガニのふんどし。",
    ["Your first gil"] = "最初の金策",
    ["Repeatable quests are the steadiest early income. You can turn them in as often as you have the items. Each one also raises your fame with that nation, which unlocks more quests. The rewards below are from Phoenix's game data."] = "繰り返せるクエストは序盤の安定した収入源です。必要な品があれば繰り返せ、国の名声が上がると受けられる依頼も増えます。以下の報酬は原ガイドのPhoenixのデータであり、CatsEyeでは未検証です。",
    ["Trade 4 Flint Stones"] = "火打石を4個渡す",
    ["Legata, Southern San d'Oria"] = "Legata、南サンドリア",
    ["Trade 5 pots of honey (needs fame level 2)"] = "蜂蜜を5個渡す（名声2が必要）",
    ["Raimbroy, Southern San d'Oria"] = "Raimbroy、南サンドリア",
    ["Trade 2 Shaman Garlic (needs fame level 3)"] = "祈祷師のニンニクを2個渡す（名声3が必要）",
    ["Maloquedil, Northern San d'Oria"] = "Maloquedil、北サンドリア",
    ["Hand out 15 flyers to NPCs around the city"] = "街のNPCにチラシ15枚を配る",
    ["440 gil and a title"] = "440ギルと称号",
    ["Regine, Port San d'Oria"] = "Regine、サンドリア港",
    ["Change the water at a tombstone in King Ranperre's Tomb (needs fame level 1)"] = "ランペールの墓で墓石の水を換える（名声1が必要）",
    ["Andecia, Southern San d'Oria"] = "Andecia、南サンドリア",
    ["Trade 3 Lufet Salt"] = "ルフェ湖の塩を3個渡す",
    ["Nogelle, Port San d'Oria"] = "Nogelle、サンドリア港",
    ["Pick up the tear from the ??? in North Gustaberg (it moves between spots) with no weapon equipped, then trade it to Wahid"] = "北グスタベルグの移動する???で、武器を外して涙を拾い、Wahidへ渡す",
    ["Wahid, Bastok Mines"] = "Wahid、バストゥーク鉱山区",
    ["Trade 3 Zeruhn Soot"] = "ツェールンの煤を3個渡す",
    ["Gerbaum, Bastok Mines"] = "Gerbaum、バストゥーク鉱山区",
    ["Trade a Galkan Sausage"] = "ガルカンソーセージを1個渡す",
    ["Hungry Wolf, Metalworks"] = "Hungry Wolf、大工房",
    ["Trade 5 Rusty Buckets, a common fishing catch"] = "釣りで手に入る錆びたバケツを5個渡す",
    ["Foss, Bastok Markets"] = "Foss、バストゥーク商業区",
    ["Trade a Copper Ring to Roh Latteh in Bastok Mines and bring back the letter unopened"] = "バストゥーク鉱山区のRoh Lattehにカッパーリングを渡し、手紙を開かずに持ち帰る",
    ["200 gil (100 if you read it)"] = "200ギル（手紙を読むと100ギル）",
    ["Nbu Latteh, Bastok Markets"] = "Nbu Latteh、バストゥーク商業区",
    ["Only at fame level 1"] = "名声1のときのみ",
    ["Collect stamps from seven NPCs around Bastok"] = "バストゥークのNPC7人からスタンプを集める",
    ["A Leather Gorget"] = "レザーゴルゲット",
    ["Arawn, Bastok Markets"] = "Arawn、バストゥーク商業区",
    ["Trade a Bird Feather and a Two-Leaf Mandragora Bud"] = "鳥の羽根とマンドラゴラの双葉を1個ずつ渡す",
    ["250 gil"] = "250ギル",
    ["Moreno-Toeno, Windurst Waters"] = "Moreno-Toeno、ウィンダス水の区",
    ["Trade 3 Beehive Chips (150 gil) or 2 Remi Shells (200 gil)"] = "蜂の巣のかけらを3個（150ギル）か、レミ貝の殻を2個（200ギル）渡す",
    ["Up to 200 gil"] = "最大200ギル",
    ["Tapoh Lihzeh, Windurst Woods"] = "Tapoh Lihzeh、ウィンダス森の区",
    ["Trade 4 Yagudo Necklaces from the Yagudo in Giddeus"] = "ギデアスのヤグードからヤグードの数珠を4個集めて渡す",
    ["200 gil and Norg fame"] = "200ギルとノーグ名声",
    ["Nanaa Mihgo, Windurst Woods"] = "Nanaa Mihgo、ウィンダス森の区",
    ["Deliver a Hard-boiled Egg, a Grilled Hare, and a Windurstian Tea with a Tortilla and Pamtam Kelp"] = "ゆで卵、野兎のグリル、ウィンダスティーを届ける。お茶にはトルティーヤとパムタム海苔を添える",
    ["1,000 gil in total"] = "合計1,000ギル",
    ["Kenapa-Keppa, Kerutoto, and Ohbiru-Dohbiru, Windurst Waters"] = "Kenapa-Keppa、Kerutoto、Ohbiru-Dohbiru、ウィンダス水の区",
    ["Collect news scoops from reporters across Windurst"] = "ウィンダス各地の記者から特ダネを集める",
    ["560 gil and a title"] = "560ギルと称号",
    ["Naiko-Paneiko, Windurst Waters"] = "Naiko-Paneiko、ウィンダス水の区",
    ["Other ways to make gil"] = "ほかの金策",
    ["Crystals. With Signet, monsters drop elemental crystals. Crafters buy them in stacks at the auction house."] = "クリスタル：シグネット中は敵から属性クリスタルを得られます。合成職人向けに競売でまとめて売れます。",
    ["Monster drops. Sell the materials you collect. Each item page shows where it drops and who sells or buys it."] = "戦利品：集めた素材を売ります。原Wikiの各アイテムページに入手元や売買するNPCが載っています。",
    ["Fishing. The fishing page lists what bites where and the skill each catch needs."] = "釣り：原Wikiの釣りページに釣れる場所と必要なスキルが載っています。",
    ["Gathering. Harvesting, Logging, Mining, and Excavation points appear throughout the early zones. You need the matching tool."] = "採集：序盤のエリアにも収穫、伐採、採掘、発掘のポイントがあります。種類に合う道具が必要です。",
    ["Chocobo digging, once you can ride. Dig fatigue is shared across your whole account."] = "チョコボ掘り：乗れるようになったら挑戦できます。原ガイドでは掘り疲労はアカウント全体で共通です。",
    ["Crafting. Every city has guilds (see the guild tables on the nation pages), and crafting turns materials into more valuable goods."] = "合成：各都市のギルドで、素材をより価値のある品に加工できます。原Wikiの各国ページのギルド一覧を参照してください。",
    ["Getting around"] = "移動手段",
    ["Outpost warps"] = "アウトポスト転送",
    ["Each region has a conquest outpost. To unlock a warp, ask your nation's gate guard for a supply run and deliver the supplies to that region's outpost. Once it's unlocked and you meet its level requirement (level 10 for the regions around the starting cities), you can warp there from your nation's city for a gil fee. The fee triples if another nation holds the region. Outpost warps cost gil only, not conquest points."] = "リージョンごとにアウトポストがあります。自国のガードから補給を受け、届けると転送を開通できます。必要レベル（初期三国周辺は10）を満たせば、自国の街からギルで転送できます。原ガイドでは他国支配だと料金3倍で、個人戦績では支払えません。",
    ["Chocobos"] = "チョコボ",
    ["After Chocobo's Wounds, you can rent chocobos at stables. In the starter cities rentals open at level 15 and cost 50 gil plus your level. Elsewhere they open at level 20 and cost more. Chocobo digging and chocobo raising are both available."] = "「傷ついたチョコボ」後はチョコボを借りられます。原ガイドでは初期三国はレベル15から、料金は50ギル＋自分のレベル。それ以外は20からで料金も高くなります。チョコボ掘りと育成もあります。",
    ["Your Mog House"] = "自分のモグハウス",
    ["Your Mog House is in your home city. Each nation has a quest that lets your Mog House exit into a different part of the city: Growing Flowers (San d'Oria), A Lady's Heart (Bastok), and Flower Child (Windurst). Complete all three to unlock the second floor of your Mog House."] = "モグハウスは所属国の街にあります。出口拡張はサンドリアの「お庭にお花さんを植えたいにゃ」、バストゥークの「センスを磨くのにゃ」、ウィンダスの「一輪のお花さんがほしいにゃ」。3つとも終えると2階を利用できます。",
    ["How Phoenix differs from retail"] = "Phoenixと小売版の違い",
    ["Phoenix follows the level-75 era, so several later systems are not available:"] = "原ガイドのPhoenixはレベル75時代に沿っており、後年の次の仕組みは利用できません。以下はCatsEyeの仕様説明ではありません。",
    ["No Trusts. Fighting alongside other players is how you progress."] = "フェイスはありません。ほかのプレイヤーと協力して進めます。",
    ["No Records of Eminence, Fields of Valor, Grounds of Valor, or Survival Guides."] = "エミネンス・レコード、フィールド・オブ・ヴァラー、グラウンド・オブ・ヴァラー、Survival Guideはありません。",
    ["Home points only set where you return after being knocked out. They don't teleport you."] = "ホームポイントは戦闘不能時の帰還先の設定だけで、転送機能はありません。",
    ["No Wings of the Goddess or later content, including Dancer, Scholar, Geomancer, and Rune Fencer."] = "「アルタナの神兵」以降のコンテンツはなく、踊り子、学者、風水士、魔導剣士もありません。",
    ["Death costs experience from level 5."] = "原ガイドではレベル5から戦闘不能時に経験値を失います。",
    ["Only one character can be logged in per IP address. Households that share a connection can ask staff for an exception."] = "原Phoenixの規則では1つのIPから同時ログインできるキャラクターは1人だけです。同居人で回線を共有する場合はスタッフに例外を相談できます。CatsEyeの規則を示すものではありません。",
    ["Where to go next"] = "次の冒険へ",
    ["Nations: city areas, guilds, and leveling areas for each nation."] = "Nations：各国の街、ギルド、レベル上げエリア。",
    ["Jobs: every job, its unlock quest, and its abilities."] = "Jobs：各ジョブの取得クエストとアビリティ。",
    ["Zones: every area, with monsters, levels, shops, and fishing."] = "Zones：各エリアの敵、レベル、店、釣り。",
    ["Quests and Missions: every quest and storyline mission."] = "Quests and Missions：クエストとストーリーミッション。",
