    -- Gate Guards and Tosuka-Porika, as the 0.3.7 step text names them.
    ["Speak with any Gate Guard: Argus (Port Bastok L-7), Cleades (Bastok Markets D-11), Malduc (Metalworks J-8) or Rashid (Bastok Mines H-10)."] = "ゲートガードに話しかける。Argus（バストゥーク港 L-7）、Cleades（バストゥーク商業区 D-11）、Malduc（大工房 J-8）、Rashid（バストゥーク鉱山区 H-10）。",
    ["Return to Bastok and speak with any Gate Guard: Argus (Port Bastok L-7), Cleades (Bastok Markets D-11), Malduc (Metalworks J-8) or Rashid (Bastok Mines H-10)."] = "バストゥークへ戻り、いずれかのゲートガードに話す。Argus（バストゥーク港 L-7）、Cleades（バストゥーク商業区 D-11）、Malduc（大工房 J-8）、Rashid（バストゥーク鉱山区 H-10）。",
    ["Return to Bastok and trade all four Fetich pieces to any Gate Guard: Argus (Port Bastok L-7), Cleades (Bastok Markets D-11), Malduc (Metalworks J-8) or Rashid (Bastok Mines H-10)."] = "バストゥークへ戻り、4パーツをいずれかのゲートガードにトレードする。Argus（バストゥーク港 L-7）、Cleades（バストゥーク商業区 D-11）、Malduc（大工房 J-8）、Rashid（バストゥーク鉱山区 H-10）。",
    ["Speak with any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "サンドリアのいずれかのゲートガードに話しかける。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Return to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "サンドリアのいずれかのゲートガードのもとへ戻る。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Return to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8) to receive the mission."] = "サンドリアのいずれかのゲートガードに戻り、ミッションを受ける。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Receive the Crystal Dowser, then return to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "クリスタル・ダウザーを受け取り、サンドリアのいずれかのゲートガードへ戻る。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Trade the Orcish Mail Scales to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "Orcish Mail Scales をサンドリアのいずれかのゲートガードにトレードする。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Trade the Orcish Axe to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "オークアクスをサンドリアのいずれかのゲートガードにトレードする。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Trade the Crystal Bass to any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8)."] = "クリスタルバスをサンドリアのいずれかのゲートガードにトレードする。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Speak with any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8) to accept the mission."] = "サンドリアのいずれかのゲートガードに話してミッションを受ける。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Speak with any Gate Guard in San d'Oria: Ambrotien (Southern San d'Oria K-10), Endracion (Southern San d'Oria F-9) or Grilau (Northern San d'Oria D-8) and accept the mission."] = "サンドリアのいずれかのゲートガードに話し、ミッションを受ける。Ambrotien（南サンドリア K-10）、Endracion（南サンドリア F-9）、Grilau（北サンドリア D-8）。",
    ["Speak with any Gate Guard in Windurst: Mokyokyo (Windurst Waters F-5), Janshura-Rashura (Port Windurst B-5), Rakoh Buuma (Windurst Woods K-10) or Zokima-Rokima (Windurst Walls H-7)."] = "ウィンダスのいずれかのゲートガードに話しかける。Mokyokyo（ウィンダス水の区 F-5）、Janshura-Rashura（ウィンダス港 B-5）、Rakoh Buuma（ウィンダス森の区 K-10）、Zokima-Rokima（ウィンダス石の区 H-7）。",
    ["Return to any Gate Guard in Windurst: Mokyokyo (Windurst Waters F-5), Janshura-Rashura (Port Windurst B-5), Rakoh Buuma (Windurst Woods K-10) or Zokima-Rokima (Windurst Walls H-7)."] = "ウィンダスのいずれかのゲートガードのもとへ戻る。Mokyokyo（ウィンダス水の区 F-5）、Janshura-Rashura（ウィンダス港 B-5）、Rakoh Buuma（ウィンダス森の区 K-10）、Zokima-Rokima（ウィンダス石の区 H-7）。",
    ["Speak with Tosuka-Porika (G-8) in Windurst Waters."] = "ウィンダス水の区の Tosuka-Porika(G-8)に話す。",
    ["Return to Windurst Waters and speak with Tosuka-Porika (G-8)."] = "ウィンダス水の区へ戻り、Tosuka-Porika(G-8)に話す。",
    ["Travel to the Optistery in Windurst Waters and speak with Tosuka-Porika (G-8)."] = "ウィンダス水の区・目の院へ行き、Tosuka-Porika(G-8)に話す。",
    ["Return to Tosuka-Porika (G-8)."] = "Tosuka-Porika(G-8)のもとへ戻る。",
    ["Speak with Tosuka-Porika (G-8) in the Optistery."] = "目の院の Tosuka-Porika(G-8)に話す。",
}
